// item B: options whose value is optional (argparse nargs='?'): the next word is the value only where
// it does not start with `-`. pytest-cov's --cov (`nargs="?", const=True`), pytest's --debug and
// --cache-show.
const PYTEST_OPTIONS_WITH_OPTIONAL_VALUE = new Set(['--cov', '--debug', '--cache-show']);
// item B: long options of pytest and common plugins that take no value, so a word after one is a path.
const PYTEST_FLAGS_WITHOUT_VALUE = new Set([
  '--help', '--version', '--pyargs', '--strict-markers', '--strict-config', '--strict',
  '--continue-on-collection-errors', '--collect-only', '--co', '--collectonly', '--noconftest',
  '--keep-duplicates', '--doctest-modules', '--doctest-continue-on-failure', '--doctest-ignore-import-errors',
  '--exitfirst', '--lf', '--last-failed', '--ff', '--failed-first', '--nf', '--new-first', '--cache-clear',
  '--sw', '--stepwise', '--sw-skip', '--stepwise-skip', '--sw-reset', '--stepwise-reset', '--verbose', '--quiet',
  '--no-header', '--no-summary', '--no-fold-skipped', '--showlocals', '--no-showlocals', '--full-trace',
  '--runxfail', '--pdb', '--trace', '--fixtures', '--funcargs', '--fixtures-per-test', '--markers',
  '--setup-only', '--setup-show', '--setup-plan', '--disable-warnings', '--disable-pytest-warnings',
  '--force-short-summary', '--xfail-tb', '--no-cov', '--no-cov-on-fail', '--cov-append', '--cov-branch',
  '--cov-reset', '--forked', '--looponfail', '--boxed', '--reuse-db', '--create-db', '--nomigrations',
  '--migrations', '--benchmark-skip', '--benchmark-only', '--benchmark-disable', '--benchmark-autosave',
  '--hypothesis-show-statistics', '--self-contained-html', '--json-report', '--clean-alluredir',
  '--random-order', '--instafail', '--mypy', '--flake8', '--black', '--isort', '--ruff', '--ruff-format', '--lsof',
]);

/**
 * goal_cejel_v27_a1_gaps_2026-11-03, item C (#649, 2): how a conftest.py declares a long option:
 * 'flag' takes no value, 'value' takes the next word, 'unknown' where a declaration of the name
 * cannot be read (a name instead of a string literal beside it, `*args` or `**kwargs`, an action
 * that is not a string literal, an `nargs=`), or two declarations disagree.
 */
type PytestDeclaredOption = 'flag' | 'value' | 'unknown';

// argparse's actions that take no value; pytest's addoption passes `action` through to argparse.
const ARGPARSE_ACTIONS_WITHOUT_VALUE: ReadonlySet<string> = new Set(['store_true', 'store_false', 'count', 'store_const', 'append_const']);
const PYTHON_ADDOPTION_CALL_PATTERN = /\.[ \t]*_?addoption[ \t]*\(/g;
const PYTHON_PLAIN_STRING_PATTERN = /^(?:"([^"\\\n]*)"|'([^'\\\n]*)')$/;

/**
 * The top-level arguments of the Python call whose `(` is at `open` in `text`, as written and
 * trimmed, and the index after its `)`. Strings (triple-quoted too), brackets and comments are
 * stepped over. Linear in the call.
 */
function readPythonCallArguments(text: string, open: number): { readonly args: string[]; readonly end: number } {
  const args: string[] = [];
  let depth = 0;
  let start = open + 1;
  for (let index = open + 1; index < text.length; index += 1) {
    const character = text[index] ?? '';
    if (character === '"' || character === "'") {
      const triple = text.startsWith(character.repeat(3), index);
      const closer = triple ? character.repeat(3) : character;
      let at = index + closer.length;
      while (at < text.length && !text.startsWith(closer, at)) {
        if (text[at] === '\\') at += 1;
        else if (!triple && text[at] === '\n') break;
        at += 1;
      }
      index = at + closer.length - 1;
      continue;
    }
    if (character === '#') {
      const newline = text.indexOf('\n', index);
      index = newline === -1 ? text.length : newline - 1;
      continue;
    }
    if (character === '(' || character === '[' || character === '{') depth += 1;
    else if (character === ')' || character === ']' || character === '}') {
      if (depth === 0) {
        const last = text.slice(start, index).replace(/#[^\n]*/g, '').trim();
        if (last !== '') args.push(last);
        return { args, end: index + 1 };
      }
      depth -= 1;
    } else if (character === ',' && depth === 0) {
      args.push(text.slice(start, index).replace(/#[^\n]*/g, '').trim());
      start = index + 1;
    }
  }
  return { args, end: text.length };
}

/**
 * The positions in a code line (one that does not start inside a string) of the matches of the
 * global `pattern` that fall outside its strings and comments: one sweep of the line beside the
 * matches, which are in order. Linear in the line.
 */
function pythonCodeMatchesOnLine(raw: string, pattern: RegExp): number[] {
  const found: number[] = [];
  let quote = '';
  let at = 0;
  for (const match of raw.matchAll(pattern)) {
    const position = match.index ?? 0;
    for (; at < position; at += 1) {
      const character = raw[at] ?? '';
      if (quote !== '') {
        if (character === '\\') at += 1;
        else if (raw.startsWith(quote, at)) {
          at += quote.length - 1;
          quote = '';
        }
      } else if (character === '#') return found;
      else if (character === '"' || character === "'") {
        quote = raw.startsWith(character.repeat(3), at) ? character.repeat(3) : character;
        at += quote.length - 1;
      }
    }
    if (quote === '') found.push(position);
  }
  return found;
}

/** item C: what the repository's conftest.py files declare. */
export interface PytestDeclaredOptions {
  /** Each long option declared with string literals, and how it is read. */
  readonly options: ReadonlyMap<string, PytestDeclaredOption>;
  /**
   * The review of #655, should-fix 6: true where some declaration names its option through
   * something other than a string literal (a name, `*args`), which may be any option.
   */
  readonly unreadName: boolean;
}

/**
 * item C: each long option the repository's conftest.py files declare with `.addoption(...)` or
 * `._addoption(...)` (on the parser or an option group), read from code, not comments or strings,
 * every call on a line (the review of #655, nit), with CRLF text read as LF (should-fix 5). Linear
 * in the files. Exported for the scaling check in scan-path-regex-bounds.test.ts.
 */
export function readPytestDeclaredOptions(repoFiles: readonly string[], readText: (file: string) => string | undefined): PytestDeclaredOptions {
  const declared = new Map<string, PytestDeclaredOption>();
  let unreadName = false;
  const record = (name: string, kind: PytestDeclaredOption) => {
    const known = declared.get(name);
    declared.set(name, known === undefined || known === kind ? kind : 'unknown');
  };
  for (const file of repoFiles) {
    if (!PYTEST_CONFTEST_PATTERN.test(file) || GENERATED_OR_VENDOR_PATH_PATTERN.test(file)) continue;
    const text = readText(file);
    if (text === undefined || !text.includes('addoption')) continue;
    const source = pythonSourceLines(text);
    // The offset of each line in the text, from the text itself (a CRLF line is one longer than its
    // raw line), so a call found in a code line is read from there on.
    let lineStart = 0;
    let readTo = 0;
    for (let line = 0; line < source.raw.length; line += 1, lineStart = nextLineStart(text, lineStart)) {
      const raw = source.raw[line] ?? '';
      if (source.inString[line] === true) continue;
      const code = source.masked[line] ?? '';
      if (!code.includes('addoption')) continue;
      for (const position of pythonCodeMatchesOnLine(raw, PYTHON_ADDOPTION_CALL_PATTERN)) {
        const at = lineStart + position;
        if (at < readTo) continue;
        const open = text.indexOf('(', at);
        const call = readPythonCallArguments(text, open);
        readTo = call.end;
        const names: string[] = [];
        let readable = true;
        let action: string | undefined;
        for (const arg of call.args) {
          // `*args` and `**kwargs` are neither a keyword nor a string literal, so they fall to the
          // last lines below and leave the declaration unreadable.
          const keyword = /^([A-Za-z_]\w*)[ \t]*=(?!=)[ \t]*([\s\S]*)$/.exec(arg);
          if (keyword) {
            if (keyword[1] === 'nargs') readable = false;
            if (keyword[1] === 'action') {
              const literal = PYTHON_PLAIN_STRING_PATTERN.exec((keyword[2] ?? '').trim());
              if (literal) action = literal[1] ?? literal[2] ?? '';
              else readable = false;
            }
            continue;
          }
          const literal = PYTHON_PLAIN_STRING_PATTERN.exec(arg);
          if (literal) names.push(literal[1] ?? literal[2] ?? '');
          else {
            readable = false;
            // A positional argument is an option name; one that is not a literal may name any option.
            if (!arg.startsWith('**')) unreadName = true;
          }
        }
        const kind: PytestDeclaredOption = !readable ? 'unknown' : action !== undefined && ARGPARSE_ACTIONS_WITHOUT_VALUE.has(action) ? 'flag' : 'value';
        for (const name of names) if (name.startsWith('--')) record(name, kind);
      }
    }
  }
  return { options: declared, unreadName };
}

/** The offset just after the line feed that ends the line starting at `from`, or past the text. */
function nextLineStart(text: string, from: number): number {
  const feed = text.indexOf('\n', from);
  return feed === -1 ? text.length + 1 : feed + 1;
}

/** pytest's words read as Cejel needs them. */
interface PytestArguments {
  readonly paths: string[];
  readonly options: { readonly name: string; readonly value?: string }[];
  readonly pyargs: boolean;
  /** item B: an option the reader does not know, and the word after it, which may be its value or a path. */
  readonly unknownOption?: string;
}

function readPytestArguments(
  words: readonly string[],
  declared: (name: string) => PytestDeclaredOption | undefined = () => undefined,
): PytestArguments {
  const paths: string[] = [];
  const options: { name: string; value?: string }[] = [];
  let pyargs = false;
  let unknownOption: string | undefined;
  for (let index = 0; index < words.length; index += 1) {
    const word = words[index] ?? '';
    if (word === '--') {
      paths.push(...words.slice(index + 1));
      break;
    }
    if (!word.startsWith('-') || word === '-') {
      paths.push(word);
      continue;
    }
    if (word === '--pyargs') pyargs = true;
    const equals = word.startsWith('--') ? word.indexOf('=') : -1;
    if (equals > 0) {
      options.push({ name: word.slice(0, equals), value: word.slice(equals + 1) });
      continue;
    }
    if (PYTEST_OPTIONS_WITH_VALUE.has(word)) {
      options.push({ name: word, value: words[index + 1] });
      index += 1;
      continue;
    }
    if (PYTEST_OPTIONS_WITH_OPTIONAL_VALUE.has(word)) {
      const next = words[index + 1];
      if (next !== undefined && !next.startsWith('-')) {
        options.push({ name: word, value: next });
        index += 1;
      } else {
        options.push({ name: word });
      }
      continue;
    }
    if (word.startsWith('--') && !PYTEST_FLAGS_WITHOUT_VALUE.has(word)) {
      // goal_cejel_v27_a1_gaps_2026-11-03, item C: an option a conftest.py declares is read as declared.
      const kind = declared(word);
      if (kind === 'flag') {
        options.push({ name: word });
        continue;
      }
      const next = words[index + 1];
      if (kind === 'value' && next !== undefined && !next.startsWith('-')) {
        options.push({ name: word, value: next });
        index += 1;
        continue;
      }
      if (next !== undefined && !next.startsWith('-')) unknownOption ??= `${word} ${next}`;
      options.push({ name: word });
      continue;
    }
    // A short option with its value attached (`-pno:skipping`, `-ofoo=bar`, `-cfile.ini`).
    const attached = /^-([pockmnWr])(.+)$/.exec(word);
    if (attached) {
      options.push({ name: `-${attached[1]}`, value: attached[2] });
      continue;
    }
    options.push({ name: word });
  }
  return { paths, options, pyargs, ...(unknownOption === undefined ? {} : { unknownOption }) };
}

/**
 * The repository's pytest settings, read per file from the pytest runs that collect it (see the
 * section comment). Linear in the configuration, CI, recipe and tox files.
 */
function readPytestCollectionSettings(repoPath: string, repoFiles: readonly string[]): PytestCollectionSettings {
  const configs = new Map<string, PytestConfigFile>();
  const fileSet = new Set(repoFiles);
  const directories = new Set<string>(['']);
  for (const file of repoFiles) {
    for (let directory = repoDirectory(file); directory !== ''; directory = repoDirectory(directory)) {
      if (directories.has(directory)) break;
      directories.add(directory);
    }
  }
  const readText = (file: string): string | undefined => {
    const fullPath = join(repoPath, file);
    return isRegularFile(fullPath) ? readRepoText(fullPath, 'utf8') : undefined;
  };
  const configAt = (file: string): PytestConfigFile | undefined => {
    if (!fileSet.has(file) || GENERATED_OR_VENDOR_PATH_PATTERN.test(file)) return undefined;
    let config = configs.get(file);
    if (config === undefined) {
      const text = readText(file);
      if (text === undefined) return undefined;
      config = readPytestConfigFile(file, text);
      configs.set(file, config);
    }
    return config;
  };
  // item E: a file's lines, read once, for the few clauses the evidence cites.
  const fileLines = new Map<string, readonly string[]>();
  const lineOf = (file: string, tokens: readonly string[], from: number): number | null => {
    let lines = fileLines.get(file);
    if (lines === undefined) {
      lines = (readText(file) ?? '').split(/\r?\n/);
      fileLines.set(file, lines);
    }
    for (const token of tokens) {
      if (token === '') continue;
      for (let index = Math.max(0, from); index < lines.length; index += 1) if ((lines[index] ?? '').includes(token)) return index + 1;
    }
    for (const token of tokens) {
      if (token === '') continue;
      for (let index = 0; index < Math.min(from, lines.length); index += 1) if ((lines[index] ?? '').includes(token)) return index + 1;
    }
    return from < lines.length ? from + 1 : null;
  };
  const invocations = readPytestInvocations(repoFiles, readText);
  // item C of goal_cejel_v27_a1_gaps_2026-11-03: read once, where a run names an option pytest's tables do not hold.
  let declaredOptions: PytestDeclaredOptions | undefined;
  const declaredOption = (name: string): PytestDeclaredOption | undefined => {
    declaredOptions ??= readPytestDeclaredOptions(repoFiles, readText);
    // The review of #655, should-fix 6: a declaration through a name may be this option's.
    return declaredOptions.unreadName ? 'unknown' : declaredOptions.options.get(name);
  };
  const view: PytestRepositoryView = { fileSet, directories, configAt, lineOf, declaredOption };
  const runs = invocations.map((invocation) => resolvePytestRun(invocation, view));
  const cache = new Map<string, PytestFileSettings>();
  return {
    forFile: (file) => {
      const cached = cache.get(file);
      if (cached) return cached;
      const collecting = runs.filter((run) => run.collects(file));
      const settings: PytestFileSettings = {
        ...firstDefined(collecting.map((run) => run.pythonFiles), 'pythonFiles'),
        ...firstDefined(collecting.map((run) => run.testNames), 'testNames'),
        ...firstDefined(collecting.map((run) => run.disablesSkipping), 'disablesSkipping'),
        hookNotLoaded: (hookPath, scope) => {
          for (const run of collecting) {
            const reason = run.hookNotLoaded(hookPath, scope, file);
            if (reason !== undefined) return reason;
          }
          return undefined;
        },
        ...(collecting.some((run) => run.configAboveRoot) ? { configAboveRoot: true } : {}),
      };
      cache.set(file, settings);
      return settings;
    },
  };
}

function firstDefined<K extends string>(
  sources: readonly (PytestSettingSource | undefined)[],
  key: K,
): { [key in K]?: PytestSettingSource } {
  const found = sources.find((source) => source !== undefined);
  return (found === undefined ? {} : { [key]: found }) as { [key in K]?: PytestSettingSource };
}

/** A pytest run as pytest would set it up. */
interface ResolvedPytestRun {
  readonly collects: (file: string) => boolean;
  readonly pythonFiles?: PytestSettingSource;
  readonly testNames?: PytestSettingSource;
  readonly disablesSkipping?: PytestSettingSource;
  /** Why this run, collecting `file`, does not call the hook in the conftest.py `hookPath` (in `scope`) with it. */
  readonly hookNotLoaded: (hookPath: string, scope: string, file: string) => PytestReason | undefined;
  /** item C: pytest's search for this run's configuration file finds none in the repository and goes above its root. */
  readonly configAboveRoot?: boolean;
}

interface PytestRepositoryView {
  readonly fileSet: ReadonlySet<string>;
  readonly directories: ReadonlySet<string>;
  readonly configAt: (file: string) => PytestConfigFile | undefined;
  /** item E: the 1-based line of `file` holding the first of `tokens` found at or after the 0-based `from`, then before it. */
  readonly lineOf: (file: string, tokens: readonly string[], from: number) => number | null;
  /** goal_cejel_v27_a1_gaps_2026-11-03, item C: how the repository's conftest.py files declare a long option, if they do. */
  readonly declaredOption?: (name: string) => PytestDeclaredOption | undefined;
}

/**
 * item A: a run whose arguments or directory cannot be known from the repository. Any option may
 * be in force for it and it may collect any file, so it switches off every removal rule for every
 * file, and A1's note names it with the reason.
 */
function unreadPytestRun(invocation: PytestInvocation, reason: string, repo: PytestRepositoryView, path?: string): ResolvedPytestRun {
  const file = path ?? invocation.file ?? '';
  const clause = `${A1_RUN_NOT_READ}\`${reason}\` in ${path === undefined ? a1NotePath(invocation.source ?? '') : a1NotePath(path)}`;
  const anchor = path === undefined ? (invocation.anchor ?? 0) : 0;
  const at = (): A1ClausePointer | undefined =>
    file === ''
      ? undefined
      : { path: file, line: repo.lineOf(file, [reason, reason.split('\n')[0] ?? '', 'session.run', 'pytest'], anchor), label: `pytest run not read (${reason})` };
  const source: PytestSettingSource = { setting: '', where: '', notRead: clause, at };
  return {
    collects: () => true,
    pythonFiles: source,
    testNames: source,
    disablesSkipping: source,
    hookNotLoaded: () => ({ text: clause, at }),
  };
}

/** item B: testpaths entries pytest expands with glob.glob(..., recursive=True) from its root, as repository paths. */
function expandTestpathsPattern(rootdir: string, pattern: string, repo: PytestRepositoryView, children: () => ReadonlyMap<string, readonly string[]>): string[] {
  if (!/[*?[]/.test(pattern)) {
    const resolved = resolveCommandPath(rootdir, pattern === '' ? '.' : pattern);
    return resolved !== null && (repo.fileSet.has(resolved) || repo.directories.has(resolved)) ? [resolved] : [];
  }
  if (pattern.startsWith('/') || /[$`{}~]/.test(pattern)) return [];
  let current = [rootdir];
  const parts = pattern.replace(/\\/g, '/').split('/').filter((part) => part !== '' && part !== '.');
  for (const [index, part] of parts.entries()) {
    const last = index === parts.length - 1;
    const next = new Set<string>();
    for (const at of current) {
      if (part === '..') {
        if (at !== '') next.add(repoDirectory(at));
        continue;
      }
      if (part === '**') {
        // `**` matches the directory itself and every directory (and, last, every path) below it.
        const stack = [at];
        while (stack.length > 0) {
          const directory = stack.pop() ?? '';
          next.add(directory);
          for (const child of children().get(directory) ?? []) {
            const name = child.slice(child.lastIndexOf('/') + 1);
            if (name.startsWith('.')) continue;
            if (repo.directories.has(child)) stack.push(child);
            else if (last) next.add(child);
          }
        }
        continue;
      }
      if (!/[*?[]/.test(part)) {
        const child = at === '' ? part : `${at}/${part}`;
        if (repo.fileSet.has(child) || repo.directories.has(child)) next.add(child);
        continue;
      }
      for (const child of children().get(at) ?? []) {
        const name = child.slice(child.lastIndexOf('/') + 1);
        // glob does not match a name starting with `.` unless the pattern part does.
        if (name.startsWith('.') && !part.startsWith('.')) continue;
        if ((last || repo.directories.has(child)) && fnmatchWhole(part, name)) next.add(child);
      }
    }
    current = [...next];
  }
  return current;
}

/**
 * How pytest 9 sets up one run (findpaths.determine_setup, Config._decide_args and confcutdir),
 * or undefined where Cejel cannot read the run whole.
 */
function resolvePytestRun(invocation: PytestInvocation, repo: PytestRepositoryView): ResolvedPytestRun {
  if (invocation.unread !== undefined) return unreadPytestRun(invocation, invocation.unread, repo);
  const { directory } = invocation;
  const commandWhere = `on a pytest command line in ${a1NotePath(invocation.source ?? '')}`;
  const file = invocation.file ?? '';
  const anchor = invocation.anchor ?? 0;
  // item E: a setting on a command line points at the line holding its word (else the pytest
  // command); a PYTEST_ADDOPTS setting at the line that sets PYTEST_ADDOPTS.
  const commandAt = (tokens: readonly string[]) => (token: string, label: string) => (): A1ClausePointer | undefined =>
    file === '' ? undefined : { path: file, line: repo.lineOf(file, [token, ...tokens], anchor), label };
  const groups: PytestFlagGroup[] = [];
  if (invocation.addopts && invocation.addopts.length > 0) {
    const elsewhere = invocation.addoptsAt;
    groups.push({
      words: invocation.addopts,
      where: `in PYTEST_ADDOPTS in ${a1NotePath(elsewhere?.source ?? invocation.source ?? '')}`,
      at: (_token, label) => () =>
        elsewhere !== undefined
          ? { path: elsewhere.file, line: repo.lineOf(elsewhere.file, ['PYTEST_ADDOPTS'], elsewhere.line), label }
          : file === ''
            ? undefined
            : { path: file, line: repo.lineOf(file, ['PYTEST_ADDOPTS'], invocation.addoptsAnchor ?? anchor), label },
    });
  }
  if (invocation.args.length > 0) groups.push({ words: invocation.args, where: commandWhere, at: commandAt(['pytest', 'py.test']) });
  const parsed = groups.map((group) => ({ group, read: readPytestArguments(group.words, repo.declaredOption) }));
  // item A: --pyargs collects by import name, from wherever Python finds the package.
  if (parsed.some(({ read }) => read.pyargs)) return unreadPytestRun(invocation, '--pyargs', repo);
  // item B: an option the reader does not know, before a word that may be its value or a path.
  const unknown = parsed.find(({ read }) => read.unknownOption !== undefined)?.read.unknownOption;
  if (unknown !== undefined) return unreadPytestRun(invocation, unknown, repo);
  const option = (name: string, alias?: string) => {
    let found: { name: string; value?: string; where: string } | undefined;
    for (const { group, read } of parsed) {
      for (const entry of read.options) {
        if (entry.name === name || entry.name === alias) found = { name: entry.name, value: entry.value, where: group.where };
      }
    }
    return found;
  };
  // Path arguments: each must resolve to a path in the repository (item A: a variable or an
  // expression in one leaves the run not read).
  const paths: string[] = [];
  const dirs: string[] = [];
  for (const { read } of parsed) {
    for (const word of read.paths) {
      const resolved = resolveCommandPath(directory, word.split('::')[0] ?? '');
      if (resolved === null) return unreadPytestRun(invocation, invocation.text ?? word, repo);
      if (repo.fileSet.has(resolved) || repo.directories.has(resolved)) {
        paths.push(resolved);
        dirs.push(repo.fileSet.has(resolved) ? repoDirectory(resolved) : resolved);
      }
    }
  }
  const pathDirectories = [...new Set(dirs)];
  const ancestor = commonRepoAncestor(pathDirectories) ?? directory;
  const rootdirOption = option('--rootdir');
  const configOption = option('-c', '--config-file');
  let config: PytestConfigFile | undefined;
  let rootdir: string | undefined;
  let configAboveRoot = false;
  if (configOption !== undefined) {
    // item A: a -c the repository does not hold (outside it, or a variable) is not read.
    const shownOption = `${configOption.name} ${configOption.value ?? ''}`;
    const path = resolveCommandPath(directory, configOption.value ?? '');
    if (path === null) return unreadPytestRun(invocation, shownOption, repo);
    config = repo.configAt(path);
    if (config === undefined) return unreadPytestRun(invocation, shownOption, repo);
    rootdir = repoDirectory(path);
  } else {
    // item C: pytest 9's determine_setup. locate_config from the common ancestor of the run's
    // paths searches every parent, above the repository's root too, for a file holding pytest's
    // configuration before it falls back to the first pyproject.toml it passed. Failing both, a
    // setup.py at or above the ancestor is the root; failing that, where the paths' directories are
    // not just the ancestor, locate_config runs again from each of them (the per-argument
    // fallback); failing that, the root is the common ancestor of the invocation directory and the
    // ancestor. Cejel sees no file above the repository's root.
    const located = locatePytestConfig([ancestor], repo);
    configAboveRoot = located === undefined || located.fallback === true;
    if (located !== undefined) {
      config = located;
      rootdir = repoDirectory(located.path);
    } else if (rootdirOption === undefined) {
      for (let at = ancestor; ; at = repoDirectory(at)) {
        if (repo.fileSet.has(at === '' ? 'setup.py' : `${at}/setup.py`)) {
          rootdir = at;
          break;
        }
        if (at === '') break;
      }
      if (rootdir === undefined) {
        const perArgument = dirs.length === 1 && dirs[0] === ancestor ? undefined : locatePytestConfig(dirs.length === 0 ? [directory] : dirs, repo);
        if (perArgument !== undefined) {
          config = perArgument;
          rootdir = repoDirectory(perArgument.path);
        }
      }
      rootdir ??= commonRepoAncestor([directory, ancestor]) ?? '';
    }
  }
  let rootdirWhere: string | undefined;
  let rootdirAt: (() => A1ClausePointer | undefined) | undefined;
  if (rootdirOption !== undefined) {
    const path = resolveCommandPath(directory, rootdirOption.value ?? '');
    if (path === null) return unreadPytestRun(invocation, `--rootdir ${rootdirOption.value ?? ''}`, repo);
    rootdir = path;
    rootdirWhere = rootdirOption.where;
    rootdirAt = (groups.find((group) => group.where === rootdirOption.where)?.at ?? commandAt([]))('--rootdir', 'pytest setting in force: --rootdir');
  }
  // The configuration's own options, then its addopts as flags, then -o overrides from any group.
  const configWhere = config === undefined ? '' : `set in ${a1NotePath(config.path)}`;
  const configFile = config;
  const configAt = (key: string) => (_token: string, label: string) => (): A1ClausePointer | undefined =>
    configFile === undefined ? undefined : { path: configFile.path, line: configFile.lines?.get(key) ?? null, label };
  const values = new Map<string, { value: PytestOptionValue; where: string; at: () => A1ClausePointer | undefined }>();
  for (const [key, value] of config?.options ?? []) {
    values.set(key, { value, where: configWhere, at: configAt(key)(key, `pytest setting in force: ${key}`) });
  }
  const addopts = values.get('addopts');
  if (addopts !== undefined) {
    const words = addopts.value.kind === 'list' ? addopts.value.items : shellWords(addopts.value.text);
    const read = readPytestArguments(words, repo.declaredOption);
    if (read.pyargs) return unreadPytestRun(invocation, '--pyargs', repo, config?.path);
    if (read.unknownOption !== undefined) return unreadPytestRun(invocation, read.unknownOption, repo, config?.path);
    parsed.unshift({ group: { words, where: configWhere, at: configAt('addopts') }, read });
  }
  for (const { group, read } of parsed) {
    for (const entry of read.options) {
      if ((entry.name === '-o' || entry.name === '--override-ini') && entry.value !== undefined) {
        const equals = entry.value.indexOf('=');
        if (equals > 0) {
          const key = entry.value.slice(0, equals).trim();
          values.set(key, {
            value: { kind: 'text', text: entry.value.slice(equals + 1) },
            where: group.where,
            at: group.at(key, `pytest setting in force: ${key}`),
          });
        }
      }
    }
  }
  const flag = (
    test: (entry: { name: string; value?: string }) => boolean,
    setting: string,
    token: string,
  ): PytestSettingSource | undefined => {
    let found: PytestSettingSource | undefined;
    for (const { group, read } of parsed) {
      if (read.options.some(test)) found ??= { setting, where: group.where, at: group.at(token, `pytest setting in force: ${setting}`) };
    }
    return found;
  };
  const noConftest = flag(({ name }) => name === '--noconftest', '--noconftest', '--noconftest');
  const disablesSkipping = flag(({ name, value }) => name === '-p' && value === 'no:skipping', '-p no:skipping', 'no:skipping');
  // The pytest command line itself, for a reason that names it.
  const commandLineAt = commandAt(['pytest', 'py.test'])('pytest', 'pytest command line that does not load the hook');
  // confcutdir: the option (from any group, the last one wins), else the configuration file's
  // directory, else the root.
  let confcutdirOption: { value?: string; where: string; group: PytestFlagGroup } | undefined;
  for (const { group, read } of parsed) {
    for (const entry of read.options) if (entry.name === '--confcutdir') confcutdirOption = { value: entry.value, where: group.where, group };
  }
  let confcutdir: string;
  let confcutdirReason: (hookPath: string) => PytestReason;
  if (confcutdirOption !== undefined) {
    const path = resolveCommandPath(directory, confcutdirOption.value ?? '');
    if (path === null) return unreadPytestRun(invocation, `--confcutdir ${confcutdirOption.value ?? ''}`, repo);
    confcutdir = path;
    const at = confcutdirOption.group.at('--confcutdir', 'pytest setting in force: --confcutdir');
    confcutdirReason = () => ({ text: `--confcutdir ${confcutdirOption?.where ?? ''}`, at });
  } else if (config !== undefined) {
    confcutdir = repoDirectory(config.path);
    const shown = a1NotePath(config.path);
    confcutdirReason = (hookPath) => ({
      text: `${shown} is pytest's configuration for the pytest command line in ${a1NotePath(invocation.source ?? '')}, so it does not load ${a1NotePath(hookPath)}`,
      at: commandLineAt,
    });
  } else {
    confcutdir = rootdir ?? '';
    confcutdirReason = (hookPath) =>
      rootdirWhere !== undefined
        ? { text: `--rootdir ${rootdirWhere}`, ...(rootdirAt === undefined ? {} : { at: rootdirAt }) }
        : {
            text: `pytest's root is ${confcutdir === '' ? 'the repository root' : a1NotePath(confcutdir)} for the pytest command line in ${a1NotePath(invocation.source ?? '')}, so it does not load ${a1NotePath(hookPath)}`,
            at: commandLineAt,
          };
  }
  // What the run collects: its paths, else testpaths where it runs in its root, else its directory.
  let targets = paths;
  if (parsed.every(({ read }) => read.paths.length === 0)) {
    targets = [];
    const testpaths = values.get('testpaths');
    if (directory === rootdir && testpaths !== undefined) {
      const patterns = optionWords(testpaths.value);
      if (patterns === undefined) return unreadPytestRun(invocation, 'testpaths', repo, config?.path);
      // item B: each entry expanded as glob.glob(..., recursive=True) expands it from the root.
      let children: Map<string, string[]> | undefined;
      const childrenOf = (): ReadonlyMap<string, readonly string[]> => {
        if (children === undefined) {
          children = new Map();
          for (const path of [...repo.directories, ...repo.fileSet]) {
            if (path === '') continue;
            const parent = repoDirectory(path);
            const list = children.get(parent) ?? [];
            list.push(path);
            children.set(parent, list);
          }
        }
        return children;
      };
      for (const pattern of patterns) targets.push(...expandTestpathsPattern(rootdir, pattern, repo, childrenOf));
    }
    if (targets.length === 0) targets = [directory];
  }
  const ignores: string[] = [];
  let ignoreGlob = false;
  for (const { read } of parsed) {
    for (const entry of read.options) {
      if (entry.name === '--ignore-glob') ignoreGlob = true;
      if (entry.name !== '--ignore' || entry.value === undefined) continue;
      const resolved = resolveCommandPath(directory, entry.value);
      if (resolved !== null) ignores.push(resolved);
    }
  }
  const pythonFilesValue = values.get('python_files');
  const pythonFilesPatterns = pythonFilesValue === undefined ? undefined : optionWords(pythonFilesValue.value);
  const pythonFiles =
    pythonFilesValue !== undefined && (pythonFilesPatterns === undefined || pythonFilesPatterns.some(pythonFilesPatternMayMatchConftest))
      ? { setting: 'python_files', where: pythonFilesValue.where, at: pythonFilesValue.at }
      : undefined;
  let testNames: PytestSettingSource | undefined;
  for (const name of ['python_functions', 'python_classes']) {
    const entry = values.get(name);
    if (entry === undefined || testNames !== undefined) continue;
    const patterns = optionWords(entry.value);
    if (patterns === undefined || patterns.some(pytestNamePatternReachesBeyondTest)) testNames = { setting: name, where: entry.where, at: entry.at };
  }
  return {
    collects: (file) => targets.some((target) => isAtOrBelow(file, target)) && !ignores.some((ignored) => isAtOrBelow(file, ignored)),
    ...(pythonFiles === undefined ? {} : { pythonFiles }),
    ...(testNames === undefined ? {} : { testNames }),
    ...(disablesSkipping === undefined ? {} : { disablesSkipping }),
    ...(configAboveRoot ? { configAboveRoot } : {}),
    hookNotLoaded: (hookPath, scope, file) => {
      if (noConftest !== undefined) return pytestSettingReason(noConftest);
      // pytest loads no conftest.py from a directory strictly above its confcutdir (_is_in_confcutdir).
      if (isStrictAncestorDirectory(scope, confcutdir)) return confcutdirReason(hookPath);
      // goal_cejel_v27_a1_restore_proof_v2_2026-11-02, item E: pytest calls every loaded conftest.py's
      // collection hook with every collected item, so a hook reaches a file outside its directory
      // where this run also collects the hook's directory, which loads its conftest.py. A run that
      // names no path at or above or below that directory, ignores it, or sets norecursedirs or
      // --ignore-glob (which Cejel does not resolve) is read as not loading it.
      if (!isAtOrBelow(file, scope)) {
        const reaches =
          targets.some((target) => isAtOrBelow(scope, target) || isAtOrBelow(target, scope)) &&
          !ignores.some((ignored) => isAtOrBelow(scope, ignored)) &&
          !ignoreGlob;
        if (!reaches) {
          return {
            text: `the pytest command line in ${a1NotePath(invocation.source ?? '')} does not collect ${a1NotePath(scope)}, so it does not load ${a1NotePath(hookPath)}`,
            at: commandLineAt,
          };
        }
        const norecursedirs = values.get('norecursedirs');
        if (norecursedirs !== undefined) return { text: `norecursedirs ${norecursedirs.where}`, at: norecursedirs.at };
      }
      return undefined;
    },
  };
}

/** An option's value as whitespace-separated words, or undefined for a value Cejel did not parse. */
function optionWords(value: PytestOptionValue): string[] | undefined {
  if (value.kind === 'unknown') return undefined;
  return (value.kind === 'text' ? [value.text] : value.items).flatMap((item) => item.split(/\s+/)).filter((item) => item !== '');
}

/** The deepest directory every given repository-relative directory is at or below, or undefined for none. */
function commonRepoAncestor(paths: readonly string[]): string | undefined {
  if (paths.length === 0) return undefined;
  let common = paths[0] ?? '';
  for (const path of paths.slice(1)) {
    while (!isAtOrBelow(path, common)) common = repoDirectory(common);
  }
  return common;
}

/**
 * pytest's locate_config over repository directories: each directory and its parents, the first
 * configuration file that holds pytest's configuration, in pytest's order; failing that, the first
 * pyproject.toml found (pytest then roots there with no options).
 */
function locatePytestConfig(
  starts: readonly string[],
  repo: PytestRepositoryView,
): (PytestConfigFile & { readonly fallback?: boolean }) | undefined {
  let firstPyproject: PytestConfigFile | undefined;
  for (const start of starts) {
    for (let at = start; ; at = repoDirectory(at)) {
      for (const name of PYTEST_CONFIG_FILE_NAMES) {
        const config = repo.configAt(at === '' ? name : `${at}/${name}`);
        if (config === undefined) continue;
        if (name === 'pyproject.toml') firstPyproject ??= config;
        if (config.holdsConfig) return config;
      }
      if (at === '') break;
    }
  }
  return firstPyproject === undefined ? undefined : { path: firstPyproject.path, holdsConfig: true, options: new Map(), fallback: true };
}

/**
 * Shell text a CI configuration runs: `run:` steps (extractCiRunCommands), the values of the
 * script-family keys (inline, block scalar or block sequence), and a Jenkinsfile's one-line `sh`
 * steps. Linear in the file.
 */
function ciShellTexts(contents: string): string[] {
  const texts = extractCiRunCommands(contents);
  const lines = contents.split(/\r?\n/);
  for (let index = 0; index < lines.length; index += 1) {
    const match = CI_SCRIPT_KEY_PATTERN.exec(lines[index] ?? '');
    if (!match) continue;
    const indent = match[1]?.length ?? 0;
    const value = (match[2] ?? '').trim();
    if (value !== '' && !/^[|>]/.test(value)) {
      texts.push(unquoteYamlListItem(value.replace(/^\[(.*)\]$/, '$1')));
      continue;
    }
    for (index += 1; index < lines.length; index += 1) {
      const nested = lines[index] ?? '';
      if (nested.trim() === '') continue;
      if (nested.length - nested.trimStart().length <= indent) {
        index -= 1;
        break;
      }
      const item = nested.trim().replace(/^-[ \t]*/, '').replace(/^[|>][-+]?$/, '');
      if (item !== '') texts.push(unquoteYamlListItem(item));
    }
  }
  for (const match of contents.matchAll(/\bsh[ \t]*\(?[ \t]*(['"])([^'"\n]*)\1/g)) texts.push(match[2] ?? '');
  return texts;
}

/** A YAML scalar with its one pair of enclosing quotes removed, if it has them. */
function unquoteYamlListItem(value: string): string {
  const quoted = /^(?:"(.*)"|'(.*)')$/.exec(value);
  return quoted ? (quoted[1] ?? quoted[2] ?? '') : value;
}

/**
 * The entries of one section of an ini-style file, as pytest's ini reader takes them: a line
 * starting `#` or `;` is a comment, a line starting with whitespace continues the previous value,
 * and a key ends at its first `=` or `:`. `outside` holds the other non-comment lines (tox's
 * commands). Linear in the file.
 */
function readIniSection(
  text: string,
  section: string,
): { present: boolean; entries: [string, string][]; lines: number[]; outside: string[] } {
  let present = false;
  let current: string | undefined;
  let last: [string, string] | undefined;
  const entries: [string, string][] = [];
  const lines: number[] = [];
  const outside: string[] = [];
  let lineNumber = 0;
  for (const raw of text.split(/\r?\n/)) {
    lineNumber += 1;
    const trimmed = raw.trim();
    if (trimmed === '' || trimmed.startsWith('#') || trimmed.startsWith(';')) continue;
    if (raw.startsWith('[')) {
      const close = raw.indexOf(']');
      current = close === -1 ? undefined : raw.slice(1, close).trim();
      last = undefined;
      if (current === section) present = true;
      continue;
    }
    if (current !== section) {
      outside.push(trimmed);
      continue;
    }
    if (/^[ \t]/.test(raw)) {
      if (last) last[1] = `${last[1]}\n${trimmed}`;
      continue;
    }
    const match = /^([^=:]+)[=:](.*)$/.exec(raw);
    last = match ? [(match[1] ?? '').trim(), (match[2] ?? '').trim()] : undefined;
    if (last) {
      entries.push(last);
      lines.push(lineNumber);
    }
  }
  return { present, entries, lines, outside };
}

/**
 * pytest's options in pyproject.toml: under [tool.pytest.ini_options], or pytest 9's native
 * [tool.pytest], however the key is dotted. Comments are not read; an array or a multi-line string
 * runs to its end. An inline table naming one of the options counts it as set to a value Cejel did
 * not parse. Linear in the file.
 */
function readPyprojectPytestSettings(
  text: string,
  // 'tool' for pyproject.toml's [tool.pytest] and [tool.pytest.ini_options]; 'pytest' for pytest.toml's [pytest].
  root: 'tool' | 'pytest' = 'tool',
): { present: boolean; entries: [string, PytestOptionValue][]; lines: number[] } {
  const lines = text.split(/\r?\n/);
  const entries: [string, PytestOptionValue][] = [];
  const entryLines: number[] = [];
  let present = false;
  let table: string[] = [];
  for (let index = 0; index < lines.length; index += 1) {
    const trimmed = (lines[index] ?? '').trim();
    if (trimmed === '' || trimmed.startsWith('#')) continue;
    const header = /^\[\[?([^\]]*)\]\]?/.exec(trimmed);
    if (header) {
      table = tomlKeyPath(header[1] ?? '');
      if (pytestTomlOptionPath(table, root)?.length === 0) present = true;
      continue;
    }
    const equals = tomlKeyEnd(trimmed);
    if (equals === -1) continue;
    const keyLine = index + 1;
    const scanner = new TomlValueScanner();
    scanner.feed(trimmed.slice(equals + 1));
    while (!scanner.complete() && index + 1 < lines.length) {
      index += 1;
      scanner.feed(`\n${lines[index] ?? ''}`);
    }
    const path = [...table, ...tomlKeyPath(trimmed.slice(0, equals))];
    const rest = pytestTomlOptionPath(path, root);
    if (rest === undefined || rest.length > 1) continue;
    present = true;
    const value = scanner.value();
    if (rest.length === 1) {
      entries.push([rest[0] ?? '', value]);
      entryLines.push(keyLine);
      continue;
    }
    for (const name of PYTEST_A1_OPTION_NAMES) {
      if (containsPythonIdentifier(scanner.code(), name)) {
        entries.push([name, { kind: 'unknown', text: value.kind === 'unknown' ? value.text : '' }]);
        entryLines.push(keyLine);
      }
    }
  }
  return { present, entries, lines: entryLines };
}

/** The part of a TOML key path below pytest's table, or undefined outside it. */
function pytestTomlOptionPath(path: readonly string[], root: 'tool' | 'pytest'): string[] | undefined {
  if (root === 'pytest') return path[0] === 'pytest' ? path.slice(1) : undefined;
  if (path[0] !== 'tool' || path[1] !== 'pytest') return undefined;
  return path[2] === 'ini_options' ? path.slice(3) : path.slice(2);
}

/** A TOML key's dotted path, each part unquoted. */
function tomlKeyPath(key: string): string[] {
  return key
    .split('.')
    .map((part) => part.trim().replace(/^"(.*)"$|^'(.*)'$/, '$1$2'))
    .filter((part) => part !== '');
}

/** The index of a TOML key line's `=`, outside quotes, or -1. */
function tomlKeyEnd(line: string): number {
  let quote: string | undefined;
  for (let index = 0; index < line.length; index += 1) {
    const character = line[index];
    if (quote !== undefined) {
      if (character === quote) quote = undefined;
    } else if (character === '"' || character === "'") {
      quote = character;
    } else if (character === '=') {
      return index;
    }
  }
  return -1;
}

/**
 * Reads a TOML value fed in chunks: its strings (basic, literal and multi-line), the code outside
 * strings and comments, and whether every bracket and string has closed. Linear in what it is fed.
 */
class TomlValueScanner {
  private quote: '"' | "'" | '"""' | "'''" | undefined;
  private escaped = false;
  private comment = false;
  private depth = 0;
  private current = '';
  private readonly strings: string[] = [];
  private outside = '';

  feed(chunk: string): void {
    for (let index = 0; index < chunk.length; index += 1) {
      const character = chunk[index] ?? '';
      if (this.comment) {
        if (character === '\n') this.comment = false;
        continue;
      }
      if (this.quote !== undefined) {
        if (this.escaped) {
          this.current += character;
          this.escaped = false;
          continue;
        }
        if (character === '\\' && (this.quote === '"' || this.quote === '"""')) {
          this.escaped = true;
          continue;
        }
        if (chunk.startsWith(this.quote, index)) {
          this.strings.push(this.current);
          this.current = '';
          index += this.quote.length - 1;
          this.quote = undefined;
          continue;
        }
        this.current += character;
        continue;
      }
      if (character === '#') {
        this.comment = true;
        continue;
      }
      if (character === '"' || character === "'") {
        const triple = character.repeat(3);
        this.quote = chunk.startsWith(triple, index) ? (triple as '"""' | "'''") : character;
        index += this.quote.length - 1;
        continue;
      }
      if (character === '[' || character === '{') this.depth += 1;
      else if (character === ']' || character === '}') this.depth -= 1;
      this.outside += character;
    }
  }

  complete(): boolean {
    return this.quote === undefined && this.depth <= 0;
  }

  code(): string {
    return this.outside;
  }

  value(): PytestOptionValue {
    const code = this.outside.trim();
    if (code.startsWith('[') && /^\[[\s,]*\]$/.test(code.replace(/[^\[\],\s]/g, ''))) {
      return { kind: 'list', items: this.strings };
    }
    if (code === '' && this.strings.length === 1) return { kind: 'text', text: this.strings[0] ?? '' };
    return { kind: 'unknown', text: this.strings.join(' ') };
  }
}

/**
 * True when a python_files pattern may match conftest.py: its last path part, matched as Python's
 * fnmatch does and case-insensitively (so it errs towards withholding).
 */
function pythonFilesPatternMayMatchConftest(pattern: string): boolean {
  const last = pattern.slice(Math.max(pattern.lastIndexOf('/'), pattern.lastIndexOf('\\')) + 1);
  return fnmatchWhole(last.toLowerCase(), 'conftest.py');
}

/**
 * True when a python_functions or python_classes pattern may reach a name that does not start with
 * test or Test, which the Python per-test reader does not read as a test. pytest takes a pattern as a
 * prefix, or as a glob where it holds a glob character, so its literal start decides.
 */
function pytestNamePatternReachesBeyondTest(pattern: string): boolean {
  const glob = pattern.search(/[*?[]/);
  const literal = glob === -1 ? pattern : pattern.slice(0, glob);
  return !literal.startsWith('test') && !literal.startsWith('Test');
}

/**
 * Python's fnmatch over a whole name: `*` any run, `?` one character, `[seq]` and `[!seq]` a set
 * (with ranges; an unclosed `[` is literal). Dynamic programming, linear in pattern times name.
 */
function fnmatchWhole(pattern: string, name: string): boolean {
  let reach = new Array<boolean>(name.length + 1).fill(false);
  reach[0] = true;
  let index = 0;
  while (index < pattern.length) {
    const character = pattern[index] ?? '';
    const next = new Array<boolean>(name.length + 1).fill(false);
    if (character === '*') {
      let any = false;
      for (let at = 0; at <= name.length; at += 1) {
        any ||= reach[at] === true;
        next[at] = any;
      }
      index += 1;
    } else {
      let test: (candidate: string) => boolean = (candidate) => candidate === character;
      let width = 1;
      if (character === '?') {
        test = () => true;
      } else if (character === '[') {
        let end = index + 1;
        if (pattern[end] === '!') end += 1;
        if (pattern[end] === ']') end += 1;
        while (end < pattern.length && pattern[end] !== ']') end += 1;
        if (end < pattern.length) {
          const negate = pattern[index + 1] === '!';
          const body = pattern.slice(index + (negate ? 2 : 1), end);
          test = (candidate) => {
            let inSet = false;
            for (let at = 0; at < body.length; at += 1) {
              const low = body[at] ?? '';
              if (body[at + 1] === '-' && at + 2 < body.length) {
                const high = body[at + 2] ?? '';
                if (candidate >= low && candidate <= high) inSet = true;
                at += 2;
              } else if (candidate === low) {
                inSet = true;
              }
            }
            return inSet !== negate;
          };
          width = end - index + 1;
        }
      }
      for (let at = 0; at < name.length; at += 1) {
        if (reach[at] && test(name[at] ?? '')) next[at + 1] = true;
      }
      index += width;
    }
    reach = next;
  }
  return reach[name.length] === true;
}

// ---- The pytest commands a repository runs (fix pass after the #626 review, items B and D) ----

/** A command read from shell text: its words, the directory it runs in (null: unknown) and PYTEST_ADDOPTS in force. */
type ShellCommandVisitor = (
  words: readonly string[],
  directory: string | null,
  addopts: readonly string[] | undefined,
  /** item A: why `directory` is unknown, where it is (a `cd` to a variable, an expression). */
  unknownDirectory?: string,
) => void;

/** Shell text with each heredoc's body removed: it is the command's input, not commands. */
function stripShellHeredocBodies(text: string): string {
  const lines = text.split('\n');
  const kept: string[] = [];
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index] ?? '';
    kept.push(line);
    const heredoc = /(?<!<)<<-?[ \t]*(['"]?)([A-Za-z_][\w-]*)\1/.exec(line);
    if (!heredoc) continue;
    const terminator = heredoc[2] ?? '';
    for (index += 1; index < lines.length && (lines[index] ?? '').trim() !== terminator; index += 1);
  }
  return kept.join('\n');
}

/**
 * Visits each command in shell text, tracking `cd`/`pushd` and `export PYTEST_ADDOPTS=...` across
 * the commands that follow, and a leading `PYTEST_ADDOPTS=...` for its own command. Comments,
 * heredoc bodies and quoted text are not commands. Linear in the text.
 */
function readShellCommands(
  text: string,
  directory: string | null,
  addopts: readonly string[] | undefined,
  visit: ShellCommandVisitor,
  unknownDirectory?: string,
  // goal_cejel_v27_a1_addopts_not_known_2026-11-05, item B (#673): where given, counts the
  // PYTEST_ADDOPTS assignments read as make's environment: an `export` word, and a leading
  // assignment or `env` prefix on a make command. Any other mention is not counted.
  // goal_cejel_v27_a1_addopts_review_fixes_698_2026-11-10, item A: `reachesOther` is set where a
  // command visited is not a make command the reader reads (a script, a launcher, pytest, anything
  // else; an echo or printf writing $GITHUB_ENV is the write itself, not a reader of it), and an
  // `export` counts only where no such command comes after it.
  mentions?: { read: number; reachesOther?: boolean },
): void {
  let current = directory;
  let why = directory === null ? unknownDirectory : undefined;
  let exported = addopts;
  let exports = 0;
  let exportReachesOther = false;
  const joined = stripShellHeredocBodies(text).replace(/\\\r?\n/g, ' ');
  for (const segment of splitShellCommandSegments(joined)) {
    const all = shellWords(segment.trim());
    // A subshell or group opener, and make's @, - or + prefix, are not part of the command's name.
    let start = 0;
    while (start < all.length && /^[({]+$/.test(all[start] ?? '')) start += 1;
    if (start >= all.length) continue;
    all[start] = (all[start] ?? '').replace(/^[({]+/, '').replace(/^[@+-]+(?=[A-Za-z./{$])/, '');
    let local = exported;
    let leading = 0;
    // Leading assignments, read by index: shifting each off would be quadratic in their number.
    while (start < all.length && /^[A-Za-z_]\w*=/.test(all[start] ?? '')) {
      const assignment = all[start] ?? '';
      if (assignment.startsWith(PYTEST_ADDOPTS_ASSIGNMENT)) {
        local = shellWords(assignment.slice(PYTEST_ADDOPTS_ASSIGNMENT.length));
        leading += 1;
      }
      start += 1;
    }
    const words = start === 0 ? all : all.slice(start);
    if (words.length === 0) {
      exported = local;
      continue;
    }
    const name = words[0] ?? '';
    if (name === 'export') {
      for (const word of words.slice(1)) {
        if (word.startsWith(PYTEST_ADDOPTS_ASSIGNMENT)) {
          exported = shellWords(word.slice(PYTEST_ADDOPTS_ASSIGNMENT.length));
          exports += 1;
        }
      }
      continue;
    }
    if (mentions !== undefined && (leading > 0 || name === 'env')) {
      const make = makeCommandOf(words);
      if (make !== undefined) mentions.read += leading + make.addoptsAssignments;
    }
    if (name === 'cd' || name === 'pushd') {
      const target = words[1];
      const before = current;
      current = current === null || target === undefined || target === '-' ? null : resolveCommandPath(current, target);
      if (current === null && before !== null) why = words.join(' ');
      continue;
    }
    if (name === 'popd') {
      if (current !== null) why = 'popd';
      current = null;
      continue;
    }
    if (mentions !== undefined && makeCommandOf(words) === undefined && !writesGithubEnvOnly(words)) {
      mentions.reachesOther = true;
      if (exports > 0) exportReachesOther = true;
    }
    visit(words, current, local, current === null ? why : undefined);
  }
  if (mentions !== undefined && !exportReachesOther) mentions.read += exports;
}

/**
 * goal_cejel_v27_a1_addopts_review_fixes_698_2026-11-10, item A: an `echo` or `printf` with a word
 * naming GITHUB_ENV (its redirection) and no command substitution: it writes the file and runs
 * nothing else. Linear in the words.
 */
function writesGithubEnvOnly(words: readonly string[]): boolean {
  const name = basename(words[0] ?? '');
  if (name !== 'echo' && name !== 'printf') return false;
  let names = false;
  for (const word of words) {
    if (word.includes('$(') || word.includes('`')) return false;
    if (word.includes('GITHUB_ENV')) names = true;
  }
  return names;
}

const PYTHON_INTERPRETER_PATTERN = /^(?:python(?:\d+(?:\.\d+)*)?|pypy\d*(?:\.\d+)?|py)(?:\.exe)?$/i;
// `{envpython}` (tox) or a make or shell variable naming a Python (`$(PYTHON)`, `${PY}`, `$PYTHON`).
const PYTHON_INTERPRETER_VARIABLE_PATTERN = /^(?:\{envpython\}|\$[({]?[A-Za-z_]*PY[A-Za-z_]*[)}]?)$/i;
// Runner options that take a value as the next word (uv run, pipx run, pdm run, hatch run).
const RUNNER_OPTIONS_WITH_VALUE = new Set([
  '--with', '--with-editable', '--with-requirements', '--python', '-p', '--extra', '--group', '--only-group',
  '--no-group', '--package', '--project', '--directory', '--env-file', '--index', '--default-index',
  '--index-url', '--extra-index-url', '--find-links', '-f', '--python-platform', '-w', '--spec', '--isolated-env',
]);

/**
 * pytest's words, when a command runs pytest: `pytest`/`py.test` (any path), `python -m pytest`,
 * `coverage run -m pytest`, or one of those through `uv run`, `poetry run`, `pdm run`,
 * `pipenv run`, `rye run`, `hatch run`, `pipx run`, `exec`, `time`, `command`, `nice` or `env`.
 * pytest named as another command's argument (`echo pytest`, `pip install pytest`) is not a run.
 * `directory` is set where the runner changes it (`uv run --directory`).
 */
function pytestCommandArguments(
  words: readonly string[],
  depth = 0,
): { args: readonly string[]; directory?: string; addopts?: readonly string[] } | undefined {
  if (depth > 4) return undefined;
  let index = 0;
  let addopts: readonly string[] | undefined;
  for (;;) {
    const word = words[index] ?? '';
    if (word === 'exec' || word === 'time' || word === 'command' || word === 'nice' || word === 'nohup') {
      index += 1;
      while ((words[index] ?? '').startsWith('-')) index += 1;
      continue;
    }
    if (word === 'env') {
      index += 1;
      while ((words[index] ?? '').startsWith('-') || /^[A-Za-z_]\w*=/.test(words[index] ?? '')) {
        const assignment = words[index] ?? '';
        if (assignment.startsWith(PYTEST_ADDOPTS_ASSIGNMENT)) addopts = shellWords(assignment.slice(PYTEST_ADDOPTS_ASSIGNMENT.length));
        index += 1;
      }
      continue;
    }
    break;
  }
  const head = words[index] ?? '';
  const name = basename(head.replace(/\\/g, '/'));
  const rest = words.slice(index + 1);
  const withAddopts = <T extends object>(found: T | undefined): (T & { addopts?: readonly string[] }) | undefined =>
    found === undefined ? undefined : addopts === undefined ? found : { addopts, ...found };
  if (PYTEST_EXECUTABLE_PATTERN.test(name)) return withAddopts({ args: rest });
  const moduleArgs = (after: readonly string[]): readonly string[] | undefined => {
    for (let at = 0; at < after.length; at += 1) {
      const option = after[at] ?? '';
      if (option === '-m' && after[at + 1] === 'pytest') return after.slice(at + 2);
      if (option === '-mpytest') return after.slice(at + 1);
      if (option === '-c' || !option.startsWith('-')) return undefined;
      if (option === '-X' || option === '-W') at += 1;
    }
    return undefined;
  };
  if (PYTHON_INTERPRETER_PATTERN.test(name) || PYTHON_INTERPRETER_VARIABLE_PATTERN.test(head)) {
    const args = moduleArgs(rest);
    return args === undefined ? undefined : withAddopts({ args });
  }
  if (name === 'coverage' && rest[0] === 'run') {
    for (let at = 1; at < rest.length; at += 1) {
      if (rest[at] === '-m') return rest[at + 1] === 'pytest' ? withAddopts({ args: rest.slice(at + 2) }) : undefined;
      if (!(rest[at] ?? '').startsWith('-')) return undefined;
      if (/^--(?:source|rcfile|omit|include|data-file|context|concurrency)$/.test(rest[at] ?? '')) at += 1;
    }
    return undefined;
  }
  const runner = ['uv', 'poetry', 'pdm', 'pipenv', 'rye', 'hatch', 'pipx'].includes(name) && rest[0] === 'run';
  if (!runner) return undefined;
  let at = 1;
  let directory: string | undefined;
  while ((rest[at] ?? '').startsWith('-')) {
    const option = rest[at] ?? '';
    if (option === '-m' || option === '--module') {
      return rest[at + 1] === 'pytest' ? withAddopts({ args: rest.slice(at + 2), ...(directory === undefined ? {} : { directory }) }) : undefined;
    }
    const equals = option.indexOf('=');
    const optionName = equals > 0 ? option.slice(0, equals) : option;
    const value = equals > 0 ? option.slice(equals + 1) : RUNNER_OPTIONS_WITH_VALUE.has(option) ? rest[at + 1] : undefined;
    if (optionName === '--directory') directory = value ?? '';
    at += equals > 0 || !RUNNER_OPTIONS_WITH_VALUE.has(option) ? 1 : 2;
  }
  const inner = pytestCommandArguments(rest.slice(at), depth + 1);
  if (inner === undefined) return undefined;
  return withAddopts({ ...inner, ...(directory === undefined ? {} : { directory }) });
}

/** The names a `make`, `gmake` or `just` command asks for, or [] for another command. */
function recipeTargetsNamed(words: readonly string[]): string[] {
  const name = basename(words[0] ?? '');
  if (name !== 'make' && name !== 'gmake' && name !== 'just' && !/^\$[({]MAKE[)}]$/.test(words[0] ?? '')) return [];
  const targets: string[] = [];
  for (let index = 1; index < words.length; index += 1) {
    const word = words[index] ?? '';
    if (/^-[Cf]$|^--(?:directory|file|makefile|justfile|working-directory)$/.test(word)) index += 1;
    else if (!word.startsWith('-') && !word.includes('=')) targets.push(word);
  }
  return targets;
}

/** The environments a `tox` command asks for with -e / --env, or []. */
function toxEnvironmentsNamed(command: readonly string[]): string[] {
  const words = asToxCommand(command);
  if (words === undefined) return [];
  const names: string[] = [];
  for (let index = 1; index < words.length; index += 1) {
    const word = words[index] ?? '';
    const value = word === '-e' || word === '--env' ? words[(index += 1)] : /^-e(.+)$/.exec(word)?.[1] ?? /^--env=(.+)$/.exec(word)?.[1];
    if (value !== undefined) names.push(...value.split(',').map((part) => part.trim()).filter((part) => part !== ''));
  }
  return names;
}

/** tox's envlist entries with `{a,b}` expanded, as names. */
function expandToxEnvironmentList(text: string): string[] {
  const entries: string[] = [];
  let depth = 0;
  let start = 0;
  for (let index = 0; index <= text.length; index += 1) {
    const character = text[index];
    if (character === '{') depth += 1;
    else if (character === '}') depth -= 1;
    else if (index === text.length || (depth === 0 && (character === ',' || character === '\n'))) {
      const entry = text.slice(start, index).trim();
      if (entry !== '') entries.push(entry);
      start = index + 1;
    }
  }
  const expand = (entry: string): string[] => {
    const open = entry.indexOf('{');
    const close = open === -1 ? -1 : entry.indexOf('}', open);
    if (open === -1 || close === -1) return [entry];
    return entry
      .slice(open + 1, close)
      .split(',')
      .flatMap((choice) => expand(`${entry.slice(0, open)}${choice.trim()}${entry.slice(close + 1)}`));
  };
  return entries.flatMap(expand);
}

/** The sections of an ini file: name to its keys, each value with continuation lines joined by '\n'. */
function readIniSections(text: string): Map<string, Map<string, string>> {
  const sections = new Map<string, Map<string, string>>();
  let current: Map<string, string> | undefined;
  let lastKey: string | undefined;
  for (const raw of text.split(/\r?\n/)) {
    const trimmed = raw.trim();
    if (trimmed === '' || trimmed.startsWith('#') || trimmed.startsWith(';')) continue;
    if (raw.startsWith('[')) {
      const close = raw.indexOf(']');
      const name = close === -1 ? '' : raw.slice(1, close).trim();
      current = sections.get(name) ?? new Map<string, string>();
      sections.set(name, current);
      lastKey = undefined;
      continue;
    }
    if (current === undefined) continue;
    if (/^[ \t]/.test(raw)) {
      if (lastKey !== undefined) current.set(lastKey, `${current.get(lastKey) ?? ''}\n${trimmed}`);
      continue;
    }
    const match = /^([^=:]+)[=:](.*)$/.exec(raw);
    lastKey = match ? (match[1] ?? '').trim() : undefined;
    if (match && lastKey !== undefined) current.set(lastKey, (match[2] ?? '').trim());
  }
  return sections;
}

interface YamlLine {
  readonly blank: boolean;
  readonly indent: number;
  readonly dash: boolean;
  /** The column the line's key (or, for a dash line, its item) starts at. */
  readonly keyColumn: number;
  readonly key?: string;
  readonly value: string;
}

/** A YAML file's lines with their structure: a block scalar's lines and comments are blank. Linear. */
function readYamlLines(text: string): YamlLine[] {
  const lines: YamlLine[] = [];
  let scalarAbove = -1;
  for (const line of text.split(/\r?\n/)) {
    const trimmed = line.trim();
    const indent = line.length - line.trimStart().length;
    if (scalarAbove >= 0) {
      if (trimmed === '' || indent > scalarAbove) {
        lines.push({ blank: true, indent, dash: false, keyColumn: indent, value: line });
        continue;
      }
      scalarAbove = -1;
    }
    if (trimmed === '' || trimmed.startsWith('#')) {
      lines.push({ blank: true, indent, dash: false, keyColumn: indent, value: '' });
      continue;
    }
    const dash = /^-(?:[ \t]+|$)/.exec(trimmed);
    const item = dash ? trimmed.slice(dash[0].length) : trimmed;
    const keyColumn = indent + (dash ? dash[0].length : 0);
    const key = yamlMappingKey(item);
    const value = key ? key.value : item;
    lines.push({
      blank: false,
      indent,
      dash: dash !== null,
      keyColumn,
      ...(key ? { key: key.key } : {}),
      value,
    });
    if (key && /^[|>][-+0-9]*(?:[ \t]+#.*)?$/.test(value)) scalarAbove = keyColumn;
  }
  return lines;
}

/**
 * A YAML block-mapping line's key and value: a quoted key, or a plain one up to the first `:`
 * followed by a blank or the line's end (a `#` first makes it no key). Linear in the line.
 */
function yamlMappingKey(item: string): { key: string; value: string } | undefined {
  let end: number;
  let key: string;
  const quote = item[0];
  if (quote === '"' || quote === "'") {
    const close = item.indexOf(quote, 1);
    if (close === -1) return undefined;
    key = item.slice(1, close);
    end = close + 1;
    while (item[end] === ' ' || item[end] === '\t') end += 1;
    if (item[end] !== ':') return undefined;
  } else {
    end = -1;
    for (let index = 0; index < item.length; index += 1) {
      const character = item[index];
      if (character === '#') return undefined;
      if (character === ':' && (index + 1 === item.length || item[index + 1] === ' ' || item[index + 1] === '\t')) {
        end = index;
        break;
      }
    }
    if (end <= 0) return undefined;
    key = item.slice(0, end).trim();
    if (key === '') return undefined;
  }
  return { key, value: item.slice(end + 1).trim() };
}

/** The index of a YAML or shell comment's `#` (one at the start or after a blank), or -1. Linear. */
function trailingCommentStart(value: string): number {
  for (let index = 0; index < value.length; index += 1) {
    if (value[index] === '#' && (index === 0 || value[index - 1] === ' ' || value[index - 1] === '\t')) return index;
  }
  return -1;
}

/** A plain or quoted YAML scalar's value, its trailing comment removed. Linear in the value. */
function yamlPlainScalar(value: string): string {
  const quote = value[0];
  if (quote === '"' || quote === "'") {
    const close = value.lastIndexOf(quote);
    if (close > 0) {
      const after = value.slice(close + 1);
      const comment = trailingCommentStart(after);
      if ((comment === -1 ? after : after.slice(0, comment)).trim() === '') return value.slice(1, close);
    }
  }
  const comment = trailingCommentStart(value);
  return (comment === -1 ? value : value.slice(0, comment)).trim();
}

/**
 * GitHub Actions `run:` steps, each with the directory it runs in (step working-directory, else
 * job, else workflow defaults.run.working-directory; null where it holds an expression) and the
 * PYTEST_ADDOPTS its env sets (step, else job, else workflow). A step or job whose `if:` is false
 * never runs and is left out. Linear in the file times its nesting.
 */
interface GithubRunStep {
  readonly command: string;
  readonly directory: string | null;
  readonly addopts?: readonly string[];
  /** The review of #648: the 0-based line of the `env:` entry that sets `addopts`, where one does. */
  readonly addoptsLine?: number;
  /** item E: the 0-based line of the step's `run:` key. */
  readonly line: number;
  /** item A: the working-directory expression that leaves `directory` unknown. */
  readonly unknownDirectory?: string;
  /**
   * goal_cejel_v27_a1_makefile_addopts_environment_2026-11-04, item A: the `PYTEST_ADDOPTS: <value>`
   * entry whose value is an expression, so whether it sets PYTEST_ADDOPTS, and to what, is not known.
   * goal_cejel_v27_a1_addopts_not_known_2026-11-05, item A (#669): read for a make command (the
   * environment make passes on to a recipe) and for a pytest run on the step; the value as written
   * (quotes kept), and `addoptsLine` is the entry's line.
   */
  readonly addoptsNotKnown?: string;
  /**
   * goal_cejel_v27_a1_addopts_not_known_2026-11-05, item B (#673): the 0-based lines of the
   * workflow-, job- and step-level `env:` entries for PYTEST_ADDOPTS read for this step.
   */
  readonly addoptsKeyLines: readonly number[];
  /** goal_cejel_v27_a1_addopts_review_fixes_698_2026-11-10, item A: the 0-based last line of the run's text. */
  readonly lastLine: number;
}

/**
 * Fix round on cejel #710 (re-review at 9ad037b1d, blocker 2), item A: a step that runs an action
 * (`uses:`), which the reader does not follow for the environment it passes on, and the 0-based lines
 * of the workflow-, job- and step-level `env:` entries for PYTEST_ADDOPTS that reach it.
 */
interface GithubUsesStep {
  readonly line: number;
  readonly addoptsKeyLines: readonly number[];
}

function readGithubRunSteps(text: string, usesSteps?: GithubUsesStep[]): GithubRunStep[] {
  const lines = readYamlLines(text);
  const raw = text.split(/\r?\n/);
  const steps: GithubRunStep[] = [];
  // One pass: each line's parent (the nearest non-blank line above it at a smaller key column) and
  // the dash line that opens the mapping its key sits in, each by a stack, so the per-step reads
  // below stay linear in the file however many steps or jobs it holds.
  const parent = new Array<number>(lines.length).fill(-1);
  const itemStart = new Array<number>(lines.length).fill(-1);
  const open: number[] = [];
  const items: { column: number; index: number }[] = [];
  lines.forEach((line, index) => {
    if (line.blank) return;
    while (open.length > 0 && (lines[open[open.length - 1] ?? 0]?.keyColumn ?? 0) >= line.keyColumn) open.pop();
    parent[index] = open[open.length - 1] ?? -1;
    open.push(index);
    while (items.length > 0 && (items[items.length - 1]?.column ?? 0) > line.keyColumn) items.pop();
    const top = items[items.length - 1];
    if (line.dash) {
      if (top?.column === line.keyColumn) items.pop();
      items.push({ column: line.keyColumn, index });
      itemStart[index] = index;
    } else if (top?.column === line.keyColumn) {
      itemStart[index] = top.index;
    }
  });
  const mappingKeys = (start: number, column: number): Map<string, number> => {
    const keys = new Map<string, number>();
    for (let index = start; index < lines.length; index += 1) {
      const line = lines[index];
      if (!line || line.blank) continue;
      if (index > start && (line.keyColumn < column || (line.dash && line.keyColumn <= column))) break;
      if (line.keyColumn === column && line.key !== undefined && (index === start || !line.dash)) keys.set(line.key, index);
    }
    return keys;
  };
  const childKeys = (keyIndex: number | undefined): Map<string, number> => {
    if (keyIndex === undefined) return new Map();
    const column = lines[keyIndex]?.keyColumn ?? 0;
    for (let index = keyIndex + 1; index < lines.length; index += 1) {
      const line = lines[index];
      if (!line || line.blank) continue;
      return line.keyColumn > column ? mappingKeys(index, line.keyColumn) : new Map();
    }
    return new Map();
  };
  const scalarAt = (index: number | undefined): string | undefined =>
    index === undefined ? undefined : yamlPlainScalar(lines[index]?.value ?? '');
  // Item A of goal_cejel_v27_a1_addopts_not_known_2026-11-05: a value as written, its quotes kept
  // and its trailing comment removed, so a clause naming it matches the line it is on.
  const writtenAt = (index: number): string => {
    const value = lines[index]?.value ?? '';
    const scalar = yamlPlainScalar(value);
    const quote = value[0];
    const close = quote === '"' || quote === "'" ? value.lastIndexOf(quote) : -1;
    return close > 0 && value.slice(1, close) === scalar ? value.slice(0, close + 1) : scalar;
  };
  const isFalse = (value: string | undefined) => value !== undefined && /^(?:false|\$\{\{\s*false\s*\}\})$/.test(value);
  const defaultDirectory = (keys: Map<string, number>) => scalarAt(childKeys(childKeys(keys.get('defaults')).get('run')).get('working-directory'));
  const addoptsLineIn = (keys: Map<string, number>) => childKeys(keys.get('env')).get('PYTEST_ADDOPTS');
  const addoptsIn = (keys: Map<string, number>) => scalarAt(addoptsLineIn(keys));
  interface MappingFacts {
    readonly never: boolean;
    readonly directory?: string;
    readonly addopts?: string;
    readonly addoptsLine?: number;
  }
  const factsOf = (keys: Map<string, number>): MappingFacts => {
    const directory = defaultDirectory(keys);
    const addopts = addoptsIn(keys);
    const addoptsLine = addoptsLineIn(keys);
    return {
      never: isFalse(scalarAt(keys.get('if'))),
      ...(directory === undefined ? {} : { directory }),
      ...(addopts === undefined ? {} : { addopts }),
      ...(addoptsLine === undefined ? {} : { addoptsLine }),
    };
  };
  const firstRootLine = lines.findIndex((line) => !line.blank);
  const root = factsOf(firstRootLine === -1 ? new Map() : mappingKeys(firstRootLine, lines[firstRootLine]?.keyColumn ?? 0));
  const jobs = new Map<number, MappingFacts>();
  const stepKeysAt = new Map<number, Map<string, number>>();
  const jobFacts = (header: number, column: number): MappingFacts => {
    let facts = jobs.get(header);
    if (facts === undefined) {
      let start = header + 1;
      while (start < lines.length && lines[start]?.blank) start += 1;
      facts = start < lines.length ? factsOf(mappingKeys(start, column)) : { never: false };
      jobs.set(header, facts);
    }
    return facts;
  };
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    if (!line || line.blank || (line.key !== 'run' && line.key !== 'uses') || line.value === '') continue;
    const column = line.keyColumn;
    // The step's first key is the dash line at this column; its other keys sit at the column too.
    const stepStart = itemStart[index] ?? -1;
    if (stepStart === -1) continue;
    // Fix round on #710, item A: a step's keys are read once, however many run: or uses: keys it
    // holds, so a step of N such keys costs its lines once, not N times.
    let stepKeys = stepKeysAt.get(stepStart);
    if (stepKeys === undefined) {
      stepKeys = mappingKeys(stepStart, column);
      stepKeysAt.set(stepStart, stepKeys);
    }
    const list = parent[stepStart] ?? -1;
    const jobHeader = list === -1 ? -1 : (parent[list] ?? -1);
    const job = jobHeader === -1 ? { never: false } : jobFacts(jobHeader, lines[list]?.keyColumn ?? 0);
    if (isFalse(scalarAt(stepKeys.get('if'))) || job.never) continue;
    // Fix round on #710, item A: a `uses:` step is recorded with the env: entries that reach it, and
    // is not a run step. (A step holding both keys is read as its run.)
    if (line.key === 'uses') {
      if (!stepKeys.has('run')) {
        usesSteps?.push({
          line: index,
          addoptsKeyLines: [root.addoptsLine, job.addoptsLine, addoptsLineIn(stepKeys)].filter((at): at is number => at !== undefined),
        });
      }
      continue;
    }
    const directoryValue = scalarAt(stepKeys.get('working-directory')) ?? job.directory ?? root.directory;
    const directory = directoryValue === undefined ? '' : directoryValue.includes('${{') ? null : resolveCommandPath('', directoryValue);
    const stepAddopts = addoptsIn(stepKeys);
    const addoptsValue = stepAddopts ?? job.addopts ?? root.addopts;
    const addoptsLine = stepAddopts !== undefined ? addoptsLineIn(stepKeys) : job.addopts !== undefined ? job.addoptsLine : root.addoptsLine;
    let command: string;
    let lastLine = index;
    if (/^[|>]/.test(line.value)) {
      const block: string[] = [];
      for (let next = index + 1; next < raw.length; next += 1) {
        const text = raw[next] ?? '';
        if (text.trim() !== '' && text.length - text.trimStart().length <= column) break;
        block.push(text);
      }
      lastLine = index + block.length;
      let indent = Number.POSITIVE_INFINITY;
      for (const text of block) if (text.trim() !== '') indent = Math.min(indent, text.length - text.trimStart().length);
      const dedented = block.map((text) => text.slice(Number.isFinite(indent) ? indent : 0));
      command = dedented.join(line.value.startsWith('>') ? ' ' : '\n');
    } else {
      command = yamlPlainScalar(line.value);
    }
    // The most specific level that sets PYTEST_ADDOPTS decides, so a literal on the step is read
    // over an expression on its job or workflow, and an expression on the step over a literal above.
    const expression = addoptsValue !== undefined && addoptsValue.includes('${{');
    const stepAddoptsLine = addoptsLineIn(stepKeys);
    steps.push({
      command,
      directory,
      line: index,
      lastLine,
      addoptsKeyLines: [root.addoptsLine, job.addoptsLine, stepAddoptsLine].filter((at): at is number => at !== undefined),
      ...(directory === null && directoryValue !== undefined ? { unknownDirectory: `working-directory: ${directoryValue}` } : {}),
      ...(addoptsValue === undefined || expression ? {} : { addopts: shellWords(addoptsValue) }),
      ...(addoptsValue === undefined || addoptsLine === undefined ? {} : { addoptsLine }),
      ...(expression ? { addoptsNotKnown: `PYTEST_ADDOPTS: ${addoptsLine === undefined ? addoptsValue : writtenAt(addoptsLine)}` } : {}),
    });
  }
  return steps;
}

/**
 * Every pytest command Cejel reads (see the section comment), the plain `pytest` at the root
 * first. `readText` reads a repository file, or undefined. Exported for the scaling check in
 * scan-path-regex-bounds.test.ts (goal_cejel_v27_conftest_timing_guard_2026-11-02, item C).
 */
export function readPytestInvocations(
  repoFiles: readonly string[],
  readText: (file: string) => string | undefined,
): PytestInvocation[] {
  const invocations: PytestInvocation[] = [{ directory: '', args: [] }];
  const namedTargets = new Set<string>();
  const namedToxEnvironments = new Set<string>();
  // item A: make variables a make command sets (`make test PYTEST_ARGS=-x`), whose Makefile value is then not the one used.
  const makeOverrides = new Set<string>();
  // item A: the words each tox command passes after `--`, which tox puts where {posargs} is.
  const toxPosargs: { words: readonly string[]; text: string; source: string; file: string; anchor: number }[] = [];
  const noxPosargs: PassedPosargs[] = [];
  // The review of #655, blocker 1: each nox command whose posargs the reader cannot see.
  const noxUnread: NoxCommandNotRead[] = [];
  const fileSet = new Set(repoFiles);
  let hatchScripts: HatchScripts | undefined;
  // The review of #648: the hatch script expansions left, across the whole read, so a script list
  // that names itself many times cannot make the work grow past linear; past it the run is not read.
  let hatchExpansionsLeft = HATCH_EXPANSION_BUDGET;
  // The review of #648: the text of every CI file read, where a CI command may set a variable in the
  // environment of the make or tox it runs (a `?=` default, TOXENV).
  const environmentTexts: string[] = [];
  // goal_cejel_v27_a1_addopts_not_known_2026-11-05, item B (#673): true where a CI file names
  // PYTEST_ADDOPTS somewhere the readers below do not read as an environment (a script a step runs
  // with it set, a comment, an expression), so a Makefile's `?=` default of it is not known.
  // goal_cejel_v27_a1_addopts_review_fixes_698_2026-11-10, item A: the first such mention, as
  // written (its line, trimmed) and where: the reason and the pointer of the runs it leaves not read.
  let addoptsMentionNotRead: { readonly text: string; readonly source: string; readonly file: string; readonly line: number } | undefined;
  // Item B: whether every whole-word PYTEST_ADDOPTS in `text` is one of the `read` mentions. Review
  // of #698, item A: where not, the mention is the first line naming PYTEST_ADDOPTS outside
  // `readLines` (the entries read, and the steps whose every mention is read).
  const noteAddoptsMentions = (text: string, read: number, readLines: ReadonlySet<number>, file: string): void => {
    if (addoptsMentionNotRead !== undefined || wordCount(text, 'PYTEST_ADDOPTS') === read) return;
    const lines = text.split(/\r?\n/);
    let at = lines.findIndex((line, index) => !readLines.has(index) && containsWord(line, 'PYTEST_ADDOPTS'));
    if (at === -1) at = lines.findIndex((line) => containsWord(line, 'PYTEST_ADDOPTS'));
    addoptsMentionNotRead = { text: (lines[at] ?? '').trim(), source: a1NotePath(file), file, line: Math.max(at, 0) };
  };
  // goal_cejel_v27_a1_makefile_addopts_environment_2026-11-04, item A: each CI make command run with
  // PYTEST_ADDOPTS in its environment, or with one Cejel cannot read. Recorded while CI is read only.
  const makeEnvironments: MakeEnvironment[] = [];
  let readingCi = true;
  const visitor = (
    source: string,
    file: string,
    anchor: number,
    depth = 0,
    // The review of #648: where an `env:` mapping set the PYTEST_ADDOPTS words `envAddopts` (0-based line).
    envAddopts?: { readonly words: readonly string[]; readonly line: number },
    // Item A: why PYTEST_ADDOPTS in this command's environment is not known (an expression, a
    // `$GITHUB_ENV` write), where it is not, and where that is written (goal_cejel_v27_a1_addopts_not_known_2026-11-05, item A).
    envNotKnown?: { readonly reason: string; readonly source: string; readonly file: string; readonly line: number },
    // Item A: the CI environment's PYTEST_ADDOPTS words a recipe's pytest runs with, and where they are set.
    addoptsAt?: { readonly words: readonly string[]; readonly source: string; readonly file: string; readonly line: number },
  ): ShellCommandVisitor => (words, directory, addopts, unknownDirectory) => {
    for (const target of recipeTargetsNamed(words)) namedTargets.add(target);
    const makeRun = readingCi ? makeCommandOf(words) : undefined;
    if (makeRun !== undefined) {
      const inForce = makeRun.addopts ?? addopts;
      // A word make or the shell would expand (`$VAR`, `$(X)`, a backtick) is not a value Cejel knows.
      const notKnown = envNotKnown?.reason ?? (inForce?.some((word) => /[$`]/.test(word)) ? `PYTEST_ADDOPTS=${inForce.join(' ')}` : undefined);
      if (inForce !== undefined || notKnown !== undefined) {
        // A Makefile named with -f may be in any directory: read as one in no known directory.
        let runIn = makeRun.namesFile ? null : directory;
        for (const step of makeRun.directories) runIn = runIn === null ? null : resolveCommandPath(runIn, step);
        makeEnvironments.push({
          directory: runIn,
          targets: makeRun.targets,
          overrides: makeRun.overrides,
          ...(notKnown !== undefined ? { notKnown } : inForce !== undefined ? { addopts: inForce } : {}),
          at: { source, file, line: envAddopts !== undefined && inForce === envAddopts.words ? envAddopts.line : anchor },
        });
      }
    }
    for (const name of makeAssignmentsNamed(words)) makeOverrides.add(name);
    for (const environment of toxEnvironmentsNamed(words)) namedToxEnvironments.add(environment);
    const posargs = toxPosargsOf(words);
    if (posargs !== undefined) toxPosargs.push({ words: posargs, text: words.join(' '), source, file, anchor });
    // goal_cejel_v27_a1_gaps_2026-11-03, item B: the words a nox command passes after `--`.
    const noxPassed = posargsOf(words, 'nox');
    if (noxPassed !== undefined) noxPosargs.push({ words: noxPassed, text: words.join(' '), source, file, anchor });
    // The review of #655, blocker 1: a nox command the reader does not read (through poetry, env,
    // hatch, pdm, `uv run --with`, uvx with options) may pass any posargs.
    else if (asPythonToolCommand(words, 'nox') === undefined && runsNoxUnread(words)) noxUnread.push({ text: words.join(' '), source, file, anchor });
    // cejel #642: the command as written is joined only where an invocation records it. Joining
    // every segment (a CI line of hundreds of thousands of words) made the run reader's garbage
    // grow faster than its input.
    let joined: string | undefined;
    const textOf = (): string => (joined ??= words.join(' '));
    const unread = (reason: string) => invocations.push({ source, file, anchor, directory: '', args: [], text: textOf(), unread: reason });
    // item A: `hatch run [env:]script`, resolved through the hatch scripts in hatch.toml or pyproject.toml.
    // The review of #648: `hatch test` runs pytest with arguments hatch adds from its own
    // configuration, which Cejel does not read.
    if (basename(words[0] ?? '') === 'hatch' && words[1] === 'test') {
      unread(textOf());
      return;
    }
    const hatch = hatchRunOf(words);
    if (hatch !== undefined && depth < 4) {
      hatchScripts ??= readHatchScripts(fileSet, readText);
      const own = hatchScripts.get(hatch.environment)?.get(hatch.name);
      // The review of #648: an environment inherits the scripts of its template (`default` unless
      // it says otherwise), so a script found only there is the template's where no template is
      // named, and not read where one may be.
      const inherited = own === undefined && hatch.environment !== 'default' ? hatchScripts.get('default')?.get(hatch.name) : undefined;
      if (inherited !== undefined && hatchNamesTemplate(fileSet, readText)) {
        unread(textOf());
        return;
      }
      const script = own ?? inherited;
      if (script !== undefined) {
        hatchExpansionsLeft -= script.commands?.length ?? 1;
        if (script.commands === undefined || hatchExpansionsLeft < 0) {
          unread(textOf());
          return;
        }
        for (const command of script.commands) {
          const substituted = substituteHatchArguments(command, hatch.args);
          // A script's command may name another script of the environment.
          const first = substituted.trim().split(/\s+/)[0] ?? '';
          const inner = hatchScripts.get(hatch.environment)?.has(first)
            ? `hatch run ${hatch.environment}:${substituted.trim()}`
            : substituted;
          // Item A of goal_cejel_v27_a1_addopts_not_known_2026-11-05: the step's environment, known or
          // not, is the script's.
          readShellCommands(inner, directory === null ? null : repoDirectory(script.file), addopts, visitor(a1NotePath(script.file), script.file, script.line, depth + 1, undefined, envNotKnown), unknownDirectory);
        }
        return;
      }
    }
    const found = pytestCommandArguments(hatch !== undefined && hatch.explicitEnvironment ? ['hatch', 'run', hatch.name, ...hatch.args] : words);
    if (found === undefined) {
      // item A: a make or shell variable naming pytest that nothing defines is a run whose words are unknown.
      if (isUnexpandedPytestVariable(words[0] ?? '')) unread(textOf());
      return;
    }
    if (directory === null) {
      unread(unknownDirectory ?? textOf());
      return;
    }
    const runIn = found.directory === undefined ? directory : resolveCommandPath(directory, found.directory);
    if (runIn === null) {
      unread(textOf());
      return;
    }
    const inForce = found.addopts ?? addopts;
    // Item A of goal_cejel_v27_a1_addopts_not_known_2026-11-05 (#669): a step, job or workflow env:
    // that sets PYTEST_ADDOPTS by an expression, which nothing in the command replaces, leaves the
    // run not read, named with the entry and pointed at its line. (A `$GITHUB_ENV` write leaves the
    // directory unknown, so its runs were named above.)
    if (inForce === undefined && envNotKnown !== undefined) {
      invocations.push({ source: envNotKnown.source, file: envNotKnown.file, anchor: envNotKnown.line, directory: '', args: [], text: textOf(), unread: envNotKnown.reason });
      return;
    }
    const addoptsAnchor =inForce !== undefined && envAddopts !== undefined && inForce === envAddopts.words ? envAddopts.line : undefined;
    const elsewhere = inForce !== undefined && addoptsAt !== undefined && inForce === addoptsAt.words ? addoptsAt : undefined;
    invocations.push({
      source,
      file,
      anchor,
      text: textOf(),
      directory: runIn,
      args: found.args,
      ...(inForce === undefined ? {} : { addopts: inForce }),
      ...(addoptsAnchor === undefined ? {} : { addoptsAnchor }),
      ...(elsewhere === undefined ? {} : { addoptsAt: { source: elsewhere.source, file: elsewhere.file, line: elsewhere.line } }),
    });
  };
  const usable = repoFiles.filter((file) => !GENERATED_OR_VENDOR_PATH_PATTERN.test(file));
  // CI first: it names the make targets and tox environments that run.
  const readActions = new Set<string>();
  const readGithubFile = (file: string, text: string): void => {
    const source = a1NotePath(file);
    environmentTexts.push(text);
    // The review of #648 (the narrow rule for steps Cejel does not read): a step that writes
    // PYTEST_ADDOPTS to $GITHUB_ENV sets it for the later steps of its job, and a checkout into a
    // `path:` moves the repository under the workspace, so a pytest run in such a file is not read.
    // The first is tested by name (a file naming both), not by reading the write.
    const remote = readGithubRemoteSteps(text);
    const writesAddopts = text.includes('GITHUB_ENV') && text.includes('PYTEST_ADDOPTS') ? 'PYTEST_ADDOPTS written to $GITHUB_ENV' : undefined;
    const unreadWhy = writesAddopts ?? remote.checkoutPath;
    // goal_cejel_v27_a1_addopts_not_known_2026-11-05, item B (#673): the mentions of PYTEST_ADDOPTS
    // read as an environment: each `env:` entry read for a run step, once; in a file the
    // `$GITHUB_ENV` rule covers, every mention on a line naming GITHUB_ENV (the rule is by name, so
    // the shell forms are not counted there); elsewhere an `export` and a leading assignment or
    // `env` prefix on a make command.
    // goal_cejel_v27_a1_addopts_review_fixes_698_2026-11-10, item A (blocker 1 of the review of
    // #698): an `env:` entry counts as read only where every step it applies to runs nothing but CI
    // make commands the reader reads, and a `$GITHUB_ENV` write only where every run step of the
    // file does (the rule is by name, so by file). Elsewhere it reaches a script, a launcher or
    // anything else the reader does not follow, which may run make with it: a mention not read.
    const keyLines = new Set<number>();
    const keysReachingOther = new Set<number>();
    const readLines = new Set<number>();
    let fileReachesOther = false;
    let shellRead = 0;
    const mentioned = text.includes('PYTEST_ADDOPTS');
    const usesSteps: GithubUsesStep[] = [];
    for (const step of readGithubRunSteps(text, usesSteps)) {
      for (const at of step.addoptsKeyLines) keyLines.add(at);
      const shellMentions = mentioned ? { read: 0, reachesOther: false } : undefined;
      const envAddopts = step.addopts !== undefined && step.addoptsLine !== undefined ? { words: step.addopts, line: step.addoptsLine } : undefined;
      // Item A: a make command's environment is not known where the file may write PYTEST_ADDOPTS
      // to $GITHUB_ENV (the rule by name) or an `env:` entry sets it by an expression.
      // goal_cejel_v27_a1_addopts_not_known_2026-11-05, item A: and a pytest run on the step, whose
      // clause points at the expression's entry.
      const notKnownReason = writesAddopts ?? step.addoptsNotKnown;
      const envNotKnown =
        notKnownReason === undefined
          ? undefined
          : { reason: notKnownReason, source, file, line: writesAddopts === undefined && step.addoptsLine !== undefined ? step.addoptsLine : step.line };
      if (unreadWhy !== undefined) readShellCommands(step.command, null, step.addopts, visitor(source, file, step.line, 0, envAddopts, envNotKnown), unreadWhy, shellMentions);
      else readShellCommands(step.command, step.directory, step.addopts, visitor(source, file, step.line, 0, envAddopts, envNotKnown), step.unknownDirectory, shellMentions);
      if (shellMentions === undefined) continue;
      if (shellMentions.reachesOther) {
        fileReachesOther = true;
        for (const at of step.addoptsKeyLines) keysReachingOther.add(at);
      }
      // In a file the $GITHUB_ENV rule covers, the shell forms are not counted (the rule is by name).
      if (writesAddopts !== undefined) continue;
      shellRead += shellMentions.read;
      if (!shellMentions.reachesOther && wordCount(step.command, 'PYTEST_ADDOPTS') === shellMentions.read) {
        for (let at = step.line; at <= step.lastLine; at += 1) readLines.add(at);
      }
    }
    if (mentioned) {
      // Fix round on #710 (blocker 2 of the re-review at 9ad037b1d; operator ruling of 10 Nov), item
      // A: a `uses:` step is one the reader does not follow for the environment (a local composite
      // action may run a script that runs make), so an `env:` entry that reaches one, and a
      // `$GITHUB_ENV` write in a file that holds one (the rule is by file), is a mention not read.
      for (const step of usesSteps) {
        fileReachesOther = true;
        for (const at of step.addoptsKeyLines) keysReachingOther.add(at);
      }
      for (const at of keyLines) if (!keysReachingOther.has(at)) readLines.add(at);
      let read = shellRead;
      for (const at of keyLines) if (!keysReachingOther.has(at)) read += 1;
      if (writesAddopts !== undefined && !fileReachesOther) {
        text.split(/\r?\n/).forEach((line, index) => {
          if (keyLines.has(index) || !line.includes('GITHUB_ENV')) return;
          read += wordCount(line, 'PYTEST_ADDOPTS');
          readLines.add(index);
        });
      }
      noteAddoptsMentions(text, read, readLines, file);
    }
    // The review of #648: a step action whose inputs run pytest (a retry or display wrapper) runs
    // it with arguments Cejel does not read.
    for (const step of remote.pytestInputs) {
      invocations.push({ source, file, anchor: step.line, directory: '', args: [], text: step.uses, unread: step.uses });
    }
    // item A: a local composite action's steps are read; a reusable workflow in another repository is not read.
    text.split(/\r?\n/).forEach((line, index) => {
      const match = GITHUB_USES_LINE_PATTERN.exec(line);
      if (!match) return;
      const value = yamlPlainScalar(match[1] ?? '');
      if (value.startsWith('./')) {
        const directory = resolveCommandPath('', value.slice(2));
        if (directory === null || /\.ya?ml$/.test(directory)) return;
        const action = [`${directory}/action.yml`, `${directory}/action.yaml`].find((candidate) => fileSet.has(candidate));
        if (action === undefined || readActions.has(action)) return;
        readActions.add(action);
        const actionText = readText(action);
        if (actionText !== undefined) readGithubFile(action, actionText);
        return;
      }
      if (value.includes('/.github/workflows/')) {
        invocations.push({ source, file, anchor: index, directory: '', args: [], text: value, unread: value });
      }
    });
  };
  for (const file of usable.filter(isCiWorkflow)) {
    const text = readText(file);
    if (text === undefined) continue;
    const source = a1NotePath(file);
    if (/^\.github\/workflows\//.test(file)) {
      readGithubFile(file, text);
      continue;
    }
    environmentTexts.push(text);
    // item A: Jenkins' dir('...') { } changes the directory in a way Cejel does not follow, so a
    // pytest run in a Jenkinsfile that holds one is not read.
    const jenkinsDir = file === 'Jenkinsfile' ? jenkinsDirCall(text) : undefined;
    const addopts = readCiAddopts(text);
    // Item B of goal_cejel_v27_a1_addopts_not_known_2026-11-05 (#673): the variables or env key
    // readCiAddopts reads (its first line, where that line is a key, not a shell assignment), and
    // the shell forms make's environment is read from.
    const shellMentions = text.includes('PYTEST_ADDOPTS') ? { read: 0, reachesOther: false } : undefined;
    for (const command of ciShellTexts(text)) {
      readShellCommands(command, jenkinsDir === undefined ? '' : null, addopts, visitor(source, file, 0), jenkinsDir, shellMentions);
    }
    if (shellMentions !== undefined) {
      // goal_cejel_v27_a1_addopts_review_fixes_698_2026-11-10, item A: the key applies to every
      // command of the file, so it counts as read only where each is a make command the reader reads.
      const lines = text.split(/\r?\n/);
      const keyAt = lines.findIndex((line) => PYTEST_ADDOPTS_LINE_PATTERN.test(line));
      const keyRead = keyAt !== -1 && PYTEST_ADDOPTS_KEY_PATTERN.test(lines[keyAt] ?? '') && !shellMentions.reachesOther;
      noteAddoptsMentions(text, shellMentions.read + (keyRead ? 1 : 0), new Set(keyRead ? [keyAt] : []), file);
    }
  }
  // item A: a noxfile's session.run calls (nox runs every session it is not told to skip). Item B
  // of goal_cejel_v27_a1_gaps_2026-11-03: `*session.posargs` holds the words after `--` of a CI or
  // recipe nox command, so the noxfiles are read after the recipes, and their runs keep this place
  // in the list.
  const noxAt = invocations.length;
  const readNoxfiles = (): PytestInvocation[] => {
    const noxRuns: PytestInvocation[] = [];
    const partitioned = partitionPosargs(noxPosargs);
    const { literal } = partitioned;
    // The review of #655, blocker 1: "no posargs" is known only where every nox invocation in the
    // repository is one the reader reads. A nox command it does not read, in a file whose commands it
    // reads or in any other file that can run one (a script, a configuration), is named like posargs
    // it cannot read. Searched only where a call takes posargs.
    let hidden: readonly NoxCommandNotRead[] | undefined;
    const unreadPosargs = (): readonly NoxCommandNotRead[] =>
      (hidden ??= [...partitioned.unread, ...noxUnread, ...noxCommandsInUnreadFiles(repoFiles, readText, readActions)]);
    // A nox command with no `--` passes none, as does nox run by hand; the empty set is always read.
    const passedSets: readonly (readonly string[])[] = [[], ...literal.map((entry) => entry.words)];
    // Each call taking posargs is read once per set, so the work is the noxfile's calls times the
    // sets' words: a product of two inputs. A shared budget bounds it; past it the call is not read.
    const callCost = passedSets.reduce((sum, words) => sum + 1 + words.length, 0);
    let noxLeft = POSARGS_BUDGET;
    // The review of #655, blocker 2: the posargs Cejel cannot read are said once per read, not once
    // per noxfile (M noxfiles and U such entries made M x U runs), and each counts against the budget.
    let unreadSaid = false;
    for (const file of usable.filter((candidate) => basename(candidate) === 'noxfile.py')) {
      const text = readText(file);
      if (text === undefined) continue;
      const source = a1NotePath(file);
      const chdir = /\bsession\.(?:chdir|cd)[ \t]*\(/.exec(text);
      for (const call of readNoxRunCalls(text)) {
        const unread = (reason: string) => noxRuns.push({ source, file, anchor: call.line, directory: '', args: [], text: call.text, unread: reason });
        if (call.unknown) {
          const literalWords = call.words.filter((word) => word !== NOX_POSARGS_WORD);
          if (/pytest/.test(call.text) || (literalWords.length > 0 && pytestCommandArguments(literalWords) !== undefined)) unread(call.text);
          continue;
        }
        const takesPosargs = call.words.includes(NOX_POSARGS_WORD);
        if (takesPosargs) {
          noxLeft -= callCost;
          if (noxLeft < 0) {
            unread(call.text);
            continue;
          }
        }
        // Each posargs set read in place of `*session.posargs`; the posargs may name pytest themselves.
        const runs = (takesPosargs ? passedSets : [[]]).flatMap((passed) => {
          const words = call.words.flatMap((word) => (word === NOX_POSARGS_WORD ? passed : [word]));
          const run = words.length === 0 ? undefined : pytestCommandArguments(words);
          return run === undefined ? [] : [run];
        });
        if (runs.length > 0 && chdir) {
          unread(chdir[0].slice(0, chdir[0].indexOf('(')).trimEnd());
          continue;
        }
        for (const run of runs) noxRuns.push({ source, file, anchor: call.line, text: call.text, directory: repoDirectory(file), args: run.args });
        // Posargs Cejel cannot read, or past the 16th set, leave the run not read, named once per
        // read, where the call runs pytest or its command comes from the posargs.
        if (takesPosargs && !unreadSaid && (runs.length > 0 || call.words[0] === NOX_POSARGS_WORD)) {
          unreadSaid = true;
          for (const entry of unreadPosargs()) {
            noxLeft -= 1;
            noxRuns.push({ source: entry.source, file: entry.file, anchor: entry.anchor, directory: '', args: [], text: entry.text, unread: entry.text });
          }
        }
      }
    }
    return noxRuns;
  };
  // goal_cejel_v27_a1_makefile_addopts_environment_2026-11-04, item A: CI has been read; a make
  // command in a recipe or a tox environment adds no environment.
  readingCi = false;
  const environments = distinctMakeEnvironments(makeEnvironments);
  for (const file of usable.filter(isRecipeFile)) {
    const text = readText(file);
    if (text === undefined) continue;
    const just = /[Jj]ustfile$/.test(file);
    const targets = just ? readJustRecipes(text) : readRecipeTargets(text);
    const headers = just ? new Map([...readJustRecipes(text)].map(([name, recipe]) => [name, recipe.line])) : makeTargetLines(text);
    // item A: make variables defined in the same Makefile (and just's own assignments) are expanded.
    // The review of #648: as make reads them, or not known (readMakeVariables); a `?=` default is
    // not known where a CI file names the variable, since a CI command may set it. Item A of
    // goal_cejel_v27_a1_makefile_addopts_environment_2026-11-04: not PYTEST_ADDOPTS, whose value in
    // the environment of each CI make command is read below.
    // Item B of goal_cejel_v27_a1_addopts_not_known_2026-11-05 (#673): PYTEST_ADDOPTS too, where a
    // CI file names it somewhere those readers do not read. That leaves a `?=` default not known here;
    // an unexported `=`, `:=`, `::=` or `+=` is read below (goal_cejel_v27_a1_addopts_assignment_not_known_2026-11-10, item A).
    const setByEnvironment = (name: string) =>
      name === 'PYTEST_ADDOPTS' ? addoptsMentionNotRead !== undefined : environmentTexts.some((ciText) => containsWord(ciText, name));
    const justVariables = just ? readJustVariables(text) : undefined;
    const make = just ? undefined : readMakeVariables(text, setByEnvironment);
    const budget = { left: MAKE_EXPANSION_BUDGET };
    const unknownIn = (variables: MakeVariables | undefined) => (name: string) => variables?.unknown.has(name) === true || makeOverrides.has(name);
    const isUnknown = unknownIn(make);
    const expandWith =
      (variables: MakeVariables | undefined) =>
      (command: string): { readonly text: string; readonly unknown: boolean } =>
        justVariables !== undefined
          ? { text: expandJustVariables(command, justVariables), unknown: false }
          : expandMakeVariables(command, variables?.values ?? new Map(), unknownIn(variables), budget);
    const expand = expandWith(make);
    // Item D: make passes PYTEST_ADDOPTS to a recipe only where the Makefile exports it. The review
    // of #648: a just file's `set export` exports every assignment.
    let addoptsUnknown = false;
    let addoptsText: string | undefined;
    // goal_cejel_v27_a1_addopts_assignment_not_known_2026-11-10, item A (#674): what leaves an
    // unexported PYTEST_ADDOPTS not known, named as the reason and pointed at. The review of #698,
    // item A: the first CI mention not read, not the assignment.
    let addoptsNotKnownAt: { readonly text: string; readonly source: string; readonly file: string; readonly line: number } | undefined;
    if (justVariables !== undefined) {
      const exportsAll = /^set[ \t]+export(?:[ \t]*:=[ \t]*true)?[ \t]*$/m.test(text);
      const assigned = /^(?:export[ \t]+)?PYTEST_ADDOPTS[ \t]*:=/m.test(text);
      const exported = /^export[ \t]+PYTEST_ADDOPTS[ \t]*:=/m.test(text) || (exportsAll && assigned);
      if (exported) {
        addoptsText = justVariables.get('PYTEST_ADDOPTS');
        addoptsUnknown = addoptsText === undefined;
      }
    } else {
      // goal_cejel_v27_a1_addopts_review_fixes_698_2026-11-10, item B: led by spaces or by nothing; a
      // tab-led line is a recipe line, as readMakeVariables reads it.
      const exported = /^ *(?:export[ \t]*|\.EXPORT_ALL_VARIABLES[ \t]*:.*|(?:override[ \t]+)?export[ \t]+PYTEST_ADDOPTS\b.*)$/m.test(text);
      // Item A (#674; the operator's ruling of 10 Nov reverses the 5 Nov text for this case): GNU make
      // passes an unexported variable to a recipe only where it is already in make's environment, and
      // then with the Makefile's value. Where a CI file names PYTEST_ADDOPTS somewhere the readers do
      // not read, that environment is not known, so neither is the value the recipe sees. Where every
      // mention is read, each CI make command's environment is read below, as before.
      // goal_cejel_v27_a1_addopts_review_fixes_698_2026-11-10, item A: every unexported assignment,
      // `?=` included, is named with the first CI mention not read and pointed at its line.
      const assigns = make?.assigned.has('PYTEST_ADDOPTS') === true || make?.defaulted.has('PYTEST_ADDOPTS') === true;
      // A value on a make command line (#648) is named first, as before.
      const mentionAt = exported || !assigns || makeOverrides.has('PYTEST_ADDOPTS') ? undefined : addoptsMentionNotRead;
      if (mentionAt !== undefined) {
        addoptsUnknown = true;
        addoptsNotKnownAt = mentionAt;
      } else if (isUnknown('PYTEST_ADDOPTS')) addoptsUnknown = true;
      else if (exported && make?.values.has('PYTEST_ADDOPTS')) {
        const expanded = expand(make.values.get('PYTEST_ADDOPTS') ?? '');
        if (expanded.unknown) addoptsUnknown = true;
        else addoptsText = expanded.text;
      }
    }
    const addopts = addoptsText === undefined ? undefined : shellWords(shellWords(addoptsText.trim()).join(' '));
    // The review of #648: a command whose expansion is not known is a pytest run not read where it,
    // what it expands to, or a variable it still names mentions pytest.
    const unknownRunsPytest = (command: string, expanded: string) =>
      command.toLowerCase().includes('pytest') ||
      expanded.toLowerCase().includes('pytest') ||
      makeReferencesIn(expanded).some((name) => make?.pytestNames.has(name) === true);
    const firstTarget = [...targets.keys()][0];
    // One read of the recipes reached from `names`, with the variables `variables` holds and
    // PYTEST_ADDOPTS `inForceAddopts` in force, or not known (`notKnown`, the reason the note names).
    const readRecipes = (
      names: readonly (string | undefined)[],
      variables: MakeVariables | undefined,
      inForceAddopts: readonly string[] | undefined,
      notKnown: string | undefined,
      addoptsAt?: { readonly words: readonly string[]; readonly source: string; readonly file: string; readonly line: number },
      // Item A of goal_cejel_v27_a1_addopts_assignment_not_known_2026-11-10: where a run not known is
      // pointed at, in place of its target's header; the review of #698, item A: the CI mention.
      notKnownAt?: { readonly source: string; readonly file: string; readonly line: number },
    ): void => {
      const pointAt = notKnown === undefined ? undefined : notKnownAt;
      const expandHere = variables === make ? expand : expandWith(variables);
      const reached = new Set<string>();
      const queue = names.filter((name): name is string => name !== undefined && targets.has(name));
      while (queue.length > 0) {
        const name = queue.shift() ?? '';
        if (reached.has(name)) continue;
        reached.add(name);
        const target = targets.get(name);
        if (!target) continue;
        queue.push(...target.dependencies.filter((dependency) => targets.has(dependency)));
        const commands = joinRecipeContinuations(target.commands);
        for (const command of commands) {
          const expanded = expandHere(command);
          if (expanded.unknown && unknownRunsPytest(command, expanded.text)) {
            invocations.push({ source: a1NotePath(file), file, anchor: headers.get(name) ?? 0, directory: '', args: [], text: command, unread: command });
            continue;
          }
          readShellCommands(expanded.text, repoDirectory(file), inForceAddopts, (words, directory, inForce, why) => {
            queue.push(...recipeTargetsNamed(words).filter((named) => targets.has(named)));
            const visit = visitor(pointAt?.source ?? a1NotePath(file), pointAt?.file ?? file, pointAt?.line ?? headers.get(name) ?? 0, 0, undefined, undefined, addoptsAt);
            if (notKnown !== undefined) visit(words, null, inForce, notKnown);
            else visit(words, directory, inForce, why);
          });
        }
      }
    };
    // make run by hand, or by a CI command with no PYTEST_ADDOPTS in its environment.
    readRecipes(
      [firstTarget, 'test', 'tests', 'check', ...namedTargets],
      make,
      addopts,
      addoptsUnknown ? (addoptsNotKnownAt?.text ?? 'PYTEST_ADDOPTS') : undefined,
      undefined,
      addoptsNotKnownAt,
    );
    // Item A of goal_cejel_v27_a1_makefile_addopts_environment_2026-11-04: each CI make command run
    // in this Makefile's directory (or one not known) with PYTEST_ADDOPTS in its environment. make
    // then passes PYTEST_ADDOPTS to every recipe, exported or not: with the Makefile's value where it
    // assigns one (`=`, `:=`, `::=`; a `+=` appends to the environment's), else the environment's
    // (`?=`, no assignment, `make -e`). An environment Cejel cannot read leaves the runs not read.
    // Where the run's PYTEST_ADDOPTS is not known already, every run these reach is named above.
    // A justfile is not read here: just passes its environment to a recipe, which is not item A.
    if (make === undefined || addoptsUnknown) continue;
    const here = repoDirectory(file);
    const baseKey = addopts?.join('\u0000');
    for (const environment of environments) {
      if (environment.directory !== null && environment.directory !== here) continue;
      const names = environment.targets.map((target) => (target === '' ? firstTarget : target));
      if (environment.notKnown !== undefined) {
        readRecipes(names, make, undefined, environment.notKnown);
        continue;
      }
      const words = environment.addopts ?? [];
      const local = readMakeVariables(text, setByEnvironment, { name: 'PYTEST_ADDOPTS', value: words.join(' '), overrides: environment.overrides });
      if (local.unknown.has('PYTEST_ADDOPTS')) {
        readRecipes(names, local, undefined, 'PYTEST_ADDOPTS');
        continue;
      }
      if (local.fromEnvironment) {
        readRecipes(names, local, words, undefined, { words, ...environment.at });
        continue;
      }
      const expanded = expandWith(local)(local.values.get('PYTEST_ADDOPTS') ?? '');
      if (expanded.unknown) {
        readRecipes(names, local, undefined, 'PYTEST_ADDOPTS');
        continue;
      }
      const inForce = shellWords(shellWords(expanded.text.trim()).join(' '));
      // The Makefile's own exported value, which the read above already used.
      if (inForce.join('\u0000') === baseKey) continue;
      readRecipes(names, local, inForce, undefined);
    }
  }
  // The review of #648: a CI file's TOXENV names the environments tox runs; one Cejel cannot
  // resolve leaves every factor-conditional pytest line not read.
  const toxenv = readToxenvValues(environmentTexts);
  for (const name of toxenv.names) namedToxEnvironments.add(name);
  // goal_cejel_v27_a1_addopts_assignment_not_known_2026-11-10, item B (#653): one posargs budget
  // across every tox.ini of the read, as the nox reader's is across every noxfile.
  const toxBudget = { left: POSARGS_BUDGET, characters: POSARGS_CHARACTER_BUDGET };
  for (const file of usable.filter((candidate) => basename(candidate) === 'tox.ini')) {
    const text = readText(file);
    if (text === undefined) continue;
    const notRead = (entry: { readonly text: string; readonly source: string; readonly file: string; readonly anchor: number }) =>
      invocations.push({ source: entry.source, file: entry.file, anchor: entry.anchor, directory: '', args: [], text: entry.text, unread: entry.text });
    readToxCommands(file, text, namedToxEnvironments, (anchor) => visitor(a1NotePath(file), file, anchor), toxPosargs, notRead, toxenv.unknown, toxBudget);
  }
  // The review of #655, blocker 1: the noxfiles are read last, once tox's commands have named
  // their nox commands too; their runs still go where the recipes' runs began. The review of #655,
  // blocker 2: never spread an input-sized list into one call (400 noxfiles overflowed the stack).
  const after = invocations.splice(noxAt);
  for (const run of readNoxfiles()) invocations.push(run);
  for (const run of after) invocations.push(run);
  return invocations;
}

/** The review of #655, blocker 1: a nox command whose posargs the reader cannot see, where it is written. */
interface NoxCommandNotRead {
  readonly text: string;
  readonly source: string;
  readonly file: string;
  readonly anchor: number;
}

/**
 * The review of #655, blocker 1: true where `words` runs nox in a form asPythonToolCommand does not
 * read (`poetry run nox`, `env CI=1 nox`, `uv run --with nox nox`, `uvx --python 3.12 nox`): a word
 * `nox` (any path), `-mnox`, or `-m nox`, not after `install` or `add` (`pip install nox`). Linear.
 */
function runsNoxUnread(words: readonly string[]): boolean {
  for (let index = 0; index < words.length; index += 1) {
    const word = words[index] ?? '';
    if (word === 'install' || word === 'add') return false;
    if (basename(word) === 'nox' || word === '-mnox' || (word === '-m' && words[index + 1] === 'nox')) return true;
  }
  return false;
}

// The review of #655, blocker 1: files that may run a nox command the reader does not read: scripts,
// Python modules, configuration and files with no extension (a script in bin/). Documentation and
// the files whose commands the reader reads (CI files, Makefiles and justfiles, tox.ini) are not here.
const NOX_COMMAND_FILE_PATTERN =
  /(?:\.(?:sh|bash|zsh|ksh|fish|ps1|psm1|bat|cmd|py|pyw|toml|cfg|ini|ya?ml|json)|(?:^|\/)(?:Dockerfile[^/]*|Containerfile|[^/.]+))$/i;
// A `nox` word, an `install` or `add` word, or a shell operator that ends a command, in one sweep.
const NOX_LINE_TOKEN_PATTERN = /(?<![\w.-])(?:nox|install|add)(?![\w.-])|&&|\|\||[;|&]/g;
// After a `nox` in a file that is not Python: a dependency (`"nox"`, `nox>=2024`, `nox = "^2024"`,
// `nox[uv]`, `- nox`), a key (`nox:`) or a bare `nox` at the end of its line, which passes no posargs.
const NOX_DEPENDENCY_AFTER_PATTERN = /["']|[ \t]*(?:[<>=!~;:[\]{}@,]|$)/y;

/**
 * The review of #655, blocker 1: the first line of each repository file (not a noxfile, not
 * documentation, not a file whose commands the reader reads) that names nox as it would be run:
 * `nox` as a word, not `import nox` or `from nox` in Python, not a dependency, a key or a bare `nox`
 * at the end of a line elsewhere, not after `install` or `add` in the same command. Linear in the
 * files: each line is swept once.
 */
function noxCommandsInUnreadFiles(
  repoFiles: readonly string[],
  readText: (file: string) => string | undefined,
  readActions: ReadonlySet<string>,
): NoxCommandNotRead[] {
  const found: NoxCommandNotRead[] = [];
  for (const file of repoFiles) {
    const name = basename(file);
    if (name === 'noxfile.py' || name === 'tox.ini' || isCiWorkflow(file) || isRecipeFile(file) || readActions.has(file)) continue;
    if (!NOX_COMMAND_FILE_PATTERN.test(file)) continue;
    const text = readText(file);
    if (text === undefined || !text.includes('nox')) continue;
    const python = /\.pyw?$/i.test(file);
    const lines = text.split(/\r?\n|\r/);
    const at = lines.findIndex((line) => {
      if (!line.includes('nox')) return false;
      if (python && /^[ \t]*(?:import|from)[ \t]+nox\b/.test(line)) return false;
      let installing = false;
      for (const match of line.matchAll(NOX_LINE_TOKEN_PATTERN)) {
        const token = match[0];
        if (token === 'install' || token === 'add') installing = true;
        else if (token !== 'nox') installing = false;
        else if (!installing) {
          if (python) return true;
          NOX_DEPENDENCY_AFTER_PATTERN.lastIndex = (match.index ?? 0) + 3;
          if (!NOX_DEPENDENCY_AFTER_PATTERN.test(line)) return true;
        }
      }
      return false;
    });
    if (at !== -1) found.push({ text: (lines[at] ?? '').trim(), source: a1NotePath(file), file, anchor: at });
  }
  return found;
}

// `uses: <value>` in a GitHub Actions file, at a job or a step.
const GITHUB_USES_LINE_PATTERN = /^[ \t]*(?:-[ \t]+)?uses:[ \t]*(.*)$/;

// The review of #648: hatch script expansions per read (see readPytestInvocations).
const HATCH_EXPANSION_BUDGET = 256;

/** The review of #648: whether a hatch configuration names an environment `template`, which changes which scripts it inherits. */
function hatchNamesTemplate(fileSet: ReadonlySet<string>, readText: (file: string) => string | undefined): boolean {
  return ['hatch.toml', 'pyproject.toml'].some((file) => fileSet.has(file) && /^[ \t]*template[ \t]*=/m.test(readText(file) ?? ''));
}

/**
 * The review of #648, the narrow rule for steps Cejel does not read: in a GitHub Actions file, each
 * step action (not a local one, not a reusable workflow) one of whose `with:` inputs runs pytest,
 * and the `path:` of a checkout action, if one has one. Linear in the file.
 */
function readGithubRemoteSteps(text: string): { readonly pytestInputs: readonly { readonly uses: string; readonly line: number }[]; readonly checkoutPath?: string } {
  const lines = text.split(/\r?\n/);
  const pytestInputs: { uses: string; line: number }[] = [];
  let checkoutPath: string | undefined;
  const indentOf = (line: string) => line.length - line.trimStart().length;
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index] ?? '';
    const match = GITHUB_USES_LINE_PATTERN.exec(line);
    if (!match) continue;
    const uses = yamlPlainScalar(match[1] ?? '');
    if (uses.startsWith('./') || uses.includes('/.github/workflows/')) continue;
    const keyColumn = line.indexOf('uses:');
    let withColumn = -1;
    let runsPytest = false;
    let next = index + 1;
    for (; next < lines.length; next += 1) {
      const candidate = lines[next] ?? '';
      if (candidate.trim() === '' || candidate.trimStart().startsWith('#')) continue;
      const indent = indentOf(candidate);
      if (indent < keyColumn) break;
      if (indent === keyColumn) {
        withColumn = /^with:[ \t]*$/.test(candidate.trim()) ? indent : -1;
        continue;
      }
      if (withColumn === -1) continue;
      const entry = candidate.trim();
      const key = /^([\w-]+):[ \t]*/.exec(entry);
      const value = (key ? entry.slice(key[0].length) : entry).replace(/^[|>][-+]?[ \t]*/, '');
      if (key?.[1] === 'path' && uses.startsWith('actions/checkout') && indent > withColumn) {
        const path = yamlPlainScalar(value);
        if (path !== '' && path !== '.' && path !== './') checkoutPath ??= `actions/checkout path: ${path}`;
      }
      if (!runsPytest && value.toLowerCase().includes('pytest')) {
        readShellCommands(yamlPlainScalar(value), '', undefined, (words) => {
          if (pytestCommandArguments(words) !== undefined) runsPytest = true;
        });
      }
    }
    if (runsPytest) pytestInputs.push({ uses: `uses: ${uses}`, line: index });
    index = next - 1;
  }
  return { pytestInputs, ...(checkoutPath === undefined ? {} : { checkoutPath }) };
}

/** The review of #648: the environment names CI files give TOXENV, and whether one cannot be resolved. */
function readToxenvValues(texts: readonly string[]): { readonly names: readonly string[]; readonly unknown: boolean } {
  const names: string[] = [];
  let unknown = false;
  for (const text of texts) {
    if (!text.includes('TOXENV')) continue;
    for (const line of text.split(/\r?\n/)) {
      const at = line.indexOf('TOXENV');
      if (at === -1) continue;
      const assignment = /^TOXENV[ \t]*[:=][ \t]*(.*)$/.exec(line.slice(at));
      if (!assignment) continue;
      const value = yamlPlainScalar((assignment[1] ?? '').trim()).replace(/^["']|["']$/g, '').trim();
      if (value === '' || /[$`{}]/.test(value)) unknown = true;
      else names.push(...value.split(',').map((part) => part.trim()).filter((part) => /^[\w.-]+$/.test(part)));
    }
  }
  return { names, unknown };
}

/** item A: the first `dir(...)` call in a Jenkinsfile, as written, or undefined. Linear. */
function jenkinsDirCall(text: string): string | undefined {
  const match = /\bdir[ \t]*\(/.exec(text);
  if (!match) return undefined;
  const start = match.index;
  const close = text.indexOf(')', start);
  const newline = text.indexOf('\n', start);
  const end = close === -1 || (newline !== -1 && newline < close) ? (newline === -1 ? text.length : newline) : close + 1;
  return text.slice(start, end).trim();
}

/** item A: a command word that is an unexpanded make or shell variable whose name holds PYTEST (`$(PYTEST)`, `${PYTEST_CMD}`). */
function isUnexpandedPytestVariable(word: string): boolean {
  if (!word.startsWith('$')) return false;
  const name = word.slice(1).replace(/^[({]/, '').replace(/[)}]$/, '');
  return /^\w+$/.test(name) && name.toUpperCase().includes('PYTEST');
}

/** The `NAME=value` words of a make command, as names. */
function makeAssignmentsNamed(words: readonly string[]): string[] {
  const name = basename(words[0] ?? '');
  if (name !== 'make' && name !== 'gmake' && !/^\$[({]MAKE[)}]$/.test(words[0] ?? '')) return [];
  return words.slice(1).flatMap((word) => {
    const equals = word.indexOf('=');
    return equals > 0 && /^[A-Za-z_][\w.-]*$/.test(word.slice(0, equals)) ? [word.slice(0, equals)] : [];
  });
}

/** GNU make's long options that take a value as the next word, where `=` does not join it. */
const MAKE_LONG_OPTIONS_WITH_VALUE: ReadonlySet<string> = new Set([
  '--directory', '--file', '--makefile', '--include-dir', '--old-file', '--assume-old', '--new-file',
  '--assume-new', '--what-if', '--jobs', '--load-average', '--max-load', '--output-sync', '--debug',
]);

/**
 * goal_cejel_v27_a1_makefile_addopts_environment_2026-11-04, item A: a command that runs make
 * (`make`, `gmake`, `$(MAKE)`, after `env` and its assignments), as what decides the environment
 * make passes on to a recipe: the directory `-C` moves to (relative, joined in order), the targets it
 * names, whether `-e` (`--environment-overrides`) gives the environment precedence, and a
 * PYTEST_ADDOPTS an `env` prefix sets. GNU make's short options are read as getopt reads them: `-C`,
 * `-f`, `-I`, `-o` and `-W` take the rest of the word or the next word, and `-j` and `-l` an attached
 * value or a next word of digits. Undefined for another command. Linear in the words.
 */
function makeCommandOf(words: readonly string[]):
  | {
      readonly directories: readonly string[];
      readonly targets: readonly string[];
      readonly overrides: boolean;
      /** `-f` / `--file`: the Makefile is named, so it may be in any directory. */
      readonly namesFile: boolean;
      readonly addopts?: readonly string[];
      /** goal_cejel_v27_a1_addopts_not_known_2026-11-05, item B: the `env` prefix's PYTEST_ADDOPTS assignments. */
      readonly addoptsAssignments: number;
    }
  | undefined {
  let index = 0;
  let addopts: readonly string[] | undefined;
  let addoptsAssignments = 0;
  if (words[0] === 'env') {
    index = 1;
    while ((words[index] ?? '').startsWith('-') || /^[A-Za-z_]\w*=/.test(words[index] ?? '')) {
      const assignment = words[index] ?? '';
      if (assignment.startsWith(PYTEST_ADDOPTS_ASSIGNMENT)) {
        addopts = shellWords(assignment.slice(PYTEST_ADDOPTS_ASSIGNMENT.length));
        addoptsAssignments += 1;
      }
      index += 1;
    }
  }
  const head = words[index] ?? '';
  const name = basename(head);
  if (name !== 'make' && name !== 'gmake' && !/^\$[({]MAKE[)}]$/.test(head)) return undefined;
  const directories: string[] = [];
  const targets: string[] = [];
  let overrides = false;
  let namesFile = false;
  for (index += 1; index < words.length; index += 1) {
    const word = words[index] ?? '';
    if (word.startsWith('--')) {
      const equals = word.indexOf('=');
      const option = equals === -1 ? word : word.slice(0, equals);
      const value = equals === -1 ? (MAKE_LONG_OPTIONS_WITH_VALUE.has(option) ? words[(index += 1)] : undefined) : word.slice(equals + 1);
      if (option === '--environment-overrides') overrides = true;
      else if (option === '--directory' && value !== undefined) directories.push(value);
      else if (option === '--file' || option === '--makefile') namesFile = true;
      continue;
    }
    if (word.startsWith('-') && word.length > 1) {
      for (let at = 1; at < word.length; at += 1) {
        const flag = word[at] ?? '';
        if (flag === 'e') overrides = true;
        else if ('CfIoW'.includes(flag)) {
          const value = at + 1 < word.length ? word.slice(at + 1) : words[(index += 1)];
          if (flag === 'C' && value !== undefined) directories.push(value);
          if (flag === 'f') namesFile = true;
          break;
        } else if (flag === 'j' || flag === 'l') {
          if (at + 1 === word.length && /^\d+(?:\.\d+)?$/.test(words[index + 1] ?? '')) index += 1;
          break;
        }
      }
      continue;
    }
    if (!word.includes('=')) targets.push(word);
  }
  return { directories, targets, overrides, namesFile, addoptsAssignments, ...(addopts === undefined ? {} : { addopts }) };
}

/**
 * goal_cejel_v27_a1_makefile_addopts_environment_2026-11-04, item A: a CI make command run with
 * PYTEST_ADDOPTS in its environment, or with an environment Cejel cannot read.
 */
interface MakeEnvironment {
  /** The directory make runs in (after `cd` and `-C`); null where it is not known. */
  readonly directory: string | null;
  /** The targets it names; empty for the default goal. */
  readonly targets: readonly string[];
  /** `make -e`: the environment's value wins over the Makefile's assignments (not `override` ones). */
  readonly overrides: boolean;
  /** PYTEST_ADDOPTS in make's environment, as words, where it is known. */
  readonly addopts?: readonly string[];
  /** Why PYTEST_ADDOPTS in make's environment is not known, where it is not. */
  readonly notKnown?: string;
  /** Where the environment's value is set, for its evidence pointer. */
  readonly at: { readonly source: string; readonly file: string; readonly line: number };
}

// Item A: at most this many distinct CI make environments are read per Makefile; the rest are read
// as one environment Cejel cannot read, so CI make commands times Makefile lines stays bounded.
const MAKE_ENVIRONMENTS_READ = 16;

/**
 * Item A: the distinct make environments, their targets merged, at most MAKE_ENVIRONMENTS_READ;
 * every later one joins a last environment that is not known, in no known directory. Linear.
 */
function distinctMakeEnvironments(environments: readonly MakeEnvironment[]): MakeEnvironment[] {
  const byKey = new Map<string, { environment: MakeEnvironment; targets: Set<string> }>();
  let rest: { environment: MakeEnvironment; targets: Set<string> } | undefined;
  for (const environment of environments) {
    const key = [environment.directory ?? '\u0001', environment.notKnown ?? '', ...(environment.addopts ?? []), String(environment.overrides)].join('\u0000');
    let entry = byKey.get(key);
    if (entry === undefined && byKey.size < MAKE_ENVIRONMENTS_READ) {
      entry = { environment, targets: new Set() };
      byKey.set(key, entry);
    }
    if (entry === undefined) {
      rest ??= { environment: { directory: null, targets: [], overrides: false, notKnown: 'PYTEST_ADDOPTS', at: environment.at }, targets: new Set() };
      entry = rest;
    }
    // The default goal is written as the empty name.
    if (environment.targets.length === 0) entry.targets.add('');
    for (const target of environment.targets) entry.targets.add(target);
  }
  return [...byKey.values(), ...(rest === undefined ? [] : [rest])].map(({ environment, targets }) => ({ ...environment, targets: [...targets] }));
}

/**
 * The review of #648: a command that runs tox, as `tox` and its words: `tox`, `python -m tox`,
 * `uvx tox`, `uv run tox`, `pipx run tox`; undefined for another command.
 */
function asToxCommand(words: readonly string[]): readonly string[] | undefined {
  return asPythonToolCommand(words, 'tox');
}

/**
 * A command that runs the Python tool `tool` (tox, or nox for goal_cejel_v27_a1_gaps_2026-11-03
 * item B), as `tool` and its words: `tool`, `python -m tool`, `uvx tool`, `uv run tool`, `pipx run
 * tool`; undefined for another command.
 */
function asPythonToolCommand(words: readonly string[], tool: 'tox' | 'nox'): readonly string[] | undefined {
  const name = basename(words[0] ?? '');
  if (name === tool) return words;
  if (PYTHON_INTERPRETER_PATTERN.test(name)) {
    if (words[1] === '-m' && words[2] === tool) return [tool, ...words.slice(3)];
    if (words[1] === `-m${tool}`) return [tool, ...words.slice(2)];
    return undefined;
  }
  if (name === 'uvx' && words[1] === tool) return words.slice(1);
  if ((name === 'uv' || name === 'pipx') && words[1] === 'run' && words[2] === tool) return words.slice(2);
  return undefined;
}

/** item A: the words a `tox` command passes after `--` (its posargs), or undefined. */
function toxPosargsOf(command: readonly string[]): readonly string[] | undefined {
  return posargsOf(command, 'tox');
}

/**
 * The words a tox or nox command passes after `--` (its posargs), or undefined where the command
 * is not one or has no `--`. nox, like tox, puts them where the configuration names them
 * (`*session.posargs`; goal_cejel_v27_a1_gaps_2026-11-03, item B).
 */
function posargsOf(command: readonly string[], tool: 'tox' | 'nox'): readonly string[] | undefined {
  const words = asPythonToolCommand(command, tool);
  if (words === undefined) return undefined;
  const separator = words.indexOf('--');
  return separator === -1 ? undefined : words.slice(separator + 1);
}

/** A posargs set a CI or recipe command passes, where it is written. */
interface PassedPosargs {
  readonly words: readonly string[];
  readonly text: string;
  readonly source: string;
  readonly file: string;
  readonly anchor: number;
}

/**
 * item A (#648), shared with nox's posargs (goal_cejel_v27_a1_gaps_2026-11-03, item B): the
 * distinct literal posargs sets, at most 16, so CI lines times configuration lines stays bounded;
 * and the sets that leave a run not read: one with a word holding `$`, a backtick or braces, and
 * every distinct set past the 16th (named as not read rather than read in part).
 */
function partitionPosargs(posargs: readonly PassedPosargs[]): { readonly literal: readonly PassedPosargs[]; readonly unread: readonly PassedPosargs[] } {
  const literal = posargs.filter((entry) => !entry.words.some((word) => /[$`{}]/.test(word)));
  const distinct = [...new Map(literal.map((entry) => [entry.words.join('\u0000'), entry])).values()];
  return { literal: distinct.slice(0, 16), unread: [...posargs.filter((entry) => !literal.includes(entry)), ...distinct.slice(16)] };
}

/** The 0-based line of each Makefile target's header. */
function makeTargetLines(text: string): Map<string, number> {
  const lines = new Map<string, number>();
  text.split(/\r?\n/).forEach((line, index) => {
    const header = /^([A-Za-z0-9][A-Za-z0-9._-]*)\s*:(?!=)/u.exec(line);
    if (header?.[1] !== undefined && !lines.has(header[1])) lines.set(header[1], index);
  });
  return lines;
}

/** A Makefile's variables as make holds them once it has read the file, and those Cejel cannot know. */
interface MakeVariables {
  readonly values: ReadonlyMap<string, string>;
  /** Names whose value make uses cannot be known from the file (see readMakeVariables). */
  readonly unknown: ReadonlySet<string>;
  /** Names any assignment of which mentions pytest, known or not. */
  readonly pytestNames: ReadonlySet<string>;
  /**
   * Item A of goal_cejel_v27_a1_makefile_addopts_environment_2026-11-04: where an environment value
   * was given, true where no assignment in the file replaced or extended it, so make passes it on as
   * the environment set it.
   */
  readonly fromEnvironment: boolean;
  /**
   * goal_cejel_v27_a1_addopts_assignment_not_known_2026-11-10, item A (#674): for each name, its
   * first assignment read with `=`, `:=`, `::=` or `+=` (not `?=`, and not one that leaves the name
   * not known), as written (trimmed), and its 0-based line.
   */
  readonly assigned: ReadonlyMap<string, { readonly text: string; readonly line: number }>;
  /**
   * goal_cejel_v27_a1_addopts_review_fixes_698_2026-11-10, item A: the names a `?=` default left not
   * known because the environment of a CI command may set them (`setByEnvironment`).
   */
  readonly defaulted: ReadonlySet<string>;
}

// The review of #648: at most this many variable substitutions per Makefile, so a chain of
// references to empty variables cannot make the reader's work grow past linear in the file.
const MAKE_EXPANSION_BUDGET = 4096;

/**
 * item A: a Makefile's variables (`NAME = value`, `:=`, `::=`, `?=`, `+=`), as make would hold them
 * before any recipe runs. The review of #648: a `:=` value is expanded where it is assigned, with the
 * variables then defined, as make does, and a `+=` to one appends the expanded text. A name is not
 * known where its value is a `!=` (shell) result, set by `define`, assigned inside a conditional
 * (`ifeq`, `ifneq`, `ifdef`, `ifndef`), assigned for a target (`test: OPTS = ...`), assigned with
 * `:::=`, or a `?=` default the environment of a CI command may replace (`setByEnvironment`).
 *
 * Item A of goal_cejel_v27_a1_makefile_addopts_environment_2026-11-04: `environment` is a variable
 * already in make's environment, as GNU make reads one: defined (recursively) before the file, so a
 * `?=` keeps it, a `+=` appends to it and `=`, `:=` or `::=` replace it; under `make -e`
 * (`overrides`) only an `override` assignment changes it.
 */
function readMakeVariables(
  text: string,
  setByEnvironment: (name: string) => boolean = () => false,
  environment?: { readonly name: string; readonly value: string; readonly overrides: boolean },
): MakeVariables {
  const values = new Map<string, string>();
  const simple = new Set<string>();
  const unknown = new Set<string>();
  const pytestNames = new Set<string>();
  const assigned = new Map<string, { readonly text: string; readonly line: number }>();
  const defaulted = new Set<string>();
  const budget = { left: MAKE_EXPANSION_BUDGET };
  let fromEnvironment = environment !== undefined;
  if (environment !== undefined) values.set(environment.name, environment.value);
  const forget = (name: string) => {
    unknown.add(name);
    values.delete(name);
  };
  let conditional = 0;
  let defining: string | undefined;
  let lineIndex = -1;
  for (const line of text.split(/\r?\n/)) {
    lineIndex += 1;
    const trimmed = line.trim();
    if (defining !== undefined) {
      if (/^endef\b/.test(trimmed)) defining = undefined;
      else if (trimmed.toLowerCase().includes('pytest')) pytestNames.add(defining);
      continue;
    }
    // A tab-led line is a recipe line, as make reads one in a rule. goal_cejel_v27_a1_addopts_review_fixes_698_2026-11-10,
    // item B: a line led by spaces is not, so an assignment with leading spaces is read as one.
    if (line.startsWith('\t')) continue;
    const body = line.replace(/^[ \t]+/, '');
    const define = /^(?:override[ \t]+)?(?:export[ \t]+)?define[ \t]+([A-Za-z_][A-Za-z0-9_.-]*)/.exec(trimmed);
    if (define) {
      defining = define[1] ?? '';
      forget(defining);
      continue;
    }
    if (/^(?:ifeq|ifneq|ifdef|ifndef)\b/.test(trimmed)) {
      conditional += 1;
      continue;
    }
    if (/^endif\b/.test(trimmed)) {
      conditional = Math.max(0, conditional - 1);
      continue;
    }
    const targetSpecific = /^[^#=:\t][^#=:]*:[ \t]*(?:(?:override|export|private)[ \t]+)*([A-Za-z_][A-Za-z0-9_.-]*)[ \t]*(?:\?=|:::=|::=|:=|\+=|!=|=)(.*)$/.exec(body);
    if (targetSpecific) {
      const name = targetSpecific[1] ?? '';
      if ((targetSpecific[2] ?? '').toLowerCase().includes('pytest')) pytestNames.add(name);
      forget(name);
      continue;
    }
    const match = /^(?:override[ \t]+)?(?:export[ \t]+)?([A-Za-z_][A-Za-z0-9_.-]*)[ \t]*(\?=|:::=|::=|:=|\+=|!=|=)(.*)$/.exec(body);
    if (!match) continue;
    const name = match[1] ?? '';
    const operator = match[2] ?? '=';
    const value = (match[3] ?? '').trim();
    if (value.toLowerCase().includes('pytest')) pytestNames.add(name);
    if (unknown.has(name)) continue;
    const fromTheEnvironment = environment !== undefined && name === environment.name;
    // Item A: under `make -e` an assignment to an environment variable is ignored unless `override`.
    if (fromTheEnvironment && environment.overrides && !/^override[ \t]/.test(body)) continue;
    if (conditional > 0 || operator === '!=' || operator === ':::=') {
      forget(name);
      continue;
    }
    if (operator === '?=' && setByEnvironment(name)) {
      defaulted.add(name);
      forget(name);
      continue;
    }
    // Item A: a `?=` keeps the environment's value; any other assignment replaces or extends it.
    if (fromTheEnvironment && operator !== '?=') fromEnvironment = false;
    if (operator !== '?=' && !assigned.has(name)) assigned.set(name, { text: line.trim(), line: lineIndex });
    if (operator === '?=') {
      if (!values.has(name)) {
        values.set(name, value);
        simple.delete(name);
      }
      continue;
    }
    if (operator === ':=' || operator === '::=' || (operator === '+=' && simple.has(name))) {
      const expanded = expandMakeVariables(value, values, (other) => unknown.has(other), budget);
      if (expanded.unknown) {
        forget(name);
        continue;
      }
      values.set(name, operator === '+=' ? `${values.get(name) ?? ''} ${expanded.text}`.trim() : expanded.text);
      simple.add(name);
      continue;
    }
    if (operator === '+=') values.set(name, `${values.get(name) ?? ''} ${value}`.trim());
    else {
      values.set(name, value);
      simple.delete(name);
    }
  }
  return { values, unknown, pytestNames, fromEnvironment, assigned, defaulted };
}

/**
 * item A: a recipe command with each `$(NAME)` / `${NAME}` the Makefile defines replaced by its
 * value (recursively, a few levels), and `$$` by `$`. A variable it does not define, or a make
 * function, is left as written. The review of #648: a variable `isUnknown` names, one past the
 * depth limit, the output cap or the shared substitution `budget`, is left as written and makes the
 * result unknown. The work is bounded by the budget times the longest value.
 */
function expandMakeVariables(
  command: string,
  values: ReadonlyMap<string, string>,
  isUnknown: (name: string) => boolean,
  budget: { left: number },
  depth = 0,
): { readonly text: string; readonly unknown: boolean } {
  if (!command.includes('$')) return { text: command, unknown: false };
  let out = '';
  let unknown = false;
  // Once a closer is missing after one opener it is missing after every later one: stop looking.
  const unclosed = { '(': false, '{': false };
  for (let index = 0; index < command.length; index += 1) {
    const character = command[index] ?? '';
    if (character !== '$') {
      out += character;
      continue;
    }
    const next = command[index + 1];
    if (next === '$') {
      out += '$';
      index += 1;
      continue;
    }
    if ((next === '(' || next === '{') && !unclosed[next]) {
      const close = command.indexOf(next === '(' ? ')' : '}', index + 2);
      if (close === -1) unclosed[next] = true;
      const name = close === -1 ? '' : command.slice(index + 2, close);
      if (/^[A-Za-z_][A-Za-z0-9_.-]*$/.test(name)) {
        const value = values.get(name);
        if (isUnknown(name)) unknown = true;
        else if (value !== undefined) {
          budget.left -= 1;
          if (budget.left < 0 || depth >= 4 || out.length >= 4096) unknown = true;
          else {
            const inner = expandMakeVariables(value, values, isUnknown, budget, depth + 1);
            out += inner.text;
            if (inner.unknown) unknown = true;
            index = close;
            continue;
          }
        }
      }
    }
    out += character;
  }
  return { text: out, unknown };
}

/** The review of #648: whether `name` appears in `text` as a whole word (letters, digits and `_` around it). */
function containsWord(text: string, name: string): boolean {
  if (name === '') return false;
  const word = (code: number) => (code >= 48 && code <= 57) || (code >= 65 && code <= 90) || (code >= 97 && code <= 122) || code === 95;
  for (let at = text.indexOf(name); at !== -1; at = text.indexOf(name, at + 1)) {
    if ((at === 0 || !word(text.charCodeAt(at - 1))) && (at + name.length >= text.length || !word(text.charCodeAt(at + name.length)))) return true;
  }
  return false;
}

/**
 * goal_cejel_v27_a1_addopts_not_known_2026-11-05, item B: how many times `name` appears in `text` as
 * a whole word, as containsWord reads one. Linear: each indexOf starts past the last match's start.
 */
function wordCount(text: string, name: string): number {
  if (name === '') return 0;
  const word = (code: number) => (code >= 48 && code <= 57) || (code >= 65 && code <= 90) || (code >= 97 && code <= 122) || code === 95;
  let count = 0;
  for (let at = text.indexOf(name); at !== -1; at = text.indexOf(name, at + 1)) {
    if ((at === 0 || !word(text.charCodeAt(at - 1))) && (at + name.length >= text.length || !word(text.charCodeAt(at + name.length)))) count += 1;
  }
  return count;
}

/** The review of #648: the names of the `$(NAME)` and `${NAME}` references left in `text`. Linear. */
function makeReferencesIn(text: string): string[] {
  const names: string[] = [];
  for (let at = text.indexOf('$'); at !== -1; at = text.indexOf('$', at + 1)) {
    const opener = text[at + 1];
    if (opener !== '(' && opener !== '{') continue;
    const close = text.indexOf(opener === '(' ? ')' : '}', at + 2);
    if (close === -1) break;
    names.push(text.slice(at + 2, close));
  }
  return names;
}

/** item A: a justfile's `name := "literal"` assignments; any other value is not known. */
function readJustVariables(text: string): Map<string, string> {
  const variables = new Map<string, string>();
  for (const line of text.split(/\r?\n/)) {
    const match = /^(?:export[ \t]+)?([A-Za-z_][\w-]*)[ \t]*:=[ \t]*(.*)$/.exec(line);
    if (!match) continue;
    const literal = /^(?:"([^"\\]*)"|'([^']*)')$/.exec((match[2] ?? '').trim());
    if (literal) variables.set(match[1] ?? '', literal[1] ?? literal[2] ?? '');
    else variables.delete(match[1] ?? '');
  }
  return variables;
}

/** item A: `{{name}}` replaced where `name` is a literal justfile variable; a recipe parameter stays as written. */
function expandJustVariables(command: string, variables: ReadonlyMap<string, string>): string {
  if (!command.includes('{{')) return command;
  let out = '';
  let index = 0;
  while (index < command.length) {
    const open = command.indexOf('{{', index);
    if (open === -1) break;
    const close = command.indexOf('}}', open + 2);
    if (close === -1) break;
    const value = variables.get(command.slice(open + 2, close).trim());
    out += command.slice(index, open) + (value ?? command.slice(open, close + 2));
    index = close + 2;
  }
  return out + command.slice(index);
}

/**
 * item A: a justfile's recipes, with or without parameters (`test *ARGS:`), each with its
 * dependencies, its body's commands and its header's 0-based line. A recipe's parameters stay as
 * `{{NAME}}` in its commands, so a pytest run passing one is not read.
 */
function readJustRecipes(text: string): Map<string, RecipeTarget & { readonly line: number }> {
  const recipes = new Map<string, { dependencies: string[]; commands: string[]; line: number }>();
  let active: { dependencies: string[]; commands: string[]; line: number } | null = null;
  text.split(/\r?\n/).forEach((line, index) => {
    if (line.trim() === '' ) return;
    if (/^[ \t]/.test(line)) {
      if (active && !line.trimStart().startsWith('#')) active.commands.push(line.trim().replace(/^[@-]+/, ''));
      return;
    }
    active = null;
    if (line.startsWith('#')) return;
    const colon = line.indexOf(':');
    if (colon <= 0 || line[colon + 1] === '=') return;
    const head = line.slice(0, colon).trim().split(/[ \t]+/);
    const name = (head[0] ?? '').replace(/^@/, '');
    if (!/^[A-Za-z_][\w-]*$/.test(name) || name === 'set' || name === 'alias' || name === 'export') return;
    const dependencies = line
      .slice(colon + 1)
      .split('#')[0]
      ?.trim()
      .split(/[ \t]+/)
      .map((dependency) => dependency.replace(/^\(/, ''))
      .filter((dependency) => /^[A-Za-z_][\w-]*$/.test(dependency)) ?? [];
    active = { dependencies, commands: [], line: index };
    recipes.set(name, active);
  });
  return recipes;
}

/** item A: hatch's scripts by environment: each its commands (undefined: a value Cejel did not parse), file and 0-based line. */
type HatchScripts = Map<string, Map<string, { readonly commands?: readonly string[]; readonly file: string; readonly line: number }>>;

/** item A: the scripts of hatch.toml ([envs.<env>.scripts]) and pyproject.toml ([tool.hatch.envs.<env>.scripts]) at the root. */
function readHatchScripts(fileSet: ReadonlySet<string>, readText: (file: string) => string | undefined): HatchScripts {
  const scripts: HatchScripts = new Map();
  for (const [file, prefix] of [['hatch.toml', [] as string[]], ['pyproject.toml', ['tool', 'hatch']]] as const) {
    if (!fileSet.has(file)) continue;
    const text = readText(file);
    if (text === undefined) continue;
    const lines = text.split(/\r?\n/);
    let table: string[] = [];
    for (let index = 0; index < lines.length; index += 1) {
      const trimmed = (lines[index] ?? '').trim();
      if (trimmed === '' || trimmed.startsWith('#')) continue;
      const header = /^\[\[?([^\]]*)\]\]?/.exec(trimmed);
      if (header) {
        table = tomlKeyPath(header[1] ?? '');
        continue;
      }
      const equals = tomlKeyEnd(trimmed);
      if (equals === -1) continue;
      const keyLine = index;
      const scanner = new TomlValueScanner();
      scanner.feed(trimmed.slice(equals + 1));
      while (!scanner.complete() && index + 1 < lines.length) {
        index += 1;
        scanner.feed(`\n${lines[index] ?? ''}`);
      }
      const path = [...table, ...tomlKeyPath(trimmed.slice(0, equals))];
      const rest = path.slice(prefix.length);
      if (prefix.some((part, at) => path[at] !== part) || rest.length !== 4 || rest[0] !== 'envs' || rest[2] !== 'scripts') continue;
      const value = scanner.value();
      const environment = rest[1] ?? '';
      const byName = scripts.get(environment) ?? new Map();
      scripts.set(environment, byName);
      if (byName.has(rest[3] ?? '')) continue;
      byName.set(rest[3] ?? '', {
        ...(value.kind === 'unknown' ? {} : { commands: value.kind === 'text' ? [value.text] : value.items }),
        file,
        line: keyLine,
      });
    }
  }
  return scripts;
}

/** item A: `hatch run [env:]name args...`, read: the environment (default `default`), the name and the arguments. */
function hatchRunOf(words: readonly string[]): { environment: string; name: string; args: readonly string[]; explicitEnvironment: boolean } | undefined {
  if (basename(words[0] ?? '') !== 'hatch' || words[1] !== 'run') return undefined;
  let index = 2;
  while ((words[index] ?? '').startsWith('-')) index += 1;
  const spec = words[index];
  if (spec === undefined) return undefined;
  const colon = spec.indexOf(':');
  return colon > 0
    ? { environment: spec.slice(0, colon), name: spec.slice(colon + 1), args: words.slice(index + 1), explicitEnvironment: true }
    : { environment: 'default', name: spec, args: words.slice(index + 1), explicitEnvironment: false };
}

/** item A: a hatch script command with `{args}` / `{args:default}` replaced by the words hatch run passes. */
function substituteHatchArguments(command: string, args: readonly string[]): string {
  const passed = args.map((arg) => (/\s/.test(arg) ? `'${arg}'` : arg)).join(' ');
  // By index, not a regex: an unclosed `{args:` repeated must stay linear.
  let out = '';
  let index = 0;
  for (;;) {
    const open = command.indexOf('{args', index);
    if (open === -1) break;
    const after = command[open + 5];
    if (after !== '}' && after !== ':') {
      out += command.slice(index, open + 5);
      index = open + 5;
      continue;
    }
    // No `}` after this one means none after any later one either.
    const close = command.indexOf('}', open + 5);
    if (close === -1) break;
    const fallback = after === ':' ? command.slice(open + 6, close) : '';
    out += command.slice(index, open) + (args.length > 0 ? passed : fallback);
    index = close + 1;
  }
  return out + command.slice(index);
}

/** goal_cejel_v27_a1_gaps_2026-11-03, item B: where a nox call's words hold `*session.posargs`. */
const NOX_POSARGS_WORD = '\u0000session.posargs';
/**
 * item B: the posargs substitutions per read, counted as one per run read plus the words put in;
 * past it a call taking posargs is not read. The input that maximises the work without it: a
 * noxfile of N calls taking posargs and a CI file passing 16 distinct sets of W words, N x 16 x W.
 * goal_cejel_v27_a1_addopts_assignment_not_known_2026-11-10, item B (#653): the tox reader takes
 * the same budget, counted the same way across every tox.ini of the read; past it a line holding
 * {posargs} is named as a run not read. Its worst input is the same shape: a tox.ini of N lines
 * holding {posargs} and 16 distinct CI sets of W words. The nox and tox reads each have their own.
 */
const POSARGS_BUDGET = 4096;
/**
 * goal_cejel_v27_a1_addopts_review_fixes_698_2026-11-10, item C (blocker 3 of the review of #698):
 * the count above charges a tox.ini line one unit per run read plus the words put in, but each
 * {posargs} on the line takes the whole set's text, so the line's work is its {posargs} count times
 * the characters put in: L/20 {posargs} and one word of L/2 characters cost 3 units and L²/40
 * characters. The tox reader also charges each line that product (a word's characters and one
 * separator, per {posargs}, per set), against this many characters across every tox.ini of a read.
 * The nox reader puts a passed word in place of *session.posargs by reference and copies no text, but
 * each *session.posargs on a call takes every set's words, so its work on a call is the call's
 * *session.posargs count times the sets' words. The count above charges a call the sets' words once,
 * however many *session.posargs it holds, so it bounds that at about 4,096 words per
 * *session.posargs (fix round on #710: this said "the call's words plus the sets' words"). The nox
 * reader takes no character charge.
 */
const POSARGS_CHARACTER_BUDGET = 262_144;

/**
 * item A: a noxfile's `session.run(...)` calls: the literal string arguments before the first
 * argument Cejel cannot read (a name, an f-string, an `env=` keyword), whether there is one, the
 * call as written (white space collapsed) and its 0-based line. Linear. Item B of
 * goal_cejel_v27_a1_gaps_2026-11-03: a `*session.posargs` argument is read as NOX_POSARGS_WORD,
 * which the caller replaces with the posargs a nox command passes.
 */
function readNoxRunCalls(text: string): { words: string[]; unknown: boolean; text: string; line: number }[] {
  const calls: { words: string[]; unknown: boolean; text: string; line: number }[] = [];
  const pattern = /\bsession\.run(?:_always)?[ \t]*\(/g;
  let line = 0;
  let counted = 0;
  for (let match = pattern.exec(text); match !== null; match = pattern.exec(text)) {
    for (; counted < match.index; counted += 1) if (text[counted] === '\n') line += 1;
    const args: string[] = [];
    let depth = 0;
    let quote: string | undefined;
    let current = '';
    let end = text.length;
    for (let index = match.index + match[0].length; index < text.length; index += 1) {
      const character = text[index] ?? '';
      if (quote !== undefined) {
        current += character;
        if (character === '\\') {
          current += text[index + 1] ?? '';
          index += 1;
        } else if (character === quote) quote = undefined;
        continue;
      }
      if (character === '"' || character === "'") quote = character;
      if (character === '(' || character === '[' || character === '{') depth += 1;
      if (character === ')' || character === ']' || character === '}') {
        if (depth === 0) {
          end = index + 1;
          break;
        }
        depth -= 1;
      }
      if (character === ',' && depth === 0) {
        args.push(current.trim());
        current = '';
        continue;
      }
      if (character === '#') {
        const newline = text.indexOf('\n', index);
        index = newline === -1 ? text.length : newline - 1;
        continue;
      }
      current += character;
    }
    if (current.trim() !== '') args.push(current.trim());
    pattern.lastIndex = end;
    const words: string[] = [];
    let unknown = false;
    for (const arg of args) {
      const keyword = /^([A-Za-z_]\w*)[ \t]*=(?!=)/.exec(arg);
      if (keyword) {
        if (keyword[1] === 'env') unknown = true;
        continue;
      }
      const literal = /^(?:"([^"\\\n]*)"|'([^'\\\n]*)')$/.exec(arg);
      if (literal && !unknown) words.push(literal[1] ?? literal[2] ?? '');
      else if (!unknown && /^\*[ \t]*session[ \t]*\.[ \t]*posargs$/.test(arg)) words.push(NOX_POSARGS_WORD);
      else unknown = true;
    }
    calls.push({ words, unknown, text: text.slice(match.index, end).replace(/\s+/g, ' ').replace(/\( /g, '(').replace(/ \)/g, ')'), line });
  }
  return calls;
}

/** Recipe lines with a trailing backslash joined to the next. */
function joinRecipeContinuations(commands: readonly string[]): string[] {
  const joined: string[] = [];
  let pending = '';
  for (const command of commands) {
    if (command.endsWith('\\')) {
      pending += `${command.slice(0, -1)} `;
      continue;
    }
    joined.push(`${pending}${command}`);
    pending = '';
  }
  if (pending !== '') joined.push(pending);
  return joined;
}

/** PYTEST_ADDOPTS set in a CI file other than GitHub Actions (a variables or env key), as words. */
function readCiAddopts(text: string): readonly string[] | undefined {
  if (!text.includes('PYTEST_ADDOPTS')) return undefined;
  for (const line of text.split(/\r?\n/)) {
    const value = PYTEST_ADDOPTS_LINE_PATTERN.exec(line)?.[1];
    if (value === undefined) continue;
    const [segment] = splitShellCommandSegments(value);
    const words = shellWords((segment ?? '').trim());
    // A quoted YAML value is one word holding the flags.
    return words.length === 1 ? shellWords(words[0] ?? '') : words;
  }
  return undefined;
}

/**
 * The commands of a tox.ini's environments that run: [testenv], and [testenv:<name>] where its
 * envlist or a CI or recipe `tox -e` names it. Each runs in its changedir (default the tox.ini's
 * directory) with its setenv's PYTEST_ADDOPTS. A factor-conditional line (`py38: ...`) is not read.
 */
function readToxCommands(
  file: string,
  text: string,
  named: ReadonlySet<string>,
  visitAt: (anchor: number) => ShellCommandVisitor,
  posargs: readonly { readonly words: readonly string[]; readonly text: string; readonly source: string; readonly file: string; readonly anchor: number }[] = [],
  notRead: (entry: { readonly text: string; readonly source: string; readonly file: string; readonly anchor: number }) => void = () => undefined,
  factorsUnknown = false,
  // goal_cejel_v27_a1_addopts_assignment_not_known_2026-11-10, item B (#653): the posargs budget
  // shared across the read's tox.ini files (POSARGS_BUDGET). The review of #698, item C: and the
  // characters left (POSARGS_CHARACTER_BUDGET).
  budget: { left: number; characters: number } = { left: POSARGS_BUDGET, characters: POSARGS_CHARACTER_BUDGET },
): void {
  const sections = readIniSections(text);
  const toxDirectory = repoDirectory(file);
  const tox = sections.get('tox');
  const listed = new Set([...expandToxEnvironmentList(tox?.get('envlist') ?? tox?.get('env_list') ?? ''), ...named]);
  const base = sections.get('testenv');
  // item E: the 0-based line holding each command line, by its text, found in one pass.
  const lineOfText = new Map<string, number>();
  text.split(/\r?\n/).forEach((raw, index) => {
    const trimmed = raw.trim();
    if (!lineOfText.has(trimmed)) lineOfText.set(trimmed, index);
    const value = /^[\w.-]+[ \t]*[=:][ \t]*(.*)$/.exec(trimmed)?.[1]?.trim();
    if (value !== undefined && value !== '' && !lineOfText.has(value)) lineOfText.set(value, index);
  });
  // item A: each environment section with the environment names it runs for (the base section: every listed one).
  const environments: { section: Map<string, string>; names: readonly string[] }[] = [];
  if (base) environments.push({ section: base, names: listed.size === 0 ? ['py'] : [...listed] });
  for (const name of listed) {
    const section = sections.get(`testenv:${name}`);
    if (section) environments.push({ section, names: [name] });
  }
  // item A: posargs with a word Cejel cannot resolve leave the run not read, once each.
  // Distinct literal posargs, at most 16, so CI lines times tox lines stays bounded; past 16 the
  // run is named as not read rather than read in part.
  const { literal: literalPosargs, unread: unreadPosargs } = partitionPosargs(posargs);
  // Item B of goal_cejel_v27_a1_addopts_assignment_not_known_2026-11-10 (#653): a line holding
  // {posargs} is read once with none and once per literal set, so its work is one per run read plus
  // the words put in, the nox reader's count. The 16-set limit caps the sets, not their length.
  // The review of #698, item C: per {posargs} on the line, the sets' words and their characters (a
  // word's characters and one separator each); a line with one {posargs} costs what it did.
  let posargsWords = 0;
  let posargsCharacters = 0;
  for (const entry of literalPosargs) {
    posargsWords += entry.words.length;
    for (const word of entry.words) posargsCharacters += word.length + 1;
  }
  let unreadSaid = false;
  const seen = new Set<Map<string, string>>();
  for (const { section, names } of environments) {
    if (seen.has(section)) continue;
    seen.add(section);
    const changedir = section.get('changedir') ?? base?.get('changedir');
    const directory =
      changedir === undefined
        ? toxDirectory
        : resolveCommandPath(toxDirectory, changedir.replace(/\{(?:toxinidir|tox_root)\}/g, '.'));
    const setenv = section.get('setenv') ?? base?.get('setenv') ?? '';
    const addoptsLine = /^PYTEST_ADDOPTS[ \t]*=[ \t]*(.*)$/m.exec(setenv)?.[1];
    const addopts = addoptsLine === undefined ? undefined : shellWords(addoptsLine);
    for (const key of ['commands_pre', 'commands', 'commands_post']) {
      for (const raw of (section.get(key) ?? '').split('\n')) {
        let line = raw.trim();
        if (line === '') continue;
        // item A: a factor-conditional line (`py38: ...`, `a,b: ...`, `a-b: ...`, `!a: ...`) runs
        // for an environment whose factors meet it; one with braces is read as meeting it.
        const factor = /^([\w.,!{}-]+):[ \t]/.exec(line);
        if (factor && factorsUnknown && /\b(?:pytest|py\.test)\b/.test(line)) {
          notRead({ text: line, source: a1NotePath(file), file, anchor: lineOfText.get(raw.trim()) ?? 0 });
          continue;
        }
        if (factor) {
          if (!toxFactorConditionMet(factor[1] ?? '', names)) continue;
          line = line.slice(factor[0].length).trim();
        }
        const anchor = lineOfText.get(raw.trim()) ?? 0;
        const relative = directory === null ? '.' : posix.relative(directory === '' ? '.' : directory, toxDirectory === '' ? '.' : toxDirectory) || '.';
        const substitute = (passed: readonly string[] | undefined) =>
          line
            .replace(/\{posargs\}/g, passed === undefined ? '' : passed.map((word) => (/\s/.test(word) ? `'${word}'` : word)).join(' '))
            .replace(/\{posargs:([^}]*)\}/g, (_, fallback: string) => (passed === undefined ? fallback : passed.join(' ')))
            .replace(/\{(?:toxinidir|tox_root)\}/g, relative);
        // Item B (#653): past the shared budget the line is named as a run not read, as the nox
        // reader names a call; none of its runs is read.
        if (line.includes('{posargs')) {
          let occurrences = 0;
          for (let at = line.indexOf('{posargs'); at !== -1; at = line.indexOf('{posargs', at + 1)) occurrences += 1;
          budget.left -= 1 + literalPosargs.length + occurrences * posargsWords;
          budget.characters -= occurrences * posargsCharacters;
          if (budget.left < 0 || budget.characters < 0) {
            notRead({ text: line, source: a1NotePath(file), file, anchor });
            continue;
          }
        }
        readShellCommands(substitute(undefined), directory, addopts, visitAt(anchor));
        if (!line.includes('{posargs')) continue;
        for (const entry of literalPosargs) readShellCommands(substitute(entry.words), directory, addopts, visitAt(anchor));
        if (!unreadSaid && /\b(?:pytest|py\.test)\b/.test(line)) {
          for (const entry of unreadPosargs) notRead(entry);
          unreadSaid = true;
        }
      }
    }
  }
}

/** item A: true when a tox factor condition holds for one of the environment names (factors split on `-`). */
function toxFactorConditionMet(condition: string, names: readonly string[]): boolean {
  if (/[{}]/.test(condition)) return true;
  return names.some((name) => {
    const factors = new Set(name.split('-'));
    return condition.split(',').some((alternative) =>
      alternative
        .split('-')
        .filter((part) => part !== '')
        .every((part) => (part.startsWith('!') ? !factors.has(part.slice(1)) : factors.has(part))),
    );
  });
}

// ---- Run-wide pytest skips (witan-rubric-v27, #518) ----------------------------------------
//
// A conftest.py is pytest's per-directory plugin: fixtures and hooks, never tests.
const PYTEST_CONFTEST_PATTERN = /(^|\/)conftest\.py$/;
// A module-level, unconditional skip of every test in the file: a top-level `pytestmark = ...`
// statement whose first line names `pytest.mark.skip`, with or without arguments, alone or in a
// list, and which is the only place the module names `pytestmark`. `skipif`, an `if` anywhere in
// the statement (a conditional expression, on any line a bracket carries it onto), a `\`
// continuation, and any other mention of `pytestmark` in the module (a later reassignment, one
// inside an `if`, an `append`) are not unconditional.
const PYTEST_MODULE_SKIP_MARK_PATTERN = /\bpytest\.mark\.skip\b(?!if)/;
const PYTEST_MODULE_SKIP_ASSIGNMENT_PATTERN = /^pytestmark[ \t]*=(?!=)/;
// How many lines a bracketed `pytestmark = (...)` statement may span before Cejel stops reading it.
const PYTEST_MODULE_SKIP_MAX_STATEMENT_LINES = 20;

/**
 * A line's code with its comment removed and each one-line string literal's contents blanked
 * (`"..."` becomes `""`), so neither a `#` nor a bracket inside a string is read as code. A quote
 * left open at the end of the line blanks the rest of it. Linear in the line.
 */
function pythonCodeOutsideStrings(line: string): string {
  let code = '';
  let quote = '';
  for (let index = 0; index < line.length; index += 1) {
    const character = line[index] ?? '';
    if (quote !== '') {
      if (character === '\\') index += 1;
      else if (character === quote) {
        code += character;
        quote = '';
      }
      continue;
    }
    if (character === '#') break;
    if (character === '"' || character === "'") quote = character;
    code += character;
  }
  return code;
}

const PYTEST_MARK_NAME_GLOBAL_PATTERN = /\bpytestmark\b/g;

function countPytestMarkMentions(text: string): number {
  return [...text.matchAll(PYTEST_MARK_NAME_GLOBAL_PATTERN)].length;
}

/** The change in bracket depth across code already free of strings and comments. */
function pythonBracketDelta(code: string): number {
  let depth = 0;
  for (const character of code) {
    if (character === '(' || character === '[' || character === '{') depth += 1;
    else if (character === ')' || character === ']' || character === '}') depth -= 1;
  }
  return depth;
}

function hasUnconditionalPytestModuleSkip(file: string, contents: string): boolean {
  if (!/\.py$/.test(file)) return false;
  const lines = contents.split('\n');
  // Every mention of `pytestmark` outside a comment, a string included, counted per occurrence so
  // two statements on one line (`pytestmark = ...; pytestmark = []`) are two mentions.
  let mentionCount = 0;
  let start = -1;
  for (const [index, line] of lines.entries()) {
    const count = Math.max(
      countPytestMarkMentions(stripPythonLineComment(line)),
      countPytestMarkMentions(pythonCodeOutsideStrings(line)),
    );
    if (count > 0 && start === -1) start = index;
    mentionCount += count;
  }
  // One statement may name `pytestmark`; a second mention may undo or change it.
  if (mentionCount !== 1) return false;
  const first = lines[start] ?? '';
  // The skip is named in code on the statement's first line, not inside a string (an `xfail`
  // whose reason names `pytest.mark.skip`): a statement continued onto more lines is only ever
  // read as fewer claims than its first line alone.
  if (
    !PYTEST_MODULE_SKIP_ASSIGNMENT_PATTERN.test(first) ||
    !pytestmarkNamesSkipAsMark(pythonCodeOutsideStrings(first))
  ) {
    return false;
  }
  // The whole statement: the line, and the lines an open bracket carries it onto. Its text is
  // read as before, up to each line's first `#` (a skip reason holding `if` still withholds the
  // claim); its brackets are counted outside strings and comments.
  const statement: string[] = [];
  let depth = 0;
  for (let index = start; index < lines.length; index += 1) {
    if (statement.length === PYTEST_MODULE_SKIP_MAX_STATEMENT_LINES) return false;
    const raw = (lines[index] ?? '').replace(/\r$/, '');
    const code = pythonCodeOutsideStrings(raw);
    if (/\\[ \t]*$/.test(code) || /\\[ \t]*$/.test(raw)) return false;
    statement.push(stripPythonLineComment(raw));
    depth += pythonBracketDelta(code);
    if (depth <= 0) break;
  }
  if (depth > 0) return false;
  return !/\bif\b/.test(statement.join('\n'));
}

const PYTEST_MODULE_SKIP_MARK_GLOBAL_PATTERN = new RegExp(PYTEST_MODULE_SKIP_MARK_PATTERN.source, 'g');

/**
 * True when the first line of a `pytestmark = ...` statement (code, string contents blanked) names
 * pytest's skip as one of the module's marks: the whole value, or an item of the list or tuple the
 * value opens with. A skip inside another mark's arguments marks only what that mark gives it
 * (`pytest.mark.parametrize("b", [pytest.param("x", marks=pytest.mark.skip), "y"])` skips one
 * parameter), so it is not read as skipping the module
 * (goal_cejel_v27_a1_test_count_overmatch_2026-11-01). Linear in the line.
 */
function pytestmarkNamesSkipAsMark(code: string): boolean {
  const equals = code.indexOf('=');
  if (equals === -1) return false;
  const value = code.slice(equals + 1);
  const valueStart = value.length - value.trimStart().length;
  const opensWithSequence = value[valueStart] === '[' || value[valueStart] === '(';
  const skips = new Set([...value.matchAll(PYTEST_MODULE_SKIP_MARK_GLOBAL_PATTERN)].map((match) => match.index ?? -1));
  if (skips.size === 0) return false;
  let depth = 0;
  for (let index = 0; index < value.length; index += 1) {
    if (skips.has(index) && (depth === 0 || (depth === 1 && opensWithSequence))) return true;
    const character = value[index];
    if (character === '(' || character === '[' || character === '{') depth += 1;
    else if (character === ')' || character === ']' || character === '}') depth -= 1;
    // The opening list or tuple closed before the end: the value is an expression on it, not a list of marks.
    if (depth === 0 && index > valueStart && opensWithSequence && value.slice(index + 1).trim() !== '') {
      return false;
    }
  }
  return false;
}

/** The line up to its first `#` (a comment start, or a `#` in a string, which only shortens it). */
function stripPythonLineComment(line: string): string {
  const hash = line.indexOf('#');
  return hash === -1 ? line : line.slice(0, hash);
}

/**
 * A pytest test file a run-wide hook may govern: a .py test file under the conftest's directory,
 * or, where nothing in the repository may keep pytest from collecting that directory
 * (`beyondScope`), any .py test file: pytest calls every loaded conftest.py's collection hook with
 * every collected item (goal_cejel_v27_a1_restore_proof_v2_2026-11-02, item E). Whether a run
 * collecting the file loads the conftest.py is read per run (hookNotLoaded).
 */
function isGovernedPytestFile(skip: PytestRunWideSkip, file: string): boolean {
  if (!/\.py$/.test(file) || PYTEST_CONFTEST_PATTERN.test(file)) return false;
  return skip.scope === '' || file.startsWith(`${skip.scope}/`) || skip.beyondScope;
}

// pytest's default norecursedirs, which it never collects (and so loads no conftest.py from).
const PYTEST_DEFAULT_NORECURSE_SEGMENT_PATTERN = /^(?:.*\.egg|\..*|_darcs|build|CVS|dist|node_modules|venv|\{arch\})$/;
// A conftest.py that names one of these may stop pytest collecting a directory.
const PYTEST_COLLECT_IGNORE_PATTERN = /\b(?:collect_ignore|collect_ignore_glob|pytest_ignore_collect)\b/;

// Only a hook defined at the top level of conftest.py is read: one defined inside an `if`, `try`
// or other block exists only on some runs, so it is conditional too.
const PYTEST_COLLECTION_HOOK_PATTERN = /^def[ \t]+pytest_collection_modifyitems[ \t]*\(/;
// goal_cejel_v27_a1_makefile_addopts_environment_2026-11-04, item C: the hook as a method, indented.
const PYTEST_CLASS_COLLECTION_HOOK_PATTERN = /^[ \t]+(?:async[ \t]+)?def[ \t]+pytest_collection_modifyitems[ \t]*\(/;
const PYTEST_COLLECTION_HOOK_NAME = 'pytest_collection_modifyitems';
const PYTEST_COLLECTION_HOOK_NAME_PATTERN = /\bpytest_collection_modifyitems\b/;
// Inside the hook: any of these makes what it does depend on something, and Cejel then makes no
// claim about it.
const PYTEST_HOOK_CONDITIONAL_PATTERN =
  /^(?:if|elif|else|while|try|except|finally|with|match|case|return|break|continue|yield)\b|\bskipif\b|\bif\b/;
// `for <name> in items:`, with any inline body after the colon in group 2.
const PYTEST_HOOK_FOR_EVERY_ITEM_PATTERN = /^for[ \t]+([A-Za-z_]\w*)[ \t]+in[ \t]+items[ \t]*:(.*)$/;
// A statement that rebinds `items` itself, so a later loop over it may not cover every item.
const PYTEST_HOOK_REBIND_ITEMS_PATTERN = /^(?:del[ \t]+)?items[ \t]*(?:[-+*/%&|^@]?=(?!=)|,|$)|\bitems[ \t]*:=/;
/**
 * A hook body line's statements: split at `;` unless the line holds a quote, where a `;` may be
 * inside a string and the line is kept whole.
 */
function pythonLineStatements(line: string): string[] {
  if (!line.includes(';') || /['"]/.test(line)) return [line];
  return line
    .split(';')
    .map((statement) => statement.trim())
    .filter((statement) => statement !== '');
}

/** One statement of a hook body, with the indent of the line it is on. */
interface PythonHookStatement {
  readonly indent: number;
  readonly text: string;
}

// `<name>.add_marker(pytest.mark.skip...)`, with the receiver in group 1.
const PYTEST_HOOK_SKIP_MARKER_PATTERN =
  /^([A-Za-z_]\w*)[ \t]*\.[ \t]*add_marker[ \t]*\([ \t]*pytest\.mark\.skip\b(?!if)/;
// `<name>.add_marker("skip")`: pytest reads a marker name as `pytest.mark.<name>`, and a bare
// `skip` mark skips unconditionally. The receiver is in group 1.
const PYTEST_HOOK_SKIP_MARKER_BY_NAME_PATTERN =
  /^([A-Za-z_]\w*)[ \t]*\.[ \t]*add_marker[ \t]*\([ \t]*(["'])skip\2[ \t]*[,)]/;
// `<name>.add_marker(<marker>)` with the marker a bare name: receiver in group 1, marker in group 2.
const PYTEST_HOOK_HELD_MARKER_PATTERN =
  /^([A-Za-z_]\w*)[ \t]*\.[ \t]*add_marker[ \t]*\([ \t]*([A-Za-z_]\w*)[ \t]*[,)]/;
// A one-line statement binding a name, in group 1, to an unconditional skip marker and nothing
// else: `<name> = pytest.mark.skip`, or with arguments holding no bracket. Read with string
// contents blanked, so a bracket in a skip reason does not end the arguments.
const PYTEST_SKIP_MARKER_BINDING_PATTERN =
  /^([A-Za-z_]\w*)[ \t]*=[ \t]*pytest\.mark\.skip(?:[ \t]*\([^()[\]{}]*\))?[ \t]*$/;
// The start of a statement that assigns to the name in group 1 (`x = `, `x += `, `x, y = `, `del x`).
const PYTHON_ASSIGNMENT_TARGET_PATTERN = /^(?:del[ \t]+)?([A-Za-z_]\w*)[ \t]*(?:[-+*/%&|^@]?=(?!=)|,)/;
const PYTHON_IDENTIFIER_PATTERN = /[A-Za-z_]\w*/g;

/** True when `text` holds `name` as a whole identifier. Linear in `text`. */
function containsPythonIdentifier(text: string, name: string): boolean {
  for (const match of text.matchAll(PYTHON_IDENTIFIER_PATTERN)) if (match[0] === name) return true;
  return false;
}


/**
 * True when a statement may rebind `name`: an assignment to it, or a `for`, `as` or `:=` outside a
 * string literal in a statement naming it.
 */
function mayRebindPythonName(text: string, name: string): boolean {
  if (PYTHON_ASSIGNMENT_TARGET_PATTERN.exec(text)?.[1] === name) return true;
  // One pass: string contents blanked, so a `for` or `as` in a skip reason is not read as code.
  // (A regex alternation over quoted strings retried from every quote of an unclosed run.)
  const code = pythonCodeOutsideStrings(text);
  return /\bfor\b|\bas\b|:=/.test(code) && containsPythonIdentifier(code, name);
}

/**
 * Names that hold an unconditional skip marker when the hook runs, each mapped to the index in the
 * hook body of the statement binding it, or to -1 for a binding at the module's top level, which is
 * made before any hook runs. A name qualifies only when its binding is one statement at the module's
 * top level or at the hook body's own first indent, and the conftest names it exactly twice in code:
 * that binding and one use. Any other mention (a second binding, a `global`, a use elsewhere) may
 * change what it holds, so then the name is not read. Linear in the file.
 */
function pytestHeldSkipMarkers(
  lines: readonly string[],
  body: readonly PythonHookStatement[],
): Map<string, number> {
  const bindings = new Map<string, number>();
  const bind = (code: string, at: number): void => {
    const name = PYTEST_SKIP_MARKER_BINDING_PATTERN.exec(code.trim())?.[1];
    if (name !== undefined) bindings.set(name, bindings.has(name) ? Number.NaN : at);
  };
  for (const line of lines) {
    if (/^[A-Za-z_]/.test(line)) bind(pythonCodeOutsideStrings(line.replace(/\r$/, '')), -1);
  }
  const hookIndent = body[0]?.indent;
  body.forEach(({ indent, text }, index) => {
    if (indent === hookIndent) bind(pythonCodeOutsideStrings(text), index);
  });
  if (bindings.size === 0) return bindings;
  const mentions = new Map<string, number>();
  for (const line of lines) {
    for (const match of pythonCodeOutsideStrings(line).matchAll(PYTHON_IDENTIFIER_PATTERN)) {
      if (bindings.has(match[0])) mentions.set(match[0], (mentions.get(match[0]) ?? 0) + 1);
    }
  }
  for (const [name, at] of bindings) {
    if (Number.isNaN(at) || mentions.get(name) !== 2) bindings.delete(name);
  }
  return bindings;
}

/**
 * True when the hook body (already free of any conditional) holds, at its own first indent, a
 * `for <name> in items:` loop whose own body, at its first level, adds a skip marker to `<name>`, and nothing in the
 * loop rebinds `<name>` and nothing in the hook rebinds `items`. The marker is `pytest.mark.skip`
 * written in the call, the name "skip", or a name `heldSkipMarkers` holds and that is bound before
 * the loop. A skip and a loop that merely
 * co-occur (a timeout on every item and a skip on one, `items[0].add_marker(...)`, a skip inside
 * a nested loop or function) are not tied together, so nothing is claimed. Linear in the body
 * for sibling loops; nested loops rescan only their own extent.
 */
function hookSkipsEveryItem(
  body: readonly PythonHookStatement[],
  heldSkipMarkers: ReadonlyMap<string, number> = new Map(),
): boolean {
  if (body.some(({ text }) => PYTEST_HOOK_REBIND_ITEMS_PATTERN.test(text))) return false;
  // The loop must run when the hook does: at the hook body's own first indent, not inside a nested
  // function or another loop.
  const hookIndent = body[0]?.indent;
  const skips = (text: string, name: string, loopIndex: number): boolean => {
    if (PYTEST_HOOK_SKIP_MARKER_PATTERN.exec(text)?.[1] === name) return true;
    if (PYTEST_HOOK_SKIP_MARKER_BY_NAME_PATTERN.exec(text)?.[1] === name) return true;
    const held = PYTEST_HOOK_HELD_MARKER_PATTERN.exec(text);
    if (held?.[1] !== name) return false;
    const boundAt = heldSkipMarkers.get(held[2] ?? '');
    return boundAt !== undefined && boundAt < loopIndex;
  };
  for (let index = 0; index < body.length; index += 1) {
    const statement = body[index] as PythonHookStatement;
    if (statement.indent !== hookIndent) continue;
    const loop = PYTEST_HOOK_FOR_EVERY_ITEM_PATTERN.exec(statement.text);
    if (!loop) continue;
    const name = loop[1] ?? '';
    const inline = (loop[2] ?? '').trim();
    if (inline !== '') {
      if (skips(inline, name, index)) return true;
      continue;
    }
    const childIndent = body[index + 1]?.indent;
    if (childIndent === undefined || childIndent <= statement.indent) continue;
    let skipped = false;
    let rebound = false;
    for (let inner = index + 1; inner < body.length; inner += 1) {
      const { indent, text } = body[inner] as PythonHookStatement;
      if (indent <= statement.indent) break;
      if (mayRebindPythonName(text, name)) rebound = true;
      if (indent === childIndent && skips(text, name, index)) skipped = true;
    }
    if (skipped && !rebound) return true;
  }
  return false;
}

/** A `for <target> in <source>:` statement's source and inline body, or undefined. Linear. */
function pythonForLoop(code: string): { source: string; body: string } | undefined {
  if (!/^for[ \t]/.test(code)) return undefined;
  let depth = 0;
  let colon = -1;
  for (let index = 0; index < code.length; index += 1) {
    const character = code[index];
    if (character === '(' || character === '[' || character === '{') depth += 1;
    else if (character === ')' || character === ']' || character === '}') depth -= 1;
    else if (character === ':' && depth === 0) {
      colon = index;
      break;
    }
  }
  if (colon === -1) return undefined;
  const head = code.slice(0, colon);
  const at = head.search(/[ \t]in[ \t]/);
  if (at === -1) return undefined;
  return { source: head.slice(at + 4).trim(), body: code.slice(colon + 1).trim() };
}

/** A call's positional and keyword arguments' texts, at its top level, from the text after `(`. Linear. */
function pythonCallArguments(afterParen: string): string[] {
  const parts: string[] = [];
  let depth = 0;
  let start = 0;
  for (let index = 0; index < afterParen.length; index += 1) {
    const character = afterParen[index];
    if (character === '(' || character === '[' || character === '{') depth += 1;
    else if (character === ')' || character === ']' || character === '}') {
      if (depth === 0) {
        parts.push(afterParen.slice(start, index).trim());
        return parts.filter((part) => part !== '');
      }
      depth -= 1;
    } else if (character === ',' && depth === 0) {
      parts.push(afterParen.slice(start, index).trim());
      start = index + 1;
    }
  }
  return parts;
}

// ---- The three outcomes of a collection hook ------------------------------------------------
//
// goal_cejel_v27_a1_restore_proof_and_hookwrapper_2026-11-02 (#631, #632, #634), replacing the
// restore reader of goal_cejel_v27_a1_test_count_overmatch_v2_2026-11-02. Every last top-level
// `pytest_collection_modifyitems` with an `items` parameter whose body touches `items` reaches
// exactly one of three outcomes, and none is chosen by default:
//   1. deselects: the reader proves the hook leaves `items` empty, so the run-wide skip rule
//      applies;
//   2. restores: the reader proves the collected items are back in `items` when the hook returns,
//      so the rule is withheld and A1's note says the hook puts them back;
//   3. not read: the reader proves neither, so the rule makes no claim for the hook, and A1's note
//      names it with the reason ("hook not read: `<reason>` in <path>").
// A hook the reader reads as never emptying the list (it only reads it, reorders it or adds to it)
// leaves the rule nothing to apply to and is not named, and one that rebinds the name `items`
// before it clears keeps #626's withhold. A hook that skips every item is read as before.
//
// The body is read as logical statements, with comments and strings blanked; the `def` may run
// onto later lines (black's wrapping). A hookwrapper (`hookwrapper=True` or `wrapper=True`) is read
// as the code after its single top-level `yield`. Any other decorator, a second or nested `yield`,
// a use of `items` before the yield, or any statement the hook's conditional rule stops (an `if`,
// a `return`, a loop exit, `with`, `try`, ...) sends a hook that touches `items` to outcome 3. The
// statements are then read in order, tracking what pytest's list holds:
//   - a clear empties it: `items.clear()`, `items[:] = []` or `()`, `del items[:]`, a whole-slice
//     assignment from a source known to be empty, or a call of a same-file helper that clears;
//   - a restore puts every collected item back: `items.extend(S)`, `items += S` or `items[:] = S`
//     (or `S[:]`), at the hook's top level, or a call of a same-file helper that does one of those
//     to its list parameter from its source parameter (there `S`, `S[:]`, `list(S)`, `tuple(S)`,
//     `sorted(S, ...)`, `[*S]` or `S.copy()`), the arguments by position or by the helper's own
//     parameter names, or of a lambda or nested function without parameters bound at the top level
//     whose body does one of those. S must be a name bound once, at the top level, before anything
//     changes the list, to a full copy (`list(items)`, `items[:]`, `items.copy()`, `[*items]`,
//     `tuple(items)` or `sorted(items, ...)`), and mentioned nowhere else in the hook, at any depth;
//   - an add from a source known to be empty changes nothing: an empty literal, `range(0)`, a
//     zero-length slice (`x[:0]`, `x[0:0]`, `x[k:k]`), a name whose last top-level binding is one of
//     those with no mention since, or, while the list is empty, the list or a copy of it;
//   - a read changes nothing: a loop over it, a builtin that only reads its arguments (`len`,
//     `list`, `sorted`, `print`, ...), `sort`, `reverse`, `index`, `count`, `copy`, a subscript
//     read, `in`, an alias bound at the top level, and a same-file helper that only reads it.
// Anything else that names the list, an alias, a closure over it, or a `.items` attribute (pytest's
// `session.items` is the same list) is not read: an add from any other source, `append`, `insert`,
// `__iadd__`, a call of a function the conftest.py does not define once at its top level, a method
// call, `*` arguments, a clear or add inside a loop, a closure stored or called with arguments, a
// use of the hook's `session` parameter or of a `.session` attribute once the list is emptied, and
// a `global` or `nonlocal` in the hook or a helper it calls. A
// use not read before the last clear, with any call after it, is not read either: the call may
// reach a reference the use stored. At the end: the list empty, outcome 1; every collected item
// back, outcome 2; anything else, outcome 3.
//
// goal_cejel_v27_a1_restore_proof_v2_2026-11-02 (supersedes #638) changes two things above. The
// file is tokenised (pythonSourceLines): strings, f-string fields, comments, brackets and
// backslash continuations are read as Python reads them, so a body ends where Python ends it, and a
// docstring or comment never decides anything. And outcome 2 is no longer what the list reading
// above ends in: it is an allowlist over the whole hook body (pytestHookRestoreAllowlist), and any
// statement that is not one of its shapes sends a hook that is not provably outcome 1 to outcome 3.

/**
 * A conftest.py tokenised as Python reads it. `masked[i]` is physical line i's code with comments
 * dropped and every string literal written `""`, except an f-string (or t-string), which is written
 * `(""` followed by `, <field code>` for each replacement field, then `)`, so the code its fields
 * run is read as code. `joins[i]` is true where line i continues the logical line before it (inside
 * a string, a bracket or a field, or after a backslash), and `inString[i]` where it starts inside a
 * string. `strings[i]` holds the contents of each string literal that starts on line i.
 * `tooDeep` is set where f-strings nest deeper than the reader follows. Linear in the text.
 */
interface PythonSourceLines {
  readonly raw: readonly string[];
  readonly masked: readonly string[];
  readonly joins: readonly boolean[];
  readonly inString: readonly boolean[];
  readonly strings: readonly (readonly string[])[];
  readonly tooDeep: boolean;
}

const PYTHON_STRING_PREFIXES: ReadonlySet<string> = new Set([
  'r', 'u', 'b', 'f', 't', 'br', 'rb', 'fr', 'rf', 'tr', 'rt',
]);
/** f-strings nested deeper than this inside one another's fields are not followed. */
const PYTHON_F_STRING_MAX_NESTING = 16;

function pythonSourceLines(text: string): PythonSourceLines {
  const raw = text.split('\n').map((line) => line.replace(/\r$/, ''));
  const masked: string[] = [];
  const joins: boolean[] = [false];
  const inString: boolean[] = [false];
  const strings: string[][] = [[]];
  let chunks: string[] = [];
  let depth = 0;
  let index = 0;
  let stringDepth = 0;
  let tooDeep = false;
  const length = text.length;
  const isIdentifierStart = (character: string): boolean => /[A-Za-z_]/.test(character) || character > '\u007f';
  const isIdentifierPart = (character: string): boolean => /\w/.test(character) || character > '\u007f';
  const newline = (join: boolean): void => {
    masked.push(chunks.join(''));
    chunks = [];
    joins.push(join);
    inString.push(stringDepth > 0);
    strings.push([]);
  };
  const identifier = (): string => {
    const start = index;
    while (index < length && isIdentifierPart(text[index] ?? '')) index += 1;
    return text.slice(start, index);
  };
  let fieldDepth = 0;
  // The code of an f-string's replacement field, from just after its `{` to its closing `}`. A
  // field nested past PYTHON_F_STRING_MAX_NESTING (fields in format specs in fields...) is skipped
  // as text and marks the source `tooDeep`, so the recursion is bounded whatever the input.
  const field = (): void => {
    if (fieldDepth >= PYTHON_F_STRING_MAX_NESTING) {
      tooDeep = true;
      return;
    }
    fieldDepth += 1;
    try {
      fieldBody();
    } finally {
      fieldDepth -= 1;
    }
  };
  const fieldBody = (): void => {
    let nesting = 0;
    while (index < length) {
      const character = text[index] ?? '';
      if (character === '\n') {
        newline(true);
        index += 1;
      } else if (character === '\r') index += 1;
      else if (character === '"' || character === "'") literal('');
      else if (isIdentifierStart(character)) {
        const word = identifier();
        const next = text[index] ?? '';
        if ((next === '"' || next === "'") && PYTHON_STRING_PREFIXES.has(word.toLowerCase())) literal(word);
        else chunks.push(word);
      } else if (character === '(' || character === '[' || character === '{') {
        nesting += 1;
        chunks.push(character);
        index += 1;
      } else if (character === ')' || character === ']') {
        nesting = Math.max(0, nesting - 1);
        chunks.push(character);
        index += 1;
      } else if (character === '}') {
        index += 1;
        if (nesting === 0) return;
        nesting -= 1;
        chunks.push(character);
      } else if (nesting === 0 && character === '!' && text[index + 1] !== '=') {
        // A conversion (`!r`): not code.
        index += 1;
        while (index < length && /\w/.test(text[index] ?? '')) index += 1;
      } else if (nesting === 0 && character === ':') {
        // The format spec: literal text, but each `{...}` in it is another field.
        index += 1;
        while (index < length) {
          const spec = text[index] ?? '';
          if (spec === '}') {
            index += 1;
            return;
          }
          if (spec === '{') {
            chunks.push(', ');
            index += 1;
            field();
          } else {
            if (spec === '\n') newline(true);
            index += 1;
          }
        }
        return;
      } else if (
        nesting === 0 &&
        character === '=' &&
        !'=!<>'.includes(text[index - 1] ?? '') &&
        /^[ \t]*[}!:]/.test(text.slice(index + 1, index + 1 + 64))
      ) {
        index += 1; // A self-documenting `=`: not code.
      } else {
        chunks.push(character);
        index += 1;
      }
    }
  };
  // A string literal starting at `index` (its quote), with `prefix` already read.
  const literal = (prefix: string): void => {
    const lower = prefix.toLowerCase();
    const formatted = (lower.includes('f') || lower.includes('t')) && stringDepth < PYTHON_F_STRING_MAX_NESTING;
    if ((lower.includes('f') || lower.includes('t')) && !formatted) tooDeep = true;
    const rawString = lower.includes('r');
    const quote = text[index] ?? '"';
    const triple = text.startsWith(quote.repeat(3), index);
    index += triple ? 3 : 1;
    const contentStart = index;
    let contentEnd = -1;
    const startLine = strings.length - 1;
    chunks.push(formatted ? '(""' : '""');
    stringDepth += 1;
    while (index < length) {
      const character = text[index] ?? '';
      if (character === '\\') {
        const next = text[index + 1] ?? '';
        if (next === '\n') {
          newline(true);
          index += 2;
        } else if (rawString && next !== '\\' && next !== quote) index += 1;
        else index += 2;
        continue;
      }
      if (character === '\n') {
        if (!triple) break; // An unterminated one-line string ends at the line's end.
        newline(true);
        index += 1;
        continue;
      }
      if (triple ? text.startsWith(quote.repeat(3), index) : character === quote) {
        contentEnd = index;
        index += triple ? 3 : 1;
        break;
      }
      if (formatted && character === '{') {
        if (text[index + 1] === '{') index += 2;
        else {
          chunks.push(', ');
          index += 1;
          field();
        }
        continue;
      }
      index += 1;
    }
    stringDepth -= 1;
    if (formatted) chunks.push(')');
    strings[startLine]?.push(text.slice(contentStart, contentEnd === -1 ? index : contentEnd));
  };
  while (index < length) {
    const character = text[index] ?? '';
    if (character === '\n') {
      newline(depth > 0);
      index += 1;
    } else if (character === '\r') index += 1;
    else if (character === '#') {
      while (index < length && text[index] !== '\n') index += 1;
    } else if (character === '\\' && (text[index + 1] === '\n' || (text[index + 1] === '\r' && text[index + 2] === '\n'))) {
      chunks.push(' ');
      index += text[index + 1] === '\r' ? 2 : 1;
      newline(true);
      index += 1;
    } else if (character === '"' || character === "'") literal('');
    else if (isIdentifierStart(character)) {
      const word = identifier();
      const next = text[index] ?? '';
      if ((next === '"' || next === "'") && PYTHON_STRING_PREFIXES.has(word.toLowerCase())) literal(word);
      else chunks.push(word);
    } else {
      if (character === '(' || character === '[' || character === '{') depth += 1;
      else if (character === ')' || character === ']' || character === '}') depth = Math.max(0, depth - 1);
      chunks.push(character);
      index += 1;
    }
  }
  masked.push(chunks.join(''));
  // `split('\n')` and the scan agree on the line count; pad defensively.
  while (masked.length < raw.length) {
    masked.push('');
    joins.push(false);
    inString.push(false);
    strings.push([]);
  }
  return { raw, masked, joins, inString, strings, tooDeep };
}

/** The physical lines [first, last] of each logical line of `source`, in order. */
function pythonLogicalLines(source: PythonSourceLines): { readonly first: number; readonly last: number }[] {
  const found: { first: number; last: number }[] = [];
  for (let line = 0; line < source.masked.length; line += 1) {
    if (line > 0 && source.joins[line] === true && found.length > 0) {
      (found[found.length - 1] as { first: number; last: number }).last = line;
    } else found.push({ first: line, last: line });
  }
  return found;
}

/** The indent of masked line `line`, or -1 where it holds no code. */
function pythonLineIndent(source: PythonSourceLines, line: number): number {
  const code = source.masked[line] ?? '';
  const trimmed = code.trimStart();
  return trimmed === '' ? -1 : code.length - trimmed.length;
}

/**
 * The physical line after the block that starts after line `from`: the first line at or after
 * `from` that starts a logical line holding code at an indent of at most `indent`, or the end.
 */
function pythonBlockEnd(source: PythonSourceLines, from: number, indent: number): number {
  for (let line = from; line < source.masked.length; line += 1) {
    if (source.joins[line] === true) continue;
    const at = pythonLineIndent(source, line);
    if (at !== -1 && at <= indent) return line;
  }
  return source.masked.length;
}

/** A logical statement of a function body, read from code with comments and strings blanked. */
interface PythonCodeStatement {
  readonly indent: number;
  /** Its lines joined, comments and string contents blanked. */
  readonly code: string;
  /** As A1's note shows it: strings as "", whitespace collapsed, no backtick, bounded. */
  readonly shown: string;
  /** The 0-based physical lines it starts and ends on. */
  readonly first: number;
  readonly last: number;
}

/** A1's note quotes a statement it could not read by at most this many characters of it. */
const A1_NOTE_CODE_MAX_LENGTH = 48;

function pythonShownCode(text: string): string {
  const shown = text.replace(/`/g, '').replace(/\s+/g, ' ').trim();
  return shown.length <= A1_NOTE_CODE_MAX_LENGTH ? shown : `${shown.slice(0, A1_NOTE_CODE_MAX_LENGTH - 3)}...`;
}

/** Code (strings blanked) split at each `;` outside brackets. Linear. */
function splitPythonCodeStatements(code: string): string[] {
  if (!code.includes(';')) return code.trim() === '' ? [] : [code.trim()];
  const parts: string[] = [];
  let depth = 0;
  let start = 0;
  for (let index = 0; index < code.length; index += 1) {
    const character = code[index];
    if (character === '(' || character === '[' || character === '{') depth += 1;
    else if (character === ')' || character === ']' || character === '}') depth -= 1;
    else if (character === ';' && depth === 0) {
      parts.push(code.slice(start, index).trim());
      start = index + 1;
    }
  }
  parts.push(code.slice(start).trim());
  return parts.filter((part) => part !== '');
}

/**
 * The logical statements of physical lines [start, end), read from the tokenised source (a
 * statement runs on while the next line joins it: inside a string, a bracket or after a
 * backslash), or why they cannot be read: a statement that runs on past `end`. A statement is
 * shown from its raw text with string contents blanked, or from its masked code where a string
 * runs across its lines. Linear in the lines.
 */
function pythonCodeStatements(
  source: PythonSourceLines,
  start: number,
  end: number,
): PythonCodeStatement[] | { readonly stop: string } {
  const statements: PythonCodeStatement[] = [];
  let first = -1;
  let indent = 0;
  let codes: string[] = [];
  let shownParts: string[] = [];
  let spansString = false;
  for (let line = start; line < end; line += 1) {
    const code = source.masked[line] ?? '';
    if (first === -1) {
      if (code.trim() === '' && source.joins[line + 1] !== true) continue;
      first = line;
      indent = code.length - code.trimStart().length;
      codes = [];
      shownParts = [];
      spansString = false;
    } else if (source.inString[line] === true) spansString = true;
    codes.push(code.trim());
    shownParts.push(pythonCodeOutsideStrings(source.raw[line] ?? '').trim());
    if (line + 1 < source.masked.length && source.joins[line + 1] === true) {
      if (line + 1 >= end) return { stop: 'unbalanced brackets' };
      continue;
    }
    const joined = codes.join(' ');
    const parts = splitPythonCodeStatements(joined);
    const shown = spansString ? parts : splitPythonCodeStatements(shownParts.join(' '));
    for (const [index, part] of parts.entries()) {
      const text = shown.length === parts.length ? (shown[index] ?? part) : part;
      statements.push({ indent, code: part, shown: pythonShownCode(text), first, last: line });
    }
    first = -1;
  }
  return first === -1 ? statements : { stop: 'unbalanced brackets' };
}

interface PythonDefHeader {
  /** Each parameter's text, in order. */
  readonly parameters: readonly string[];
  /** The 0-based line the body starts on. */
  readonly bodyStart: number;
  /** Code after the header's colon on its last line (a one-line body), or ''. */
  readonly inline: string;
}

const PYTHON_DEF_HEAD_PATTERN = /^[ \t]*(?:async[ \t]+)?def[ \t]+[A-Za-z_]\w*[ \t]*\(/;
const PYTHON_DEF_TAIL_PATTERN = /^[ \t]*(?:->[^:]*)?:(.*)$/;

/**
 * The `def` header on masked line `index`, its parameters possibly running onto later lines, with
 * or without a trailing comma (#634, item D), or undefined where it does not close. Linear.
 */
function pythonDefHeader(masked: readonly string[], index: number): PythonDefHeader | undefined {
  const head = PYTHON_DEF_HEAD_PATTERN.exec(masked[index] ?? '');
  if (!head) return undefined;
  let depth = 0;
  let parameters = '';
  for (let line = index; line < masked.length; line += 1) {
    const code = (masked[line] ?? '').replace(/\r$/, '');
    for (let column = line === index ? head[0].length : 0; column < code.length; column += 1) {
      const character = code[column] ?? '';
      if (character === '(' || character === '[' || character === '{') depth += 1;
      else if (character === ')' || character === ']' || character === '}') {
        if (depth === 0) {
          const tail = PYTHON_DEF_TAIL_PATTERN.exec(code.slice(column + 1));
          if (!tail) return undefined;
          return { parameters: pythonCallArguments(`${parameters})`), bodyStart: line + 1, inline: (tail[1] ?? '').trim() };
        }
        depth -= 1;
      }
      parameters += character;
    }
    parameters += ' ';
  }
  return undefined;
}

/** A parameter's name: '*' for a star parameter or a bare `*`, '' where it is not a plain name. */
function pythonParameterName(parameter: string): string {
  const text = parameter.trim();
  if (text.startsWith('*')) return '*';
  const name = text.replace(/[:=].*$/, '').trim();
  return /^[A-Za-z_]\w*$/.test(name) ? name : '';
}

const PYTEST_HOOKIMPL_DECORATOR_PATTERN = /^@[ \t]*(?:pytest[ \t]*\.[ \t]*)?hookimpl[ \t]*(?:\((.*)\))?$/;
const PYTEST_HOOKIMPL_OPTION_PATTERN = /^(hookwrapper|wrapper|tryfirst|trylast|optionalhook)[ \t]*=[ \t]*(True|False)$/;

/**
 * Whether the hook's decorators make it a wrapper (#632), or the first one the reader cannot place:
 * anything but `pytest.hookimpl` (or `hookimpl`) with True or False options it knows.
 */
function pytestHookDecoration(source: PythonSourceLines, index: number): { readonly wrapper: boolean } | { readonly unread: string } {
  const masked = source.masked;
  let top = index;
  for (let line = index - 1; line >= 0; line -= 1) {
    const code = masked[line] ?? '';
    if (code.trim() !== '' && source.joins[line] !== true && !/^@/.test(code)) break;
    top = line;
  }
  let from = -1;
  for (let line = top; line < index && from === -1; line += 1) if ((masked[line] ?? '').startsWith('@')) from = line;
  if (from === -1) return { wrapper: false };
  const decorators = pythonCodeStatements(source, from, index);
  if ('stop' in decorators) return { unread: decorators.stop };
  let wrapper = false;
  for (const decorator of decorators) {
    const hookimpl = PYTEST_HOOKIMPL_DECORATOR_PATTERN.exec(decorator.code);
    if (!hookimpl) return { unread: decorator.shown };
    for (const option of hookimpl[1] === undefined ? [] : pythonCallArguments(`${hookimpl[1]})`)) {
      const known = PYTEST_HOOKIMPL_OPTION_PATTERN.exec(option);
      if (!known) return { unread: decorator.shown };
      if ((known[1] === 'hookwrapper' || known[1] === 'wrapper') && known[2] === 'True') wrapper = true;
    }
  }
  return { wrapper };
}

// A hookwrapper's own yield: `yield`, `outcome = yield`, `(yield)`, or `return (yield)`.
const PYTEST_WRAPPER_YIELD_PATTERN =
  /^(?:(?:[A-Za-z_]\w*[ \t]*=[ \t]*)?(?:yield|\([ \t]*yield[ \t]*\))|return[ \t]*\([ \t]*yield[ \t]*\))$/;
// A `.items` attribute that is not a call (`session.items` is pytest's list; `d.items()` is not).
const PYTHON_ITEMS_ATTRIBUTE_PATTERN = /\.[ \t]*items\b(?![ \t]*\()/;
const PYTHON_SESSION_ATTRIBUTE_PATTERN = /\.[ \t]*session\b/;
const PYTHON_GLOBAL_STATEMENT_PATTERN = /^(?:global|nonlocal)\b/;
const PYTEST_ITEMS_NAMES: ReadonlySet<string> = new Set(['items']);

const PYTHON_READ_ONLY_LIST_METHODS: ReadonlySet<string> = new Set([
  'sort', 'reverse', 'index', 'count', 'copy', '__len__', '__contains__', '__iter__', '__getitem__',
]);
const PYTHON_READ_ONLY_BUILTINS: ReadonlySet<string> = new Set([
  'len', 'list', 'tuple', 'sorted', 'reversed', 'enumerate', 'zip', 'print', 'iter', 'set', 'frozenset',
  'str', 'repr', 'bool', 'any', 'all', 'sum', 'min', 'max', 'id', 'type', 'isinstance', 'hash',
]);
// Words before a `(` that open a parenthesised expression, not a call.
const PYTHON_NOT_CALLEES: ReadonlySet<string> = new Set([
  'in', 'and', 'or', 'not', 'is', 'lambda', 'for', 'if', 'else', 'return', 'yield', 'await', 'assert', 'del', 'as',
]);
const PYTHON_METHOD_CALL_STICKY = /\.[ \t]*([A-Za-z_]\w*)[ \t]*(\()?/y;
const PYTHON_AUGMENTED_ASSIGNMENT_STICKY = /(?:[-+*/%&|^@]|\/\/|\*\*|<<|>>)=/y;

/** The index of the last non-blank character before `at`, or -1. */
function pythonIndexBefore(code: string, at: number): number {
  let index = at - 1;
  while (index >= 0 && (code[index] === ' ' || code[index] === '\t')) index -= 1;
  return index;
}

/** The index of the first non-blank character at or after `at`. */
function pythonIndexAfter(code: string, at: number): number {
  let index = at;
  while (code[index] === ' ' || code[index] === '\t') index += 1;
  return index;
}

/** The identifier ending just before `at` (blanks skipped) and where it starts, or undefined. */
function pythonIdentifierBefore(code: string, at: number): { readonly name: string; readonly start: number } | undefined {
  const end = pythonIndexBefore(code, at) + 1;
  let start = end;
  while (start > 0 && /\w/.test(code[start - 1] ?? '')) start -= 1;
  if (start === end || /\d/.test(code[start] ?? '')) return undefined;
  return { name: code.slice(start, end), start };
}

/** For each position, the innermost bracket open there (or -1); for each opening bracket, its close (or -1). Linear. */
function pythonBracketNesting(code: string): { readonly enclosing: Int32Array; readonly close: Int32Array } {
  const enclosing = new Int32Array(code.length).fill(-1);
  const close = new Int32Array(code.length).fill(-1);
  const stack: number[] = [];
  for (let index = 0; index < code.length; index += 1) {
    const character = code[index];
    enclosing[index] = stack[stack.length - 1] ?? -1;
    if (character === '(' || character === '[' || character === '{') stack.push(index);
    else if (character === ')' || character === ']' || character === '}') {
      const open = stack.pop();
      if (open !== undefined) close[open] = index;
    }
  }
  return { enclosing, close };
}

/**
 * Where `code` names one of `names` as a variable: not an attribute (`x.items`) and not a keyword
 * argument's name (`f(items=x)`). Linear in `code`.
 */
function pythonNameMentions(code: string, names: ReadonlySet<string>): { readonly name: string; readonly at: number }[] {
  const found: { name: string; at: number }[] = [];
  let nesting: ReturnType<typeof pythonBracketNesting> | undefined;
  for (const match of code.matchAll(PYTHON_IDENTIFIER_PATTERN)) {
    const at = match.index ?? 0;
    if (!names.has(match[0]) || (at > 0 && /\w/.test(code[at - 1] ?? ''))) continue;
    if (code[pythonIndexBefore(code, at)] === '.') continue;
    const after = pythonIndexAfter(code, at + match[0].length);
    if (code[after] === '=' && code[after + 1] !== '=') {
      nesting ??= pythonBracketNesting(code);
      const open = nesting.enclosing[at] ?? -1;
      if (open !== -1 && code[open] === '(') continue;
    }
    found.push({ name: match[0], at });
  }
  return found;
}

/**
 * True when the mention of a list at `at` only reads it: a method that removes nothing, a
 * subscript read, after `in`, a `*` unpacking, or a whole argument of a builtin that only reads.
 */
function pythonListMentionReadsOnly(
  code: string,
  at: number,
  length: number,
  nesting: ReturnType<typeof pythonBracketNesting>,
): boolean {
  const after = pythonIndexAfter(code, at + length);
  const next = code[after];
  if (next === '.') {
    PYTHON_METHOD_CALL_STICKY.lastIndex = after;
    const method = PYTHON_METHOD_CALL_STICKY.exec(code);
    return method !== null && method[2] === '(' && PYTHON_READ_ONLY_LIST_METHODS.has(method[1] ?? '');
  }
  if (next === '[') {
    const close = nesting.close[after] ?? -1;
    if (close === -1 || /^del\b/.test(code)) return false;
    const rest = pythonIndexAfter(code, close + 1);
    if (code[rest] === '=' && code[rest + 1] !== '=') return false;
    PYTHON_AUGMENTED_ASSIGNMENT_STICKY.lastIndex = rest;
    return !PYTHON_AUGMENTED_ASSIGNMENT_STICKY.test(code);
  }
  if (pythonIdentifierBefore(code, at)?.name === 'in') return true;
  const previous = pythonIndexBefore(code, at);
  if (code[previous] === '*') {
    const before = pythonIndexBefore(code, previous);
    return before === -1 || '([{,'.includes(code[before] ?? '');
  }
  const open = nesting.enclosing[at] ?? -1;
  if (open === -1 || code[open] !== '(' || (next !== ',' && next !== ')')) return false;
  const callee = pythonIdentifierBefore(code, open);
  return callee !== undefined && PYTHON_READ_ONLY_BUILTINS.has(callee.name) && code[pythonIndexBefore(code, callee.start)] !== '.';
}

/** True when every mention of one of `names` in `code` only reads the list. */
function pythonListMentionsReadOnly(code: string, names: ReadonlySet<string>): boolean {
  const mentions = pythonNameMentions(code, names);
  if (mentions.length === 0) return true;
  const nesting = pythonBracketNesting(code);
  return mentions.every(({ name, at }) => pythonListMentionReadsOnly(code, at, name.length, nesting));
}

/** True when `code` calls something other than a builtin that only reads. Linear. */
function pythonCallsOtherThanReadOnlyBuiltin(code: string): boolean {
  for (let open = code.indexOf('('); open !== -1; open = code.indexOf('(', open + 1)) {
    const before = code[pythonIndexBefore(code, open)];
    if (before === ')' || before === ']') return true;
    const callee = pythonIdentifierBefore(code, open);
    if (callee === undefined || PYTHON_NOT_CALLEES.has(callee.name)) continue;
    if (code[pythonIndexBefore(code, callee.start)] === '.' || !PYTHON_READ_ONLY_BUILTINS.has(callee.name)) return true;
  }
  return false;
}

const PYTHON_EMPTY_SOURCE_PATTERN =
  /^(?:\[[ \t]*\]|\([ \t]*\)|\{[ \t]*\}|(?:list|tuple|set|frozenset|dict)[ \t]*\([ \t]*\)|range[ \t]*\([ \t]*0[ \t]*\))$/;

/** True when `source` ends in a zero-length slice: `[:0]`, `[0:0]`, or `[k:k]` for one integer or name k. Linear. */
function pythonZeroLengthSlice(source: string): boolean {
  if (!source.endsWith(']')) return false;
  let depth = 0;
  let open = -1;
  for (let index = source.length - 1; index >= 0 && open === -1; index -= 1) {
    const character = source[index];
    if (character === ']' || character === ')' || character === '}') depth += 1;
    else if (character === '[' || character === '(' || character === '{') {
      depth -= 1;
      if (depth === 0) open = index;
    }
  }
  if (open <= 0 || source.slice(0, open).trim() === '' || source[open] !== '[') return false;
  const parts = source.slice(open + 1, -1).split(':');
  if (parts.length !== 2) return false;
  const low = (parts[0] ?? '').trim();
  const high = (parts[1] ?? '').trim();
  return (high === '0' && (low === '' || low === '0')) || (low !== '' && low === high && /^(?:\d+|[A-Za-z_]\w*)$/.test(low));
}

// A full copy of a list: the name copied in group 1.
const PYTHON_FULL_COPY_PATTERNS: readonly RegExp[] = [
  /^(?:list|tuple)[ \t]*\([ \t]*([A-Za-z_]\w*)[ \t]*\)$/,
  /^([A-Za-z_]\w*)[ \t]*\[[ \t]*:[ \t]*\]$/,
  /^([A-Za-z_]\w*)[ \t]*\.[ \t]*copy[ \t]*\([ \t]*\)$/,
  /^\[[ \t]*\*[ \t]*([A-Za-z_]\w*)[ \t]*,?[ \t]*\]$/,
  /^sorted[ \t]*\([ \t]*([A-Za-z_]\w*)[ \t]*(?:,[ \t]*(?:key|reverse)[ \t]*=.*)?\)$/,
];

/** The name `value` is a full copy of (every element, in some order), or undefined. */
function pythonFullCopyOf(value: string): string | undefined {
  for (const pattern of PYTHON_FULL_COPY_PATTERNS) {
    const match = pattern.exec(value);
    if (match && (!value.startsWith('sorted') || callClosesAtEnd(value, value.indexOf('(')))) return match[1];
  }
  return undefined;
}

/** The bare name a restore puts back, written `S` or `S[:]` (or, in a helper, any full copy of S), or undefined. */
function pythonRestoreSourceName(source: string, fullCopies: boolean): string | undefined {
  const bare = /^([A-Za-z_]\w*)(?:[ \t]*\[[ \t]*:[ \t]*\])?$/.exec(source);
  if (bare) return bare[1];
  return fullCopies ? pythonFullCopyOf(source) : undefined;
}

type PythonListAddForm = 'extend' | 'iadd' | 'dunder' | 'one value' | 'whole' | 'slice' | 'index';

const PYTHON_LIST_ADD_METHOD_PATTERN = /^([A-Za-z_]\w*)[ \t]*\.[ \t]*(extend|append|insert|__iadd__)[ \t]*\(/;
const PYTHON_LIST_AUGMENTED_ADD_PATTERN = /^([A-Za-z_]\w*)[ \t]*\+=(?!=)(.*)$/;
const PYTHON_LIST_SUBSCRIPT_TARGET_PATTERN = /^([A-Za-z_]\w*)[ \t]*\[/;
const PYTHON_LIST_CLEAR_PATTERN = /^([A-Za-z_]\w*)[ \t]*\.[ \t]*clear[ \t]*\([ \t]*\)$/;
const PYTHON_LIST_DELETE_ALL_PATTERN = /^del[ \t]+([A-Za-z_]\w*)[ \t]*\[[ \t]*:[ \t]*\]$/;
const PYTHON_SIMPLE_BINDING_PATTERN = /^([A-Za-z_]\w*)[ \t]*=(?!=)[ \t]*(.*)$/;
const PYTHON_LAMBDA_BINDING_PATTERN = /^([A-Za-z_]\w*)[ \t]*=[ \t]*lambda\b(.*)$/;
const PYTHON_NESTED_DEF_PATTERN = /^(?:async[ \t]+)?def[ \t]+([A-Za-z_]\w*)[ \t]*\(/;
const PYTHON_CALL_PATTERN = /^(?:[A-Za-z_]\w*[ \t]*=[ \t]*)?([A-Za-z_]\w*)[ \t]*\(/;
const PYTHON_BARE_CALL_PATTERN = /^([A-Za-z_]\w*)[ \t]*\([ \t]*\)$/;
// In a helper: a statement after which the rest may not run, or runs only on some calls.
const PYTHON_HELPER_BRANCH_PATTERN = /^(?:if|elif|else|while|try|except|finally|with|match|case|break|continue|raise|async[ \t]+with)\b/;
const PYTHON_DEAD_IF_PATTERN = /^if[ \t]+(?:False|0|None)[ \t]*:/;

/** How a statement adds to (or assigns into) a list it starts with: the list, the form and its source. */
function pythonListAddForm(
  code: string,
  names: ReadonlySet<string>,
): { readonly target: string; readonly form: PythonListAddForm; readonly source: string } | undefined {
  const method = PYTHON_LIST_ADD_METHOD_PATTERN.exec(code);
  if (method && names.has(method[1] ?? '')) {
    const open = method[0].length - 1;
    if (!callClosesAtEnd(code, open)) return { target: method[1] ?? '', form: 'index', source: '' };
    const args = pythonCallArguments(code.slice(open + 1));
    const kind = method[2];
    if (kind === 'append' || kind === 'insert') return { target: method[1] ?? '', form: 'one value', source: args.join(', ') };
    if (args.length !== 1) return { target: method[1] ?? '', form: 'index', source: '' };
    return { target: method[1] ?? '', form: kind === 'extend' ? 'extend' : 'dunder', source: args[0] ?? '' };
  }
  const augmented = PYTHON_LIST_AUGMENTED_ADD_PATTERN.exec(code);
  if (augmented && names.has(augmented[1] ?? '')) return { target: augmented[1] ?? '', form: 'iadd', source: (augmented[2] ?? '').trim() };
  const subscript = PYTHON_LIST_SUBSCRIPT_TARGET_PATTERN.exec(code);
  if (!subscript || !names.has(subscript[1] ?? '')) return undefined;
  const open = subscript[0].length - 1;
  const close = pythonBracketNesting(code).close[open] ?? -1;
  if (close === -1) return undefined;
  const rest = pythonIndexAfter(code, close + 1);
  if (code[rest] !== '=' || code[rest + 1] === '=') return undefined;
  const inside = code.slice(open + 1, close);
  const source = code.slice(rest + 1).trim();
  if (/^[ \t]*:[ \t]*$/.test(inside)) return { target: subscript[1] ?? '', form: 'whole', source };
  return { target: subscript[1] ?? '', form: inside.includes(':') ? 'slice' : 'index', source };
}

/** What a function does to a list passed as one of its parameters. */
type PythonListParameterEffect =
  | { readonly effect: 'none' | 'clear' | 'unknown' }
  | { readonly effect: 'add-from' | 'replace-from'; readonly from: number };

interface PythonFunction {
  /** Each parameter's name, '*' or '' (pythonParameterName). */
  readonly parameters: readonly string[];
  readonly body: readonly PythonCodeStatement[];
  /** Effects already read, by the list's parameter position. */
  readonly effects: Map<number, PythonListParameterEffect>;
}

/** A conftest.py's top-level functions, read on demand. */
interface PythonModuleScope {
  /** A function defined once at the top level, undecorated and named nowhere else at the top level; null otherwise. */
  readonly function: (name: string) => PythonFunction | null | undefined;
}

function pythonModuleScope(source: PythonSourceLines): PythonModuleScope {
  const masked = source.masked;
  const defined = new Map<string, number[]>();
  for (const [line, code] of masked.entries()) {
    const head = source.joins[line] === true ? null : /^(?:async[ \t]+)?def[ \t]+([A-Za-z_]\w*)/.exec(code);
    if (!head) continue;
    const at = defined.get(head[1] ?? '') ?? [];
    at.push(line);
    defined.set(head[1] ?? '', at);
  }
  const named = new Map<string, number>();
  if (defined.size > 0) {
    for (const code of masked) {
      if (!/^[A-Za-z_@]/.test(code)) continue;
      for (const match of code.matchAll(PYTHON_IDENTIFIER_PATTERN)) {
        if (defined.has(match[0])) named.set(match[0], (named.get(match[0]) ?? 0) + 1);
      }
    }
  }
  const read = new Map<string, PythonFunction | null>();
  return {
    function: (name) => {
      const at = defined.get(name);
      if (at === undefined) return undefined;
      if (read.has(name)) return read.get(name);
      let result: PythonFunction | null = null;
      const line = at[0] ?? -1;
      let above = line - 1;
      while (above >= 0 && (masked[above] ?? '').trim() === '') above -= 1;
      const header = at.length === 1 && named.get(name) === 1 && !/^[@)\]}]/.test(masked[above] ?? '') ? pythonDefHeader(masked, line) : undefined;
      if (header !== undefined && header.inline === '') {
        const end = pythonBlockEnd(source, header.bodyStart, 0);
        const body = pythonCodeStatements(source, header.bodyStart, end);
        if (!('stop' in body)) result = { parameters: header.parameters.map(pythonParameterName), body, effects: new Map() };
      }
      read.set(name, result);
      return result;
    },
  };
}

type PythonListState = 'collected' | 'grown' | 'empty' | 'restored' | 'unknown';

type PythonListUse =
  | { readonly use: 'none' | 'read' | 'clear' | 'add-empty' | 'add' | 'unknown' | 'rebind' }
  | { readonly use: 'restore'; readonly source: string; readonly replace: boolean }
  | { readonly use: 'alias'; readonly names: readonly string[] }
  | { readonly use: 'call'; readonly closure: string };

interface PythonListReading {
  readonly state: PythonListState;
  /** The statement that made the state unknown, as A1's note shows it. */
  readonly reason?: string;
  readonly cleared: boolean;
  /** The base name was rebound before its list was changed, and a clear follows. */
  readonly rebinds: boolean;
  /** The uses that changed the list, in order. */
  readonly changes: readonly PythonListUse[];
}

/** Calls of closures and helpers are read this many deep; deeper is not read. */
const PYTHON_LIST_READ_DEPTH = 3;

/**
 * Reads what a function body does to the list named `base` (pytest's `items` in the hook, or a
 * helper's list parameter), statement by statement, in the order they run.
 */
function readPythonList(
  statements: readonly PythonCodeStatement[],
  base: string,
  scope: PythonModuleScope,
  helper: { readonly sources: ReadonlySet<string> } | undefined,
  depth: number,
  guarded: ReadonlySet<string> = new Set(),
): PythonListReading {
  const listNames = new Set([base]);
  const closures = new Map<string, { readonly from: number; readonly to: number } | { readonly lambda: PythonCodeStatement } | null>();
  const localFunctions = new Map<string, PythonFunction | null>();
  // Static: occurrences of each name, the statements that mention it, and the restores that use it.
  const occurrences = new Map<string, number>();
  const mentionedAt = new Map<string, number[]>();
  for (const [ordinal, statement] of statements.entries()) {
    const seen = new Set<string>();
    for (const match of statement.code.matchAll(PYTHON_IDENTIFIER_PATTERN)) {
      const at = match.index ?? 0;
      if (at > 0 && /\w/.test(statement.code[at - 1] ?? '')) continue;
      if (statement.code[pythonIndexBefore(statement.code, at)] === '.') continue;
      occurrences.set(match[0], (occurrences.get(match[0]) ?? 0) + 1);
      if (seen.has(match[0])) continue;
      seen.add(match[0]);
      const list = mentionedAt.get(match[0]) ?? [];
      list.push(ordinal);
      mentionedAt.set(match[0], list);
    }
  }
  const functionNamed = (name: string): PythonFunction | null | undefined =>
    localFunctions.has(name) ? localFunctions.get(name) : scope.function(name);
  const restoreUses = new Map<string, number>();
  const countRestore = (code: string) => {
    const add = pythonListAddForm(code, new Set([base]));
    if (add && (add.form === 'extend' || add.form === 'iadd' || add.form === 'whole')) {
      const name = pythonRestoreSourceName(add.source, helper !== undefined);
      if (name !== undefined) restoreUses.set(name, (restoreUses.get(name) ?? 0) + 1);
      return;
    }
    const call = PYTHON_CALL_PATTERN.exec(code);
    if (!call || !callClosesAtEnd(code, call[0].length - 1)) return;
    // Functions nested in the hook are not known yet: a restore through one is not counted, so it is not proven.
    const fn = scope.function(call[1] ?? '');
    const mapped = fn ? pythonMapArguments(fn, code.slice(call[0].length)) : undefined;
    if (!fn || !mapped) return;
    for (const [position, argument] of mapped) {
      if (argument !== base) continue;
      const effect = pythonParameterEffect(fn, position, scope, depth);
      if (effect.effect !== 'add-from' && effect.effect !== 'replace-from') continue;
      const name = pythonRestoreSourceName(mapped.get(effect.from) ?? '', false);
      if (name !== undefined) restoreUses.set(name, (restoreUses.get(name) ?? 0) + 1);
    }
  };
  for (const statement of statements) {
    const lambda = PYTHON_LAMBDA_BINDING_PATTERN.exec(statement.code);
    countRestore(lambda ? (pythonLambdaBody(lambda[2] ?? '') ?? '') : statement.code);
  }
  // The last statement shaped like a clear of the base name (for a rebind before it).
  const lastClear = statements.reduce(
    (found, { code }, ordinal) =>
      PYTHON_LIST_CLEAR_PATTERN.exec(code)?.[1] === base ||
      PYTHON_LIST_DELETE_ALL_PATTERN.exec(code)?.[1] === base ||
      pythonListAddForm(code, new Set([base]))?.form === 'whole'
        ? ordinal
        : found,
    -1,
  );

  let state: PythonListState = 'collected';
  let reason: string | undefined;
  let escape: string | undefined;
  let callSinceClear = false;
  let cleared = false;
  let rebinds = false;
  let stopped = false;
  const changes: PythonListUse[] = [];
  const copies = new Set<string>();
  const lastBinding = new Map<string, number>();
  const emptyBinding = new Map<number, boolean>();

  const firstMentionAfter = (name: string, after: number): number => {
    const list = mentionedAt.get(name) ?? [];
    let low = 0;
    let high = list.length - 1;
    let found = -1;
    while (low <= high) {
      const middle = (low + high) >> 1;
      if ((list[middle] ?? 0) > after) {
        found = list[middle] ?? -1;
        high = middle - 1;
      } else low = middle + 1;
    }
    return found;
  };
  const knownEmpty = (source: string, ordinal: number, inline: boolean): boolean => {
    const value = source.trim();
    if (PYTHON_EMPTY_SOURCE_PATTERN.test(value) || pythonZeroLengthSlice(value)) return true;
    if (/^[A-Za-z_]\w*$/.test(value) && !listNames.has(value) && !inline) {
      const bound = lastBinding.get(value);
      // goal_cejel_v27_a1_restore_proof_v2_2026-11-02, item C: the binding must be the name's first
      // mention in the hook, at any depth; a closure defined before it may fill the list it binds.
      if (bound !== undefined && emptyBinding.get(bound) === true && (mentionedAt.get(value) ?? [])[0] === bound) {
        const next = firstMentionAfter(value, bound);
        if (next === -1 || next >= ordinal) return true;
      }
    }
    if (state !== 'empty') return false;
    if (listNames.has(value)) return true;
    const copied = pythonFullCopyOf(value) ?? /^reversed[ \t]*\([ \t]*([A-Za-z_]\w*)[ \t]*\)$/.exec(value)?.[1];
    if (copied !== undefined && listNames.has(copied)) return true;
    if (value.startsWith('[') && value.endsWith(']')) {
      return pythonNameMentions(value, listNames).some(({ at }) => pythonIdentifierBefore(value, at)?.name === 'in');
    }
    return false;
  };
  const savedProof = (name: string): boolean =>
    helper !== undefined
      ? helper.sources.has(name) && (occurrences.get(name) ?? 0) === (restoreUses.get(name) ?? 0)
      : copies.has(name) && (occurrences.get(name) ?? 0) === 1 + (restoreUses.get(name) ?? 0);
  const setUnknown = (statement: PythonCodeStatement) => {
    if (state === 'unknown') return;
    state = 'unknown';
    reason = statement.shown;
  };
  // goal_cejel_v27_a1_restore_proof_v2_2026-11-02, item F: the closure names are kept as one set,
  // updated where a closure or local function is bound, not rebuilt for every statement (which
  // made a body of N stored lambdas cost N squared).
  const closureNameSet = new Set<string>();
  const refreshClosureName = (name: string): void => {
    if (closures.has(name) || localFunctions.get(name) === null) closureNameSet.add(name);
    else closureNameSet.delete(name);
  };
  const closureNames = (): ReadonlySet<string> => closureNameSet;

  const classify = (statement: PythonCodeStatement, ordinal: number, inline: boolean): PythonListUse => {
    const code = statement.code;
    const mentions = pythonNameMentions(code, listNames);
    const closureMentions = pythonNameMentions(code, closureNames());
    if (PYTHON_ITEMS_ATTRIBUTE_PATTERN.test(code)) return { use: 'unknown' };
    // pytest's session holds the same list (session.items), so once the list is emptied or put back,
    // a use of the session, or of any object's session, may change it.
    if (
      (state === 'empty' || state === 'restored') &&
      (pythonNameMentions(code, guarded).length > 0 || PYTHON_SESSION_ATTRIBUTE_PATTERN.test(code))
    ) {
      return { use: 'unknown' };
    }
    if (mentions.length === 0 && closureMentions.length === 0) return { use: 'none' };
    const call = PYTHON_CALL_PATTERN.exec(code);
    const callee = call && callClosesAtEnd(code, call[0].length - 1) ? functionNamed(call[1] ?? '') : undefined;
    if (closureMentions.length > 0) {
      const bare = PYTHON_BARE_CALL_PATTERN.exec(code);
      if (bare && closures.has(bare[1] ?? '') && closureMentions.length === 1 && mentions.length === 0) {
        return { use: 'call', closure: bare[1] ?? '' };
      }
      return { use: 'unknown' };
    }
    if (listNames.has(PYTHON_LIST_CLEAR_PATTERN.exec(code)?.[1] ?? '') || listNames.has(PYTHON_LIST_DELETE_ALL_PATTERN.exec(code)?.[1] ?? '')) {
      return { use: 'clear' };
    }
    const add = pythonListAddForm(code, listNames);
    if (add !== undefined) {
      // goal_cejel_v27_a1_restore_proof_v2_2026-11-02, items A and D: an assignment to a slice that
      // is not the whole list (`items[0:] = []`, `items[::1] = ()`, `items[:len(items)] = ()`,
      // `items[1:] = []`) may remove any number of items, so it is never read as adding nothing.
      if (add.form === 'index' || add.form === 'slice') return { use: 'unknown' };
      const readsOnly = pythonListMentionsReadOnly(add.source, listNames);
      if (add.form === 'whole') {
        if (knownEmpty(add.source, ordinal, inline)) return { use: 'clear' };
        if (!readsOnly) return { use: 'unknown' };
        const name = pythonRestoreSourceName(add.source, helper !== undefined);
        if (name !== undefined && add.target === base && !listNames.has(name)) return { use: 'restore', source: name, replace: true };
        const copied = pythonFullCopyOf(add.source);
        if (state === 'collected' && copied !== undefined && listNames.has(copied)) return { use: 'read' };
        return { use: 'unknown' };
      }
      if (add.form !== 'one value' && knownEmpty(add.source, ordinal, inline)) return { use: 'add-empty' };
      if (!readsOnly) return { use: 'unknown' };
      if ((add.form === 'extend' || add.form === 'iadd') && add.target === base) {
        const name = pythonRestoreSourceName(add.source, helper !== undefined);
        if (name !== undefined && !listNames.has(name)) return { use: 'restore', source: name, replace: false };
      }
      return { use: 'add' };
    }
    const target = PYTHON_ASSIGNMENT_TARGET_PATTERN.exec(code)?.[1];
    const aliases = code.split('=').map((part) => part.trim());
    if (
      aliases.length >= 2 &&
      listNames.has(aliases[aliases.length - 1] ?? '') &&
      aliases.slice(0, -1).every((name) => /^[A-Za-z_]\w*$/.test(name) && !listNames.has(name))
    ) {
      return inline ? { use: 'unknown' } : { use: 'alias', names: aliases.slice(0, -1) };
    }
    if (target !== undefined && listNames.has(target)) {
      // `items = ...` (or `items, x = ...`) rebinds the name; `items *= 0` and the like change the list.
      const plain = !/^[A-Za-z_]\w*[ \t]*[-+*/%&|^@]=/.test(code);
      return plain && target === base && pythonListMentionsReadOnly(code.slice(code.indexOf('=') + 1), listNames)
        ? { use: 'rebind' }
        : { use: 'unknown' };
    }
    if (mentions.some(({ at }) => pythonIdentifierBefore(code, at)?.name === 'as' || pythonIdentifierBefore(code, at)?.name === 'for')) {
      return { use: 'unknown' };
    }
    if (callee !== undefined && call) {
      if (callee === null || depth >= PYTHON_LIST_READ_DEPTH) return { use: 'unknown' };
      return pythonHelperCallUse(callee, code.slice(call[0].length), listNames, base, scope, depth, (source) => knownEmpty(source, ordinal, inline));
    }
    return pythonListMentionsReadOnly(code, listNames) ? { use: 'read' } : { use: 'unknown' };
  };

  const apply = (use: PythonListUse, statement: PythonCodeStatement, ordinal: number, inline: number): void => {
    switch (use.use) {
      case 'none':
      case 'read':
      case 'add-empty':
        return;
      case 'clear':
        if (state === 'unknown') escape ??= reason;
        state = 'empty';
        cleared = true;
        callSinceClear = false;
        changes.push(use);
        return;
      case 'restore':
        if (!savedProof(use.source)) {
          apply({ use: 'add' }, statement, ordinal, inline);
          return;
        }
        changes.push(use);
        if (use.replace) {
          if (state === 'unknown') escape ??= reason;
          state = 'restored';
        } else if (state === 'empty' || state === 'restored') state = 'restored';
        else if (state === 'collected' || state === 'grown') state = 'grown';
        return;
      case 'add':
        changes.push(use);
        if (state === 'empty' || state === 'restored') setUnknown(statement);
        else if (state === 'collected') state = 'grown';
        return;
      case 'alias':
        for (const name of use.names) listNames.add(name);
        return;
      case 'rebind':
        if (helper === undefined && inline === 0 && listNames.size === 1 && closures.size === 0) {
          rebinds = (state === 'collected' || state === 'grown') && lastClear > ordinal;
          stopped = true;
          return;
        }
        setUnknown(statement);
        return;
      case 'call': {
        const closure = closures.get(use.closure);
        if (!closure || inline >= PYTHON_LIST_READ_DEPTH) {
          setUnknown(statement);
          return;
        }
        if ('lambda' in closure) apply(classify(closure.lambda, ordinal, true), closure.lambda, ordinal, inline + 1);
        else run(closure.from, closure.to, inline + 1);
        return;
      }
      case 'unknown':
        setUnknown(statement);
        return;
    }
  };

  const extentMentions = (from: number, to: number): boolean => {
    for (let ordinal = from; ordinal < to; ordinal += 1) {
      const code = statements[ordinal]?.code ?? '';
      if (
        pythonNameMentions(code, listNames).length > 0 ||
        pythonNameMentions(code, closureNameSet).length > 0 ||
        pythonNameMentions(code, guarded).length > 0 ||
        PYTHON_ITEMS_ATTRIBUTE_PATTERN.test(code) ||
        PYTHON_SESSION_ATTRIBUTE_PATTERN.test(code)
      ) {
        return true;
      }
    }
    return false;
  };

  // A statement inside a loop: it may run any number of times, so only a use that changes nothing
  // (or a clear of a list already empty) is read.
  const inBlock = (statement: PythonCodeStatement, ordinal: number): void => {
    if (PYTHON_NESTED_DEF_PATTERN.test(statement.code) || PYTHON_CLASS_PATTERN.test(statement.code) || /\blambda\b/.test(statement.code)) {
      if (extentMentions(ordinal, ordinal + 1)) setUnknown(statement);
      return;
    }
    const use = classify(statement, ordinal, true);
    if (use.use === 'none' || use.use === 'read' || use.use === 'add-empty') return;
    if (use.use === 'clear' && state === 'empty') return;
    setUnknown(statement);
  };

  function run(from: number, to: number, inline: number): void {
    for (let ordinal = from; ordinal < to && !stopped; ) {
      const statement = statements[ordinal] as PythonCodeStatement;
      let end = ordinal + 1;
      while (end < to && (statements[end]?.indent ?? 0) > statement.indent) end += 1;
      const code = statement.code;
      if (/^return\b/.test(code)) {
        // Only a helper reaches here (the hook's conditional rule stops a `return`): the rest of the
        // body does not run. A return in an inlined closure ends only the closure, which is not read.
        if (helper === undefined || inline > 0 || extentMentions(ordinal, end)) setUnknown(statement);
        stopped = helper !== undefined && inline === 0;
        return;
      }
      if (helper !== undefined && PYTHON_DEAD_IF_PATTERN.test(code) && !/^(?:elif|else)\b/.test(statements[end]?.code ?? '')) {
        ordinal = end;
        continue;
      }
      if (PYTHON_HELPER_BRANCH_PATTERN.test(code)) {
        if (/^raise\b/.test(code) || extentMentions(ordinal, end)) setUnknown(statement);
        ordinal = end;
        continue;
      }
      const nested = PYTHON_NESTED_DEF_PATTERN.exec(code) ?? PYTHON_CLASS_PATTERN.exec(code);
      if (nested) {
        const name = nested[1] ?? '';
        const header = PYTHON_CLASS_PATTERN.test(code) ? undefined : pythonDefHeader([code], 0);
        const parameters = header?.parameters.map(pythonParameterName) ?? ['*'];
        const captures = extentMentions(ordinal + 1, end) || (header?.inline ?? '') !== '';
        closures.delete(name);
        localFunctions.delete(name);
        if (header !== undefined && parameters.length === 0 && header.inline === '') {
          if (captures) closures.set(name, { from: ordinal + 1, to: end });
        } else if (captures || header === undefined || header.inline !== '') {
          localFunctions.set(name, null);
        } else {
          localFunctions.set(name, { parameters, body: statements.slice(ordinal + 1, end), effects: new Map() });
        }
        refreshClosureName(name);
        ordinal = end;
        continue;
      }
      const lambda = PYTHON_LAMBDA_BINDING_PATTERN.exec(code);
      if (lambda) {
        const name = lambda[1] ?? '';
        const body = pythonLambdaBody(lambda[2] ?? '');
        closures.delete(name);
        if (extentMentions(ordinal, ordinal + 1)) {
          closures.set(name, body === undefined || inline > 0 ? null : { lambda: { ...statement, code: body } });
        }
        refreshClosureName(name);
        ordinal = end;
        continue;
      }
      const loop = pythonForLoop(code);
      if (loop) {
        // The header with its `in`, so a loop over the list itself reads it, and a loop rebinding a list name does not.
        const head = code.slice(0, code.length - loop.body.length);
        if (!pythonListMentionsReadOnly(head, listNames) || pythonNameMentions(head, closureNames()).length > 0) {
          setUnknown(statement);
        } else if (!knownEmpty(loop.source, ordinal, inline > 0)) {
          if (loop.body !== '') inBlock({ ...statement, code: loop.body }, ordinal);
          for (let inner = ordinal + 1; inner < end; inner += 1) inBlock(statements[inner] as PythonCodeStatement, inner);
        }
        ordinal = end;
        continue;
      }
      if (code.startsWith('@')) {
        if (extentMentions(ordinal, ordinal + 1)) setUnknown(statement);
        ordinal += 1;
        continue;
      }
      const binding = inline === 0 ? PYTHON_SIMPLE_BINDING_PATTERN.exec(code) : null;
      const bound = binding?.[1];
      const value = (binding?.[2] ?? '').trim();
      const emptyValue = bound !== undefined && knownEmpty(value, ordinal, false);
      const fullCopy = bound !== undefined && state === 'collected' && listNames.has(pythonFullCopyOf(value) ?? '');
      const calls = pythonCallsOtherThanReadOnlyBuiltin(code);
      const use = classify(statement, ordinal, inline > 0);
      apply(use, statement, ordinal, inline);
      if (bound !== undefined && !listNames.has(bound)) {
        lastBinding.set(bound, ordinal);
        emptyBinding.set(ordinal, emptyValue);
        if (fullCopy) copies.add(bound);
      }
      if (calls && use.use !== 'clear') callSinceClear = true;
      for (let inner = ordinal + 1; inner < end; inner += 1) inBlock(statements[inner] as PythonCodeStatement, inner);
      ordinal = end;
    }
  }

  if (statements.length > 0) run(0, statements.length, 0);
  // `run` changes these through closures, which the compiler does not follow.
  const ended = state as PythonListState;
  if (escape !== undefined && (callSinceClear as boolean) && (ended === 'empty' || ended === 'restored')) {
    return { state: 'unknown', reason: escape, cleared, rebinds, changes };
  }
  return { state: ended, ...(reason === undefined ? {} : { reason }), cleared, rebinds, changes };
}

/** A lambda's body expression when it takes no parameters, or undefined. */
function pythonLambdaBody(afterLambda: string): string | undefined {
  const colon = /^[ \t]*:(.*)$/.exec(afterLambda);
  return colon ? (colon[1] ?? '').trim() : undefined;
}

/** A call's arguments by the callee's parameter position, or undefined where they cannot be mapped (`*` arguments, an unknown keyword). */
function pythonMapArguments(fn: PythonFunction, afterParen: string): Map<number, string> | undefined {
  const mapped = new Map<number, string>();
  let position = 0;
  for (const argument of pythonCallArguments(afterParen)) {
    if (argument.startsWith('*')) return undefined;
    const keyword = /^([A-Za-z_]\w*)[ \t]*=(?!=)[ \t]*(.*)$/.exec(argument);
    if (keyword) {
      const at = fn.parameters.indexOf(keyword[1] ?? '');
      if (at === -1 || mapped.has(at)) return undefined;
      mapped.set(at, (keyword[2] ?? '').trim());
      continue;
    }
    const parameter = fn.parameters[position];
    if (parameter === undefined || parameter === '' || parameter === '*' || mapped.has(position)) return undefined;
    mapped.set(position, argument);
    position += 1;
  }
  return mapped;
}

/** What a call of a same-file function, given the list, does to it, as a use of the list. */
function pythonHelperCallUse(
  fn: PythonFunction,
  afterParen: string,
  listNames: ReadonlySet<string>,
  base: string,
  scope: PythonModuleScope,
  depth: number,
  knownEmpty: (source: string) => boolean,
): PythonListUse {
  const mapped = pythonMapArguments(fn, afterParen);
  if (mapped === undefined) return { use: 'unknown' };
  const given = [...mapped].filter(([, argument]) => listNames.has(argument));
  for (const [, argument] of mapped) {
    if (!listNames.has(argument) && !pythonListMentionsReadOnly(argument, listNames)) return { use: 'unknown' };
  }
  if (given.length === 0) return { use: 'read' };
  const [entry] = given;
  if (given.length > 1 || entry === undefined) return { use: 'unknown' };
  const [position, argument] = entry;
  const effect = pythonParameterEffect(fn, position, scope, depth);
  if (!('from' in effect)) return { use: effect.effect === 'none' ? 'read' : effect.effect === 'clear' ? 'clear' : 'unknown' };
  const source = mapped.get(effect.from);
  if (source === undefined) return { use: 'unknown' };
  if (knownEmpty(source)) return effect.effect === 'add-from' ? { use: 'add-empty' } : { use: 'clear' };
  const name = pythonRestoreSourceName(source, false);
  if (name !== undefined && argument === base && !listNames.has(name)) {
    return { use: 'restore', source: name, replace: effect.effect === 'replace-from' };
  }
  return effect.effect === 'add-from' ? { use: 'add' } : { use: 'unknown' };
}

/** What a function does to the list passed at parameter `position`, read once and kept. */
function pythonParameterEffect(fn: PythonFunction, position: number, scope: PythonModuleScope, depth: number): PythonListParameterEffect {
  const known = fn.effects.get(position);
  if (known !== undefined) return known;
  fn.effects.set(position, { effect: 'unknown' });
  const effect = readPythonParameterEffect(fn, position, scope, depth);
  fn.effects.set(position, effect);
  return effect;
}

function readPythonParameterEffect(fn: PythonFunction, position: number, scope: PythonModuleScope, depth: number): PythonListParameterEffect {
  const parameter = fn.parameters[position];
  if (parameter === undefined || parameter === '' || parameter === '*' || depth >= PYTHON_LIST_READ_DEPTH) return { effect: 'unknown' };
  // A global or nonlocal binding may keep the list where a later call reaches it.
  if (fn.body.some(({ code }) => PYTHON_GLOBAL_STATEMENT_PATTERN.test(code))) return { effect: 'unknown' };
  // A generator: calling it runs none of its body.
  if (fn.body.some(({ code }) => containsPythonIdentifier(code, 'yield'))) return { effect: 'none' };
  const sources = new Set(fn.parameters.filter((name, at) => at !== position && name !== '' && name !== '*'));
  const reading = readPythonList(fn.body, parameter, scope, { sources }, depth + 1);
  if (reading.state === 'unknown' || reading.rebinds) return { effect: 'unknown' };
  if (reading.changes.length === 0) return { effect: 'none' };
  if (reading.state === 'empty') return { effect: 'clear' };
  const last = reading.changes[reading.changes.length - 1];
  if (last?.use !== 'restore' || !sources.has(last.source)) return { effect: 'unknown' };
  const from = fn.parameters.indexOf(last.source);
  if (reading.state === 'restored' && (last.replace || reading.changes.some(({ use }) => use === 'clear'))) return { effect: 'replace-from', from };
  if (reading.state === 'grown' && reading.changes.length === 1 && !last.replace) return { effect: 'add-from', from };
  return { effect: 'unknown' };
}

// ---- Outcome 2 as an allowlist (goal_cejel_v27_a1_restore_proof_v2_2026-11-02) ---------------
//
// A hook puts the collected items back (outcome 2) only when every statement of its body (after a
// hookwrapper's yield; before it, only docstrings) is one of these shapes, at the body's own
// indent, in this order of effect:
//   - a copy binding `S = list(items)`, `S = items[:]`, `S = items.copy()`, `S = [*items]` or
//     `S = tuple(items)`, before anything empties the list, with S mentioned at most once more in
//     the hook (`list` and `tuple` count only where the module binds neither name anywhere);
//   - an emptying `items.clear()`, `del items[:]` or `items[:] = []`;
//   - a restore after an emptying, from a copy not used yet: `items.extend(S)`, `items += S`,
//     `items[:] = S` or `items[:] = S[:]`;
//   - a call of a same-file helper read strictly (pytestStrictRestoreHelper) given `items` and a
//     copy not used yet;
//   - a docstring (a statement that is only string literals).
// It ends with the list put back. Anything else (a lambda, a nested or async def, a decorator,
// `sorted`, a slice, another name for the list, exec, getattr, an f-string field, ...) is outside
// the allowlist, and the hook is not credited with outcome 2.
//
// The review of #644 at bca7ebfbf: an allowlist that admits a call trusts every name the call can
// reach. So it admits no report call (`config.hook.pytest_deselected(...)`, which any conftest.py
// or plugin may implement; `print` and logging calls, which run handlers and their arguments'
// `__str__`), and a hook whose body passes is still refused where its conftest.py can rebind a name
// the allowlist trusts without spelling it (pythonModuleRebindHazard): a star import, `setattr`,
// `builtins` or `__builtins__`, `sys.modules`, a module `__getattr__`, or an assignment to `list`
// or `tuple` through an attribute. Each such hook is named (outcome 3), never credited.

/** A name read as Python's own builtin, or exec-like access the reader cannot follow. */
const PYTHON_DYNAMIC_ACCESS_PATTERN =
  /(?<![\w.])(?:exec|eval|compile|getattr|setattr|delattr|globals|locals|vars|__import__|__builtins__)\b|\.[ \t]*__dict__\b/;
const PYTHON_STRING_ONLY_PATTERN = /^(?:""[ \t]*)+$/;
// A conftest.py naming any of these, bare or as an attribute, may rebind a name the allowlist
// trusts without spelling it: setattr(sys.modules[__name__], "li" + "st", ...), builtins.print = ...,
// __builtins__["list"] = ..., vars(module)[...], a module __getattr__ (#644 review at bca7ebfbf).
const PYTHON_REBIND_HAZARD_NAMES: ReadonlySet<string> = new Set([
  'setattr', 'delattr', '__setattr__', '__delattr__', 'builtins', '__builtins__', 'modules', '__dict__',
  '__globals__', '__getattr__', '__getattribute__', '__import__', 'importlib',
]);
// The same, read only where the name is bare (Python's builtin), not an attribute (`re.compile`).
const PYTHON_REBIND_HAZARD_BUILTINS: ReadonlySet<string> = new Set(['exec', 'eval', 'compile', 'globals', 'vars', 'locals']);
// Names the allowlist trusts as Python's builtins: an attribute of that name other than a call
// (`conftest.list = ...`, `sys.modules[__name__].tuple = ...`) may bind the module's global.
const PYTHON_TRUSTED_BUILTINS: ReadonlySet<string> = new Set(['list', 'tuple']);
const PYTHON_REBINDING_KEYWORDS: ReadonlySet<string> = new Set(['for', 'as', 'def', 'class', 'import', 'global', 'nonlocal']);

/** A same-file helper the allowlist reads: which parameter it fills, from which, and whether it empties first. */
interface PythonStrictHelper {
  readonly parameters: readonly string[];
  readonly list: number;
  readonly source: number;
  readonly replaces: boolean;
  /** True where its restore copies through a builtin call (`list(src)`, `tuple(src)`). */
  readonly callsBuiltin: boolean;
}

// goal_cejel_v27_a1_gaps_2026-11-03, item A (#646). A copy that calls a builtin (`list(items)`,
// `tuple(items)`) is the builtin's result, and any module pytest imports (one the conftest.py
// imports, another conftest.py, a plugin) can replace `builtins.list` at import time. The copy forms
// that call no builtin (`items[:]`, `items.copy()`, `[*items]`) are read from the list's own type,
// which cannot be patched. The review of #655, blocker 3: a module can reach builtins, or the
// conftest module's own `list`, without spelling `builtins` as a word (`f_builtins`, a fullwidth
// letter Python folds under NFKC, `sys.modules` with a joined name, `getattr`, a frame's globals,
// `conftest.list = ...`), and the file list A1 walks leaves out vendor/, build/, dist/, venv/,
// coverage/ and the like. So a builtin copy is credited only where no file the repository tracks,
// in any directory, is a Python source (read under NFKC, code, strings and comments alike) naming
// one of PYTHON_BUILTINS_REACH_PATTERN, or a compiled or archived module Cejel cannot read; and
// where those files can be listed and read. A module installed from outside the repository (an
// entry-point plugin, a sitecustomize, a .pth file in site-packages) is not read, nor is a way of
// reaching builtins the pattern does not list.
const PYTHON_BUILTIN_COPY_CALL_PATTERN = /^(?:list|tuple)[ \t]*\(/;
// One sweep for: `builtins` anywhere (builtins, __builtins__, f_builtins); a module, frame or
// namespace reached by a computed name; Python's own exec, eval, compile, globals, vars and locals,
// not an attribute (`re.compile`); an attribute named list or tuple that is not called.
const PYTHON_BUILTINS_REACH_PATTERN =
  /builtins|(?<![A-Za-z0-9_])(?:modules|__dict__|__globals__|__getattr__|__getattribute__|__setattr__|__delattr__|__import__|importlib|setattr|delattr|getattr|attrgetter|_getframe|currentframe|f_globals|f_locals|f_back|tb_frame|gi_frame|cr_frame|ag_frame|gc|ctypes|__subclasses__|pickle|marshal|runpy|__loader__|__spec__)(?![A-Za-z0-9_])|(?<![A-Za-z0-9_.])(?:exec|eval|compile|globals|vars|locals)(?![A-Za-z0-9_])|\.[ \t]*(?:list|tuple)(?![A-Za-z0-9_])(?![ \t]*\()/;
const PYTHON_SOURCE_FILE_PATTERN = /\.(?:py|pyw|pyx|pxd|pxi)$/i;
// A module Python can import whose code Cejel cannot read: bytecode, an extension, an archive, a .pth.
const PYTHON_UNREAD_MODULE_FILE_PATTERN = /\.(?:pyc|pyo|so|pyd|egg|whl|zip|pth)$/i;

/**
 * The review of #655, blocker 3: every file the repository tracks, in any directory (A1's file list
 * leaves out vendor/, build/, dist/, venv/, coverage/ and the like), or undefined where they cannot
 * be listed. Outside Git, every file under the root but .git. Linear in the files.
 */
function filesIncludingExcluded(repoPath: string): readonly string[] | undefined {
  const tracked = readGitTrackedFileOutput(repoPath);
  if (tracked.ok) return tracked.stdout.split('\n').filter((line) => line !== '');
  if (!isExpectedGitAbsence(tracked)) return undefined;
  const files: string[] = [];
  const pending = [''];
  for (let next = pending.pop(); next !== undefined; next = pending.pop()) {
    let entries: Dirent[];
    try {
      entries = readdirSync(join(repoPath, next), { withFileTypes: true });
    } catch {
      return undefined;
    }
    for (const entry of entries) {
      const path = next === '' ? entry.name : `${next}/${entry.name}`;
      if (entry.isDirectory()) {
        if (entry.name !== '.git') pending.push(path);
      } else files.push(path);
    }
  }
  return files;
}

/**
 * The review of #655, blocker 3: why a builtin copy is not credited, as the words after "calls a
 * builtin": the first tracked file that may replace the builtin, or that the files could not be
 * listed; undefined where no file may. Linear in the files.
 */
function builtinCopyReplacedBy(repoPath: string): string | undefined {
  const files = filesIncludingExcluded(repoPath);
  if (files === undefined) return "and the repository's files could not be listed";
  for (const listed of files) {
    // git quotes a path holding unusual characters; such a file is named, not read.
    const quoted = listed.startsWith('"') && listed.endsWith('"') && listed.length > 1;
    const file = quoted ? listed.slice(1, -1) : listed;
    const unread = PYTHON_UNREAD_MODULE_FILE_PATTERN.test(file);
    if (!unread && !PYTHON_SOURCE_FILE_PATTERN.test(file)) continue;
    const replaces = `which ${a1NotePath(file)} may replace`;
    if (unread || quoted) return replaces;
    const fullPath = join(repoPath, file);
    let size: number;
    try {
      const stat = lstatSync(fullPath);
      if (!stat.isFile()) return replaces;
      size = stat.size;
    } catch {
      return replaces;
    }
    if (size > MAX_REPOSITORY_CONTENT_BYTES) return replaces;
    const text = readRepoText(fullPath, 'utf8');
    if (isGitLfsPointerText(text)) return replaces;
    // Python folds identifiers under NFKC (`ｂuiltins` is builtins); ASCII text is already folded.
    const folded = /[^\x00-\x7f]/.test(text) ? text.normalize('NFKC') : text;
    if (PYTHON_BUILTINS_REACH_PATTERN.test(folded)) return replaces;
  }
  return undefined;
}

/** What the allowlist needs to know about a conftest.py's module: read on demand, each once. */
interface PythonModuleFacts {
  /** True where the module never binds `name` (every mention a call or a subscript, never in a def, class or string). */
  readonly unbound: (name: string) => boolean;
  /** The first statement of the module that may rebind a name the allowlist trusts without spelling it, or undefined. */
  readonly hazard: () => PythonCodeStatement | undefined;
  /** The helper `name` read strictly, where the hook mentions it `hookMentions` times; undefined otherwise. */
  readonly helper: (name: string, hookMentions: number) => PythonStrictHelper | undefined;
}

/** Each place `code` names `name` as a variable (not an attribute), with the character after it. Linear. */
function pythonBareMentions(code: string, name: string): { readonly at: number; readonly next: string; readonly before: string }[] {
  const found: { at: number; next: string; before: string }[] = [];
  if (!code.includes(name)) return found;
  for (const match of code.matchAll(PYTHON_IDENTIFIER_PATTERN)) {
    if (match[0] !== name) continue;
    const at = match.index ?? 0;
    if (code[pythonIndexBefore(code, at)] === '.') continue;
    const after = pythonIndexAfter(code, at + name.length);
    found.push({ at, next: code.slice(after, after + 2), before: pythonIdentifierBefore(code, at)?.name ?? '' });
  }
  return found;
}

function pythonModuleFacts(source: PythonSourceLines): PythonModuleFacts {
  const masked = source.masked;
  const logical = pythonLogicalLines(source);
  const topLevel = logical
    .filter(({ first }) => pythonLineIndent(source, first) === 0)
    .map(({ first, last }) => ({ first, last, code: masked.slice(first, last + 1).map((line) => line.trim()).join(' ') }));
  const mentions = (name: string) => masked.flatMap((code) => pythonBareMentions(code, name));
  const named = (name: string) => source.strings.some((list) => list.some((text) => containsPythonIdentifier(text, name)));
  const cache = new Map<string, boolean>();
  const unbound = (name: string): boolean => {
    const known = cache.get(name);
    if (known !== undefined) return known;
    const result =
      !named(name) &&
      mentions(name).every(({ next, before }) => (next.startsWith('(') || next.startsWith('[')) && before !== 'def' && before !== 'class');
    cache.set(name, result);
    return result;
  };
  let hazardRead = false;
  let hazardFound: PythonCodeStatement | undefined;
  const hazard = (): PythonCodeStatement | undefined => {
    if (!hazardRead) {
      hazardRead = true;
      hazardFound = pythonModuleRebindHazard(source);
    }
    return hazardFound;
  };
  const helper = (name: string, hookMentions: number): PythonStrictHelper | undefined => {
    if (!/^[A-Za-z_]\w*$/.test(name) || named(name)) return undefined;
    // Bound nowhere else: its one `def` and the hook's mentions are every mention, at any indent,
    // and no attribute of that name is written (`conftest.refill = ...` rebinds the global).
    if (mentions(name).length !== 1 + hookMentions) return undefined;
    if (masked.some((code) => pythonAttributeMentions(code, name).length > 0)) return undefined;
    const defs = topLevel.filter(({ code }) => new RegExp(`^def[ \\t]+${name}[ \\t]*\\(`).test(code));
    const definition = defs[0];
    if (defs.length !== 1 || definition === undefined) return undefined;
    // Undecorated: the logical line above it is not a decorator.
    const above = logical.filter(({ last }) => last < definition.first && pythonLineIndent(source, last) !== -1).pop();
    if (above !== undefined && (masked[above.first] ?? '').trimStart().startsWith('@')) return undefined;
    const header = pythonDefHeader(masked, definition.first);
    if (header === undefined || header.inline !== '') return undefined;
    const parameters = header.parameters.map(pythonParameterName);
    if (parameters.length !== 2 || parameters.some((parameter) => parameter === '' || parameter === '*')) return undefined;
    const body = pythonCodeStatements(source, header.bodyStart, pythonBlockEnd(source, header.bodyStart, 0));
    if ('stop' in body) return undefined;
    const statements = body.filter(({ code }) => !PYTHON_STRING_ONLY_PATTERN.test(code));
    if (statements.length === 0 || statements.length > 2 || statements.some(({ indent }) => indent !== body[0]?.indent)) return undefined;
    const restore = statements[statements.length - 1] as PythonCodeStatement;
    for (const [list, from] of [
      [0, 1],
      [1, 0],
    ] as const) {
      const target = parameters[list] ?? '';
      const origin = parameters[from] ?? '';
      const emptying = statements.length === 2 ? statements[0] : undefined;
      if (emptying !== undefined && !pythonEmptiesList(emptying.code, target)) continue;
      const restored = pythonRestoreFrom(restore.code, target, unbound);
      if (restored === undefined || restored.copy !== origin) continue;
      return {
        parameters,
        list,
        source: from,
        replaces: emptying !== undefined || restored.replace,
        callsBuiltin: PYTHON_BUILTIN_COPY_CALL_PATTERN.test(restored.source),
      };
    }
    return undefined;
  };
  return { unbound, hazard, helper };
}

/** Each place `code` names `name` as an attribute (after a `.`), with the two characters after it. Linear. */
function pythonAttributeMentions(code: string, name: string): { readonly at: number; readonly next: string }[] {
  const found: { at: number; next: string }[] = [];
  if (!code.includes(name)) return found;
  for (const match of code.matchAll(PYTHON_IDENTIFIER_PATTERN)) {
    if (match[0] !== name) continue;
    const at = match.index ?? 0;
    if (code[pythonIndexBefore(code, at)] !== '.') continue;
    const after = pythonIndexAfter(code, at + name.length);
    found.push({ at, next: code.slice(after, after + 2) });
  }
  return found;
}

/**
 * The first logical statement of a conftest.py that may rebind a name the allowlist trusts without
 * spelling it (#644 review at bca7ebfbf), or undefined: a star import; a name of
 * PYTHON_REBIND_HAZARD_NAMES anywhere, or of PYTHON_REBIND_HAZARD_BUILTINS bare; an attribute named
 * `list` or `tuple` that is not called. A module that cannot be split into statements is a hazard.
 * Read from code with strings blanked and comments dropped. Linear in the text.
 */
function pythonModuleRebindHazard(source: PythonSourceLines): PythonCodeStatement | undefined {
  const statements = pythonCodeStatements(source, 0, source.masked.length);
  if ('stop' in statements) return { indent: 0, code: '', shown: statements.stop, first: 0, last: 0 };
  for (const statement of statements) {
    const code = statement.code;
    if (/^from\b/.test(code) && code.includes('*')) return statement;
    for (const match of code.matchAll(PYTHON_IDENTIFIER_PATTERN)) {
      const name = match[0];
      const at = match.index ?? 0;
      if (at > 0 && /\w/.test(code[at - 1] ?? '')) continue;
      if (PYTHON_REBIND_HAZARD_NAMES.has(name)) return statement;
      const attribute = code[pythonIndexBefore(code, at)] === '.';
      if (!attribute && PYTHON_REBIND_HAZARD_BUILTINS.has(name)) return statement;
      if (attribute && PYTHON_TRUSTED_BUILTINS.has(name) && code[pythonIndexAfter(code, at + name.length)] !== '(') return statement;
    }
  }
  return undefined;
}

/** True when `code` is `<list>.clear()`, `del <list>[:]` or `<list>[:] = []`. */
function pythonEmptiesList(code: string, list: string): boolean {
  if (PYTHON_LIST_CLEAR_PATTERN.exec(code)?.[1] === list || PYTHON_LIST_DELETE_ALL_PATTERN.exec(code)?.[1] === list) return true;
  const add = pythonListAddForm(code, new Set([list]));
  return add?.form === 'whole' && /^\[[ \t]*\]$/.test(add.source);
}

/**
 * The copy a statement restores `<list>` from: `<list>.extend(X)`, `<list> += X` or `<list>[:] = X`,
 * where X is a name S, `S[:]`, `list(S)` or `tuple(S)` (where those are unbound), `[*S]` or
 * `S.copy()`. `copy` is S; `source` is X as written; `replace` is true for the slice assignment.
 */
function pythonRestoreFrom(
  code: string,
  list: string,
  unbound: (name: string) => boolean,
): { readonly copy: string; readonly source: string; readonly replace: boolean; readonly helperCopy: boolean } | undefined {
  const add = pythonListAddForm(code, new Set([list]));
  if (add === undefined || add.target !== list || (add.form !== 'extend' && add.form !== 'iadd' && add.form !== 'whole')) return undefined;
  const source = add.source.trim();
  const bare = /^([A-Za-z_]\w*)(?:[ \t]*\[[ \t]*:[ \t]*\])?$/.exec(source);
  if (bare) return { copy: bare[1] ?? '', source, replace: add.form === 'whole', helperCopy: false };
  const copied = pythonItemsCopyOf(source, unbound);
  return copied === undefined ? undefined : { copy: copied, source, replace: add.form === 'whole', helperCopy: true };
}

/** The name `value` is a full copy of, in the allowlist's shapes, or undefined (sorted is never one). */
function pythonItemsCopyOf(value: string, unbound: (name: string) => boolean): string | undefined {
  const call = /^(list|tuple)[ \t]*\([ \t]*([A-Za-z_]\w*)[ \t]*\)$/.exec(value);
  if (call) return unbound(call[1] ?? '') ? call[2] : undefined;
  return (
    /^([A-Za-z_]\w*)[ \t]*\[[ \t]*:[ \t]*\]$/.exec(value)?.[1] ??
    /^([A-Za-z_]\w*)[ \t]*\.[ \t]*copy[ \t]*\([ \t]*\)$/.exec(value)?.[1] ??
    /^\[[ \t]*\*[ \t]*([A-Za-z_]\w*)[ \t]*,?[ \t]*\]$/.exec(value)?.[1]
  );
}

/**
 * True when a statement may bind `name` itself: as a target of `=` (not a subscript or attribute of
 * it), after for, as, def, class, import, global or nonlocal, in an import's names, after a bare
 * `del`, or before `:=`. Conservative: any doubt reads as a rebinding. Linear in the statement.
 */
function pythonStatementMayRebind(code: string, name: string): boolean {
  const mentions = pythonBareMentions(code, name);
  if (mentions.length === 0) return false;
  if (/^(?:import|from)\b/.test(code)) return true;
  // The `for` and ` in ` words, in order, swept once beside the mentions (which are in order too).
  const words = [...code.matchAll(/\bfor\b|[ \t]in(?=[ \t([])/g)].map((match) => ({ at: match.index ?? 0, isFor: match[0] === 'for' }));
  let word = 0;
  let inForTarget = false;
  for (const { at, next, before } of mentions) {
    if (PYTHON_REBINDING_KEYWORDS.has(before)) return true;
    if (before === 'del' && !next.startsWith('[') && !next.startsWith('.')) return true;
    if (next === ':=') return true;
    // A for target list (`for x, items in ...`, in a statement or a comprehension): after a `for`
    // with no ` in ` since.
    while (word < words.length && (words[word]?.at ?? 0) < at) {
      inForTarget = words[word]?.isFor === true;
      word += 1;
    }
    if (inForTarget) return true;
  }
  // A target of `=`: everything before the last top-level `=` that is an assignment.
  let depth = 0;
  let lastAssignment = -1;
  for (let index = 0; index < code.length; index += 1) {
    const character = code[index];
    if (character === '(' || character === '[' || character === '{') depth += 1;
    else if (character === ')' || character === ']' || character === '}') depth -= 1;
    else if (
      character === '=' &&
      depth === 0 &&
      code[index + 1] !== '=' &&
      !'=!<>:+-*/%&|^@'.includes(code[index - 1] ?? '')
    ) {
      lastAssignment = index;
    }
  }
  if (lastAssignment === -1) return false;
  return mentions.some(({ at, next }) => at < lastAssignment && !next.startsWith('[') && !next.startsWith('.'));
}

/**
 * Why the allowlist does not credit a hook: the first statement outside it, or none where the body
 * ends without the list put back. A credited body names its first statement that copies through a
 * builtin call, if any (item A).
 */
type PytestAllowlistVerdict =
  | { readonly restores: true; readonly builtin?: PythonCodeStatement }
  | { readonly restores: false; readonly at?: PythonCodeStatement };

function pytestHookRestoreAllowlist(
  body: readonly PythonCodeStatement[],
  before: readonly PythonCodeStatement[],
  parameters: readonly string[],
  facts: PythonModuleFacts,
): PytestAllowlistVerdict {
  const refuse = (at?: PythonCodeStatement): PytestAllowlistVerdict => ({ restores: false, ...(at === undefined ? {} : { at }) });
  for (const statement of before) if (!PYTHON_STRING_ONLY_PATTERN.test(statement.code)) return refuse(statement);
  const counts = new Map<string, number>();
  for (const { code } of body) {
    for (const match of code.matchAll(PYTHON_IDENTIFIER_PATTERN)) {
      const at = match.index ?? 0;
      if ((at > 0 && /\w/.test(code[at - 1] ?? '')) || code[pythonIndexBefore(code, at)] === '.') continue;
      counts.set(match[0], (counts.get(match[0]) ?? 0) + 1);
    }
  }
  const indent = body[0]?.indent;
  let state: 'collected' | 'empty' | 'restored' = 'collected';
  const copies = new Map<string, boolean>();
  const unusedCopy = (name: string): boolean => copies.get(name) === false;
  let builtin: PythonCodeStatement | undefined;
  for (const statement of body) {
    const code = statement.code;
    if (statement.indent !== indent) return refuse(statement);
    if (PYTHON_STRING_ONLY_PATTERN.test(code)) continue;
    const binding = /^([A-Za-z_]\w*)[ \t]*=(?!=)[ \t]*(.*)$/.exec(code);
    const value = (binding?.[2] ?? '').trim();
    if (binding && pythonItemsCopyOf(value, facts.unbound) === 'items') {
      const name = binding[1] ?? '';
      if (state !== 'collected' || name === 'items' || parameters.includes(name) || copies.has(name) || (counts.get(name) ?? 0) > 2) {
        return refuse(statement);
      }
      copies.set(name, false);
      if (builtin === undefined && PYTHON_BUILTIN_COPY_CALL_PATTERN.test(value)) builtin = statement;
      continue;
    }
    if (pythonEmptiesList(code, 'items')) {
      state = 'empty';
      continue;
    }
    const restore = pythonRestoreFrom(code, 'items', facts.unbound);
    if (restore !== undefined) {
      if (restore.helperCopy || state !== 'empty' || !unusedCopy(restore.copy) || !/^[A-Za-z_]\w*(?:[ \t]*\[[ \t]*:[ \t]*\])?$/.test(restore.source)) {
        return refuse(statement);
      }
      copies.set(restore.copy, true);
      state = 'restored';
      continue;
    }
    // No report call: config.hook.*, print and logging run code outside the proved steps (#644 review).
    const call = /^([A-Za-z_]\w*)[ \t]*\(/.exec(code);
    if (call && callClosesAtEnd(code, call[0].length - 1)) {
      const callee = call[1] ?? '';
      const helper = facts.helper(callee, counts.get(callee) ?? 0);
      if (helper !== undefined) {
        const mapped = pythonMapArguments({ parameters: helper.parameters, body: [], effects: new Map() }, code.slice(call[0].length));
        const copy = mapped?.get(helper.source) ?? '';
        if (mapped === undefined || mapped.size !== 2 || mapped.get(helper.list) !== 'items' || !unusedCopy(copy)) return refuse(statement);
        if (state === 'restored' || (state === 'collected' && !helper.replaces)) return refuse(statement);
        copies.set(copy, true);
        state = 'restored';
        if (builtin === undefined && helper.callsBuiltin) builtin = statement;
        continue;
      }
    }
    return refuse(statement);
  }
  if (state !== 'restored') return refuse();
  // A body the allowlist reads whole is still refused where the module may rebind what it trusts.
  const hazard = facts.hazard();
  if (hazard !== undefined) return refuse(hazard);
  return builtin === undefined ? { restores: true } : { restores: true, builtin };
}

/** True when `code` names the hook's `items` (not as an attribute or keyword), or a `.items` attribute. */
function pytestMentionsItems(code: string): boolean {
  return pythonNameMentions(code, PYTEST_ITEMS_NAMES).length > 0 || PYTHON_ITEMS_ATTRIBUTE_PATTERN.test(code);
}

type PytestHookReading =
  | { readonly kind: 'skip' | 'clear' | 'restores' | 'rebinds' }
  /** `builtins`: why a copy through a builtin is not credited, the words after "calls a builtin" (item A; #655 review, blocker 3). */
  | { readonly kind: 'not read'; readonly reason: string; readonly builtins?: string };

/**
 * Reads the last top-level `pytest_collection_modifyitems` of a conftest.py, at line `index`: what
 * the run-wide skip rule may say about it, or undefined where it has nothing to say (the hook takes
 * no `items`, never names it, or never empties or skips it). `builtinsNamedIn` says why a builtin
 * copy may not be the items (builtinCopyReplacedBy), read only where a credit rests on one.
 */
function readPytestCollectionHook(
  source: PythonSourceLines,
  index: number,
  builtinsNamedIn: () => string | undefined = () => undefined,
): PytestHookReading | undefined {
  const lines = source.raw;
  const masked = source.masked;
  // pytest passes the collected items only to a hook that names an `items` parameter (#621); the
  // parameters may run onto later lines (#634, item D).
  const header = pythonDefHeader(masked, index);
  if (!header || !header.parameters.some((parameter) => /^[ \t]*items(?![\w])/.test(parameter))) return undefined;
  // The body ends where Python ends it: at the next logical line at column 0, never at a line a
  // string or a bracket carries there (goal_cejel_v27_a1_restore_proof_v2_2026-11-02, item B).
  const end = pythonBlockEnd(source, header.bodyStart, 0);
  const indented: (PythonHookStatement & { readonly line: number })[] = [];
  for (let next = header.bodyStart; next < end; next += 1) {
    if (source.inString[next] === true) continue;
    const raw = lines[next] ?? '';
    const trimmed = raw.trim();
    if (trimmed === '' || trimmed.startsWith('#')) continue;
    const indent = raw.length - raw.trimStart().length;
    for (const text of pythonLineStatements(stripPythonLineComment(trimmed).trim())) indented.push({ indent, text, line: next });
  }
  const logical = pythonCodeStatements(source, header.bodyStart, end);
  // exec, getattr and the like may reach the list with no mention of it in code.
  const touchesCode = (code: string) => pytestMentionsItems(code) || PYTHON_DYNAMIC_ACCESS_PATTERN.test(code);
  const touches =
    touchesCode(header.inline) ||
    ('stop' in logical ? masked.slice(header.bodyStart, end).some(touchesCode) : logical.some(({ code }) => touchesCode(code)));
  if (!touches) return undefined;
  const notRead = (reason: string): PytestHookReading => ({ kind: 'not read', reason });
  if (header.inline !== '') return notRead(pythonShownCode(header.inline));
  if ('stop' in logical) return notRead(logical.stop);
  if (source.tooDeep) return notRead('f-string');
  const decoration = pytestHookDecoration(source, index);
  if ('unread' in decoration) return notRead(decoration.unread);
  let read: readonly PythonCodeStatement[] = logical;
  let beforeYield: readonly PythonCodeStatement[] = [];
  let gatedCode: readonly PythonCodeStatement[] = logical;
  let readRaw: readonly (PythonHookStatement & { readonly line: number })[] = indented;
  if (decoration.wrapper) {
    // #632: a hookwrapper is read as the code after its single top-level yield.
    const top = logical[0]?.indent;
    const yields = logical.flatMap((statement, at) => (containsPythonIdentifier(statement.code, 'yield') ? [at] : []));
    const at = yields[0] ?? -1;
    const yielded = logical[at];
    if (yields.length !== 1 || yielded === undefined || yielded.indent !== top || !PYTEST_WRAPPER_YIELD_PATTERN.test(yielded.code)) {
      return notRead('yield');
    }
    const before = logical.slice(0, at).find(({ code }) => pytestMentionsItems(code));
    if (before !== undefined) return notRead(before.shown);
    let after = /^return\b/.test(yielded.code) ? [] : logical.slice(at + 1);
    const dropped = new Set<number>();
    for (let line = yielded.first; line <= yielded.last; line += 1) dropped.add(line);
    const tail = after[after.length - 1];
    // A new-style wrapper returns the result it was given.
    let tailStatement: PythonCodeStatement | undefined;
    if (tail !== undefined && tail.indent === top && /^return\b/.test(tail.code) && !pytestMentionsItems(tail.code)) {
      after = after.slice(0, -1);
      tailStatement = tail;
      for (let line = tail.first; line <= tail.last; line += 1) dropped.add(line);
    }
    read = after;
    beforeYield = logical.slice(0, at);
    gatedCode = logical.filter((statement) => statement !== yielded && statement !== tailStatement);
    readRaw = after.length === 0 ? [] : indented.filter(({ line }) => line > yielded.last && !dropped.has(line));
  }
  // The conditional rule reads code, strings blanked (item B): an `if` in a docstring is no condition.
  const stops = gatedCode.map(({ code }) => PYTEST_HOOK_CONDITIONAL_PATTERN.exec(code)).find((match) => match !== null);
  if (stops) return notRead(stops[0]);
  // A global or nonlocal binding may keep the list where a later call reaches it.
  const global = read.find(({ code }) => PYTHON_GLOBAL_STATEMENT_PATTERN.test(code));
  if (global !== undefined) return notRead(global.shown);
  // exec, eval, getattr, globals and the like may reach or change anything (item A, blocker 9).
  const dynamic = read.find(({ code }) => PYTHON_DYNAMIC_ACCESS_PATTERN.test(code));
  if (dynamic !== undefined) return notRead(dynamic.shown);
  const parameters = header.parameters.map(pythonParameterName);
  const session = new Set(parameters.filter((name) => name === 'session'));
  const reading = read.length === 0 ? undefined : readPythonList(read, 'items', pythonModuleScope(source), undefined, 0, session);
  // goal_cejel_v27_a1_restore_proof_v2_2026-11-02, item C: a statement that may bind the name
  // `items` itself, at or before the last statement that empties it, may leave that emptying on
  // another list, so the hook is never rated as deselecting everything (`items = copy.copy(items)`
  // then `items.clear()`, or `for items in [list(items)]:`). #626's read-only rebind keeps its own
  // withhold below.
  let lastEmptying = -1;
  read.forEach(({ code }, at) => {
    if (pythonEmptiesList(code, 'items') || PYTHON_LIST_DELETE_ALL_PATTERN.exec(code)?.[1] === 'items' || pythonListAddForm(code, PYTEST_ITEMS_NAMES)?.form === 'whole') {
      lastEmptying = at;
    }
  });
  const rebindAt = read.findIndex(({ code }) => pythonStatementMayRebind(code, 'items'));
  // An emptying the reader does not see as one (through a helper) counts as coming last.
  const rebindHazard = rebindAt !== -1 && (lastEmptying === -1 || rebindAt <= lastEmptying) && reading?.rebinds !== true;
  if (reading?.state === 'empty' && reading.cleared && !reading.rebinds && !rebindHazard) return { kind: 'clear' };
  if (!rebindHazard && hookSkipsEveryItem(readRaw, pytestHeldSkipMarkers(lines, readRaw))) return { kind: 'skip' };
  if (reading === undefined) return undefined;
  if (reading.rebinds) return { kind: 'rebinds' };
  // Outcome 2 only for a body the allowlist reads whole, and the list reading agrees.
  const allowlist = pytestHookRestoreAllowlist(read, beforeYield, parameters, pythonModuleFacts(source));
  if (allowlist.restores && reading.state === 'restored' && reading.cleared) {
    // item A (#646): a copy through a builtin call is the builtin's result, which another file may patch.
    const named = allowlist.builtin === undefined ? undefined : builtinsNamedIn();
    if (allowlist.builtin !== undefined && named !== undefined) return { kind: 'not read', reason: allowlist.builtin.shown, builtins: named };
    return { kind: 'restores' };
  }
  if (reading.state === 'unknown') return notRead(reading.reason ?? 'items');
  if (reading.state === 'empty' || (reading.state === 'restored' && reading.cleared)) {
    return notRead(allowlist.restores ? 'items' : (allowlist.at?.shown ?? 'items'));
  }
  return undefined;
}

interface PytestRunWideSkip {
  /** The conftest.py, repository-relative. */
  readonly path: string;
  /** 1-based line of the hook's `def`. */
  readonly line: number;
  /** The directory the conftest governs, '' for the repository root. */
  readonly scope: string;
  /** 'unread': a hook that touches `items` the reader could not place (outcome 3). */
  readonly kind: 'skip' | 'clear' | 'unread';
  /**
   * Set on a hook that empties `items` but may leave pytest's list holding them (item A), and on a
   * hook the reader could not read: why the rule is not applied, as A1's note says it. Such a hook
   * disables no file.
   */
  readonly withheld?: string;
  /** For an unread hook: the reason, as A1's note and evidence name it. */
  readonly unread?: string;
  /**
   * The hook may govern test files outside its directory (item E): no part of the directory is one
   * pytest skips by default, and no conftest.py names collect_ignore or pytest_ignore_collect.
   */
  readonly beyondScope: boolean;
}

/** How A1's note opens the clause naming a hook the reader could not read (outcome 3). */
const A1_HOOK_NOT_READ = 'hook not read: ';

/**
 * Finds conftest.py hooks that disable every test they collect (a `pytest_collection_modifyitems`
 * that empties the list, or loops over `items` adding a skip marker), the hooks that empty it but
 * put the items back, and the hooks the reader cannot place (goal_cejel_v27_a1_restore_proof_and_
 * hookwrapper_2026-11-02, the three outcomes above). A hook whose body never names `items` is not
 * reported; one that skips only slow tests, or only on one platform, is read as not read, never as
 * disabling the suite.
 * Exported for the scaling check in scan-path-regex-bounds.test.ts
 * (goal_cejel_v27_conftest_timing_guard_2026-11-02, item C).
 */
export function findPytestRunWideSkips(
  repoPath: string,
  repoFiles: readonly string[],
): PytestRunWideSkip[] {
  const found: Omit<PytestRunWideSkip, 'beyondScope'>[] = [];
  let ignoresCollection = false;
  // item A (#646): read once, and only where a credit rests on a builtin copy.
  let builtinsRead = false;
  let builtinsFile: string | undefined;
  const builtinsNamedIn = (): string | undefined => {
    if (!builtinsRead) {
      builtinsRead = true;
      builtinsFile = builtinCopyReplacedBy(repoPath);
    }
    return builtinsFile;
  };
  for (const file of repoFiles) {
    // Test directories are where a conftest.py lives, so only generated or vendored copies are
    // excluded here, not test paths.
    if (!PYTEST_CONFTEST_PATTERN.test(file) || GENERATED_OR_VENDOR_PATH_PATTERN.test(file)) continue;
    const fullPath = join(repoPath, file);
    if (!isRegularFile(fullPath)) continue;
    const text = readRepoText(fullPath, 'utf8');
    const source = pythonSourceLines(text);
    if (source.masked.some((code) => PYTEST_COLLECT_IGNORE_PATTERN.test(code))) ignoresCollection = true;
    // The module's hook is whatever the name is bound to last when it finishes executing. Of
    // top-level `def` statements that is the last one; any other binding of the name (an indented
    // or conditional `def`, an assignment, `del`, an import, or any other mention in code or in a
    // string other than a docstring, which Cejel does not try to rule out) may replace it, so then
    // nothing is claimed. The file is read as logical lines (goal_cejel_v27_a1_restore_proof_v2_
    // 2026-11-02, item B): a comment, or a statement that is only a string (a docstring), that names
    // the hook binds nothing.
    let last = -1;
    // Once another binding or mention is met, no module-level hook is claimed (the loop goes on
    // only to find the class hooks below).
    let blocked = false;
    // goal_cejel_v27_a1_makefile_addopts_environment_2026-11-04, item C (#634 item 3): a collection
    // hook defined as a method of a class (a plugin class registered from pytest_configure, through
    // pytest_plugins or config.pluginmanager.register) is not read. Where its body names `items` it
    // is named as not read, at its `def`. One pass: a stack of the open blocks, and of the class
    // hooks open in them, the innermost of which a line naming `items` marks.
    const classHooks: { readonly line: number; readonly className: string; touches: boolean }[] = [];
    const blocks: { readonly indent: number; readonly className?: string; readonly hook: boolean }[] = [];
    const openHooks: number[] = [];
    for (const { first, last: final } of pythonLogicalLines(source)) {
      const indent = pythonLineIndent(source, first);
      const opening = source.masked[first] ?? '';
      if (indent !== -1) {
        while (blocks.length > 0 && (blocks[blocks.length - 1]?.indent ?? 0) >= indent) {
          if (blocks.pop()?.hook === true) openHooks.pop();
        }
        const enclosing = blocks[blocks.length - 1]?.className;
        if (indent > 0 && enclosing !== undefined && PYTEST_CLASS_COLLECTION_HOOK_PATTERN.test(opening)) {
          classHooks.push({ line: first, className: enclosing, touches: false });
          openHooks.push(classHooks.length - 1);
          blocks.push({ indent, hook: true });
        } else {
          let logical = '';
          for (let line = first; line <= final; line += 1) logical += `${source.masked[line] ?? ''}\n`;
          const open = openHooks[openHooks.length - 1];
          if (open !== undefined && /\bitems\b/.test(logical)) (classHooks[open] as { touches: boolean }).touches = true;
          if (logical.trimEnd().endsWith(':')) {
            const className = /^[ \t]*class[ \t]+([A-Za-z_]\w*)/.exec(opening)?.[1];
            blocks.push({ indent, hook: false, ...(className === undefined ? {} : { className }) });
          }
        }
      }
      if (PYTEST_COLLECTION_HOOK_PATTERN.test(opening)) {
        if (!blocked) last = first;
        continue;
      }
      if (blocked) continue;
      let named = false;
      let code = '';
      for (let line = first; line <= final && !named; line += 1) {
        const masked = source.masked[line] ?? '';
        code += masked;
        named = masked.includes(PYTEST_COLLECTION_HOOK_NAME) && PYTEST_COLLECTION_HOOK_NAME_PATTERN.test(masked);
      }
      if (!named && !PYTHON_STRING_ONLY_PATTERN.test(code.trim())) {
        for (let line = first; line <= final && !named; line += 1) {
          named = (source.strings[line] ?? []).some((content) => content.includes(PYTEST_COLLECTION_HOOK_NAME));
        }
      }
      if (named) {
        last = -1;
        blocked = true;
      }
    }
    const scope = dirname(file);
    for (const hook of classHooks) {
      if (!hook.touches) continue;
      const reason = `${hook.className}.${PYTEST_COLLECTION_HOOK_NAME}`;
      found.push({
        path: file,
        line: hook.line + 1,
        scope: scope === '.' ? '' : scope,
        kind: 'unread',
        unread: reason,
        withheld: `${A1_HOOK_NOT_READ}\`${reason}\` in ${a1NotePath(file)}`,
      });
    }
    if (last === -1) continue;
    const reading = readPytestCollectionHook(source, last, builtinsNamedIn);
    if (reading === undefined) continue;
    const where = { path: file, line: last + 1, scope: scope === '.' ? '' : scope };
    if (reading.kind === 'not read') {
      const because = reading.builtins === undefined ? '' : ` calls a builtin, ${reading.builtins}`;
      found.push({
        ...where,
        kind: 'unread',
        unread: reading.reason,
        withheld: `${A1_HOOK_NOT_READ}\`${reading.reason}\` in ${a1NotePath(file)}${because}`,
      });
    } else if (reading.kind === 'restores') {
      found.push({ ...where, kind: 'clear', withheld: `the hook in ${a1NotePath(file)} puts the collected items back` });
    } else if (reading.kind === 'rebinds') {
      found.push({
        ...where,
        kind: 'clear',
        withheld: `the hook in ${a1NotePath(file)} rebinds items, so its clear may not empty pytest's list`,
      });
    } else {
      found.push({ ...where, kind: reading.kind });
    }
  }
  return found.map((skip) => ({
    ...skip,
    beyondScope: !ignoresCollection && !skip.scope.split('/').some((segment) => PYTEST_DEFAULT_NORECURSE_SEGMENT_PATTERN.test(segment)),
  }));
}

// ---- Per-test unconditional skips (witan-rubric-v27, v27 freeze change F2) -----------------
//
// A test file whose every test carries its own unconditional skip runs no test, as a run-wide skip
// leaves it (#518). Each reader claims only when it can see every test the file defines and every
// one is skipped; anything it cannot place (a test defined inside a block, an import or assignment
// that may bind a test, a class that may inherit tests, a conditional skip, a todo) makes no claim,
// so the file keeps its reading under every other rubric.

interface PerTestSkipReading {
  /** 1-based line of the first skip. */
  readonly line: number;
  /** Each skip as Cejel names it, in the order first met. */
  readonly skips: readonly string[];
}

interface PerTestSkippedFile extends PerTestSkipReading {
  readonly path: string;
}

const JS_OR_TS_TEST_SOURCE_PATTERN = /\.[cm]?[jt]sx?$/;

function readEveryTestUnconditionallySkipped(
  file: string,
  contents: string,
  pytestSettings: PytestFileSettings,
): PerTestSkipReading | undefined {
  // The Python reader assumes pytest's own test names and its skipping plugin
  // (goal_cejel_v27_a1_test_count_overmatch_2026-11-01): either set otherwise, no claim.
  if (/\.py$/.test(file)) {
    return pytestSettings.testNames !== undefined || pytestSettings.disablesSkipping !== undefined
      ? undefined
      : readEveryPythonTestSkipped(contents);
  }
  if (JS_OR_TS_TEST_SOURCE_PATTERN.test(file)) return readEveryJavaScriptTestSkipped(contents);
  return undefined;
}

/** One logical Python statement: its first line's indent and line, and its lines joined. */
interface PythonLogicalStatement {
  readonly indent: number;
  readonly line: number;
  readonly lineCount: number;
  readonly text: string;
}

/**
 * Logical statements of Python source already free of comments and string contents: a statement
 * runs on while a bracket is open. A backslash continuation, a tab in an indent, or brackets that
 * do not balance return undefined. Linear in the source.
 */
function pythonLogicalStatements(code: string): PythonLogicalStatement[] | undefined {
  const statements: PythonLogicalStatement[] = [];
  let current: { indent: number; line: number; parts: string[] } | undefined;
  let depth = 0;
  for (const [index, raw] of code.split('\n').entries()) {
    const line = raw.replace(/\r$/, '');
    if (current === undefined) {
      if (line.trim() === '') continue;
      const lead = /^[ \t]*/.exec(line)?.[0] ?? '';
      if (lead.includes('\t')) return undefined;
      current = { indent: lead.length, line: index + 1, parts: [] };
    }
    current.parts.push(line.trim());
    if (/\\[ \t]*$/.test(line)) return undefined;
    depth += pythonBracketDelta(line);
    if (depth < 0) return undefined;
    if (depth === 0) {
      statements.push({
        indent: current.indent,
        line: current.line,
        lineCount: current.parts.length,
        text: current.parts.join(' ').trim(),
      });
      current = undefined;
    }
  }
  return current === undefined ? statements : undefined;
}

/** True when the `(` at `open` closes at the last character of `text`, and not before. */
function callClosesAtEnd(text: string, open: number): boolean {
  if (text[open] !== '(') return false;
  let depth = 0;
  for (let index = open; index < text.length; index += 1) {
    const character = text[index];
    if (character === '(') depth += 1;
    else if (character === ')') {
      depth -= 1;
      if (depth === 0) return index === text.length - 1;
    }
  }
  return false;
}

// Identifiers pytest or unittest may collect: functions and methods named test*, classes Test*.
// `TestCase` is unittest's base class, not a test.
const PYTHON_TEST_NAME_PATTERN = /^(?:test|Test)/;
const PYTHON_UNBOUND_IDENTIFIER_PATTERN = /(?<![\w.])[A-Za-z_]\w*/g;
const PYTHON_DEF_PATTERN = /^(?:async[ \t]+)?def[ \t]+([A-Za-z_]\w*)/;
const PYTHON_CLASS_PATTERN = /^class[ \t]+([A-Za-z_]\w*)[ \t]*/;
const PYTHON_BLOCK_STATEMENT_PATTERN =
  /^(?:if|elif|else|for|while|try|except|finally|with|match|case|async[ \t]+(?:for|with))\b/;
// Bases a class may name and still define no test it does not show: a class with any other base may
// inherit tests from it.
const PYTHON_TEST_CLASS_PLAIN_BASES = new Set([
  '',
  'object',
  'TestCase',
  'unittest.TestCase',
  'IsolatedAsyncioTestCase',
  'unittest.IsolatedAsyncioTestCase',
]);

function isPythonTestName(name: string): boolean {
  return PYTHON_TEST_NAME_PATTERN.test(name) && name !== 'TestCase';
}

/** True when `text` names, other than as an attribute, an identifier pytest or unittest may collect. */
function namesPythonTestIdentifier(text: string): boolean {
  for (const match of text.matchAll(PYTHON_UNBOUND_IDENTIFIER_PATTERN)) {
    if (isPythonTestName(match[0])) return true;
  }
  return false;
}

/**
 * True when an import statement may bind a name pytest or unittest collects, or is a star import,
 * which may bind anything. Undefined when `text` is not an import.
 */
function pythonImportMayBindTest(text: string): boolean | undefined {
  const from = /^from[ \t]+\S+[ \t]+import[ \t]+(.*)$/.exec(text);
  const plain = from ? undefined : /^import[ \t]+(.*)$/.exec(text);
  const names = from?.[1] ?? plain?.[1];
  if (names === undefined) return undefined;
  if (names.includes('*')) return true;
  return names
    .replace(/[()]/g, ' ')
    .split(',')
    .map((item) => item.trim())
    .filter((item) => item !== '')
    .some((item) => {
      const alias = /[ \t]as[ \t]+([A-Za-z_]\w*)$/.exec(item)?.[1];
      const bound = alias ?? (item.split('.')[0] ?? '').trim();
      return isPythonTestName(bound);
    });
}

/**
 * The skip a decorator applies unconditionally, as Cejel names it, or undefined. `text` is the
 * decorator without its `@`, free of comments and string contents, whitespace removed.
 * `skipif`/`skipIf` count only with the literal condition `True`, which Python cannot rebind.
 */
function pythonUnconditionalSkipDecorator(text: string, heldSkipNames: ReadonlySet<string>): string | undefined {
  if (text === 'pytest.mark.skip') return '@pytest.mark.skip';
  const call = (prefix: string): boolean => text.startsWith(`${prefix}(`) && callClosesAtEnd(text, prefix.length);
  if (call('pytest.mark.skip')) return '@pytest.mark.skip';
  if (call('unittest.skip')) return '@unittest.skip';
  if (call('pytest.mark.skipif') && /^pytest\.mark\.skipif\(True[,)]/.test(text)) return '@pytest.mark.skipif(True)';
  if (call('unittest.skipIf') && /^unittest\.skipIf\(True,/.test(text)) return '@unittest.skipIf(True)';
  if (heldSkipNames.has(text)) return `@${text}, bound to pytest.mark.skip`;
  return undefined;
}

/**
 * The unconditional skip in a decorator stack, with its line, or undefined. The skip may sit under
 * other pytest marks, which only annotate; under any other decorator, which may replace what it
 * wraps, Cejel does not read it.
 */
function pythonSkipInDecorators(
  decorators: readonly PythonLogicalStatement[],
  heldSkipNames: ReadonlySet<string>,
): { skip: string; line: number } | undefined {
  for (const decorator of decorators) {
    const text = decorator.text.slice(1).replace(/\s+/g, '');
    const skip = pythonUnconditionalSkipDecorator(text, heldSkipNames);
    if (skip !== undefined) return { skip, line: decorator.line };
    if (!text.startsWith('pytest.mark.')) return undefined;
  }
  return undefined;
}

/**
 * Names bound once, on one line at the module's top level, to `pytest.mark.skip` (with or without
 * arguments), whose every other mention in code is a bare `@name` decorator after the binding.
 */
function pythonHeldSkipNames(code: string, statements: readonly PythonLogicalStatement[]): Set<string> {
  const bindings = new Map<string, number>();
  for (const statement of statements) {
    if (statement.indent !== 0) continue;
    const name = PYTEST_SKIP_MARKER_BINDING_PATTERN.exec(statement.text)?.[1];
    if (name === undefined) continue;
    bindings.set(name, bindings.has(name) || statement.lineCount !== 1 ? Number.NaN : statement.line);
  }
  const held = new Set<string>();
  if (bindings.size === 0) return held;
  const mentions = new Map<string, number>();
  for (const match of code.matchAll(PYTHON_UNBOUND_IDENTIFIER_PATTERN)) {
    if (bindings.has(match[0])) mentions.set(match[0], (mentions.get(match[0]) ?? 0) + 1);
  }
  // Each bare `@name` decorator: how many, and the first line.
  const uses = new Map<string, { count: number; first: number }>();
  for (const statement of statements) {
    const name = /^@([A-Za-z_]\w*)$/.exec(statement.text.replace(/\s+/g, ''))?.[1];
    if (name === undefined || !bindings.has(name)) continue;
    const seen = uses.get(name);
    uses.set(name, { count: (seen?.count ?? 0) + 1, first: seen?.first ?? statement.line });
  }
  for (const [name, line] of bindings) {
    const use = uses.get(name);
    if (Number.isNaN(line) || use === undefined || use.first < line) continue;
    if (mentions.get(name) === use.count + 1) held.add(name);
  }
  return held;
}

// v27 freeze change F3-e. unittest's loader and pytest both run a TestCase's `runTest` when the
// class defines no `test*` method; a live one is a test the reader does not count.
const PYTHON_RUN_TEST_PATTERN = /(?<!\w)runTest(?!\w)/;
// The #610 review residual C2. unittest calls a module's `load_tests(loader, tests, pattern)` to
// build the module's suite, which may add tests the reader does not see.
const PYTHON_LOAD_TESTS_PATTERN = /(?<!\w)load_tests(?!\w)/;

/**
 * The #610 review residual C1: true when a decorator is one the reader knows adds no test: an
 * unconditional skip (pythonUnconditionalSkipDecorator) or a pytest mark, which only annotates
 * (`@pytest.mark.parametrize` beside a skip, as #610 left it). Any other decorator may register
 * tests (`@register_test(CacheTest)` on a helper, `@add_contract_tests` on a TestCase), as
 * `add_contract_tests(CacheTest)` may (F3-f).
 */
function isPythonDecoratorAddingNoTest(decorator: PythonLogicalStatement, heldSkipNames: ReadonlySet<string>): boolean {
  const text = decorator.text.slice(1).replace(/\s+/g, '');
  return pythonUnconditionalSkipDecorator(text, heldSkipNames) !== undefined || text.startsWith('pytest.mark.');
}
// v27 freeze change F3-f. Words before a `(` that is not a call.
const PYTHON_PARENTHESIS_KEYWORDS: ReadonlySet<string> = new Set([
  'if', 'elif', 'while', 'for', 'in', 'not', 'and', 'or', 'is', 'return', 'assert', 'with', 'del', 'yield',
  'lambda', 'await', 'except', 'raise', 'from', 'import', 'case', 'match', 'else',
]);
const PYTHON_ASSIGNMENT_OPERATOR_PATTERN = /^(?:[-+*/%&|^@]|\/\/|\*\*|<<|>>)?=(?!=)/;
// `if __name__ == "__main__":`, as written: its body runs only when the file is run as a script.
const PYTHON_MAIN_GUARD_PATTERN =
  /^if[ \t]+(?:__name__[ \t]*==[ \t]*(['"])__main__\1|(['"])__main__\2[ \t]*==[ \t]*__name__)[ \t]*:[ \t]*(?:#.*)?\r?$/;

/**
 * True when a statement, free of comments and string contents, calls something: a `(` after a name
 * that is not one of PYTHON_PARENTHESIS_KEYWORDS, or after a `)` or `]`. Plain backward scanning
 * from each `(`, linear in the statement.
 */
function pythonStatementCalls(text: string): boolean {
  for (let open = text.indexOf('('); open !== -1; open = text.indexOf('(', open + 1)) {
    let end = open - 1;
    while (end >= 0 && (text[end] === ' ' || text[end] === '\t')) end -= 1;
    const before = text[end] ?? '';
    if (before === ')' || before === ']') return true;
    if (!/\w/.test(before)) continue;
    let start = end;
    while (start > 0 && /\w/.test(text[start - 1] ?? '')) start -= 1;
    const word = text.slice(start, end + 1);
    if (!/^[0-9]/.test(word) && !PYTHON_PARENTHESIS_KEYWORDS.has(word)) return true;
  }
  return false;
}

/** True when a statement assigns to an attribute (`CacheTest.test_put = check`, `a.b += 1`). */
function pythonAssignsAttribute(text: string): boolean {
  let end = 0;
  while (end < text.length && /[\w.]/.test(text[end] ?? '')) end += 1;
  const target = text.slice(0, end);
  return /^[A-Za-z_]/.test(target) && target.includes('.') && PYTHON_ASSIGNMENT_OPERATOR_PATTERN.test(text.slice(end).trimStart());
}

/**
 * True when a statement read outside any function body may add a test the reader does not see
 * (v27 freeze change F3-f): it calls something (a helper that adds tests to a class or module,
 * `setattr`, `globals()`) or assigns to an attribute (a test method set on a class). A name bound to
 * pytest's skip marker (pythonHeldSkipNames) and `pytestmark = ...` add no test and are not read so.
 */
function pythonStatementMayAddTest(text: string): boolean {
  if (PYTEST_SKIP_MARKER_BINDING_PATTERN.test(text) || /^pytestmark[ \t]*=/.test(text)) return false;
  return pythonStatementCalls(text) || pythonAssignsAttribute(text);
}

/**
 * Every test function and test method in a Python test file, read where pytest and unittest
 * collect them: `def test*` at the module's top level, and `def test*` at the first indent of a
 * top-level class. Each must carry an unconditional skip itself or on its class, or no claim is
 * made. Also no claim when the file defines a test elsewhere (inside a block, a nested class) or may
 * bind one another way (an import, an assignment), or a class that may inherit tests is not itself
 * skipped. Linear in the file.
 *
 * v27 freeze change F3: also no claim when the file names `runTest` (F3-e), or when a statement at
 * the top level, in a top-level block or at a class body's indent may add a test
 * (pythonStatementMayAddTest, F3-f). The body of an `if __name__ == "__main__":` block is not read
 * for that, since it does not run when the tests are collected.
 *
 * The #610 review residuals: also no claim when the file names `load_tests` (C2), or holds a
 * decorator, anywhere in the file, other than a skip form or a pytest mark (C1,
 * isPythonDecoratorAddingNoTest). Comments and strings are masked first, so a decorator or
 * `load_tests` named only there does not count.
 */
function readEveryPythonTestSkipped(contents: string): PerTestSkipReading | undefined {
  const { code } = maskCommentsAndStrings(contents, true);
  if (PYTHON_RUN_TEST_PATTERN.test(code) || PYTHON_LOAD_TESTS_PATTERN.test(code)) return undefined;
  const statements = pythonLogicalStatements(code);
  if (statements === undefined) return undefined;
  const rawLines = contents.split('\n');
  const isMainGuard = (statement: PythonLogicalStatement) =>
    statement.lineCount === 1 && PYTHON_MAIN_GUARD_PATTERN.test(rawLines[statement.line - 1] ?? '');
  let inMainGuard = false;
  const heldSkipNames = pythonHeldSkipNames(code, statements);
  if (
    statements.some(
      (statement) => statement.text.startsWith('@') && !isPythonDecoratorAddingNoTest(statement, heldSkipNames),
    )
  ) {
    return undefined;
  }
  const found: { skip: string; line: number }[] = [];
  let decorators: PythonLogicalStatement[] = [];
  // What the latest top-level statement opened: a function body (ignored: pytest does not collect
  // what a function defines), a class body, or another block.
  let opened = 'none' as 'def' | 'class' | 'block' | 'none';
  let classSkip: { skip: string; line: number } | undefined;
  let classBodyIndent: number | undefined;
  /** Reads a decorator, def, class or other statement at the top level or a class body's indent. */
  const readStatement = (statement: PythonLogicalStatement, inClass: boolean): boolean => {
    const { text } = statement;
    if (text.startsWith('@')) {
      decorators.push(statement);
      return true;
    }
    const stack = decorators;
    decorators = [];
    const def = PYTHON_DEF_PATTERN.exec(text);
    if (def) {
      if (!inClass) opened = 'def';
      if (!PYTHON_TEST_NAME_PATTERN.test(def[1] ?? '')) return true;
      const skip = (inClass ? classSkip : undefined) ?? pythonSkipInDecorators(stack, heldSkipNames);
      if (skip === undefined) return false;
      found.push(skip);
      return true;
    }
    const klass = PYTHON_CLASS_PATTERN.exec(text);
    if (klass) {
      if (inClass) return false;
      const name = klass[1] ?? '';
      const rest = text.slice(klass[0].length);
      let bases = '';
      if (rest.startsWith('(')) {
        const close = rest.indexOf(')');
        if (close === -1 || rest.indexOf('(', 1) !== -1) return false;
        bases = rest.slice(1, close);
      }
      const skip = pythonSkipInDecorators(stack, heldSkipNames);
      const plain = bases
        .split(',')
        .map((base) => base.trim())
        .every((base) => PYTHON_TEST_CLASS_PLAIN_BASES.has(base));
      if (skip === undefined && !plain) return false;
      opened = 'class';
      classSkip = skip === undefined ? undefined : { skip: `${skip.skip} on class ${name}`, line: skip.line };
      classBodyIndent = undefined;
      return true;
    }
    if (stack.length > 0) return false;
    const imported = pythonImportMayBindTest(text);
    if (imported !== undefined) {
      if (!inClass) opened = 'none';
      return !imported;
    }
    if (PYTHON_BLOCK_STATEMENT_PATTERN.test(text)) {
      if (inClass) return false;
      opened = 'block';
      inMainGuard = isMainGuard(statement);
      return !namesPythonTestIdentifier(text) && (inMainGuard || !pythonStatementMayAddTest(text));
    }
    if (!inClass) opened = 'none';
    return !namesPythonTestIdentifier(text) && !pythonStatementMayAddTest(text);
  };
  for (const statement of statements) {
    if (statement.indent === 0) {
      classSkip = undefined;
      if (!readStatement(statement, false)) return undefined;
      continue;
    }
    if (opened === 'def') continue;
    if (opened === 'block') {
      if (
        /^(?:@|class\b|(?:async[ \t]+)?def\b)/.test(statement.text) ||
        namesPythonTestIdentifier(statement.text) ||
        (!inMainGuard && pythonStatementMayAddTest(statement.text))
      ) {
        return undefined;
      }
      continue;
    }
    if (opened !== 'class') return undefined;
    classBodyIndent ??= statement.indent;
    if (statement.indent < classBodyIndent) return undefined;
    if (statement.indent > classBodyIndent) continue;
    if (!readStatement(statement, true)) return undefined;
  }
  if (decorators.length > 0 || found.length === 0) return undefined;
  const ordered = [...found].sort((left, right) => left.line - right.line);
  return { line: ordered[0]?.line ?? 1, skips: [...new Set(ordered.map(({ skip }) => skip))] };
}

// Keywords after which a `/` starts a regular expression rather than dividing.
const JS_REGEX_PRECEDING_KEYWORDS = new Set([
  'return', 'typeof', 'instanceof', 'in', 'of', 'new', 'delete', 'void', 'throw', 'case', 'do', 'else', 'yield', 'await',
]);

/**
 * JavaScript or TypeScript with comments, string, template and regular-expression literals blanked,
 * offsets and newlines kept, or undefined where the lexing is in doubt: a quote or regular
 * expression still open at the end of its line, or a comment or template never closed. A wrong
 * lexing could hide a live test call, so doubt withholds the claim. Linear in the source.
 */
function maskJavaScriptLiterals(contents: string): string | undefined {
  const output = contents.split('');
  const blank = (from: number, to: number) => {
    for (let index = from; index < to; index += 1) if (output[index] !== '\n') output[index] = ' ';
  };
  // The last significant token outside literals: '/' after it divides when it is 'x' (a value).
  let previous = '';
  let index = 0;
  while (index < contents.length) {
    const character = contents[index] ?? '';
    const next = contents[index + 1] ?? '';
    if (character === '/' && next === '/') {
      let end = contents.indexOf('\n', index);
      if (end === -1) end = contents.length;
      blank(index, end);
      index = end;
    } else if (character === '/' && next === '*') {
      const close = contents.indexOf('*/', index + 2);
      if (close === -1) return undefined;
      blank(index, close + 2);
      index = close + 2;
    } else if (character === "'" || character === '"' || character === '`' || (character === '/' && previous !== 'x')) {
      let end = index + 1;
      let inClass = false;
      let closed = false;
      while (end < contents.length) {
        const inner = contents[end] ?? '';
        if (inner === '\\') {
          end += 2;
          continue;
        }
        if (inner === '\n' && character !== '`') return undefined;
        end += 1;
        if (character === '/' && inner === '[') inClass = true;
        else if (character === '/' && inner === ']') inClass = false;
        else if (inner === character && !inClass) {
          closed = true;
          break;
        }
      }
      if (!closed) return undefined;
      if (character === '/') while (/[A-Za-z]/.test(contents[end] ?? '')) end += 1;
      blank(index, end);
      previous = 'x';
      index = end;
    } else if (/[A-Za-z_$]/.test(character)) {
      let end = index + 1;
      while (/[\w$]/.test(contents[end] ?? '')) end += 1;
      previous = JS_REGEX_PRECEDING_KEYWORDS.has(contents.slice(index, end)) ? '(' : 'x';
      index = end;
    } else if ((character === '+' || character === '-') && next === character) {
      // `++` and `--` (v27 freeze change F3-d): a `/` after either divides. After a postfix one it
      // follows a value; after a prefix one a regular expression is not an operand JavaScript
      // accepts. Read one at a time, `runs++ / 2` opened a regular expression at the slash.
      previous = 'x';
      index += 2;
    } else {
      if (/[0-9)\]]/.test(character)) previous = 'x';
      else if (!/\s/.test(character)) previous = character;
      index += 1;
    }
  }
  return output.join('');
}

// A test-framework global, its member chain (`.skip`, `.only.each`) in group 2, and the opening
// parenthesis of its call, if any, in group 3.
const JS_TEST_GLOBAL_PATTERN =
  /(?<![\w$.])(it|test|specify|fit|xit|xtest|xspecify|describe|xdescribe|fdescribe|context|xcontext|suite)(?![\w$])((?:\s*\.\s*[A-Za-z_$][\w$]*)*)\s*(\()?/g;
const JS_TEST_CASE_GLOBALS = new Set(['it', 'test', 'specify', 'fit', 'xit', 'xtest', 'xspecify']);
// Import and require bindings name the globals without calling them. Each whitespace run has one
// quantifier, so a long blank run backtracks linearly.
const JS_TEST_GLOBAL_BINDING_PATTERN =
  /\bimport\s+(?:type\s+)?(?:[A-Za-z_$][\w$]*\s*(?:,\s*)?)?(?:\{[^{}]*\}\s*|\*\s*as\s+[A-Za-z_$][\w$]*\s*)?from\b|\b(?:const|let|var)\s*\{[^{}]*\}\s*=\s*require\s*\(/g;

// v27 freeze change F3-d. Hook calls: their callbacks run around tests and register none.
const JS_TEST_HOOK_CALL_PATTERN = /(?<![\w$.])(?:beforeEach|afterEach|beforeAll|afterAll|before|after)\s*\(/g;
// JSX closes every element with `</` or `/>`. The masker would read the slash as a regular
// expression that can hide a live call (`<p>hi</p>; it('adds', ...)`).
const JSX_CLOSING_PATTERN = /<\/|\/>/;
// Words before a `(` that does not call a function the file defines or imports: keywords that take
// a parenthesis, a function expression (`function (`, `async (`), and `require(`.
const JS_PARENTHESIS_KEYWORDS: ReadonlySet<string> = new Set([
  'if', 'for', 'while', 'switch', 'catch', 'with', 'return', 'typeof', 'void', 'await', 'yield', 'in', 'of',
  'instanceof', 'delete', 'throw', 'case', 'do', 'else', 'function', 'async', 'require',
]);

/**
 * True when the `(` at `open` in masked code calls something: a name that is not one of
 * JS_PARENTHESIS_KEYWORDS and is not being declared (`function name(`), a member (`Deno.test(`,
 * `t.test(`), or a call's or index's result (`)(`, `](`, a generic `>(`). Plain backward scanning
 * over the words just before it.
 */
function isJavaScriptCallParenthesis(code: string, open: number): boolean {
  let end = open - 1;
  while (end >= 0 && /\s/.test(code[end] ?? '')) end -= 1;
  const before = code[end] ?? '';
  if (before === ')' || before === ']') return true;
  if (before === '>') return code[end - 1] !== '=';
  if (!/[\w$]/.test(before)) return false;
  let start = end;
  while (start > 0 && /[\w$]/.test(code[start - 1] ?? '')) start -= 1;
  const word = code.slice(start, end + 1);
  let previous = start - 1;
  while (previous >= 0 && /\s/.test(code[previous] ?? '')) previous -= 1;
  if (code[previous] === '.') return true;
  if (/^[0-9]/.test(word) || JS_PARENTHESIS_KEYWORDS.has(word)) return false;
  // A declaration, `function name(` or `function* name(`.
  while (previous >= 0 && /[\s*]/.test(code[previous] ?? '')) previous -= 1;
  return code.slice(Math.max(0, previous - 7), previous + 1) !== 'function' || /[\w$]/.test(code[previous - 8] ?? '');
}

/** The skip a call applies to itself or to what its callback registers, as Cejel names it. */
function javaScriptUnconditionalSkip(name: string, members: string): string | undefined {
  if (name === 'xit' || name === 'xtest' || name === 'xdescribe' || name === 'xcontext') return members === '' ? name : undefined;
  if (members !== '.skip') return undefined;
  return ['it', 'test', 'describe', 'context', 'suite'].includes(name) ? `${name}.skip` : undefined;
}

/**
 * Every test case in a JavaScript or TypeScript test file: each `it`, `test`, `specify` or `fit`
 * call, with any member chain. Each must be skipped unconditionally, as `it.skip`, `test.skip`,
 * `xit` or `xtest`, or by sitting inside the callback of a `describe.skip`, `context.skip`,
 * `suite.skip`, `xdescribe` or `xcontext` call; otherwise no claim. Also no claim when a test-case
 * global is named without being called (an alias, a property), or any call is a `.todo`, which stays out of
 * scope and keeps its reading. `skipIf`, `runIf` and every other member are not skips. Linear in
 * the file.
 *
 * v27 freeze change F3-d: also no claim where a live test may sit where the reader cannot see it.
 * That is any JSX (JSX_CLOSING_PATTERN), and any call outside the bodies of test-case and hook calls
 * that is not a test, suite or hook global, a keyword, `require` or a declaration
 * (isJavaScriptCallParenthesis). Such a call may register tests: a method (`Deno.test`, `tap.test`,
 * `t.test`, `QUnit.test`) or a helper (`behavesLikeAnAdder(sum)`), at the top level or in a suite's
 * callback.
 */
function readEveryJavaScriptTestSkipped(contents: string): PerTestSkipReading | undefined {
  if (JSX_CLOSING_PATTERN.test(contents)) return undefined;
  const masked = maskJavaScriptLiterals(contents);
  if (masked === undefined) return undefined;
  const code = masked.replace(JS_TEST_GLOBAL_BINDING_PATTERN, (binding) => ' '.repeat(binding.length));
  // Each `(`'s matching `)`, in one pass; -1 where it never closes.
  const closeOf = new Int32Array(code.length).fill(-1);
  const opens: number[] = [];
  for (let index = 0; index < code.length; index += 1) {
    if (code[index] === '(') opens.push(index);
    else if (code[index] === ')') {
      const open = opens.pop();
      if (open !== undefined) closeOf[open] = index;
    }
  }
  // Matches come in source order and suites nest, so the skipped suites still open at a match are a
  // stack, outermost first.
  const openSuites: { open: number; close: number; skip: string }[] = [];
  const sources = new Map<number, string>();
  let cases = 0;
  // F3-d: the `(` of each test, suite and hook call, and how many test-case or hook bodies cover
  // each offset (a running sum over `bodies`).
  const knownCalls = new Set<number>();
  const bodies = new Int32Array(code.length + 1);
  for (const match of code.matchAll(JS_TEST_GLOBAL_PATTERN)) {
    const name = match[1] ?? '';
    const at = match.index ?? 0;
    while ((openSuites.at(-1)?.close ?? Infinity) < at) openSuites.pop();
    // A test-case global named but not called may be aliased into a test Cejel does not see. A
    // suite global not called (a `context` variable) registers nothing.
    if (match[3] === undefined) {
      if (JS_TEST_CASE_GLOBALS.has(name)) return undefined;
      continue;
    }
    const open = at + match[0].length - 1;
    knownCalls.add(open);
    const members = (match[2] ?? '').replace(/\s+/g, '');
    if (/\.todo(?![\w$])/.test(members)) return undefined;
    const skip = javaScriptUnconditionalSkip(name, members);
    if (JS_TEST_CASE_GLOBALS.has(name)) {
      cases += 1;
      const close = closeOf[open] ?? -1;
      if (close === -1) return undefined;
      bodies[open] = (bodies[open] ?? 0) + 1;
      bodies[close + 1] = (bodies[close + 1] ?? 0) - 1;
      const suite = openSuites[0];
      if (skip !== undefined) sources.set(at, skip);
      else if (suite !== undefined) sources.set(suite.open, suite.skip);
      else return undefined;
      continue;
    }
    if (skip === undefined) continue;
    const close = closeOf[open] ?? -1;
    if (close === -1) return undefined;
    openSuites.push({ open, close, skip });
  }
  if (cases === 0) return undefined;
  for (const match of code.matchAll(JS_TEST_HOOK_CALL_PATTERN)) {
    const open = (match.index ?? 0) + match[0].length - 1;
    const close = closeOf[open] ?? -1;
    if (close === -1) return undefined;
    knownCalls.add(open);
    bodies[open] = (bodies[open] ?? 0) + 1;
    bodies[close + 1] = (bodies[close + 1] ?? 0) - 1;
  }
  let insideBodies = 0;
  for (let index = 0; index < code.length; index += 1) {
    insideBodies += bodies[index] ?? 0;
    if (code[index] !== '(' || insideBodies > 0 || knownCalls.has(index)) continue;
    if (isJavaScriptCallParenthesis(code, index)) return undefined;
  }
  const ordered = [...sources.entries()].sort(([left], [right]) => left - right);
  const first = ordered[0]?.[0] ?? 0;
  return {
    line: contents.slice(0, first).split('\n').length,
    skips: [...new Set(ordered.map(([, skip]) => skip))],
  };
}

function countFilesContaining(repoPath: string, files: readonly string[], pattern: RegExp): number {
  return files.filter((file) => fileContains(repoPath, file, pattern)).length;
}

// Counts files matching ANY of several patterns, never double-counting a file that matches more
// than one — a single RegExp with an `i` flag cannot mix case-insensitive and case-sensitive
// alternatives, so a caller that needs both (e.g. case-insensitive vendor-product words plus
// case-sensitive npm package identifiers) passes them as separate patterns here instead.
function countFilesMatchingAny(
  repoPath: string,
  files: readonly string[],
  patterns: readonly RegExp[],
): number {
  return files.filter((file) => patterns.some((pattern) => fileContains(repoPath, file, pattern)))
    .length;
}

function countPatternMatches(repoPath: string, files: readonly string[], pattern: RegExp): number {
  const flags = pattern.flags.includes('g') ? pattern.flags : `${pattern.flags}g`;
  const matcher = new RegExp(pattern.source, flags);
  let count = 0;

  for (const file of files) {
    const fullPath = join(repoPath, file);
    if (!isRegularFile(fullPath)) continue;
    count += [...readRepoText(fullPath, 'utf8').matchAll(matcher)].length;
  }

  return count;
}

function readCoveragePercent(repoPath: string, files: readonly string[]): number | null {
  for (const file of files) {
    const fullPath = join(repoPath, file);
    if (!isRegularFile(fullPath)) continue;
    const contents = readRepoText(fullPath, 'utf8');
    const summaryPercent = parseCoverageSummaryPercent(contents);
    if (summaryPercent !== null) return summaryPercent;
    const thresholdPercent = parseCoverageThresholdPercent(contents);
    if (thresholdPercent !== null) return thresholdPercent;
  }

  return null;
}

function parseCoverageSummaryPercent(contents: string): number | null {
  const parsed = parseJsonObject(contents);
  const total = parsed ? parsed.total : null;
  if (!isRecord(total)) return null;

  const percentages = ['statements', 'lines', 'branches', 'functions']
    .map((key) => {
      const bucket = total[key];
      if (!isRecord(bucket)) return null;
      return typeof bucket.pct === 'number' ? bucket.pct : null;
    })
    .filter((value): value is number => value !== null && value >= 0 && value <= 100);

  return averageNumbers(percentages);
}

function parseCoverageThresholdPercent(contents: string): number | null {
  const statementMatch = /statements\s*[:=]\s*["']?(\d+(?:\.\d+)?)/i.exec(contents);
  if (statementMatch?.[1]) return Number(statementMatch[1]);

  const percentages = [...contents.matchAll(COVERAGE_PERCENT_PATTERN)]
    .map((match) => Number(match[1]))
    .filter((value) => Number.isFinite(value) && value >= 0 && value <= 100);

  return averageNumbers(percentages);
}

function averageNumbers(values: readonly number[]): number | null {
  if (values.length === 0) return null;
  return Math.round((values.reduce((sum, value) => sum + value, 0) / values.length) * 10) / 10;
}

interface DependencySpec {
  name: string;
  version: string;
}

// Choose the manifest that parses the most dependency specs, so evidence
// pointers and the suspicious-name check target the file that actually carries
// dependencies. Falls back to the first manifest when none parse any specs
// (preserving prior behavior), and returns undefined when there are none.
function pickPrimaryDependencyManifest(
  repoPath: string,
  manifests: readonly string[],
): string | undefined {
  let best: string | undefined;
  let bestCount = -1;
  for (const candidate of manifests) {
    const count = readDependencySpecs(repoPath, [candidate]).length;
    if (count > bestCount) {
      bestCount = count;
      best = candidate;
    }
  }
  return best;
}

function readDependencySpecs(repoPath: string, manifests: readonly string[]): DependencySpec[] {
  const specs: DependencySpec[] = [];

  for (const manifest of manifests) {
    const fullPath = join(repoPath, manifest);
    if (!isRegularFile(fullPath)) continue;
    if (manifest.endsWith('package.json')) {
      specs.push(...readPackageJsonDependencySpecs(fullPath));
      continue;
    }
    if (/requirements(?:[^/]*)\.txt$/.test(manifest)) {
      specs.push(...readRequirementsDependencySpecs(fullPath));
      continue;
    }
    if (manifest.endsWith('go.mod')) {
      specs.push(...readGoModDependencySpecs(fullPath));
      continue;
    }
    if (manifest.endsWith('Cargo.toml')) {
      specs.push(...readCargoTomlDependencySpecs(fullPath));
      continue;
    }
    if (manifest.endsWith('pyproject.toml')) {
      specs.push(...readPyprojectDependencySpecs(fullPath));
      continue;
    }
    if (manifest.endsWith('Pipfile')) {
      specs.push(...readPipfileDependencySpecs(fullPath));
      continue;
    }
    if (manifest.endsWith('vcpkg.json')) {
      specs.push(...readVcpkgJsonDependencySpecs(fullPath));
      continue;
    }
    if (manifest.endsWith('conanfile.txt')) {
      specs.push(...readConanfileTxtDependencySpecs(fullPath));
      continue;
    }
    if (manifest.endsWith('conanfile.py')) {
      specs.push(...readConanfilePyDependencySpecs(fullPath));
      continue;
    }
    if (manifest.endsWith('CMakeLists.txt')) {
      specs.push(...readCMakeDependencySpecs(fullPath));
    }
  }

  return specs;
}

function readGoModDependencySpecs(path: string): DependencySpec[] {
  const specs: DependencySpec[] = [];
  const contents = readRepoText(path, 'utf8');
  // Match both block and single-line require statements
  const blockPattern = /require\s*\(([^)]+)\)/gs;
  const singlePattern = /^require\s+(\S+)\s+(\S+)/gm;

  for (const blockMatch of contents.matchAll(blockPattern)) {
    const block = blockMatch[1] ?? '';
    for (const line of block.split('\n')) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('//')) continue;
      const parts = trimmed.split(/\s+/);
      if (parts.length >= 2) {
        specs.push({ name: parts[0] ?? trimmed, version: parts[1] ?? '' });
      }
    }
  }

  for (const singleMatch of contents.matchAll(singlePattern)) {
    specs.push({ name: singleMatch[1] ?? '', version: singleMatch[2] ?? '' });
  }

  return specs;
}

function readCargoTomlDependencySpecs(path: string): DependencySpec[] {
  const specs: DependencySpec[] = [];
  const contents = readRepoText(path, 'utf8');
  // Find [dependencies] section
  const depSectionPattern =
    /^\[(?:dependencies|dev-dependencies|build-dependencies)\]([\s\S]*?)(?=^\[|(?![\s\S]))/gm;

  for (const sectionMatch of contents.matchAll(depSectionPattern)) {
    const section = sectionMatch[1] ?? '';
    for (const line of section.split('\n')) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) continue;
      // name = "version" or name = { version = "version", ... }
      const simpleMatch = /^(\w[\w-]*)\s*=\s*"([^"]+)"/.exec(trimmed);
      if (simpleMatch) {
        specs.push({ name: simpleMatch[1] ?? trimmed, version: simpleMatch[2] ?? '' });
        continue;
      }
      const tableMatch = /^(\w[\w-]*)\s*=\s*\{[^}]*version\s*=\s*"([^"]+)"/.exec(trimmed);
      if (tableMatch) {
        specs.push({ name: tableMatch[1] ?? trimmed, version: tableMatch[2] ?? '' });
      }
    }
  }

  return specs;
}

function readPyprojectDependencySpecs(path: string): DependencySpec[] {
  const specs: DependencySpec[] = [];
  const contents = readRepoText(path, 'utf8');
  // (?![\s\S]) is a JS-compatible end-of-string anchor (no char follows).
  // \z is not valid in JS regex (treated as literal 'z'), so we use this instead.

  // Poetry style: [tool.poetry.dependencies] / name = "^version"
  const poetrySectionPattern = /^\[tool\.poetry\.dependencies\]([\s\S]*?)(?=^\[|(?![\s\S]))/gm;
  for (const sectionMatch of contents.matchAll(poetrySectionPattern)) {
    const section = sectionMatch[1] ?? '';
    for (const line of section.split('\n')) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#') || trimmed.startsWith('python')) continue;
      const match = /^([\w-]+)\s*=\s*"([^"]+)"/.exec(trimmed);
      if (match) {
        specs.push({ name: match[1] ?? trimmed, version: match[2] ?? '' });
      }
    }
  }
  // PEP 621 style: [project] / dependencies = ["name>=version"]
  const pep621Pattern = /^\[project\]([\s\S]*?)(?=^\[|(?![\s\S]))/gm;
  for (const sectionMatch of contents.matchAll(pep621Pattern)) {
    const section = sectionMatch[1] ?? '';
    const depsArrayMatch = /dependencies\s*=\s*\[([\s\S]*?)\]/m.exec(section);
    if (depsArrayMatch) {
      for (const rawDep of (depsArrayMatch[1] ?? '').split(',')) {
        const dep = rawDep.replace(/["'\s]/g, '');
        if (!dep) continue;
        const nameMatch = /^([A-Za-z0-9][\w.-]*)/.exec(dep);
        const versionConstraint = firstVersionConstraint(dep);
        const depName = nameMatch?.[1];
        if (depName) {
          specs.push({ name: depName, version: versionConstraint ?? dep });
        }
      }
    }
  }

  return specs;
}

function readPipfileDependencySpecs(path: string): DependencySpec[] {
  const specs: DependencySpec[] = [];
  const contents = readRepoText(path, 'utf8');
  const sectionPattern = /^\[(?:packages|dev-packages)\]([\s\S]*?)(?=^\[|$(?![\s\S]))/gm;
  for (const sectionMatch of contents.matchAll(sectionPattern)) {
    for (const line of (sectionMatch[1] ?? '').split('\n')) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) continue;
      const match = /^([\w][\w.-]*)\s*=\s*["']?([^"'\n#]+?)["']?\s*(?:#.*)?$/.exec(trimmed);
      if (match) specs.push({ name: match[1] ?? trimmed, version: match[2]?.trim() ?? '' });
    }
  }
  return specs;
}

function readVcpkgJsonDependencySpecs(path: string): DependencySpec[] {
  const parsed = parseJsonObject(readRepoText(path, 'utf8'));
  if (!parsed) return [];
  const rawDeps = Array.isArray(parsed.dependencies) ? parsed.dependencies : [];
  const specs: DependencySpec[] = [];
  for (const dep of rawDeps) {
    if (typeof dep === 'string') {
      // No version constraint: vcpkg pins via the builtin-baseline field in vcpkg.json.
      specs.push({ name: dep, version: 'baseline' });
    } else if (isRecord(dep) && typeof dep.name === 'string') {
      // { "name": "foo", "version>=": "1.2.11" } or { "name": "foo" }
      const version =
        dep['version>='] ?? dep['version=='] ?? dep.version ?? dep['version>'] ?? 'baseline';
      specs.push({ name: dep.name, version: String(version) });
    }
  }
  return specs;
}

function readConanfileTxtDependencySpecs(path: string): DependencySpec[] {
  const specs: DependencySpec[] = [];
  const contents = readRepoText(path, 'utf8');
  const requiresMatch = /^\[requires\]([\s\S]*?)(?=^\[|$(?![\s\S]))/m.exec(contents);
  if (!requiresMatch) return specs;
  for (const line of (requiresMatch[1] ?? '').split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    // Format: name/version or name/version@user/channel
    const match = /^([\w.\-]+)\/([\w.\-]+)/.exec(trimmed);
    if (match) specs.push({ name: match[1] ?? trimmed, version: match[2] ?? '' });
  }
  return specs;
}

function readConanfilePyDependencySpecs(path: string): DependencySpec[] {
  const specs: DependencySpec[] = [];
  const contents = readRepoText(path, 'utf8');
  // self.requires("name/version") or self.requires("name/version@user/channel")
  for (const match of contents.matchAll(/self\.requires\s*\(\s*["']([\w.\-]+)\/([\w.\-]+)["']/g)) {
    specs.push({ name: match[1] ?? '', version: match[2] ?? '' });
  }
  // requirements = ["name/version", ...]
  const listMatch = /requirements\s*=\s*\[([\s\S]*?)\]/m.exec(contents);
  if (listMatch) {
    for (const match of (listMatch[1] ?? '').matchAll(/["']([\w.\-]+)\/([\w.\-]+)["']/g)) {
      specs.push({ name: match[1] ?? '', version: match[2] ?? '' });
    }
  }
  return specs;
}

function readCMakeDependencySpecs(path: string): DependencySpec[] {
  const specs: DependencySpec[] = [];
  const contents = readRepoText(path, 'utf8');
  // find_package(Name [version] [REQUIRED ...])
  for (const match of contents.matchAll(/find_package\s*\(\s*([\w]+)(?:\s+([\d.]+))?/gi)) {
    const name = match[1];
    if (!name) continue;
    // Skip cmake-internal packages that are not real dependencies
    if (/^(Threads|PkgConfig|CMakePackageConfigHelpers|GNUInstallDirs)$/i.test(name)) continue;
    specs.push({ name, version: match[2] ?? 'find' });
  }
  // FetchContent_Declare(name ... GIT_TAG tag)
  for (const match of contents.matchAll(
    /FetchContent_Declare\s*\(\s*([\w]+)[\s\S]*?GIT_TAG\s+([\w.\-]+)/gi,
  )) {
    specs.push({ name: match[1] ?? '', version: match[2] ?? '' });
  }
  return specs;
}

function readPackageJsonDependencySpecs(packageJsonPath: string): DependencySpec[] {
  const parsed = parseJsonObject(readRepoText(packageJsonPath, 'utf8'));
  if (!parsed) return [];

  // Peer deps marked optional via peerDependenciesMeta are a declared compatibility range,
  // not installed runtime attack surface — a clean zero-runtime-dep library commonly declares
  // many of these (e.g. an optional test-framework integration). Do not count them toward the
  // pinned-dependency-ratio denominator (goal_cejel_rubric_refinement_from_lua_2026-07-06).
  const optionalPeerNames = new Set<string>();
  const peerDependenciesMeta = parsed.peerDependenciesMeta;
  if (isRecord(peerDependenciesMeta)) {
    for (const [name, meta] of Object.entries(peerDependenciesMeta)) {
      if (isRecord(meta) && meta.optional === true) optionalPeerNames.add(name);
    }
  }

  const specs: DependencySpec[] = [];
  for (const field of [
    'dependencies',
    'devDependencies',
    'peerDependencies',
    'optionalDependencies',
  ]) {
    const dependencies = parsed[field];
    if (!isRecord(dependencies)) continue;
    for (const [name, version] of Object.entries(dependencies)) {
      if (typeof version !== 'string') continue;
      if (field === 'peerDependencies' && optionalPeerNames.has(name)) continue;
      specs.push({ name, version });
    }
  }
  return specs;
}

function readRequirementsDependencySpecs(path: string): DependencySpec[] {
  return readRepoText(path, 'utf8')
    .split('\n')
    .map((line) => line.trim())
    .filter((line) => line.length > 0 && !line.startsWith('#'))
    .map((line) => {
      const [name = line, version = ''] = line.split(/[<>=~!]=?/, 2);
      return { name: name.trim(), version: line.includes('==') ? version.trim() : line };
    });
}

function isPinnedDependencyVersion(version: string): boolean {
  const trimmed = version.trim();
  if (/^(workspace:|file:|link:|portal:)/.test(trimmed)) return true;
  // vcpkg baseline: packages are pinned via the builtin-baseline hash in vcpkg.json
  if (trimmed === 'baseline') return true;
  // Python exact pin: "==1.2.3" in pyproject.toml [project] dependencies array
  if (/^==\d/.test(trimmed)) return true;
  if (/^(latest|\*|x)$/i.test(trimmed)) return false;
  if (/^[~^<>=]/.test(trimmed)) return false;
  // CMake find_package without an explicit version: system-managed, not a version pin
  if (trimmed === 'find') return false;
  return /^\d+\.\d+(?:\.\d+)?(?:[-+][0-9A-Za-z.-]+)?$/.test(trimmed);
}

function workflowTargetsDefaultBranch(repoPath: string, file: string): boolean {
  const fullPath = join(repoPath, file);
  if (!isRegularFile(fullPath)) return false;
  const contents = readRepoText(fullPath, 'utf8').toLowerCase();
  return (
    /\bpull_request\b/.test(contents) ||
    /\bbranches:\s*\[[^\]]*\b(main|master)\b[^\]]*\]/.test(contents) ||
    /\bbranches:\s*\n\s*-\s*(main|master)\b/.test(contents)
  );
}

function isPrMergeCommit(commit: GitCommitSummary): boolean {
  return /merge pull request|pull request|#\d+/i.test(commit.subject);
}

function parseJsonObject(contents: string): Record<string, unknown> | null {
  try {
    const parsed = JSON.parse(stripBom(contents)) as unknown;
    return isRecord(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isTestRunnerConfig(repoPath: string, file: string): boolean {
  return (
    /(^|\/)(vitest|jest|pytest|playwright|cypress|mocha)\.config\.[cm]?[jt]s$/.test(file) ||
    /(^|\/)(pytest\.ini|tox\.ini)$/.test(file) ||
    /(^|\/)phpunit\.xml(\.dist)?$/.test(file) ||
    (/(^|\/)pyproject\.toml$/.test(file) &&
      fileContains(repoPath, file, /^\[tool\.pytest(?:\.|\])/m)) ||
    (/(^|\/)CMakeLists\.txt$/.test(file) &&
      fileContains(repoPath, file, /\b(?:enable_testing|add_test|ctest_add_tests)\s*\(/i)) ||
    (/(^|\/)Makefile$/.test(file) &&
      fileContains(repoPath, file, /^[^\S\n\r\u2028\u2029]*(?:test|tests|check)\s*:/m))
  );
}

function isRecipeTestEntry(repoPath: string, file: string): boolean {
  return (
    isRecipeFile(file) &&
    fileContains(repoPath, file, /^[^\S\n\r\u2028\u2029]*(?:test|tests|check)\s*:/m)
  );
}

export function findCoverageConfigFiles(
  repoPath: string,
  repoFiles: readonly string[],
  authoredOnly = false,
): string[] {
  return repoFiles.filter(
    (file) => (!authoredOnly || isAuthoredProductionPath(file)) && isCoverageConfig(repoPath, file),
  );
}

export function findConcreteTestFiles(
  repoPath: string,
  repoFiles: readonly string[],
  rubricVersion = WITAN_RUBRIC_VERSION,
): string[] {
  const contentCppTests = collectContentBasedCppTestFiles(repoPath, repoFiles);
  return [
    ...repoFiles.filter((file) => isTestFile(file, rubricVersion)),
    ...contentCppTests.filter((file) => !isTestFile(file, rubricVersion)),
  ];
}

export function findConfiguredTestRunnerFiles(
  repoPath: string,
  repoFiles: readonly string[],
): string[] {
  const configured = repoFiles.filter(
    (file) => isAuthoredProductionPath(file) && isTestRunnerConfig(repoPath, file),
  );
  for (const packageJson of repoFiles.filter(
    (file) => /(^|\/)package\.json$/.test(file) && isAuthoredProductionPath(file),
  )) {
    if (
      [...readPackageScripts(join(repoPath, packageJson)).values()].some((script) =>
        TEST_RUNNER_PATTERN.test(script),
      )
    ) {
      configured.push(packageJson);
    }
  }
  configured.push(
    ...repoFiles
      .filter((file) => isAuthoredProductionPath(file) && isCiWorkflow(file))
      .filter((file) => fileContains(repoPath, file, CI_TEST_COMMAND_PATTERN)),
  );
  return [...new Set(configured)].sort();
}

export function findNonLeanTestToolchainPremiseFiles(
  repoPath: string,
  repoFiles: readonly string[],
  rubricVersion = WITAN_RUBRIC_VERSION,
): string[] {
  const testFiles = findConcreteTestFiles(repoPath, repoFiles, rubricVersion);
  if (testFiles.length === 0) return [];
  const packageJsonFiles = repoFiles.filter(
    (file) => /(^|\/)package\.json$/.test(file) && isAuthoredProductionPath(file),
  );
  const configured = findConfiguredTestRunnerFiles(repoPath, repoFiles);
  const usesLeanBuiltInTestRunner =
    packageJsonFiles.some((manifest) =>
      [...readPackageScripts(join(repoPath, manifest)).values()].some((script) =>
        LEAN_TEST_RUNNER_SCRIPT_PATTERN.test(script),
      ),
    ) || testFiles.some((file) => fileContains(repoPath, file, LEAN_TEST_RUNNER_IMPORT_PATTERN));
  const heavyManifests = packageJsonFiles.filter((manifest) =>
    packageJsonHasHeavyTestDependency(repoPath, manifest),
  );
  if (usesLeanBuiltInTestRunner && heavyManifests.length === 0) return [];
  return [...new Set([...heavyManifests, ...configured])].sort();
}

export function findTenantStoragePremiseFiles(
  repoPath: string,
  repoFiles: readonly string[],
): string[] {
  return repoFiles
    .filter((file) => /(^|\/)(?:migrations?|drizzle|prisma)\/|\.(?:sql|prisma)$/i.test(file))
    .filter((file) => fileContains(repoPath, file, TENANT_SCOPE_PATTERN_V11));
}

export function findRlsPolicyFiles(repoPath: string, repoFiles: readonly string[]): string[] {
  return repoFiles
    .filter((file) => /(^|\/)(?:migrations?|drizzle|prisma)\/|\.(?:sql|prisma)$/i.test(file))
    .filter((file) =>
      fileContains(
        repoPath,
        file,
        /\b(?:create\s+policy|enable\s+row\s+level\s+security|force\s+row\s+level\s+security)\b/i,
      ),
    );
}

export interface RlsPolicyScopeInventory {
  policyFiles: string[];
  policyCount: number;
  scopeIdentifiers: string[];
  storageFiles: string[];
}

const RLS_CLAUSE_SQL_WORDS = new Set([
  'all',
  'and',
  'any',
  'as',
  'asc',
  'between',
  'by',
  'case',
  'cast',
  'current',
  'desc',
  'distinct',
  'else',
  'end',
  'exists',
  'false',
  'from',
  'in',
  'is',
  'join',
  'like',
  'limit',
  'not',
  'null',
  'on',
  'or',
  'order',
  'select',
  'then',
  'text',
  'true',
  'uuid',
  'varchar',
  'when',
  'where',
]);

function extractBalancedSqlClause(statement: string, keyword: 'using' | 'with check'): string[] {
  const clauses: string[] = [];
  const keywordPattern = keyword === 'using' ? /\busing\s*\(/gi : /\bwith\s+check\s*\(/gi;
  for (const match of statement.matchAll(keywordPattern)) {
    const openingParen = (match.index ?? 0) + match[0].lastIndexOf('(');
    let depth = 0;
    let quote: "'" | '"' | null = null;
    for (let index = openingParen; index < statement.length; index += 1) {
      const character = statement[index];
      if (quote) {
        if (character === quote && statement[index - 1] !== '\\') quote = null;
        continue;
      }
      if (character === "'" || character === '"') {
        quote = character;
      } else if (character === '(') {
        depth += 1;
      } else if (character === ')') {
        depth -= 1;
        if (depth === 0) {
          clauses.push(statement.slice(openingParen + 1, index));
          break;
        }
      }
    }
  }
  return clauses;
}

function extractRlsScopeIdentifiers(clause: string): string[] {
  const scrubbed = clause.replace(/'(?:''|[^'])*'/g, ' ').replace(/"(?:""|[^"])*"/g, ' ');
  const identifiers = new Set<string>();
  const identifierPattern = /\b[A-Za-z_][A-Za-z0-9_$]*(?:\.[A-Za-z_][A-Za-z0-9_$]*)*\b/g;
  for (const match of scrubbed.matchAll(identifierPattern)) {
    const token = match[0];
    const segments = token.split('.').map((segment) => segment.toLowerCase());
    const lastSegment = segments.at(-1);
    if (!lastSegment || lastSegment.length < 2 || RLS_CLAUSE_SQL_WORDS.has(lastSegment)) continue;
    if (['app', 'auth', 'jwt', 'request', 'session'].includes(segments[0] ?? '')) continue;
    const remainder = scrubbed.slice((match.index ?? 0) + token.length);
    if (/^\s*\(/.test(remainder)) continue;
    if (['auth', 'current_setting', 'jwt', 'pg_catalog', 'public', 'uid'].includes(lastSegment)) {
      continue;
    }
    identifiers.add(lastSegment);
  }
  return [...identifiers].sort();
}

/**
 * Re-derive multi-tenancy from the repository's own RLS language.
 *
 * There is deliberately no tenant/org/workspace token dictionary here. We first
 * locate RLS policy files, then parse CREATE POLICY statements and their
 * USING/WITH CHECK clauses. Identifiers found in those clauses become that
 * repository's native isolation vocabulary and are traced across its data-layer
 * files. A schema token with no policy cannot manufacture a multi-tenant claim.
 */
export function deriveRlsPolicyScopeInventory(
  repoPath: string,
  repoFiles: readonly string[],
): RlsPolicyScopeInventory {
  const candidatePolicyFiles = findRlsPolicyFiles(repoPath, repoFiles);
  const policyFiles = new Set<string>();
  const scopeIdentifiers = new Set<string>();
  let policyCount = 0;

  for (const file of candidatePolicyFiles) {
    let content: string;
    try {
      content = readRepoText(join(repoPath, file), 'utf8');
    } catch {
      continue;
    }
    for (const match of content.matchAll(/\bcreate\s+policy\b[\s\S]*?(?:;|$)/gi)) {
      const statement = match[0];
      const clauses = [
        ...extractBalancedSqlClause(statement, 'using'),
        ...extractBalancedSqlClause(statement, 'with check'),
      ];
      if (clauses.length === 0) continue;
      policyCount += 1;
      policyFiles.add(file);
      for (const clause of clauses) {
        for (const identifier of extractRlsScopeIdentifiers(clause)) {
          scopeIdentifiers.add(identifier);
        }
      }
    }
  }

  const identifiers = [...scopeIdentifiers].sort();
  const dataLayerFiles = repoFiles.filter((file) =>
    /(^|\/)(?:migrations?|drizzle|prisma)\/|\.(?:sql|prisma)$/i.test(file),
  );
  const storageFiles =
    identifiers.length === 0
      ? []
      : dataLayerFiles.filter((file) =>
          identifiers.some((identifier) =>
            fileContains(
              repoPath,
              file,
              new RegExp(`\\b${identifier.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i'),
            ),
          ),
        );

  return {
    policyFiles: [...policyFiles].sort(),
    policyCount,
    scopeIdentifiers: identifiers,
    storageFiles,
  };
}

// ---- v26 item 6, A2 T-1..T-3: an identifiable tenant table with no row-level security --------
//
// docs/calibration/v26/ruling-item-6.md. The finding fires only when the repository's own SQL
// settles it: row-level security is its mechanism (T-1), a CREATE TABLE statement defines a tenant
// column under a readable name (T-2), and no ENABLE ROW LEVEL SECURITY or CREATE POLICY ... ON names
// that table, a later DISABLE counting as uncovered (T-3). Anything Cejel cannot read settles
// nothing, and the reading chosen wherever the ruling is silent is the one that fires less:
//   - only `.sql` files are parsed; an RLS statement in any other data-layer file (an ORM migration,
//     a Prisma schema) means coverage Cejel cannot read, so it abstains on every table;
//   - comments are not code; an RLS statement inside a string or dollar-quoted body is dynamic SQL,
//     and so is one whose table name cannot be normalised: either abstains on every table;
//   - table names compare case-insensitively on their last segment, so coverage written with a
//     different case, quoting or schema prefix still covers (two schemas' same-named tables count
//     as one);
//   - DISABLE uncovers a table only when it is later than the table's last ENABLE or CREATE POLICY
//     in the same directory; migration files are ordered by path with numeric runs compared as
//     numbers, and statements by position;
//   - a name with more than two segments, or a quoted name that is not a plain identifier, is not
//     identifiable, so that table yields no finding;
//   - a table that no longer exists under its CREATE TABLE name is followed
//     (goal_cejel_v26_item6_revision_2026-10-14): a later DROP TABLE in the same directory removes
//     it, and a later ALTER TABLE ... RENAME TO moves its name and its coverage history. Across
//     directories there is no readable order, so a DROP or RENAME there means the table may be
//     gone and it is not named. A DROP or RENAME whose name cannot be normalised, or one inside a
//     string or dollar-quoted body, may name any table, so it abstains on every table;
//   - at most three tables are named.
const DATA_LAYER_PATH_PATTERN = /(^|\/)(?:migrations?|drizzle|prisma)\/|\.(?:sql|prisma)$/i;
const RLS_STATEMENT_PHRASE_PATTERN =
  /\b(?:enable|disable)\s+row\s+level\s+security\b|\bcreate\s+(?:or\s+replace\s+)?policy\b/i;
const SQL_TABLE_REMOVAL_PHRASE_PATTERN = /\bdrop\s+table\b|\brename\s+to\b/i;
const SQL_CREATE_TABLE_HEAD =
  /^create\s+(?:(?:global|local)\s+)?(?:(?:temporary|temp|unlogged)\s+)?table\s+(?:if\s+not\s+exists\s+)?/i;
const SQL_ALTER_TABLE_HEAD = /^alter\s+table\s+(?:if\s+exists\s+)?(?:only\s+)?/i;
const SQL_DROP_TABLE_HEAD = /^drop\s+table\s+(?:if\s+exists\s+)?/i;
const SQL_RENAME_TO_CLAUSE = /^\s+rename\s+to\s+/i;
const SQL_CREATE_POLICY_HEAD = /^create\s+(?:or\s+replace\s+)?policy\s+/i;
const SQL_RLS_TOGGLE_PATTERN = /\b(enable|disable)\s+row\s+level\s+security\b/gi;
const SQL_PLAIN_IDENTIFIER_PATTERN = /^[A-Za-z_][A-Za-z0-9_$]*$/;
const SQL_TABLE_CONSTRAINT_PATTERN = /^(?:constraint|primary|foreign|unique|check|exclude|like)\b/i;
const MAX_UNCOVERED_TENANT_TABLES = 3;

export interface UncoveredTenantTable {
  /** Normalised: lower case, unquoted, `schema.table` when the CREATE TABLE qualified it. */
  readonly name: string;
  readonly file: string;
  /** 1-based line of the CREATE TABLE statement. */
  readonly line: number;
}

/** Path order for migrations: numeric runs compare as numbers, everything else by code unit. */
function compareMigrationPaths(left: string, right: string): number {
  const leftChunks = left.match(/\d+|\D+/g) ?? [];
  const rightChunks = right.match(/\d+|\D+/g) ?? [];
  for (let index = 0; index < Math.min(leftChunks.length, rightChunks.length); index += 1) {
    const a = leftChunks[index] as string;
    const b = rightChunks[index] as string;
    if (a === b) continue;
    if (/^\d/.test(a) && /^\d/.test(b)) {
      const x = a.replace(/^0+(?=\d)/, '');
      const y = b.replace(/^0+(?=\d)/, '');
      if (x.length !== y.length) return x.length - y.length;
      if (x !== y) return x < y ? -1 : 1;
      return a.length - b.length;
    }
    return a < b ? -1 : 1;
  }
  return leftChunks.length - rightChunks.length;
}

/**
 * Blank comments, string literal bodies and dollar-quoted bodies to spaces, keeping every offset
 * and line break, so statement positions still map to lines. `dynamic` is true when a blanked
 * string or body names an RLS statement, a DROP TABLE or a RENAME TO: SQL Cejel cannot attribute
 * to a table.
 */
function blankSqlNonCode(text: string): { code: string; dynamic: boolean } {
  const out = text.split('');
  let dynamic = false;
  const blank = (from: number, to: number): void => {
    for (let index = from; index < to; index += 1) {
      if (out[index] !== '\n' && out[index] !== '\r') out[index] = ' ';
    }
  };
  const noteBody = (from: number, to: number): void => {
    const body = text.slice(from, to);
    if (RLS_STATEMENT_PHRASE_PATTERN.test(body) || SQL_TABLE_REMOVAL_PHRASE_PATTERN.test(body)) {
      dynamic = true;
    }
  };
  let index = 0;
  while (index < text.length) {
    const character = text[index];
    const next = text[index + 1];
    if (character === '-' && next === '-') {
      const newline = text.indexOf('\n', index);
      const end = newline === -1 ? text.length : newline;
      blank(index, end);
      index = end;
    } else if (character === '/' && next === '*') {
      let depth = 1;
      let cursor = index + 2;
      while (cursor < text.length && depth > 0) {
        if (text[cursor] === '/' && text[cursor + 1] === '*') {
          depth += 1;
          cursor += 2;
        } else if (text[cursor] === '*' && text[cursor + 1] === '/') {
          depth -= 1;
          cursor += 2;
        } else {
          cursor += 1;
        }
      }
      blank(index, cursor);
      index = cursor;
    } else if (character === "'") {
      const escapes =
        index > 0 && /[Ee]/.test(text[index - 1] ?? '') && !/[A-Za-z0-9_$]/.test(text[index - 2] ?? '');
      let cursor = index + 1;
      while (cursor < text.length) {
        if (escapes && text[cursor] === '\\') {
          cursor += 2;
        } else if (text[cursor] === "'") {
          if (text[cursor + 1] !== "'") break;
          cursor += 2;
        } else {
          cursor += 1;
        }
      }
      noteBody(index + 1, cursor);
      blank(index + 1, cursor);
      index = cursor + 1;
    } else if (character === '"') {
      // A quoted identifier is code: kept, and skipped so nothing inside it opens a comment.
      let cursor = index + 1;
      while (cursor < text.length) {
        if (text[cursor] === '"') {
          if (text[cursor + 1] !== '"') break;
          cursor += 2;
        } else {
          cursor += 1;
        }
      }
      index = cursor + 1;
    } else if (character === '$' && !/[A-Za-z0-9_$]/.test(text[index - 1] ?? '')) {
      const tag = /^\$(?:[A-Za-z_][A-Za-z0-9_]*)?\$/.exec(text.slice(index, index + 66))?.[0];
      if (tag === undefined) {
        index += 1;
        continue;
      }
      const close = text.indexOf(tag, index + tag.length);
      const end = close === -1 ? text.length : close;
      noteBody(index + tag.length, end);
      blank(index + tag.length, end);
      index = close === -1 ? text.length : close + tag.length;
    } else {
      index += 1;
    }
  }
  return { code: out.join(''), dynamic };
}

function splitSqlStatements(code: string): { text: string; start: number }[] {
  const statements: { text: string; start: number }[] = [];
  let start = 0;
  let quoted = false;
  for (let index = 0; index <= code.length; index += 1) {
    const character = code[index];
    if (character === '"') quoted = !quoted;
    if (index === code.length || (character === ';' && !quoted)) {
      const raw = code.slice(start, index);
      const lead = raw.length - raw.trimStart().length;
      if (raw.trim() !== '') statements.push({ text: raw.slice(lead), start: start + lead });
      start = index + 1;
    }
  }
  return statements;
}

/** One identifier, quoted or bare, from `from`. `value` is null when it is not a plain identifier. */
function readSqlIdentifier(text: string, from: number): { value: string | null; end: number } | null {
  let index = from;
  while (/\s/.test(text[index] ?? '')) index += 1;
  if (text[index] === '"') {
    let cursor = index + 1;
    while (cursor < text.length) {
      if (text[cursor] === '"') {
        if (text[cursor + 1] !== '"') break;
        cursor += 2;
      } else {
        cursor += 1;
      }
    }
    if (cursor >= text.length) return null;
    const inner = text.slice(index + 1, cursor).replace(/""/g, '"');
    return { value: SQL_PLAIN_IDENTIFIER_PATTERN.test(inner) ? inner : null, end: cursor + 1 };
  }
  const bare = /^[^\s(),;.]+/.exec(text.slice(index))?.[0];
  if (bare === undefined) return null;
  return { value: SQL_PLAIN_IDENTIFIER_PATTERN.test(bare) ? bare : null, end: index + bare.length };
}

/** A one- or two-segment table name, lower-cased; `segments` is null when it cannot be normalised. */
function readSqlTableName(text: string, from: number): { segments: string[] | null; end: number } {
  const segments: string[] = [];
  let normalisable = true;
  let index = from;
  for (;;) {
    const identifier = readSqlIdentifier(text, index);
    if (identifier === null) return { segments: null, end: index };
    if (identifier.value === null) normalisable = false;
    else segments.push(identifier.value.toLowerCase());
    index = identifier.end;
    let cursor = index;
    while (/\s/.test(text[cursor] ?? '')) cursor += 1;
    if (text[cursor] !== '.') break;
    index = cursor + 1;
  }
  return {
    segments: normalisable && segments.length >= 1 && segments.length <= 2 ? segments : null,
    end: index,
  };
}

/** Whether a CREATE TABLE column list, starting at its `(`, defines a tenant column. */
function sqlColumnListHasTenantColumn(text: string, open: number): boolean {
  let depth = 0;
  let quoted = false;
  let elementStart = open + 1;
  const elements: string[] = [];
  for (let index = open; index < text.length; index += 1) {
    const character = text[index];
    if (character === '"') quoted = !quoted;
    if (quoted) continue;
    if (character === '(') depth += 1;
    else if (character === ')') {
      depth -= 1;
      if (depth === 0) {
        elements.push(text.slice(elementStart, index));
        break;
      }
    } else if (character === ',' && depth === 1) {
      elements.push(text.slice(elementStart, index));
      elementStart = index + 1;
    }
  }
  return elements.some((element) => {
    const trimmed = element.trim();
    if (trimmed === '' || SQL_TABLE_CONSTRAINT_PATTERN.test(trimmed)) return false;
    const column = readSqlIdentifier(trimmed, 0)?.value;
    return column != null && TENANT_SCOPE_PATTERN_V11.test(column);
  });
}

function lineAtOffset(text: string, offset: number): number {
  let line = 1;
  for (let index = 0; index < offset && index < text.length; index += 1) {
    if (text[index] === '\n') line += 1;
  }
  return line;
}

/**
 * The identifiable tenant tables this repository's SQL leaves without row-level security, when
 * row-level security is its mechanism; otherwise []. [] is also the answer whenever coverage
 * cannot be read, so the caller cannot tell "covered" from "unsettled" here and must not try.
 */
export function findUncoveredTenantTables(
  repoPath: string,
  repoFiles: readonly string[],
): UncoveredTenantTable[] {
  interface CoverageEvent {
    readonly key: string;
    readonly covers: boolean;
    readonly order: number;
    readonly dir: string;
  }
  // A DROP TABLE (`to` undefined) or an ALTER TABLE ... RENAME TO.
  interface NameEvent {
    readonly key: string;
    readonly to?: string;
    readonly order: number;
    readonly dir: string;
  }
  interface TenantTable {
    readonly key: string;
    readonly segments: readonly string[];
    readonly file: string;
    readonly line: number;
    readonly order: number;
    readonly dir: string;
  }
  const events: CoverageEvent[] = [];
  const nameEvents: NameEvent[] = [];
  const tenantTables: TenantTable[] = [];
  let order = 0;
  const dataLayerFiles = repoFiles
    .filter((file) => DATA_LAYER_PATH_PATTERN.test(file))
    .sort(compareMigrationPaths);
  for (const file of dataLayerFiles) {
    const fullPath = join(repoPath, file);
    if (!isRegularFile(fullPath)) continue;
    const contents = readRepoText(fullPath, 'utf8');
    if (!/\.sql$/i.test(file)) {
      if (RLS_STATEMENT_PHRASE_PATTERN.test(contents)) return [];
      continue;
    }
    const { code, dynamic } = blankSqlNonCode(contents);
    if (dynamic) return [];
    const dir = posix.dirname(file);
    for (const statement of splitSqlStatements(code)) {
      order += 1;
      const createTable = SQL_CREATE_TABLE_HEAD.exec(statement.text);
      if (createTable) {
        const { segments, end } = readSqlTableName(statement.text, createTable[0].length);
        const open = statement.text.slice(end).search(/\S/);
        if (segments === null || open === -1 || statement.text[end + open] !== '(') continue;
        if (sqlColumnListHasTenantColumn(statement.text, end + open)) {
          tenantTables.push({
            key: segments[segments.length - 1] as string,
            segments,
            file,
            line: lineAtOffset(contents, statement.start),
            order,
            dir,
          });
        }
        continue;
      }
      const dropTable = SQL_DROP_TABLE_HEAD.exec(statement.text);
      if (dropTable) {
        let cursor = dropTable[0].length;
        for (;;) {
          const { segments, end } = readSqlTableName(statement.text, cursor);
          if (segments === null) return [];
          nameEvents.push({ key: segments[segments.length - 1] as string, order, dir });
          const comma = /^\s*,/.exec(statement.text.slice(end));
          if (!comma) break;
          cursor = end + comma[0].length;
        }
        continue;
      }
      const alterTable = SQL_ALTER_TABLE_HEAD.exec(statement.text);
      if (alterTable) {
        const { segments: renamed, end: renamedEnd } = readSqlTableName(
          statement.text,
          alterTable[0].length,
        );
        const renameTo =
          renamed === null ? null : SQL_RENAME_TO_CLAUSE.exec(statement.text.slice(renamedEnd));
        if (renamed !== null && renameTo) {
          const { segments: to } = readSqlTableName(statement.text, renamedEnd + renameTo[0].length);
          if (to === null) return [];
          nameEvents.push({
            key: renamed[renamed.length - 1] as string,
            to: to[to.length - 1] as string,
            order,
            dir,
          });
          continue;
        }
        const toggles = [...statement.text.matchAll(SQL_RLS_TOGGLE_PATTERN)];
        if (toggles.length === 0) {
          // A RENAME TO on a table Cejel cannot name may have moved any table.
          if (SQL_TABLE_REMOVAL_PHRASE_PATTERN.test(statement.text)) return [];
          continue;
        }
        const { segments } = readSqlTableName(statement.text, alterTable[0].length);
        if (segments === null) return [];
        const key = segments[segments.length - 1] as string;
        for (const toggle of toggles) {
          order += 1; // two toggles in one statement are ordered by position
          events.push({ key, covers: toggle[1]?.toLowerCase() === 'enable', order, dir });
        }
        continue;
      }
      const createPolicy = SQL_CREATE_POLICY_HEAD.exec(statement.text);
      if (createPolicy) {
        const policyName = readSqlIdentifier(statement.text, createPolicy[0].length);
        const on = policyName ? /^\s+on\s+/i.exec(statement.text.slice(policyName.end)) : null;
        if (!policyName || !on) return [];
        const { segments } = readSqlTableName(statement.text, policyName.end + on[0].length);
        if (segments === null) return [];
        events.push({ key: segments[segments.length - 1] as string, covers: true, order, dir });
        continue;
      }
      if (RLS_STATEMENT_PHRASE_PATTERN.test(statement.text)) return [];
    }
  }
  // T-1: row-level security is this repository's own mechanism.
  if (!events.some((event) => event.covers)) return [];
  // The names a table has held, each with the statement positions it held it between, or null
  // when the table may no longer exist: a later DROP in its directory, or any DROP or RENAME of
  // one of its names in another directory, where there is no order to read.
  interface NameSpan {
    readonly key: string;
    readonly from: number;
    readonly until: number;
  }
  const followTable = (table: TenantTable): NameSpan[] | null => {
    const spans: NameSpan[] = [];
    let key = table.key;
    let from = Number.NEGATIVE_INFINITY;
    for (;;) {
      const current = key;
      if (nameEvents.some((event) => event.key === current && event.dir !== table.dir)) return null;
      const next = nameEvents.find(
        (event) => event.key === current && event.dir === table.dir && event.order > Math.max(from, table.order),
      );
      if (next === undefined) {
        spans.push({ key, from, until: Number.POSITIVE_INFINITY });
        return spans;
      }
      if (next.to === undefined) return null;
      spans.push({ key, from, until: next.order });
      key = next.to;
      from = next.order;
    }
  };
  // Coverage follows the table through a rename: an event counts when it names the table by the
  // name it held at that point. An event in another directory has no order, so it counts under
  // any of the table's names.
  const isCovered = (table: TenantTable, spans: readonly NameSpan[]): boolean => {
    const forTable = events.filter((event) =>
      spans.some(
        (span) =>
          span.key === event.key &&
          (event.dir !== table.dir || (event.order > span.from && event.order < span.until)),
      ),
    );
    const lastCover = forTable.filter((event) => event.covers).at(-1);
    const lastDisable = forTable.filter((event) => !event.covers).at(-1);
    if (lastCover === undefined) return false;
    if (lastDisable === undefined) return true;
    // Files in different directories have no order Cejel can read, so the DISABLE is not later.
    if (lastCover.dir !== lastDisable.dir) return true;
    return lastCover.order > lastDisable.order;
  };
  const uncovered = new Map<string, UncoveredTenantTable & { readonly order: number }>();
  for (const table of tenantTables) {
    const spans = followTable(table);
    const current = spans?.at(-1)?.key;
    if (spans === null || current === undefined || uncovered.has(current)) continue;
    if (isCovered(table, spans)) continue;
    uncovered.set(current, {
      name: [...table.segments.slice(0, -1), current].join('.'),
      file: table.file,
      line: table.line,
      order: table.order,
    });
  }
  return [...uncovered.values()]
    .sort((left, right) => left.order - right.order)
    .slice(0, MAX_UNCOVERED_TENANT_TABLES)
    .map(({ name, file, line }) => ({ name, file, line }));
}

export function findCiOrReleaseDeployFiles(
  _repoPath: string,
  repoFiles: readonly string[],
): string[] {
  return repoFiles.filter(
    (file) =>
      isAuthoredProductionPath(file) && (isCiWorkflow(file) || isExplicitDeployTarget(file)),
  );
}

export function findDependencyLockfiles(repoFiles: readonly string[]): string[] {
  return repoFiles.filter(isLockfile);
}

export function findDependencyManifests(repoFiles: readonly string[]): string[] {
  return repoFiles.filter(isDependencyManifest);
}

export function findDeployableServicePremiseFiles(
  repoPath: string,
  repoFiles: readonly string[],
  strictOperationalBoundary = false,
): string[] {
  const explicitTargets = repoFiles.filter(
    (file) =>
      isAuthoredProductionPath(file) &&
      isExplicitDeployTarget(file) &&
      (!strictOperationalBoundary || isV47OperationalApplicationPath(file)),
  );
  const deployWorkflows = repoFiles
    .filter((file) => isAuthoredProductionPath(file) && isCiWorkflow(file))
    .filter((file) => fileContains(repoPath, file, CI_DEPLOY_JOB_PATTERN))
    .filter(
      (file) => !strictOperationalBoundary || !isDocumentationOnlyDeployWorkflow(repoPath, file),
    );
  const serverEntrypoint = findServerEntrypointFile(repoPath, repoFiles, true);
  const runtimeContainer = findRuntimeContainerEntrypointFile(repoPath, repoFiles);
  if (strictOperationalBoundary) {
    const runtimeFiles = [serverEntrypoint, runtimeContainer].filter(
      (file): file is string => file != null && isV47OperationalApplicationPath(file),
    );
    const directApplicationTargets = explicitTargets.filter(
      (file) => !isInfrastructureOnlyDeployTarget(file),
    );
    const infrastructureTargets =
      runtimeFiles.length > 0
        ? [...explicitTargets.filter(isInfrastructureOnlyDeployTarget), ...deployWorkflows]
        : [];
    return [...directApplicationTargets, ...runtimeFiles, ...infrastructureTargets];
  }
  return [
    ...explicitTargets,
    ...deployWorkflows,
    ...(serverEntrypoint &&
    (!strictOperationalBoundary || isV47OperationalApplicationPath(serverEntrypoint))
      ? [serverEntrypoint]
      : []),
    ...(runtimeContainer &&
    (!strictOperationalBoundary || isV47OperationalApplicationPath(runtimeContainer))
      ? [runtimeContainer]
      : []),
  ];
}

function isInfrastructureOnlyDeployTarget(file: string): boolean {
  return (
    /(^|\/)docker-compose\.ya?ml$/i.test(file) ||
    /(^|\/)(?:k8s|kubernetes|manifests?)\/.+\.ya?ml$/i.test(file) ||
    /(^|\/)(?:charts?|helm)\/.+\.ya?ml$/i.test(file)
  );
}

const V47_NON_OPERATIONAL_APPLICATION_PATH_PATTERN =
  /(^|\/)(?:cookbooks?|lessons?|tutorials?|docs?|documentation|examples?|samples?|demos?)(\/|$)/i;

function isV47OperationalApplicationPath(path: string): boolean {
  return !V47_NON_OPERATIONAL_APPLICATION_PATH_PATTERN.test(path);
}

function isDocumentationOnlyDeployWorkflow(repoPath: string, file: string): boolean {
  if (/(?:docs?|pages?)/i.test(basename(file))) return true;
  return fileContains(
    repoPath,
    file,
    /\b(?:deploy[-_ ]?docs?|mkdocs|docusaurus|vitepress|gh-pages|github pages)\b/i,
  );
}

export function findPackagedApplicationPremiseFiles(
  repoPath: string,
  repoFiles: readonly string[],
): string[] {
  return repoFiles
    .filter((file) => /(^|\/)package\.json$/.test(file) && isAuthoredProductionPath(file))
    .filter((file) => packageJsonDescribesPackagedApplication(repoPath, file, repoFiles));
}

// The file-selection half of each repoFiles-walking A5 signal, named once so the live filter and
// the withheld-path check consult literally the same test and cannot drift — the same discipline
// A3's healthReadinessRouteReads/observabilityDepthReads follow. Each is a path test only: it is
// the predicate that decides which files the signal looks at, never a content judgement, and
// never an extension map or a criterion association (see abstainSignalOnWithheldPaths).
export function isClaimSourceFile(file: string): boolean {
  return /^(?:README|readme)\.md$/.test(file) || /^docs\/[^/]+\.(?:md|mdx)$/.test(file);
}

export function isClaimRealityReconciliationPath(file: string): boolean {
  return /(^|\/)claim[-_]reality[-_]reconciliation\.(?:md|mdx|json)$/i.test(file);
}

export function isSecurityOrThreatModelDoc(file: string): boolean {
  return /(^|\/)(SECURITY|THREAT[_-]?MODEL)\.md$/i.test(file);
}

export function isNegativeSpaceDocCandidate(file: string): boolean {
  return isClaimSourceFile(file) || isSecurityOrThreatModelDoc(file);
}

export function claimImplementationFileReads(authoredOnly: boolean): (file: string) => boolean {
  return (file) =>
    isImplementationFile(file) && (!authoredOnly || isAuthoredProductionPath(file));
}

export function findClaimSourceFiles(repoFiles: readonly string[]): string[] {
  return repoFiles.filter(isClaimSourceFile).sort((left, right) => {
    const leftRootReadme = /^(?:README|readme)\.md$/.test(left);
    const rightRootReadme = /^(?:README|readme)\.md$/.test(right);
    return Number(rightRootReadme) - Number(leftRootReadme) || left.localeCompare(right);
  });
}

export function findClaimImplementationFiles(
  repoFiles: readonly string[],
  authoredOnly = false,
): string[] {
  return repoFiles.filter(claimImplementationFileReads(authoredOnly));
}

export function findClaimRealityReconciliationArtifacts(
  repoPath: string,
  repoFiles: readonly string[],
): string[] {
  return repoFiles
    .filter(isClaimRealityReconciliationPath)
    .filter((file) => isAuthenticatedClaimRealityArtifact(repoPath, file));
}

function isAuthenticatedClaimRealityArtifact(repoPath: string, file: string): boolean {
  const fullPath = join(repoPath, file);
  if (!isRegularFile(fullPath)) return false;
  const contents = readRepoText(fullPath, 'utf8');
  if (/\.json$/i.test(file)) {
    return parseJsonObject(contents)?.artifactKind === 'claim_reality_reconciliation';
  }
  let inFence = false;
  for (const line of contents.split(/\r?\n/)) {
    if (/^\s*(?:```|~~~)/.test(line)) {
      inFence = !inFence;
      continue;
    }
    if (!inFence && /^#\s+Claim Reality Reconciliation\s*$/i.test(line)) return true;
  }
  return false;
}

// ---- v26 item 6, S-A5: a declared claim-reconciliation artifact that is absent ---------------
//
// docs/calibration/v26/ruling-item-6.md. The repository itself names the artifact, and the named
// path is not in the tree. Where the ruling is silent, each choice below is the reading that fires
// less, and each is listed in the change's record.

// The bounded vocabulary: `claim` or `claims`, then `reconciliation`, `register` or `ledger`, with
// an optional `reality` between, joined by `-`, `_`, `.` or nothing, in any case. A document or a
// data file only.
const DECLARED_CLAIM_ARTIFACT_BASENAME_PATTERN =
  /^claims?[-_.]?(?:reality[-_.]?)?(?:reconciliation|register|ledger)\.(?:md|mdx|json|ya?ml)$/i;
// Only a path Cejel can state back verbatim counts as a declaration; anything else cannot be
// normalised and declares nothing.
const DECLARED_CLAIM_ARTIFACT_PATH_PATTERN = /^[A-Za-z0-9._/-]{1,160}$/;
const MARKDOWN_FENCE_PATTERN = /^\s{0,3}(`{3,}|~{3,})/;
const MARKDOWN_INLINE_LINK_PATTERN = /(!?)\[[^\]]*\]\(\s*<?([^\s)>]+)>?[^)]*\)/g;
const MARKDOWN_REFERENCE_DEFINITION_PATTERN = /^\s{0,3}\[[^\]]+\]:\s*<?([^\s>]+)>?/;
const MARKDOWN_CODE_SPAN_PATTERN = /`([^`]+)`/g;

interface DeclaredClaimArtifact {
  /** Repository-relative, normalised. */
  readonly path: string;
  readonly declaringFile: string;
  readonly line: number;
}

interface ClaimArtifactDeclaration {
  /** Every repository-relative reading of the declared path; present if any one is present. */
  readonly candidates: readonly string[];
  readonly line: number;
}

// The places the ruling names: a claim source (README.md, a top-level docs/ page), CONTRIBUTING,
// and a step of a GitHub Actions workflow.
function isClaimArtifactDeclaringDocument(file: string): boolean {
  return isClaimSourceFile(file) || /^CONTRIBUTING\.md$/i.test(file);
}

function isClaimArtifactDeclaringWorkflow(file: string): boolean {
  return /^\.github\/workflows\/[^/]+\.ya?ml$/.test(file);
}

function normaliseDeclaredClaimArtifactPath(candidate: string, baseDir: string): string | null {
  if (!DECLARED_CLAIM_ARTIFACT_PATH_PATTERN.test(candidate)) return null;
  const joined = candidate.startsWith('/')
    ? posix.normalize(candidate.slice(1))
    : posix.normalize(posix.join(baseDir, candidate));
  const path = stripTrailingSlashes(joined);
  if (path === '' || path === '.' || path === '..' || path.startsWith('../') || path.startsWith('/')) {
    return null;
  }
  return DECLARED_CLAIM_ARTIFACT_BASENAME_PATTERN.test(posix.basename(path)) ? path : null;
}

function markdownLinkTarget(target: string): string | null {
  // An external URL, a protocol-relative URL or an in-page anchor names no repository path.
  if (/^[a-z][a-z0-9+.-]*:/i.test(target) || target.startsWith('//') || target.startsWith('#')) {
    return null;
  }
  const withoutSuffix = stripFromQueryOrFragment(target);
  try {
    return decodeURIComponent(withoutSuffix);
  } catch {
    return null;
  }
}

function markdownClaimArtifactDeclarations(
  file: string,
  contents: string,
): ClaimArtifactDeclaration[] {
  const baseDir = posix.dirname(file);
  const declarations: ClaimArtifactDeclaration[] = [];
  let fence: string | null = null;
  let inHtmlComment = false;
  contents.split(/\r?\n/).forEach((rawLine, index) => {
    const marker = MARKDOWN_FENCE_PATTERN.exec(rawLine)?.[1];
    if (fence !== null) {
      if (marker !== undefined && marker[0] === fence[0] && marker.length >= fence.length) fence = null;
      return;
    }
    if (marker !== undefined) {
      fence = marker;
      return;
    }
    let line = rawLine;
    if (inHtmlComment) {
      const close = line.indexOf('-->');
      if (close === -1) return;
      line = line.slice(close + 3);
      inHtmlComment = false;
    }
    line = line.replace(/<!--[\s\S]*?-->/g, ' ');
    const open = line.indexOf('<!--');
    if (open !== -1) {
      line = line.slice(0, open);
      inHtmlComment = true;
    }
    const lineNumber = index + 1;
    // A code-span path is read from the repository root and from the declaring file's
    // directory; it is present if either reading is.
    for (const match of line.matchAll(MARKDOWN_CODE_SPAN_PATTERN)) {
      const span = (match[1] ?? '').trim().replace(/^\.\//, '');
      const candidates = [
        normaliseDeclaredClaimArtifactPath(span, '.'),
        normaliseDeclaredClaimArtifactPath(span, baseDir),
      ].filter((path): path is string => path !== null);
      if (candidates.length > 0) declarations.push({ candidates: [...new Set(candidates)], line: lineNumber });
    }
    const prose = line.replace(MARKDOWN_CODE_SPAN_PATTERN, ' ');
    const targets: string[] = [];
    for (const match of prose.matchAll(MARKDOWN_INLINE_LINK_PATTERN)) {
      if (match[1] === '!') continue; // an image embeds a file; it does not declare an artifact
      targets.push(match[2] ?? '');
    }
    const reference = MARKDOWN_REFERENCE_DEFINITION_PATTERN.exec(prose);
    if (reference?.[1]) targets.push(reference[1]);
    for (const target of targets) {
      const decoded = markdownLinkTarget(target);
      // A relative link resolves against the declaring file, as the Markdown renderer resolves it.
      const path = decoded === null ? null : normaliseDeclaredClaimArtifactPath(decoded, baseDir);
      if (path !== null) declarations.push({ candidates: [path], line: lineNumber });
    }
  });
  return declarations;
}

// A path a step writes is output, not a declaration of a file the repository should hold. Every
// token after the first of these on a line is a written path: a shell redirect (`>`, `>>`), `tee`,
// or an output option (`-o`, `--out`, `--output`, and other `--out…` spellings). Read loosely on
// purpose, because a written path wrongly read as declared is the reading that fires more.
const WORKFLOW_WRITE_OPERATOR_PATTERN = />|(?:^|[\s|;&(])(?:tee|-o|--out[\w-]*)(?=[\s=]|$)/;
// The artifact actions' `path:` is what the step uploads or downloads, so the whole step declares
// nothing. Any version or sub-action.
const WORKFLOW_ARTIFACT_ACTION_PATTERN =
  /^\s*(?:-\s+)?uses\s*:\s*["']?actions\/(?:upload|download)-artifact(?:[/@]|["']?\s*$)/i;

function workflowClaimArtifactDeclarations(contents: string): ClaimArtifactDeclaration[] {
  // A step that may run elsewhere than the repository root names a path Cejel cannot resolve.
  if (/^[^\S\n\r\u2028\u2029]*(?:-\s+)?working-directory\s*:/m.test(contents)) return [];
  const declarations: ClaimArtifactDeclaration[] = [];
  let stepsIndent: number | null = null;
  let stepItemIndent: number | null = null;
  // One step's declarations, kept back until the step ends, because its `uses:` may follow them.
  let step: { declarations: ClaimArtifactDeclaration[]; movesArtifact: boolean } | null = null;
  // A write operator on a line that ends in `\` carries on to the continuation line.
  let writeContinues = false;
  const closeStep = (): void => {
    if (step !== null && !step.movesArtifact) declarations.push(...step.declarations);
    step = null;
    writeContinues = false;
  };
  contents.split(/\r?\n/).forEach((rawLine, index) => {
    const line = stripHashCommentAtStartOrAfterBlank(rawLine);
    if (line.trim() === '') return;
    const indent = line.length - line.trimStart().length;
    if (
      stepsIndent !== null &&
      (indent < stepsIndent || (indent === stepsIndent && !line.trimStart().startsWith('- ')))
    ) {
      closeStep();
      stepsIndent = null;
    }
    const stepsKey = /^(\s*)steps\s*:\s*$/.exec(line);
    if (stepsKey) {
      closeStep();
      stepsIndent = stepsKey[1]?.length ?? 0;
      stepItemIndent = null;
      return;
    }
    if (stepsIndent === null) return;
    if (line.trimStart().startsWith('- ') && (stepItemIndent === null || indent <= stepItemIndent)) {
      closeStep();
      stepItemIndent = indent;
    }
    step ??= { declarations: [], movesArtifact: false };
    if (WORKFLOW_ARTIFACT_ACTION_PATTERN.test(line)) step.movesArtifact = true;
    const writeAt = writeContinues ? 0 : line.search(WORKFLOW_WRITE_OPERATOR_PATTERN);
    writeContinues = writeAt !== -1 && /\\\s*$/.test(line);
    const read = writeAt === -1 ? line : line.slice(0, writeAt);
    for (const token of read.split(/[\s'"`=,;:()[\]{}<>|&]+/)) {
      const path = normaliseDeclaredClaimArtifactPath(token.replace(/^\.\//, ''), '.');
      if (path !== null) step.declarations.push({ candidates: [path], line: index + 1 });
    }
  });
  closeStep();
  return declarations;
}

export interface ClaimArtifactDeclarationScan {
  /** Whether the repository names any claim-reconciliation artifact, present or absent. */
  readonly declared: boolean;
  /** The first named artifact that is absent from the tree, if any. */
  readonly firstAbsent?: DeclaredClaimArtifact;
}

/**
 * Whether this repository names a claim-reconciliation artifact, and the first one it names that
 * is absent from its tree. "Absent" is checked against the tracked file list plus every path the
 * walk withheld from it, case-insensitively, so a file Cejel declined to read is never reported
 * missing.
 */
export function scanClaimArtifactDeclarations(
  repoPath: string,
  repoFiles: readonly string[],
): ClaimArtifactDeclarationScan {
  const declaringFiles = repoFiles
    .filter((file) => isClaimArtifactDeclaringDocument(file) || isClaimArtifactDeclaringWorkflow(file))
    .sort();
  let declared = false;
  if (declaringFiles.length === 0) return { declared };
  const known = [...repoFiles, ...withheldRepoPaths().map(({ path }) => path)].map((path) =>
    path.toLowerCase(),
  );
  const isPresent = (path: string): boolean => {
    const lower = path.toLowerCase();
    return known.some((file) => file === lower || file.startsWith(`${lower}/`));
  };
  for (const file of declaringFiles) {
    const fullPath = join(repoPath, file);
    if (!isRegularFile(fullPath)) continue;
    const contents = readRepoText(fullPath, 'utf8');
    const declarations = isClaimArtifactDeclaringWorkflow(file)
      ? workflowClaimArtifactDeclarations(contents)
      : markdownClaimArtifactDeclarations(file, contents);
    for (const declaration of declarations) {
      declared = true;
      if (declaration.candidates.some(isPresent)) continue;
      const [path] = declaration.candidates;
      if (path !== undefined) {
        return { declared, firstAbsent: { path, declaringFile: file, line: declaration.line } };
      }
    }
  }
  return { declared };
}

function isCoverageConfig(repoPath: string, file: string): boolean {
  if (
    /(^|\/)(nyc|c8|coverage|codecov)\.(json|yml|yaml)$/.test(file) ||
    /(^|\/)\.coveragerc$/.test(file) ||
    /(^|\/)lcov\.info$/.test(file) ||
    /(^|\/)\.coveralls\.yml$/.test(file)
  ) {
    return true;
  }
  // Documented configuration locations, every rubric
  // (goal_cejel_v26_coverage_config_recognition_2026-10-14). Each is the tool's own documented
  // file; the PR that added them lists each documentation URL.
  if (
    /(^|\/)\.codecov\.ya?ml$/.test(file) ||
    /(^|\/)\.nycrc(?:\.json|\.ya?ml)?$/.test(file) ||
    /(^|\/)\.c8rc(?:\.json)?$/.test(file) ||
    /(^|\/)\.?tarpaulin\.toml$/.test(file)
  ) {
    return true;
  }
  if (/(^|\/)(?:setup\.cfg|tox\.ini)$/.test(file)) {
    // coverage.py reads these files only under the `coverage:`-prefixed section names.
    return fileContains(repoPath, file, /^[^\S\n\r\u2028\u2029]*\[coverage:(?:run|report)\]\s*$/m);
  }
  if (/(^|\/)vite\.config\.[cm]?[jt]s$/.test(file)) {
    return viteConfigCollectsCoverage(repoPath, file);
  }
  if (/(^|\/)\.simplecov$/.test(file)) {
    // A line that can hold SimpleCov has a non-blank, so `\s*` in the lookahead never left it.
    return fileContains(repoPath, file, /^(?![^\S\n\r\u2028\u2029]*#).*\bSimpleCov\b/m);
  }
  if (/(^|\/)phpunit\.xml(?:\.dist)?$/.test(file)) {
    return /<coverage(?=[\s>/])/.test(stripXmlComments(readRepoText(join(repoPath, file), 'utf8')));
  }
  if (/(^|\/)pom\.xml$/.test(file)) {
    return pomAppliesJacoco(readRepoText(join(repoPath, file), 'utf8'));
  }
  if (/(^|\/)build\.gradle(?:\.kts)?$/.test(file)) {
    return gradleAppliesJacoco(readRepoText(join(repoPath, file), 'utf8'));
  }
  if (/(^|\/)vitest\.config\.[cm]?[jt]s$/.test(file)) {
    return fileContains(repoPath, file, /\bcoverage\s*:/i);
  }
  if (/(^|\/)jest\.config\.[cm]?[jt]s$/.test(file)) {
    return fileContains(
      repoPath,
      file,
      /\b(?:collectCoverage|coverageThreshold|coverageProvider|coverageDirectory)\s*:/,
    );
  }
  if (/(^|\/)pyproject\.toml$/.test(file)) {
    return fileContains(repoPath, file, /^\[tool\.coverage(?:\.|\])/m);
  }
  if (/(^|\/)package\.json$/.test(file)) {
    return packageJsonHasCoverageTooling(repoPath, file);
  }
  return false;
}

function packageJsonHasCoverageTooling(repoPath: string, file: string): boolean {
  const fullPath = join(repoPath, file);
  if (!isRegularFile(fullPath)) return false;
  const parsed = parseJsonObject(readRepoText(fullPath, 'utf8'));
  if (!parsed) return false;

  const scripts = parsed.scripts;
  if (typeof scripts === 'object' && scripts !== null && !Array.isArray(scripts)) {
    for (const command of Object.values(scripts)) {
      if (typeof command === 'string' && commandInvokesCoverageTool(command)) {
        return true;
      }
    }
  }

  return packageJsonHasStaticCoverageTooling(repoPath, file);
}

// The v23 disabled-value rules for a Vitest `coverage` property: absent, `false`, `null` or
// `undefined`, or an object alongside `enabled: false`, does not collect. `contents` must already
// have comments stripped.
function vitestCoveragePropertyCollects(contents: string): boolean {
  const property = widenToLeadingBlankRun(
    /(?:^|[{,])[^\S\n\r\u2028\u2029]*["']?coverage["']?\s*:\s*([^,\r\n}]*)/im.exec(contents),
    contents,
  )?.[1]?.trim();
  if (!property || /^(?:false\b|null\b|undefined\b)/i.test(property)) return false;
  if (/^\{/.test(property) && /\benabled\s*:\s*false\b/i.test(contents)) return false;
  return true;
}

// Vitest reads `test` from vite.config unless a vitest.config beside it takes priority, which it
// does wholesale unless it merges vite.config in (vitest.dev/config/). Only the `test` block's
// own `coverage` property counts, under the same disabled-value rules as vitest.config.
function viteConfigCollectsCoverage(repoPath: string, file: string): boolean {
  const directory = dirname(file);
  for (const extension of ['ts', 'mts', 'cts', 'js', 'mjs', 'cjs']) {
    const sibling = join(repoPath, directory, `vitest.config.${extension}`);
    if (!isRegularFile(sibling)) continue;
    const vitestConfig = stripJavaScriptComments(readRepoText(sibling, 'utf8'));
    if (!/["']\.\/vite\.config(?:\.[cm]?[jt]s)?["']/.test(vitestConfig)) return false;
  }
  const contents = stripJavaScriptComments(readRepoText(join(repoPath, file), 'utf8'));
  const testProperty = widenToLeadingBlankRun(
    /(?:^|[{,])[^\S\n\r\u2028\u2029]*["']?test["']?\s*:\s*\{/m.exec(contents),
    contents,
  );
  if (!testProperty) return false;
  const block = balancedBraceBlock(contents, testProperty.index + testProperty[0].length - 1);
  return vitestCoveragePropertyCollects(block);
}

/** The `{...}` block opening at `open`, quote-aware; the rest of the text if it never closes. */
function balancedBraceBlock(contents: string, open: number): string {
  let depth = 0;
  let quote: string | null = null;
  for (let index = open; index < contents.length; index += 1) {
    const character = contents[index];
    if (quote) {
      if (character === '\\') index += 1;
      else if (character === quote) quote = null;
      continue;
    }
    if (character === '"' || character === "'" || character === '`') quote = character;
    else if (character === '{') depth += 1;
    else if (character === '}') {
      depth -= 1;
      if (depth === 0) return contents.slice(open, index + 1);
    }
  }
  return contents.slice(open);
}

function stripXmlComments(contents: string): string {
  return contents.replace(/<!--[\s\S]*?-->/g, '');
}

// JaCoCo's Maven plugin collects only when the build applies it: <pluginManagement> alone applies
// nothing (maven.apache.org/pom.html), and `skip` / `jacoco.skip` suppress execution.
function pomAppliesJacoco(contents: string): boolean {
  const pom = stripXmlComments(contents).replace(/<pluginManagement>[\s\S]*?<\/pluginManagement>/g, '');
  if (/<jacoco\.skip>\s*true\s*<\/jacoco\.skip>/i.test(pom)) return false;
  for (const plugin of pom.matchAll(/<plugin>([\s\S]*?)<\/plugin>/g)) {
    const body = plugin[1] ?? '';
    if (!/<artifactId>\s*jacoco-maven-plugin\s*<\/artifactId>/.test(body)) continue;
    if (/<skip>\s*true\s*<\/skip>/i.test(body)) continue;
    return true;
  }
  return false;
}

// Gradle's JaCoCo plugin, applied in either DSL: `id 'jacoco'` / `id("jacoco")` / Kotlin's bare
// `jacoco` inside `plugins { }`, or `apply plugin: 'jacoco'` / `apply(plugin = "jacoco")`.
function gradleAppliesJacoco(contents: string): boolean {
  const script = stripJavaScriptComments(contents);
  if (/\bapply\s*\(?\s*plugin\s*[:=]\s*["']jacoco["']/.test(script)) return true;
  for (const block of script.matchAll(/\bplugins\s*\{([^{}]*)\}/g)) {
    if (
      /(?:^|[\s;])(?:id\s*\(?\s*["']jacoco["']\s*\)?|jacoco)[ \t]*(?:$|[\s;])/m.test(block[1] ?? '')
    ) {
      return true;
    }
  }
  return false;
}

function isV23CoverageConfig(repoPath: string, file: string): boolean {
  if (/(^|\/)vitest\.config\.[cm]?[jt]s$/.test(file)) {
    return vitestCoveragePropertyCollects(
      stripJavaScriptComments(readRepoText(join(repoPath, file), 'utf8')),
    );
  }
  if (/(^|\/)jest\.config\.[cm]?[jt]s$/.test(file)) {
    const contents = stripJavaScriptComments(readRepoText(join(repoPath, file), 'utf8'));
    return (
      /(?:^|[{,])[^\S\n\r\u2028\u2029]*["']?collectCoverage["']?\s*:\s*true\b/m.test(contents) ||
      /(?:^|[{,])[^\S\n\r\u2028\u2029]*["']?(?:coverageThreshold|coverageProvider|coverageDirectory)["']?\s*:/m.test(
        contents,
      )
    );
  }
  if (/(^|\/)package\.json$/.test(file)) {
    return packageJsonHasStaticCoverageTooling(repoPath, file);
  }
  return isCoverageConfig(repoPath, file);
}

function coverageConfigurationDecision(
  repoPath: string,
  file: string,
): CoverageDetectorDecision | null {
  const detectorState = isV23CoverageConfig(repoPath, file) ? 'collects' : 'none';
  if (/(^|\/)vitest\.config\.[cm]?[jt]s$/.test(file)) {
    const rawContents = readRepoText(join(repoPath, file), 'utf8');
    const contents = stripJavaScriptComments(rawContents);
    const match = widenToLeadingBlankRun(
      /(?:^|[{,])[^\S\n\r\u2028\u2029]*["']?coverage["']?\s*:\s*([^,\r\n}]*)/im.exec(contents),
      contents,
    );
    if (!match) return null;
    return {
      path: file,
      source: 'runner-configuration',
      locator: 'coverage',
      evidence: rawContents.slice(match.index, match.index + match[0].length).trim(),
      detectorRecognized: true,
      detectorState,
    };
  }
  if (/(^|\/)jest\.config\.[cm]?[jt]s$/.test(file)) {
    const rawContents = readRepoText(join(repoPath, file), 'utf8');
    const contents = stripJavaScriptComments(rawContents);
    const match = widenToLeadingBlankRun(
      /(?:^|[{,])[^\S\n\r\u2028\u2029]*["']?(collectCoverage|coverageThreshold|coverageProvider|coverageDirectory)["']?\s*:\s*([^,\r\n}]*)/m.exec(
        contents,
      ),
      contents,
    );
    if (!match) return null;
    return {
      path: file,
      source: 'runner-configuration',
      locator: match[1] ?? 'coverage',
      evidence: rawContents.slice(match.index, match.index + match[0].length).trim(),
      detectorRecognized: true,
      detectorState,
    };
  }
  if (detectorState === 'none') return null;
  return {
    path: file,
    source: 'runner-configuration',
    locator: 'coverage',
    evidence: file,
    detectorRecognized: true,
    detectorState,
  };
}

function packageJsonHasStaticCoverageTooling(repoPath: string, file: string): boolean {
  const fullPath = join(repoPath, file);
  if (!isRegularFile(fullPath)) return false;
  const parsed = parseJsonObject(readRepoText(fullPath, 'utf8'));
  if (!parsed) return false;
  // Jest reads its configuration from a top-level "jest" key (jestjs.io/docs/configuration);
  // the same keys, with collectCoverage only when true, that v23 reads in jest.config.
  const jest = parsed.jest;
  if (
    isRecord(jest) &&
    (jest.collectCoverage === true ||
      isRecord(jest.coverageThreshold) ||
      typeof jest.coverageProvider === 'string')
  ) {
    return true;
  }
  return ['nyc', 'c8', 'istanbul'].some((key) => {
    const config = parsed[key];
    return typeof config === 'object' && config !== null && !Array.isArray(config);
  });
}

export type CoverageCommandState = 'none' | 'collects' | 'unresolved';

// Observability seam for review evidence: `evidence` preserves the source fact while the
// detector-prefixed fields label Cejel's interpretation. This is intentionally not attached to a
// certificate or presentation surface.
export interface CoverageDetectorDecision {
  readonly path: string;
  readonly source: 'ci-run' | 'package-script' | 'recipe-command' | 'runner-configuration';
  readonly locator: string;
  /** Raw repository evidence. Callers must sanitize it before presentation or persistence. */
  readonly evidence: string;
  readonly detectorRecognized: boolean;
  readonly detectorState: CoverageCommandState;
}

export interface CoverageConfigurationAnalysis {
  readonly coverageFiles: string[];
  readonly unresolvedFiles: string[];
  readonly hasCoverageCommand: boolean;
  readonly detectorDecisions: readonly CoverageDetectorDecision[];
}

interface PackageScriptReferences {
  readonly names: string[];
  readonly dynamic: boolean;
}

interface RecipeTarget {
  readonly dependencies: string[];
  readonly commands: string[];
}

// Coverage absence is an assertion, so command-derived coverage needs two independent facts:
// a coverage-capable runner owns an enabling flag, and the command is reachable from a test entry
// point. Mentions, upload-only commands, unused scripts, and dependencies alone prove neither.
export function analyzeCoverageConfiguration(
  repoPath: string,
  repoFiles: readonly string[],
  authoredOnly = false,
): CoverageConfigurationAnalysis {
  const eligibleFiles = repoFiles.filter(
    (file) => !authoredOnly || isAuthoredProductionPath(file),
  );
  const eligibleSet = new Set(eligibleFiles);
  const coverageFiles = new Set<string>();
  const unresolvedFiles = new Set<string>();
  const ciCommandsByFile = new Map<string, string[]>();
  const detectorDecisions: CoverageDetectorDecision[] = [];
  let hasCoverageCommand = false;

  for (const file of eligibleFiles.filter(isCiWorkflow)) {
    const commands = extractCiRunCommands(readRepoText(join(repoPath, file), 'utf8'));
    ciCommandsByFile.set(file, commands);
    const commandDecisions = commands.map((command, index) =>
      coverageDetectorDecision(repoPath, eligibleSet, {
        path: file,
        source: 'ci-run',
        locator: String(index),
        command,
      }),
    );
    detectorDecisions.push(...commandDecisions);
    const state = combineCoverageCommandStates(
      commandDecisions.map((decision) => decision.detectorState),
    );
    if (state === 'collects') {
      coverageFiles.add(file);
      hasCoverageCommand = true;
    }
    if (state === 'unresolved') unresolvedFiles.add(file);
  }

  const ciCommands = [...ciCommandsByFile.values()].flat();
  for (const file of eligibleFiles) {
    if (isCiWorkflow(file) || isRecipeFile(file)) continue;
    if (/(^|\/)package\.json$/.test(file)) {
      if (packageJsonHasStaticCoverageTooling(repoPath, file)) coverageFiles.add(file);
      const packageState = packageScriptCoverageState(
        repoPath,
        eligibleSet,
        file,
        file === 'package.json' ? ciCommands : [],
        detectorDecisions,
      );
      if (packageState === 'collects') {
        coverageFiles.add(file);
        hasCoverageCommand = true;
      }
      if (packageState === 'unresolved') unresolvedFiles.add(file);
      continue;
    }
    const configurationDecision = coverageConfigurationDecision(repoPath, file);
    if (configurationDecision) detectorDecisions.push(configurationDecision);
    if (configurationDecision?.detectorState === 'collects') coverageFiles.add(file);
  }

  for (const file of eligibleFiles.filter(isRecipeFile)) {
    const state = recipeCoverageState(
      repoPath,
      eligibleSet,
      file,
      ciCommands,
      detectorDecisions,
    );
    if (state === 'collects') {
      coverageFiles.add(file);
      hasCoverageCommand = true;
    }
    if (state === 'unresolved') unresolvedFiles.add(file);
  }

  for (const file of coverageFiles) unresolvedFiles.delete(file);
  return {
    coverageFiles: [...coverageFiles].sort(),
    unresolvedFiles: [...unresolvedFiles].sort(),
    hasCoverageCommand,
    detectorDecisions,
  };
}

function unionWithLegacyCoverageRecognition(
  analysis: CoverageConfigurationAnalysis,
  legacyFiles: readonly string[],
  hasLegacyCoverageScript: boolean,
): CoverageConfigurationAnalysis {
  const legacy = new Set(legacyFiles);
  const coverageFiles = [
    ...legacyFiles,
    ...analysis.coverageFiles.filter((file) => !legacy.has(file)),
  ];
  return {
    coverageFiles,
    unresolvedFiles: analysis.unresolvedFiles.filter((file) => !legacy.has(file)),
    hasCoverageCommand: hasLegacyCoverageScript || analysis.hasCoverageCommand,
    detectorDecisions: analysis.detectorDecisions,
  };
}

function stripJavaScriptComments(contents: string): string {
  let output = '';
  let quote: "'" | '"' | '`' | null = null;
  let escaped = false;
  let lineComment = false;
  let blockComment = false;

  for (let index = 0; index < contents.length; index += 1) {
    const character = contents[index] ?? '';
    const next = contents[index + 1] ?? '';
    if (lineComment) {
      if (character === '\n') {
        lineComment = false;
        output += '\n';
      } else {
        output += ' ';
      }
      continue;
    }
    if (blockComment) {
      if (character === '*' && next === '/') {
        output += '  ';
        index += 1;
        blockComment = false;
      } else {
        output += character === '\n' ? '\n' : ' ';
      }
      continue;
    }
    if (escaped) {
      output += character;
      escaped = false;
      continue;
    }
    if (quote) {
      output += character;
      if (character === '\\') escaped = true;
      else if (character === quote) quote = null;
      continue;
    }
    if (character === "'" || character === '"' || character === '`') {
      quote = character;
      output += character;
      continue;
    }
    if (character === '/' && next === '/') {
      output += '  ';
      index += 1;
      lineComment = true;
      continue;
    }
    if (character === '/' && next === '*') {
      output += '  ';
      index += 1;
      blockComment = true;
      continue;
    }
    output += character;
  }
  return output;
}

function packageScriptCoverageState(
  repoPath: string,
  repoFiles: ReadonlySet<string>,
  packageJson: string,
  ciCommands: readonly string[],
  detectorDecisions: CoverageDetectorDecision[],
): CoverageCommandState {
  const scripts = readPackageScripts(join(repoPath, packageJson));
  if (scripts.size === 0) return 'none';

  const roots = new Set<string>();
  let unresolved = false;
  if (scripts.has('test')) roots.add('test');
  for (const command of ciCommands) {
    const references = packageScriptReferences(command, scripts);
    for (const name of references.names) roots.add(name);
    if (
      references.dynamic &&
      [...scripts.values()].some(
        (candidate) =>
          commandInvokesCoverageTool(candidate) || containsPotentialCoverageFlag(candidate),
      )
    ) {
      unresolved = true;
    }
  }

  const queue = [...roots];
  const visited = new Set<string>();
  while (queue.length > 0) {
    const name = queue.shift();
    if (!name || visited.has(name)) continue;
    const command = scripts.get(name);
    if (command === undefined) continue;
    visited.add(name);

    const decision = coverageDetectorDecision(repoPath, repoFiles, {
      path: packageJson,
      source: 'package-script',
      locator: name,
      command,
    });
    detectorDecisions.push(decision);
    const state = decision.detectorState;
    if (state === 'collects') return 'collects';
    if (state === 'unresolved') unresolved = true;

    const references = packageScriptReferences(command, scripts);
    for (const referenced of references.names) {
      if (!visited.has(referenced)) queue.push(referenced);
    }
    for (const lifecycle of [`pre${name}`, `post${name}`]) {
      if (scripts.has(lifecycle) && !visited.has(lifecycle)) queue.push(lifecycle);
    }
    if (
      references.dynamic &&
      [...scripts.values()].some(
        (candidate) =>
          commandInvokesCoverageTool(candidate) || containsPotentialCoverageFlag(candidate),
      )
    ) {
      unresolved = true;
    }
  }
  return unresolved ? 'unresolved' : 'none';
}

function packageScriptReferences(
  command: string,
  scripts: ReadonlyMap<string, string>,
): PackageScriptReferences {
  const names = new Set<string>();
  let dynamic = false;
  for (const segment of splitShellCommandSegments(command)) {
    // A `pnpm run /<regex>/` selector is never compiled: the regex is repository text, and
    // evaluating it lets the repository stall the scan (goal_cejel_scan_path_regex_bounds_2026-10-15).
    // It is a reference Cejel cannot resolve, so it takes the existing dynamic path. Any argument
    // starting with `/` counts: no literal script name below can start with one, and the former
    // `\/((?:\\.|[^/])+)\/` capture was itself ambiguous on backslashes.
    if (/\bpnpm\s+run\s+\//iu.test(segment)) dynamic = true;

    for (const match of segment.matchAll(
      /\b(?:npm|pnpm|yarn)\s+(?:run\s+)?([A-Za-z0-9][A-Za-z0-9:._-]*)/giu,
    )) {
      const name = match[1];
      if (name && scripts.has(name)) names.add(name);
    }
    if (/\b(?:npm|pnpm|yarn)\s+run\s+(?:\$|["']\$|`)/u.test(segment)) dynamic = true;
  }
  return { names: [...names], dynamic };
}

function extractCiRunCommands(contents: string): string[] {
  const lines = contents.split(/\r?\n/);
  const commands: string[] = [];
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index] ?? '';
    const match = /^(\s*)(?:-\s*)?run\s*:\s*(.*)$/u.exec(line);
    if (!match) continue;
    const indentation = match[1]?.length ?? 0;
    const value = match[2]?.trim() ?? '';
    if (value === '|' || value === '>' || value.startsWith('|-') || value.startsWith('>-')) {
      const block: string[] = [];
      for (index += 1; index < lines.length; index += 1) {
        const nested = lines[index] ?? '';
        if (nested.trim().length === 0) {
          block.push('');
          continue;
        }
        const nestedIndentation = /^\s*/u.exec(nested)?.[0].length ?? 0;
        if (nestedIndentation <= indentation) {
          index -= 1;
          break;
        }
        block.push(nested.slice(Math.min(nested.length, indentation + 2)));
      }
      commands.push(block.join(value.startsWith('>') ? ' ' : '\n'));
      continue;
    }
    if (value.length === 0) continue;
    const quoted = /^(?:"([\s\S]*)"|'([\s\S]*)')$/u.exec(value);
    commands.push(quoted ? (quoted[1] ?? quoted[2] ?? '') : value);
  }
  return commands;
}

function isRecipeFile(file: string): boolean {
  return /(^|\/)(?:Makefile|makefile|GNUmakefile|[Jj]ustfile)$/.test(file);
}

function recipeCoverageState(
  repoPath: string,
  repoFiles: ReadonlySet<string>,
  file: string,
  ciCommands: readonly string[],
  detectorDecisions: CoverageDetectorDecision[],
): CoverageCommandState {
  const targets = readRecipeTargets(readRepoText(join(repoPath, file), 'utf8'));
  const roots = new Set(['test', 'tests', 'check'].filter((target) => targets.has(target)));
  const runner = /[Jj]ustfile$/.test(file) ? 'just' : 'make';
  for (const command of ciCommands) {
    for (const match of command.matchAll(new RegExp(`\\b${runner}\\s+([A-Za-z0-9._-]+)`, 'gu'))) {
      const target = match[1];
      if (target && targets.has(target)) roots.add(target);
    }
  }

  const queue = [...roots];
  const visited = new Set<string>();
  let unresolved = false;
  while (queue.length > 0) {
    const name = queue.shift();
    if (!name || visited.has(name)) continue;
    const target = targets.get(name);
    if (!target) continue;
    visited.add(name);
    const commandDecisions = target.commands.map((command, index) =>
      coverageDetectorDecision(repoPath, repoFiles, {
        path: file,
        source: 'recipe-command',
        locator: `${name}:${index}`,
        command,
      }),
    );
    detectorDecisions.push(...commandDecisions);
    const state = combineCoverageCommandStates(
      commandDecisions.map((decision) => decision.detectorState),
    );
    if (state === 'collects') return 'collects';
    if (state === 'unresolved') unresolved = true;
    for (const dependency of target.dependencies) {
      if (targets.has(dependency) && !visited.has(dependency)) queue.push(dependency);
    }
    for (const command of target.commands) {
      const pattern = new RegExp(`(?:\\$\\(MAKE\\)|\\b${runner})\\s+([A-Za-z0-9._-]+)`, 'gu');
      for (const match of command.matchAll(pattern)) {
        const referenced = match[1];
        if (referenced && targets.has(referenced) && !visited.has(referenced)) queue.push(referenced);
      }
    }
  }
  return unresolved ? 'unresolved' : 'none';
}

function readRecipeTargets(contents: string): Map<string, RecipeTarget> {
  const targets = new Map<string, { dependencies: string[]; commands: string[] }>();
  let active: { dependencies: string[]; commands: string[] } | null = null;
  for (const line of contents.split(/\r?\n/)) {
    const header = /^([A-Za-z0-9][A-Za-z0-9._-]*)\s*:\s*([^#]*)/u.exec(line);
    if (header) {
      const name = header[1];
      if (!name) continue;
      active = {
        dependencies: (header[2] ?? '').trim().split(/\s+/u).filter(Boolean),
        commands: [],
      };
      targets.set(name, active);
      continue;
    }
    if (active && /^\s+/u.test(line) && line.trim().length > 0) {
      active.commands.push(line.trim().replace(/^[@+-]+/u, ''));
      continue;
    }
    if (line.trim().length > 0 && !line.trimStart().startsWith('#')) active = null;
  }
  return targets;
}

interface CoverageCommandEvaluation {
  readonly recognized: boolean;
  readonly state: CoverageCommandState;
}

function coverageCommandEvaluation(
  repoPath: string,
  repoFiles: ReadonlySet<string>,
  command: string,
  depth = 0,
): CoverageCommandEvaluation {
  if (depth > 4) {
    const recognized = containsPotentialCoverageFlag(command);
    return { recognized, state: recognized ? 'unresolved' : 'none' };
  }
  const normalized = normalizeCoverageCommandPrefixes(command);
  const segments = normalized.splitShellOperators
    ? splitShellCommandSegments(normalized.segment)
    : [normalized.segment];
  const evaluations = segments.map((rawSegment): CoverageCommandEvaluation => {
    const candidate = normalizeCoverageCommandPrefixes(rawSegment);
    if (commandInvokesCoverageTool(candidate.segment)) {
      return { recognized: true, state: 'collects' };
    }
    const words = shellWords(candidate.segment);
    if (words.length === 0) return { recognized: false, state: 'none' };
    const direct = coverageFlagCommandState(words);
    if (direct !== 'none') return { recognized: true, state: direct };
    const hasCoverageSyntax = containsPotentialCoverageFlag(candidate.segment);
    if (isRecognizedCoverageFlagRunner(words)) {
      return { recognized: hasCoverageSyntax, state: 'none' };
    }

    const wrapper = reachableShellWrapper(words, repoFiles);
    if (wrapper) {
      return coverageCommandEvaluation(
        repoPath,
        repoFiles,
        readRepoText(join(repoPath, wrapper), 'utf8'),
        depth + 1,
      );
    }
    const executable = commandExecutable(words);
    const potentialFlagState = flagState(
      words.slice(1),
      ['--experimental-test-coverage', '--collectcoverage', '--collect-coverage', '--coverage', '--cov'],
      [
        '--no-experimental-test-coverage',
        '--no-collectcoverage',
        '--no-collect-coverage',
        '--no-coverage',
        '--no-cov',
      ],
    );
    if (
      hasCoverageSyntax &&
      potentialFlagState !== 'none' &&
      executable &&
      /(?:test|spec|runner)/i.test(executable) &&
      !/(?:docs?|map|report|upload|codecov|coveralls)/i.test(executable)
    ) {
      return { recognized: true, state: 'unresolved' };
    }
    return { recognized: false, state: 'none' };
  });
  return {
    recognized: evaluations.some((evaluation) => evaluation.recognized),
    state: combineCoverageCommandStates(
      evaluations.map((evaluation) => evaluation.state),
    ),
  };
}

function coverageDetectorDecision(
  repoPath: string,
  repoFiles: ReadonlySet<string>,
  input: {
    readonly path: string;
    readonly source: CoverageDetectorDecision['source'];
    readonly locator: string;
    readonly command: string;
  },
): CoverageDetectorDecision {
  const evaluation = coverageCommandEvaluation(repoPath, repoFiles, input.command);
  return {
    path: input.path,
    source: input.source,
    locator: input.locator,
    evidence: input.command,
    detectorRecognized: evaluation.recognized,
    detectorState: evaluation.state,
  };
}

function combineCoverageCommandStates(states: readonly CoverageCommandState[]): CoverageCommandState {
  if (states.includes('collects')) return 'collects';
  return states.includes('unresolved') ? 'unresolved' : 'none';
}

/** Exported for the equivalence check in scan-path-regex-bounds.test.ts. */
export function shellWords(segment: string): string[] {
  const words: string[] = [];
  let offset = 0;
  while (offset < segment.length) {
    const scanned = scanShellWord(segment, offset);
    if (!scanned) break;
    words.push(scanned.word);
    if (scanned.end <= offset) break;
    offset = scanned.end;
  }
  return words;
}

function commandExecutable(words: readonly string[]): string | undefined {
  const normalized = unwrapPackageManagerExecutable(words);
  const executable = normalized[0];
  return executable ? basename(executable).replace(/\.cmd$/i, '').toLowerCase() : undefined;
}

function unwrapPackageManagerExecutable(words: readonly string[]): string[] {
  if (words.length === 0) return [];
  const first = basename(words[0] ?? '').toLowerCase();
  if (first === 'pnpm' || first === 'yarn') {
    const second = words[1]?.toLowerCase();
    return words.slice(second === 'exec' || second === 'dlx' ? 2 : 1);
  }
  if (first === 'npx') return words.slice(1).filter((word) => !/^--(?:yes|no-install)$/u.test(word));
  if (first === 'npm' && words[1]?.toLowerCase() === 'exec') {
    let offset = 2;
    while (/^--(?:yes|no-install)$/u.test(words[offset] ?? '')) offset += 1;
    if (words[offset] === '--') offset += 1;
    return words.slice(offset);
  }
  return [...words];
}

function coverageFlagCommandState(words: readonly string[]): CoverageCommandState {
  const command = unwrapPackageManagerExecutable(words);
  const executable = basename(command[0] ?? '').replace(/\.cmd$/i, '').toLowerCase();
  const args = command.slice(1);
  if (!executable) return 'none';

  if (executable === 'node') {
    if (!args.includes('--test')) return 'none';
    return flagState(args, ['--experimental-test-coverage'], ['--no-experimental-test-coverage']);
  }
  if (executable === 'pytest' || executable === 'py.test') {
    return flagState(args, ['--cov'], ['--no-cov']);
  }
  if (executable === 'bun' || executable === 'deno') {
    if (args[0]?.toLowerCase() !== 'test') return 'none';
    return flagState(args.slice(1), ['--coverage'], ['--no-coverage']);
  }
  if (executable === 'jest') {
    return flagState(
      args,
      ['--coverage', '--collectcoverage', '--collect-coverage'],
      ['--no-coverage', '--no-collectcoverage', '--no-collect-coverage'],
    );
  }
  if (executable === 'vitest' || executable === 'bnt') {
    return flagState(args, ['--coverage'], ['--no-coverage']);
  }
  // goal_cejel_v26_coverage_config_recognition_2026-10-14, each from the tool's own documentation.
  if (isPythonModuleRunner(executable, args)) {
    // `python -m pytest` is pytest (docs.pytest.org); flags before `-m` are the interpreter's.
    return flagState(args.slice(2), ['--cov'], ['--no-cov']);
  }
  if (executable === 'go') {
    if (args[0]?.toLowerCase() !== 'test') return 'none';
    // Everything after -args goes to the test binary uninterpreted (go help testflag).
    const end = args.findIndex((arg, index) => index > 0 && /^--?args$/i.test(arg));
    return goTestCoverageState(end < 0 ? args.slice(1) : args.slice(1, end));
  }
  if (executable === 'dotnet') {
    if (args[0]?.toLowerCase() !== 'test') return 'none';
    // Arguments after `--` are RunSettings key=value pairs, not dotnet test options.
    const end = args.indexOf('--', 1);
    return dotnetTestCoverageState(end < 0 ? args.slice(1) : args.slice(1, end));
  }
  if (executable === 'cargo') {
    const subcommand = args[0]?.startsWith('+') ? args.slice(1) : args;
    if (subcommand[0]?.toLowerCase() !== 'llvm-cov') return 'none';
    // `report`, `clean` and `show-env` run no tests, nor does `--no-run`; `run` runs a binary,
    // not the tests (github.com/taiki-e/cargo-llvm-cov).
    if (['report', 'clean', 'show-env', 'run'].includes(subcommand[1]?.toLowerCase() ?? '')) {
      return 'none';
    }
    const end = subcommand.indexOf('--');
    const owned = end < 0 ? subcommand.slice(1) : subcommand.slice(1, end);
    return owned.some((arg) => arg.toLowerCase() === '--no-run') ? 'none' : 'collects';
  }
  return 'none';
}

function isPythonModuleRunner(executable: string, args: readonly string[]): boolean {
  return (
    /^(?:python[0-9.]*|py)$/.test(executable) &&
    args[0] === '-m' &&
    (args[1] === 'pytest' || args[1] === 'py.test')
  );
}

// `-cover` enables coverage; `-covermode`, `-coverpkg` and `-coverprofile` each "set -cover"
// whatever their value. Go accepts one or two leading dashes.
function goTestCoverageState(args: readonly string[]): CoverageCommandState {
  let enabled = false;
  let disabled = false;
  let unresolved = false;
  for (const raw of args) {
    const [name, assigned] = raw.toLowerCase().replace(/^--/u, '-').split('=', 2);
    if (name === '-covermode' || name === '-coverpkg' || name === '-coverprofile') {
      enabled = true;
    } else if (name === '-cover') {
      if (assigned === undefined || /^(?:true|t|1)$/u.test(assigned)) enabled = true;
      else if (/^(?:false|f|0)$/u.test(assigned)) disabled = true;
      else unresolved = true;
    }
  }
  if (unresolved || (enabled && disabled)) return 'unresolved';
  return enabled ? 'collects' : 'none';
}

// `--collect "XPlat Code Coverage"` (coverlet) or `--collect "Code Coverage"` (Microsoft), the
// friendly name case-insensitive (learn.microsoft.com/dotnet/core/testing/unit-testing-code-coverage);
// or coverlet.msbuild's `/p:CollectCoverage=true` (coverlet MSBuildIntegration.md).
function dotnetTestCoverageState(args: readonly string[]): CoverageCommandState {
  let enabled = false;
  let disabled = false;
  let unresolved = false;
  for (let index = 0; index < args.length; index += 1) {
    const lower = (args[index] ?? '').toLowerCase();
    const collect = /^--collect(?:[:=]([\s\S]*))?$/u.exec(lower);
    if (collect) {
      const value = (collect[1] ?? args[(index += 1)]?.toLowerCase() ?? '').trim();
      if (/\$|\{|\}/u.test(value)) unresolved = true;
      else if (value === 'xplat code coverage' || value === 'code coverage') enabled = true;
      continue;
    }
    const property = /^(?:[/-]p|--property):([\s\S]*)$/u.exec(lower);
    if (!property) continue;
    for (const assignment of (property[1] ?? '').split(/[;,]/u)) {
      const [name, value] = assignment.split('=', 2).map((part) => part.trim());
      if (name !== 'collectcoverage' || value === undefined) continue;
      if (value === 'true') enabled = true;
      else if (value === 'false') disabled = true;
      else unresolved = true;
    }
  }
  if (unresolved || (enabled && disabled)) return 'unresolved';
  return enabled ? 'collects' : 'none';
}

function isRecognizedCoverageFlagRunner(words: readonly string[]): boolean {
  const command = unwrapPackageManagerExecutable(words);
  const executable = basename(command[0] ?? '').replace(/\.cmd$/i, '').toLowerCase();
  if (['bnt', 'vitest', 'jest', 'pytest', 'py.test'].includes(executable)) return true;
  if (executable === 'node') return command.slice(1).includes('--test');
  if (isPythonModuleRunner(executable, command.slice(1))) return true;
  const subcommand = command[1]?.toLowerCase();
  if (executable === 'go' || executable === 'dotnet') return subcommand === 'test';
  if (executable === 'cargo') {
    return (subcommand?.startsWith('+') ? command[2] : command[1])?.toLowerCase() === 'llvm-cov';
  }
  return (executable === 'bun' || executable === 'deno') && subcommand === 'test';
}

function flagState(
  args: readonly string[],
  enablingNames: readonly string[],
  disablingNames: readonly string[],
): CoverageCommandState {
  let enabled = false;
  let disabled = false;
  let unresolved = false;
  const enabling = new Set(enablingNames.map((name) => name.toLowerCase()));
  const disabling = new Set(disablingNames.map((name) => name.toLowerCase()));

  for (let index = 0; index < args.length; index += 1) {
    const raw = args[index] ?? '';
    const lower = raw.toLowerCase();
    if (disabling.has(lower)) {
      disabled = true;
      continue;
    }
    const [name, assigned] = lower.split('=', 2);
    if (!name || !enabling.has(name)) continue;
    if (assigned !== undefined) {
      if (assigned === 'false' || assigned === '0' || assigned === 'off') disabled = true;
      else if (/\$|\{|\}/u.test(assigned)) unresolved = true;
      else enabled = true;
      continue;
    }
    const next = args[index + 1]?.toLowerCase();
    if (next === 'false' || next === '0' || next === 'off') {
      disabled = true;
      index += 1;
    } else if (next && /\$|\{|\}/u.test(next)) {
      unresolved = true;
      index += 1;
    } else {
      enabled = true;
    }
  }
  if (unresolved || (enabled && disabled)) return 'unresolved';
  return enabled && !disabled ? 'collects' : 'none';
}

function containsPotentialCoverageFlag(command: string): boolean {
  return /(?:^|\s)--(?:experimental-test-coverage|collect-?coverage|no-coverage|coverage|no-cov|cov)(?:[=\s]|$)/iu.test(
    command,
  );
}

function reachableShellWrapper(
  words: readonly string[],
  repoFiles: ReadonlySet<string>,
): string | undefined {
  const executable = basename(words[0] ?? '').toLowerCase();
  const candidate = /^(?:ba|da|k|z)?sh$/u.test(executable) ? words[1] : words[0];
  if (!candidate || !isShellScriptPath(candidate)) return undefined;
  const normalized = candidate.replace(/^\.\//u, '');
  if (normalized.startsWith('/') || normalized.split('/').includes('..')) return undefined;
  return repoFiles.has(normalized) ? normalized : undefined;
}

function commandInvokesCoverageTool(command: string): boolean {
  return normalizedCommandInvokesCoverageTool(normalizeCoverageCommandPrefixes(command), 0);
}

function normalizedCommandInvokesCoverageTool(
  normalized: { segment: string; splitShellOperators: boolean },
  depth: number,
): boolean {
  const segments = normalized.splitShellOperators
    ? splitShellCommandSegments(normalized.segment)
    : [normalized.segment];
  return segments.some((rawSegment) => {
    const candidate = normalizeCoverageCommandPrefixes(rawSegment);
    if (/^(?:nyc|c8|istanbul)(?:\s|$)/iu.test(candidate.segment)) return true;
    return (
      depth < 4 &&
      candidate.splitShellOperators &&
      candidate.segment !== rawSegment.trim() &&
      normalizedCommandInvokesCoverageTool(candidate, depth + 1)
    );
  });
}

function splitShellCommandSegments(command: string): string[] {
  const segments: string[] = [];
  let start = 0;
  let quote: "'" | '"' | null = null;
  let escaped = false;

  for (let index = 0; index < command.length; index += 1) {
    const character = command[index];
    if (escaped) {
      escaped = false;
      continue;
    }
    if (character === '\\' && quote !== "'") {
      escaped = true;
      continue;
    }
    if (quote) {
      if (character === quote) quote = null;
      continue;
    }
    if (character === "'" || character === '"') {
      quote = character;
      continue;
    }
    if (character === '#' && (index === 0 || /[\s;|&()]/u.test(command[index - 1] ?? ''))) {
      segments.push(command.slice(start, index));
      const newline = command.indexOf('\n', index + 1);
      if (newline < 0) return segments;
      index = newline;
      start = newline + 1;
      continue;
    }

    const isBoundary =
      character === ';' || character === '|' || character === '&' || character === '\n';
    if (!isBoundary) continue;
    segments.push(command.slice(start, index));
    if ((character === '|' || character === '&') && command[index + 1] === character) index += 1;
    start = index + 1;
  }
  segments.push(command.slice(start));
  return segments;
}

function normalizeCoverageCommandPrefixes(rawSegment: string): {
  segment: string;
  splitShellOperators: boolean;
} {
  let segment = rawSegment.trim();
  let unwrapQuotedShellCommand = false;
  let splitShellOperators = true;
  for (let index = 0; index < 8; index += 1) {
    const before = segment;
    segment = stripOuterShellGroup(segment);
    segment = segment.replace(/^(?:[A-Za-z_][A-Za-z0-9_]*=(?:"[^"]*"|'[^']*'|[^\s]+)\s+)*/u, '');
    segment = segment.replace(
      /^(?:npx|npm\s+exec|pnpm\s+(?:exec|dlx)|yarn\s+(?:exec|dlx))(?:\s+--(?:no-install|yes))*(?:\s+--)?\s+/iu,
      '',
    );
    segment = segment.replace(/^(?:command(?:\s+-p)?(?:\s+--)?|time(?:\s+-p)?)\s+/iu, '');
    const explicitShellCommand = extractExplicitShellCommand(segment);
    if (explicitShellCommand !== null) {
      segment = explicitShellCommand;
      unwrapQuotedShellCommand = false;
      splitShellOperators = true;
    }
    const environmentPrefix = stripEnvironmentCommandPrefix(segment);
    segment = environmentPrefix.segment;
    unwrapQuotedShellCommand ||= environmentPrefix.unwrapQuotedShellCommand;
    if (environmentPrefix.splitShellOperators !== null) {
      splitShellOperators = environmentPrefix.splitShellOperators;
    }
    if (segment === before) break;
  }
  return {
    segment: unwrapQuotedShellCommand ? segment.replace(/^(["'])(.*)\1$/u, '$2').trim() : segment,
    splitShellOperators,
  };
}

function extractExplicitShellCommand(segment: string): string | null {
  const shellExecutable = /^(?:(?:\/(?:usr\/)?bin\/)?(?<shell>(?:ba|da|k|z)?sh))(?=\s|$)/iu.exec(
    segment,
  );
  if (!shellExecutable) return null;
  const shell = shellExecutable.groups?.shell?.toLowerCase();
  if (!shell) return null;

  let offset = shellExecutable[0].length;
  let noExecute = false;
  let dumpStrings = false;
  for (let optionCount = 0; optionCount < 32; optionCount += 1) {
    const option = scanShellWord(segment, offset);
    if (!option || (!option.word.startsWith('-') && !option.word.startsWith('+'))) return null;
    offset = option.end;

    if (option.word === '--') return null;

    const zshLongOption =
      shell === 'zsh' ? /^(?<sign>--|\+-)(?<name>[A-Za-z][A-Za-z_-]*)$/u.exec(option.word) : null;
    if (zshLongOption) {
      const optionName = zshLongOption.groups?.name?.replaceAll('-', '');
      if (!optionName) return null;
      const resolvedSetOption = resolveSupportedShellSetOption(shell, optionName);
      if (!resolvedSetOption && !isSupportedZshLongInvocationOption(optionName)) return null;
      if (resolvedSetOption?.name === 'noexec') {
        noExecute = (zshLongOption.groups?.sign === '--') !== resolvedSetOption.inverted;
      }
      continue;
    }

    if (option.word === '--rcfile' || option.word === '--init-file') {
      const operand = scanShellWord(segment, offset);
      if (shell !== 'bash' || !operand) return null;
      offset = operand.end;
      continue;
    }
    if (
      shell === 'bash' &&
      /^--(?:debug|debugger|login|noediting|noprofile|norc|posix|protected|restricted|verbose)$/u.test(
        option.word,
      )
    ) {
      continue;
    }

    const cluster = parseSupportedShellOptionCluster(shell, option.word);
    if (!cluster) return null;
    if (cluster.changesNoExecute) noExecute = cluster.sign === '-';
    if (cluster.enablesDumpStrings) dumpStrings = true;

    if (cluster.operandKind) {
      const operand = scanShellWord(segment, offset);
      const resolvedSetOperand =
        operand && cluster.operandKind === 'set'
          ? resolveSupportedShellSetOption(shell, operand.word)
          : null;
      const operandIsZshInvocationOption =
        shell === 'zsh' &&
        operand !== null &&
        cluster.operandKind === 'set' &&
        isSupportedZshLongInvocationOption(operand.word);
      const operandIsSupported =
        cluster.operandKind === 'set'
          ? resolvedSetOperand !== null || operandIsZshInvocationOption
          : shell === 'bash' && operand && BASH_SHOPT_OPTIONS.has(operand.word);
      if (!operand || !operandIsSupported) return null;
      if (resolvedSetOperand?.name === 'noexec') {
        noExecute = (cluster.sign === '-') !== resolvedSetOperand.inverted;
      }
      offset = operand.end;
    }

    if (cluster.hasCommand) {
      return noExecute || dumpStrings ? null : readShellWord(segment, offset);
    }
  }
  return null;
}

const BASH_SET_OPTIONS = new Set([
  'allexport',
  'braceexpand',
  'emacs',
  'errexit',
  'errtrace',
  'functrace',
  'hashall',
  'histexpand',
  'history',
  'ignoreeof',
  'keyword',
  'monitor',
  'noclobber',
  'noexec',
  'noglob',
  'nolog',
  'notify',
  'nounset',
  'onecmd',
  'physical',
  'pipefail',
  'posix',
  'privileged',
  'verbose',
  'vi',
  'xtrace',
]);

const BASH_SHOPT_OPTIONS = new Set([
  'autocd',
  'cdable_vars',
  'cdspell',
  'checkhash',
  'checkjobs',
  'checkwinsize',
  'cmdhist',
  'complete_fullquote',
  'direxpand',
  'dirspell',
  'dotglob',
  'execfail',
  'expand_aliases',
  'extdebug',
  'extglob',
  'extquote',
  'failglob',
  'force_fignore',
  'globasciiranges',
  'globskipdots',
  'globstar',
  'gnu_errfmt',
  'histappend',
  'histreedit',
  'histverify',
  'hostcomplete',
  'huponexit',
  'inherit_errexit',
  'interactive_comments',
  'lastpipe',
  'lithist',
  'localvar_inherit',
  'localvar_unset',
  'login_shell',
  'mailwarn',
  'nocaseglob',
  'nocasematch',
  'no_empty_cmd_completion',
  'nullglob',
  'progcomp',
  'progcomp_alias',
  'promptvars',
  'restricted_shell',
  'shift_verbose',
  'sourcepath',
  'varredir_close',
  'xpg_echo',
]);

const POSIX_SET_OPTIONS = new Set([
  'allexport',
  'errexit',
  'ignoreeof',
  'noclobber',
  'noexec',
  'noglob',
  'nounset',
  'verbose',
  'vi',
  'xtrace',
]);

const ZSH_LONG_INVOCATION_OPTIONS = new Set([
  'interactive',
  'login',
  'privileged',
  'shinstdin',
  'stdin',
]);

function isSupportedShellSetOption(shell: string, option: string): boolean {
  if (shell === 'bash') return BASH_SET_OPTIONS.has(option);
  if (shell === 'sh' || shell === 'dash') return POSIX_SET_OPTIONS.has(option);
  if (shell === 'ksh' || shell === 'zsh') {
    return POSIX_SET_OPTIONS.has(option) || option === 'pipefail';
  }
  return false;
}

function normalizeShellSetOption(shell: string, option: string): string {
  if (shell === 'zsh') return option.toLowerCase().replaceAll('_', '');
  return option;
}

function isSupportedZshLongInvocationOption(option: string): boolean {
  const normalized = normalizeShellSetOption('zsh', option);
  if (ZSH_LONG_INVOCATION_OPTIONS.has(normalized)) return true;
  return (
    normalized.startsWith('no') &&
    !normalized.startsWith('nono') &&
    ZSH_LONG_INVOCATION_OPTIONS.has(normalized.slice(2))
  );
}

function resolveSupportedShellSetOption(
  shell: string,
  option: string,
): { name: string; inverted: boolean } | null {
  const normalized = normalizeShellSetOption(shell, option);
  if (shell === 'zsh' && normalized === 'exec') {
    return { name: 'noexec', inverted: true };
  }
  if (isSupportedShellSetOption(shell, normalized)) {
    return { name: normalized, inverted: false };
  }
  if (
    shell === 'zsh' &&
    normalized.startsWith('no') &&
    !normalized.startsWith('nono') &&
    isSupportedShellSetOption(shell, normalized.slice(2))
  ) {
    return { name: normalized.slice(2), inverted: true };
  }
  return null;
}

function parseSupportedShellOptionCluster(
  shell: string,
  option: string,
): {
  sign: '-' | '+';
  hasCommand: boolean;
  changesNoExecute: boolean;
  enablesDumpStrings: boolean;
  operandKind: 'set' | 'shopt' | null;
} | null {
  if (!/^[+-][A-Za-z]+$/u.test(option)) return null;
  const sign = option[0] as '-' | '+';
  let letters = option.slice(1);
  let operandKind: 'set' | 'shopt' | null = null;
  const operandLetter = letters.at(-1);
  if (operandLetter === 'o' || operandLetter === 'O') {
    if (operandLetter === 'O' && shell !== 'bash') return null;
    letters = letters.slice(0, -1);
    if (letters.includes('c')) return null;
    operandKind = operandLetter === 'o' ? 'set' : 'shopt';
  }

  const supportedLetters =
    shell === 'bash'
      ? 'abcefhkmnptuvxBCEHPTilrsD'
      : shell === 'sh'
        ? 'abCcefimnsuvx'
        : shell === 'dash'
          ? 'abCcefilmnsuvx'
          : 'acefilmnpsuvx';
  if (![...letters].every((letter) => supportedLetters.includes(letter))) return null;

  return {
    sign,
    hasCommand: letters.includes('c'),
    changesNoExecute: letters.includes('n'),
    enablesDumpStrings: shell === 'bash' && letters.includes('D'),
    operandKind,
  };
}

/**
 * Whether a UTF-16 code unit is one `/\s/u` matches: ECMAScript's WhiteSpace and LineTerminator
 * code points (tab, LF, VT, FF, CR, space, NBSP, U+1680, U+2000-U+200A, LS, PS, U+202F, U+205F,
 * U+3000, BOM). A comparison, not a regex test, so a scanner pays nothing per character for it
 * (goal_cejel_v27_conftest_timing_guard_2026-11-02). Pinned against `/\s/u` for every code unit in
 * scan-path-regex-bounds.test.ts.
 */
export function isShellWhitespaceCode(code: number): boolean {
  if (code <= 0x20) return code === 0x20 || (code >= 0x09 && code <= 0x0d);
  if (code < 0xa0) return false;
  return (
    code === 0xa0 ||
    code === 0x1680 ||
    (code >= 0x2000 && code <= 0x200a) ||
    code === 0x2028 ||
    code === 0x2029 ||
    code === 0x202f ||
    code === 0x205f ||
    code === 0x3000 ||
    code === 0xfeff
  );
}

const SHELL_BACKSLASH = 0x5c;
const SHELL_SINGLE_QUOTE = 0x27;
const SHELL_DOUBLE_QUOTE = 0x22;
const SHELL_NEWLINE = 0x0a;
const SHELL_DOLLAR = 0x24;
const SHELL_BACKTICK = 0x60;

/**
 * One shell word from `start`: leading white space skipped, quotes removed, a backslash escape
 * applied (outside single quotes; inside double quotes only before $ ` " \ or a newline), and an
 * escaped newline dropped. Null when the text ends inside a quote or an escape, or holds no word.
 * Characters kept as written are copied a run at a time, not appended one by one, so a long word
 * costs one pass (goal_cejel_v27_conftest_timing_guard_2026-11-02; the words are unchanged).
 */
function scanShellWord(value: string, start: number): { word: string; end: number } | null {
  let result = '';
  let quote = 0;
  let escaped = false;
  let index = start;

  while (index < value.length && isShellWhitespaceCode(value.charCodeAt(index))) index += 1;
  const wordStart = index;
  // value.slice(copyFrom, index) is kept as written and not yet in `result`.
  let copyFrom = index;

  for (; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    if (escaped) {
      // The escaped character is kept (copyFrom already points at it), except a newline.
      if (code === SHELL_NEWLINE) copyFrom = index + 1;
      escaped = false;
      continue;
    }
    if (code === SHELL_BACKSLASH && quote !== SHELL_SINGLE_QUOTE) {
      const next = value.charCodeAt(index + 1);
      const escapesNext =
        quote !== SHELL_DOUBLE_QUOTE ||
        next === SHELL_DOLLAR ||
        next === SHELL_BACKTICK ||
        next === SHELL_DOUBLE_QUOTE ||
        next === SHELL_BACKSLASH ||
        next === SHELL_NEWLINE;
      if (escapesNext) {
        result += value.slice(copyFrom, index);
        copyFrom = index + 1;
        escaped = true;
      }
      continue;
    }
    if (quote !== 0) {
      if (code === quote) {
        result += value.slice(copyFrom, index);
        copyFrom = index + 1;
        quote = 0;
      }
      continue;
    }
    if (code === SHELL_SINGLE_QUOTE || code === SHELL_DOUBLE_QUOTE) {
      result += value.slice(copyFrom, index);
      copyFrom = index + 1;
      quote = code;
      continue;
    }
    if (isShellWhitespaceCode(code)) break;
  }

  if (escaped || quote !== 0 || index === wordStart) return null;
  return { word: result + value.slice(copyFrom, index), end: index };
}

function readShellWord(value: string, start: number): string | null {
  return scanShellWord(value, start)?.word ?? null;
}

function stripOuterShellGroup(segment: string): string {
  if (!segment.startsWith('(') || segment.startsWith('((')) return segment;

  let depth = 0;
  let quote: "'" | '"' | null = null;
  let escaped = false;
  for (let index = 0; index < segment.length; index += 1) {
    const character = segment[index];
    if (escaped) {
      escaped = false;
      continue;
    }
    if (character === '\\' && quote !== "'") {
      escaped = true;
      continue;
    }
    if (quote) {
      if (character === quote) quote = null;
      continue;
    }
    if (character === "'" || character === '"') {
      quote = character;
      continue;
    }
    if (character === '(') {
      depth += 1;
      continue;
    }
    if (character !== ')') continue;
    depth -= 1;
    if (depth < 0) return segment;
    if (depth === 0) {
      if (segment.slice(index + 1).trim().length > 0) return segment;
      return segment.slice(1, index).trim();
    }
  }
  return segment;
}

function stripEnvironmentCommandPrefix(segment: string): {
  segment: string;
  unwrapQuotedShellCommand: boolean;
  splitShellOperators: boolean | null;
} {
  const wrapper = /^(cross-env(?:-shell)?|env)(?:\s|$)/iu.exec(segment);
  if (!wrapper) {
    return { segment, unwrapQuotedShellCommand: false, splitShellOperators: null };
  }

  let remainder = segment.slice(wrapper[0].length).trimStart();
  let unwrapQuotedShellCommand = wrapper[1]?.toLowerCase() === 'cross-env-shell';
  let splitShellOperators = true;
  while (remainder.length > 0) {
    const splitString =
      /^(?:-S|--split-string)(?:=|\s+)(?:"([^"]*)"|'([^']*)'|([^\s]+))(?:\s+|$)/u.exec(remainder);
    if (splitString) {
      const splitCommand = splitString[1] ?? splitString[2] ?? splitString[3] ?? '';
      remainder = `${splitCommand} ${remainder.slice(splitString[0].length)}`.trim();
      unwrapQuotedShellCommand = false;
      splitShellOperators = false;
      continue;
    }

    const assignment = /^[A-Za-z_][A-Za-z0-9_]*=(?:"[^"]*"|'[^']*'|[^\s]+)(?:\s+|$)/u.exec(
      remainder,
    );
    if (assignment) {
      remainder = remainder.slice(assignment[0].length).trimStart();
      continue;
    }

    const optionWithValue =
      /^(?:-u|--unset|-C|--chdir)(?:=|\s+)(?:"[^"]*"|'[^']*'|[^\s]+)(?:\s+|$)/u.exec(remainder);
    if (optionWithValue) {
      remainder = remainder.slice(optionWithValue[0].length).trimStart();
      continue;
    }

    const flag = /^(?:--ignore-environment|-i|--)(?:\s+|$)/u.exec(remainder);
    if (flag) {
      remainder = remainder.slice(flag[0].length).trimStart();
      continue;
    }
    break;
  }
  return { segment: remainder, unwrapQuotedShellCommand, splitShellOperators };
}

function isCiWorkflow(file: string): boolean {
  return (
    /^\.github\/workflows\/.+\.ya?ml$/.test(file) ||
    /^\.gitlab-ci\.ya?ml$/.test(file) ||
    /^\.circleci\/config\.ya?ml$/.test(file) ||
    /^azure-pipelines\.ya?ml$/.test(file) ||
    /^Jenkinsfile$/.test(file)
  );
}

function isDeployConfig(file: string): boolean {
  return (
    /(^|\/)(vercel|netlify|fly|render|railway)\.(json|toml|ya?ml)$/.test(file) ||
    /(^|\/)Dockerfile$/.test(file) ||
    /(^|\/)docker-compose\.ya?ml$/.test(file) ||
    /(^|\/)k8s\//.test(file)
  );
}

// Explicit deploy targets — Dockerfile alone is excluded because it is often
// a build or CI artifact; require it paired with a server entrypoint or
// a platform-specific deploy config to treat a repo as a deployable service.
function isExplicitDeployTarget(file: string): boolean {
  return (
    /(^|\/)(vercel|netlify|fly|render|railway)\.(json|toml|ya?ml)$/.test(file) ||
    /(^|\/)docker-compose\.ya?ml$/.test(file) ||
    /(^|\/)Procfile$/.test(file) ||
    /(^|\/)app\.ya?ml$/.test(file) ||
    /(^|\/)serverless\.ya?ml$/.test(file) ||
    /(^|\/)(k8s|kubernetes|manifests?)\/.+\.ya?ml$/i.test(file) ||
    /(^|\/)(charts?|helm)\/.+\.ya?ml$/i.test(file)
  );
}

// Entry-point-shaped file names (main, server, app, wsgi, asgi, index, etc.).
// Limiting server-entrypoint content scanning to these avoids false positives
// on framework source files that define (but do not call) listen/serve methods.
const MAIN_ENTRYPOINT_FILE_PATTERN =
  /(^|\/)(main|server|app|wsgi|asgi|index|entry|start|run)\.(ts|tsx|js|jsx|mjs|cjs|py|go|rs)$/i;
const RACK_ENTRYPOINT_FILE_PATTERN = /(^|\/)(?:config\.ru|(?:main|server|app|start|run)\.rb)$/i;

// app.listen / app.run under a test/example/fixture dir does NOT make the repo a deployable
// service — uses the shared isTestOrFixturePath classifier (see canonical block above), not a
// private regex of its own.

// Active server/port-binding calls across common frameworks and languages.
// Matches invocations (app.listen(port), uvicorn.run(app, ...), etc.) rather
// than method definitions in framework source (Application.prototype.listen = ...).
const SERVER_ENTRYPOINT_PATTERN =
  /\bapp\.listen\s*\(|\bserver\.listen\s*\(\s*(?:PORT|port|\d+)|http\.ListenAndServe\s*\(|http\.ListenAndServeTLS\s*\(|axum::Server(?:::|\.)|actix_web::HttpServer(?:::|\.)|uvicorn\.run\s*\(/;
// V20-only direct Node HTTP shape. Requiring both an entrypoint-shaped authored path and a
// bounded createServer(...).listen(port) expression avoids changing historical deployability
// classification or treating a helper that merely constructs an unbound server as production.
const V20_DIRECT_HTTP_SERVER_PATTERN =
  /\b(?:http|https)\.createServer\s*\([\s\S]{0,1500}?\)\.listen\s*\(\s*(?:PORT|port|\d+)/;
// Firebase/Netlify-style serverless functions convention. See healthReadinessRouteReads above
// for why this is a separate, signal-scoped pattern rather than a change to isImplementationFile.
const HEALTH_ROUTE_FUNCTIONS_DIR_PATTERN =
  /(^|\/)functions\/.*\.(?:ts|tsx|js|jsx|py|go|rs|java|rb|cpp|cc|cxx|c|h|hpp|kt|swift|php)$/;
// goal_cejel_a3_handler_shapes_and_inline_health_2026-10-12: the other ordinary homes of a
// production HTTP entrypoint that sit outside isImplementationFile's directory list, catalogued
// in a3-health-route-idioms.test.ts. Each is anchored to the REPOSITORY ROOT, never to a nested
// path, so `docs/api/index.js` or `vendor/server/x.js` cannot match:
//   - a root-level single-file server (`server.ts`, `index.js`, `app.ts`, `main.js`), the
//     smallest Express/Fastify service layout;
//   - a `server/`, `backend/` or `api/` tree (a conventional Node backend root; `api/` is also the
//     Vercel functions directory).
// Scoped to this one signal like the functions/ pattern above. It is always evaluated together
// with isAuthoredProductionPath, which still excludes tests, fixtures, examples, generated and
// vendored paths; `scripts/`, `tools/` and `docs/` are not admitted.
const HEALTH_ROUTE_ENTRYPOINT_HOME_PATTERN =
  /^(?:(?:server|index|app|main)\.(?:ts|tsx|js|jsx|mjs|cjs)|(?:server|backend|api)\/.*\.(?:ts|tsx|js|jsx|mjs|cjs|py|go|rs|java|rb|php))$/;
// Widened from an exact `["'`]/(health|ready|...)["'`]` match, which required the route
// literal to contain nothing but the bare keyword. That missed the Kubernetes convention
// (/healthz, /readyz, /livez), any mount prefix (/api/health), and any suffix (/health/live) —
// all public-documentation idioms, not narrow spellings. Still bounded to a single path segment
// on each side of the keyword so it cannot cross string boundaries or read like arbitrary prose;
// a route defined by a router mounted at '/health' with its own relative '/' handler is a
// cross-expression case this pattern still cannot see (goal_cejel_a3_runtime_pattern_coverage,
// stated as out of scope).
//
// goal_cejel_a3_health_route_idioms_v23 widened this further, on fixture evidence
// (a3-health-route-idioms.test.ts), in two bounded ways plus one new keyword:
//   - a single `_` or `-` is now allowed directly between the mandatory leading `/` and the
//     keyword (`/_health`, `/-/ready` already matched via the multi-segment case; `/_health` did
//     not, and it is the same GAE/`_ah`-style convention).
//   - bare whole-string keywords are limited to healthz, readiness, and liveness.
//     The common word health additionally requires `@Get('health')` decorator context.
//     Whole-string matching alone still credits unrelated state/event/config literals such as
//     'ready', 'live', and 'health'; the idiom suite guards those false positives.
// `up` was added as a keyword — Rails' documented convention (`/up`) — but ONLY in the
// slash-anchored form above, never in the bare-string alternative: an un-anchored bare 'up' also
// matches ordinary direction/toggle literals (`'up' | 'down'`), which the slash requirement rules
// out. `ping`, `status`, and `alive` were considered and deliberately left uncredited: they are
// either too generic (a `/status` or `/ping` endpoint is common for meanings that have nothing to
// do with health) or not a named, documented convention the way `/up` and `/healthz` are — see
// the idiom table in a3-health-route-idioms.test.ts. A trailing query string (`/health?probe=1`)
// is also deliberately left uncredited: crediting it would also credit an outbound probe/test URL
// with a query string appended, and this signal treats a false assertion as worse than a miss.
const V20_HEALTH_OR_READINESS_ROUTE_PATTERN =
  /["'`](?:[\w${}./-]{0,60}\/[_-]?(?:(?:health|ready|live)z?|readiness|liveness|up)(?=["'`/])|(?:healthz|readiness|liveness)(?=["'`]))|@Get\s*\(\s*(["'`])health\1\s*\)/i;
// Express recognizes error-handling middleware by arity alone — any four-parameter
// function/arrow is treated as an error handler — but the canonical public-documentation form
// names the parameters (err, req, res, next), optionally TypeScript-typed. Matching by name
// rather than bare arity keeps this from firing on an unrelated four-parameter function.
//
// The type-annotation group tolerates one level of generic type arguments (`Request<P, ResBody,
// ReqBody>`) by treating a balanced `<...>` span as a single atom the surrounding comma-split
// cannot see inside — a bare `[^,()]+` stops at the first comma INSIDE the generic, so a
// realistic Express+TypeScript handler typed with route/response/body generics never matched.
// Does not handle nested generics (`Foo<Bar<Baz, Qux>>`); that is a documented limit, not silent.
//
// goal_cejel_a3_error_boundary_idioms_2026-09-22: the first and fourth parameter names also
// tolerate a leading underscore (`_err`, `_next`) — the ordinary lint-driven convention for
// marking a required-but-unused parameter, still a named four-parameter match, not an arity-only
// one. A three-parameter form with `next` omitted entirely is deliberately NOT matched here:
// Express recognizes error middleware by arity, so a bare `(err, req, res)` is indistinguishable
// from ordinary middleware missing its fourth parameter by mistake, and matching on three names
// alone is the arity-adjacent false positive this pattern exists to avoid. Stated limit, not a
// silent gap: recorded in src/witan/__tests__/a3-error-boundary-idioms.test.ts.
//
// goal_cejel_a3_handler_shapes_and_inline_health_2026-10-12 widened this in two bounded ways, on
// fixture evidence (rows 10a-10h in the same test file):
//   - the second and third parameter names (`req`/`request`, `res`/`response`) also tolerate a
//     leading underscore. Same lint convention as `_err`/`_next`: a required-but-unused
//     parameter, `(err, _req, res, next)`, is the ordinary spelling when the handler never reads
//     the request. Still four NAMED parameters, never an arity-only match.
//   - one optional trailing comma after the fourth parameter and its optional type, before the
//     closing paren. Prettier's default `trailingComma: "all"` emits it on every multi-line
//     parameter list, so a handler formatted one parameter per line never matched. `,?` allows
//     exactly one comma after `next`; it does not admit an extra parameter, and a three-parameter
//     list with a trailing comma stays uncredited (row 4c's limit is unchanged).
// Reachability (EXPRESS_MIDDLEWARE_REACHABLE_PATTERN) and the test/docs/comment exclusions apply
// unchanged to every newly matched shape: rows D6-D8 pin that.
const EXPRESS_ERROR_MIDDLEWARE_PATTERN =
  /\(\s*(?:_?err|_?error)(?:\s*:\s*(?:[^,()<]|<[^<>]*>)*)?\s*,\s*_?(?:req|request)(?:\s*:\s*(?:[^,()<]|<[^<>]*>)*)?\s*,\s*_?(?:res|response)(?:\s*:\s*(?:[^,()<]|<[^<>]*>)*)?\s*,\s*_?next(?:\s*:\s*(?:[^,()<]|<[^<>]*>)*)?\s*,?\s*\)\s*(?:=>|\{)/i;
// A parameter-shape match alone also matches a fully dead, never-registered stub. Requiring the
// same file to show some sign the handler is reachable — passed directly to `.use(`, or exported
// so another file could import and register it — excludes tutorial boilerplate copy-pasted into
// an unrelated file with nothing else referencing it, without requiring the wiring call site
// itself to be in the same file (frequently isn't: a named handler declared in one file is
// commonly registered via `app.use(errorHandler)` in the app's entrypoint).
//
// goal_cejel_a3_error_boundary_idioms_2026-09-22: `export class` added alongside the existing
// `export default`/`function`/`const` alternatives — a class-based handler
// (`export class ErrorService { handleError(err, req, res, next) {...} }`, registered elsewhere
// via `app.use(svc.handleError.bind(svc))`) is a real, public-documentation Express idiom that
// the original three alternatives did not cover. Evaluated with comments stripped first (see
// fileMatchesOutsideComments) so a commented-out `.use(` cannot satisfy this pattern while
// registering nothing.
const EXPRESS_MIDDLEWARE_REACHABLE_PATTERN =
  /\.use\s*\(|\bmodule\.exports\b|\bexport\s+(?:default\b|function\b|const\b|class\b)/;
// A3's filename-convention error boundary: `error-boundary.tsx`, or a Next.js-style `error.tsx`
// route file. Anchored to a whole path segment (#433).
const ERROR_BOUNDARY_FILENAME_PATTERN = /(^|\/)(?:error-boundary|error)\.(?:tsx|jsx|ts|js)$/;
const RACK_SERVER_ENTRYPOINT_PATTERN = /Rack::(?:Server|Handler(?:::\w+)?)\.(?:start|run)\s*\(/;
const RACK_CONFIG_RUN_PATTERN =
  /^[^\S\n\r\u2028\u2029]*run\s+(?:(?:[A-Z]\w*(?:::\w+)*(?:\.new)?|lambda)\b|->)/m;
const RUNTIME_CONTAINER_COMMAND_PATTERN =
  /^[^\S\n\r\u2028\u2029]*(?:CMD|ENTRYPOINT)\s+.*(?:\b(?:start|serve|server|qgis|nginx|apache|gunicorn|uvicorn)\b|manage\.py\s+runserver).*$/im;
const NON_RUNTIME_CONTAINER_COMMAND_PATTERN = /\b(?:test|lint|build|compile|package|check)\b/i;
const V20_NODE_RUNTIME_CONTAINER_COMMAND_PATTERN =
  /\bnode\b.*\b(?:main|server|app|service|index)\.(?:[cm]?js|ts)\b/i;

// CI workflow job/step patterns that indicate a real deployment step.
// Covers named deploy jobs in YAML and common deploy CLI commands.
const CI_DEPLOY_JOB_PATTERN =
  /(?:^\s{2,4}deploy\s*:|\b(?:fly|heroku|vercel|netlify|railway|render)\s+deploy\b|kubectl\s+apply\b|helm\s+(?:install|upgrade|deploy)\b|docker\s+push\b)/im;

function isDeployableService(
  repoPath: string,
  repoFiles: readonly string[],
  useV27Detectors: boolean,
): boolean {
  // Explicit platform deploy target (Procfile, vercel.json, docker-compose, k8s, etc.)
  if (
    repoFiles.some(
      (file) =>
        (useV27Detectors ? isAuthoredProductionPath(file) : isProductionSourcePath(file)) &&
        isExplicitDeployTarget(file),
    )
  ) {
    return true;
  }
  // CI workflow with a real deploy job/step
  if (detectCiDeployJob(repoPath, repoFiles, useV27Detectors)) return true;
  // Production server entrypoint in a main/server/app file (not in examples/tests)
  if (detectServerEntrypoint(repoPath, repoFiles, useV27Detectors)) return true;
  // A production Dockerfile is a runtime surface only when it declares an actual start
  // command. Build/test-only Dockerfiles remain non-deployable.
  if (useV27Detectors && findRuntimeContainerEntrypointFile(repoPath, repoFiles)) return true;
  return false;
}

function detectCiDeployJob(
  repoPath: string,
  repoFiles: readonly string[],
  authoredOnly = false,
): boolean {
  const workflows = repoFiles.filter(
    (file) => (!authoredOnly || isAuthoredProductionPath(file)) && isCiWorkflow(file),
  );
  return workflows.some((file) => fileContains(repoPath, file, CI_DEPLOY_JOB_PATTERN));
}

function detectServerEntrypoint(
  repoPath: string,
  repoFiles: readonly string[],
  useV27Detectors: boolean,
): boolean {
  return findServerEntrypointFile(repoPath, repoFiles, useV27Detectors) !== null;
}

function findServerEntrypointFile(
  repoPath: string,
  repoFiles: readonly string[],
  useV27Detectors: boolean,
): string | null {
  // Restrict to entry-point-shaped files to avoid matching framework source files
  // (e.g. gin's gin.go, express's lib/application.js) that define but never call serve.
  const candidates = repoFiles
    .filter(
      (file) =>
        (MAIN_ENTRYPOINT_FILE_PATTERN.test(file) ||
          (useV27Detectors && RACK_ENTRYPOINT_FILE_PATTERN.test(file))) &&
        (useV27Detectors ? isAuthoredProductionPath(file) : isProductionSourcePath(file)),
    )
    .slice(0, 30);
  return (
    candidates.find(
      (file) =>
        fileContains(repoPath, file, SERVER_ENTRYPOINT_PATTERN) ||
        (useV27Detectors && fileContains(repoPath, file, RACK_SERVER_ENTRYPOINT_PATTERN)) ||
        (useV27Detectors &&
          /\.ru$/i.test(file) &&
          fileContains(repoPath, file, RACK_CONFIG_RUN_PATTERN)),
    ) ?? null
  );
}

function findV20DirectHttpServerEntrypointFile(
  repoPath: string,
  repoFiles: readonly string[],
): string | null {
  return (
    repoFiles
      .filter(
        (file) => MAIN_ENTRYPOINT_FILE_PATTERN.test(file) && isAuthoredProductionPath(file),
      )
      .slice(0, 30)
      .find((file) => fileContains(repoPath, file, V20_DIRECT_HTTP_SERVER_PATTERN)) ?? null
  );
}

const V22_SIMPLE_PACKAGE_START_PATTERN =
  /^(?:node|tsx)\s+(\.?\/?[A-Za-z0-9_.-]+(?:\/[A-Za-z0-9_.-]+)*\.[cm]?[jt]s)$/;

function findV22PackageStartHttpServerEntrypointFile(
  repoPath: string,
  repoFiles: readonly string[],
): string | null {
  const packageJson = findRootPackageJson(repoFiles);
  if (!packageJson) return null;
  const start = readPackageScripts(join(repoPath, packageJson)).get('start')?.trim();
  if (!start) return null;
  const declaredPath = V22_SIMPLE_PACKAGE_START_PATTERN.exec(start)?.[1];
  if (!declaredPath) return null;
  const normalizedPath = declaredPath.replace(/^\.\//, '');
  if (
    normalizedPath.startsWith('/') ||
    normalizedPath.split('/').includes('..') ||
    !repoFiles.includes(normalizedPath) ||
    !isAuthoredProductionPath(normalizedPath)
  ) {
    return null;
  }
  return fileContains(repoPath, normalizedPath, V20_DIRECT_HTTP_SERVER_PATTERN)
    ? normalizedPath
    : null;
}

function findRuntimeContainerEntrypointFile(
  repoPath: string,
  repoFiles: readonly string[],
  useV20NodeEntrypoints = false,
): string | null {
  return (
    repoFiles
      .filter((file) => /(^|\/)Dockerfile$/i.test(file) && isAuthoredProductionPath(file))
      .find((file) => {
        const fullPath = join(repoPath, file);
        if (!isRegularFile(fullPath)) return false;
        const lines = readRepoText(fullPath, 'utf8').split(/\r?\n/);
        const finalStageStart = lines.reduce(
          (last, line, index) => (/^\s*FROM\b/i.test(line) ? index : last),
          0,
        );
        const finalStageLines = lines.slice(finalStageStart);
        const entrypoint = [...finalStageLines]
          .reverse()
          .find((line) => /^\s*ENTRYPOINT\b/i.test(line));
        const command = [...finalStageLines].reverse().find((line) => /^\s*CMD\b/i.test(line));
        const effectiveCommand = [entrypoint, command].filter(Boolean).join(' ');
        return (
          effectiveCommand.length > 0 &&
          (RUNTIME_CONTAINER_COMMAND_PATTERN.test(effectiveCommand) ||
            (useV20NodeEntrypoints &&
              V20_NODE_RUNTIME_CONTAINER_COMMAND_PATTERN.test(effectiveCommand))) &&
          !NON_RUNTIME_CONTAINER_COMMAND_PATTERN.test(effectiveCommand)
        );
      }) ?? null
  );
}

function isHealthCheckSignalFile(repoPath: string, file: string): boolean {
  if (/docs\/|audit|architecture|adr/i.test(file)) return false;
  if (/^Dockerfile$/.test(file) && fileContains(repoPath, file, /\bHEALTHCHECK\b/i)) return true;
  if (/k8s\/|kubernetes\/|helm\//.test(file)) {
    return fileContains(repoPath, file, /livenessProbe|readinessProbe/i);
  }
  if (/(^|\/)(health|healthcheck|readiness|liveness|ready)\.[cm]?[jt]sx?$/.test(file)) {
    return fileContains(repoPath, file, /health|ready|readiness|liveness/i);
  }
  if (/(^|\/)(health|healthcheck|readiness|liveness|ready)\.py$/.test(file)) {
    return fileContains(repoPath, file, /health|ready|readiness|liveness/i);
  }
  return false;
}

function isDependencyManifest(file: string): boolean {
  return /(^|\/)(package\.json|pyproject\.toml|requirements(?:[^/]*)?\.txt|go\.mod|Cargo\.toml|pom\.xml|build\.gradle|vcpkg\.json|Pipfile|CMakeLists\.txt|conanfile\.txt|conanfile\.py)$/.test(
    file,
  );
}

function isLockfile(file: string): boolean {
  return /(^|\/)(pnpm-lock\.yaml|package-lock\.json|yarn\.lock|uv\.lock|poetry\.lock|go\.sum|Cargo\.lock|Pipfile\.lock|composer\.lock|conan\.lock|vcpkg\.lock\.json)$/.test(
    file,
  );
}

function isDependencyUpdateConfig(file: string): boolean {
  return (
    /(^|\/)(renovate\.json|renovate\.json5|\.renovaterc\.json|dependabot\.ya?ml)$/.test(file) ||
    /^\.github\/dependabot\.ya?ml$/.test(file)
  );
}

function packageJsonHasAuditScript(repoPath: string, manifest: string): boolean {
  if (!manifest.endsWith('package.json')) return false;
  const scripts = readPackageScripts(join(repoPath, manifest));
  return [...scripts.values()].some((script) =>
    /\b(audit|npm audit|pnpm audit|yarn audit)\b/i.test(script),
  );
}

function packageJsonHasHeavyTestDependency(repoPath: string, manifest: string): boolean {
  const fullPath = join(repoPath, manifest);
  if (!isRegularFile(fullPath)) return false;
  const parsed = parseJsonObject(readRepoText(fullPath, 'utf8'));
  if (!parsed) return false;
  const names = [
    ...Object.keys(isRecord(parsed.dependencies) ? parsed.dependencies : {}),
    ...Object.keys(isRecord(parsed.devDependencies) ? parsed.devDependencies : {}),
  ];
  return names.some((name) => HEAVY_TEST_DEPENDENCY_NAME_PATTERN.test(name));
}

function packageJsonDescribesPackagedApplication(
  repoPath: string,
  manifest: string,
  repoFiles: readonly string[],
): boolean {
  const fullPath = join(repoPath, manifest);
  if (!isRegularFile(fullPath)) return false;
  const parsed = parseJsonObject(readRepoText(fullPath, 'utf8'));
  if (!parsed) return false;
  const scripts = isRecord(parsed.scripts) ? Object.values(parsed.scripts) : [];
  const dependencies = {
    ...(isRecord(parsed.dependencies) ? parsed.dependencies : {}),
    ...(isRecord(parsed.devDependencies) ? parsed.devDependencies : {}),
  };
  const build = isRecord(parsed.build) ? parsed.build : null;
  const hasDesktopRuntime = Object.keys(dependencies).some(
    (name) => name.toLowerCase() === 'electron' || /^@tauri-apps\/(?:api|plugin-)/i.test(name),
  );
  const hasPackagingCommand = scripts.some(
    (script) =>
      typeof script === 'string' &&
      /\b(?:electron-builder|electron-packager|tauri\s+build)\b/i.test(script),
  );
  const hasApplicationMetadata =
    isNonEmptyString(parsed.productName) ||
    isNonEmptyString(parsed.main) ||
    (build != null && isNonEmptyString(build.appId)) ||
    findTauriApplicationMetadata(repoPath, manifest, repoFiles);
  return hasDesktopRuntime && hasPackagingCommand && hasApplicationMetadata;
}

function findTauriApplicationMetadata(
  repoPath: string,
  manifest: string,
  repoFiles: readonly string[],
): boolean {
  const manifestDirectory = dirname(manifest);
  const prefix = manifestDirectory === '.' ? '' : `${manifestDirectory}/`;
  const candidates = [`${prefix}src-tauri/tauri.conf.json`, `${prefix}tauri.conf.json`];
  return candidates.some((file) => {
    if (!repoFiles.includes(file)) return false;
    const fullPath = join(repoPath, file);
    if (!isRegularFile(fullPath)) return false;
    const config = parseJsonObject(readRepoText(fullPath, 'utf8'));
    const packageMetadata = isRecord(config?.package) ? config.package : null;
    return (
      isNonEmptyString(config?.productName) ||
      isNonEmptyString(config?.identifier) ||
      (packageMetadata != null && isNonEmptyString(packageMetadata.productName))
    );
  });
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === 'string' && value.trim().length > 0;
}

function isImplementationFile(file: string): boolean {
  return (
    /(^|\/)(src|app|lib|packages|cmd|include|source|Sources)\//.test(file) &&
    /\.(ts|tsx|js|jsx|py|go|rs|java|rb|cpp|cc|cxx|c|h|hpp|kt|swift|php)$/.test(file)
  );
}

function isAuditFile(file: string): boolean {
  return (
    // goal_cejel_calibration_fix_with_strict_gate_2026-07-06: mature OSS repos document the
    // same audit-trail practice under different filenames/extensions than Alfred's own
    // conventions (Flask ships CHANGES.rst, not CHANGELOG.md) — recognize the common OSS
    // release-notes/security-policy/provenance equivalents so real audit-trail artifacts are
    // credited instead of silently missing the pattern.
    /(^|\/)(CHANGELOG|CHANGES|HISTORY|NEWS|RELEASE_NOTES|RELEASES|SECURITY|AUDIT|STATUS)\.(md|rst|txt)$/i.test(
      file,
    ) ||
    /(^|\/)docs\/.*(audit|runbook|incident|changelog|security).*\.(md|rst)$/i.test(file) ||
    // Provenance/signed-release tooling config is itself audit-trail evidence (a repo that
    // wires SLSA/cosign attestation or CITATION.cff is documenting release provenance).
    /(^|\/)CITATION\.cff$/i.test(file)
  );
}

// A security-policy document (SECURITY.md and its docs/*security* equivalent) is a static
// vulnerability-disclosure notice, not a changelog/audit trail — real-world copies rarely
// change after being written, so there is no "freshness" for B4 to rate. Every other
// isAuditFile match (CHANGELOG/CHANGES/HISTORY/NEWS/RELEASE_NOTES/RELEASES/AUDIT/STATUS,
// docs runbook/incident/changelog notes, CITATION.cff) is a genuine over-time trail.
// goal_cejel_b4_archetype_gate_2026-07-11: distinguishes "has a security policy" from
// "has an audit trail" so the N/A gate below can tell them apart.
function isSecurityPolicyOnlyAuditFile(file: string): boolean {
  return (
    /(^|\/)SECURITY\.(md|rst|txt)$/i.test(file) || /(^|\/)docs\/.*security.*\.(md|rst)$/i.test(file)
  );
}

function isFreshnessRatableAuditFile(file: string): boolean {
  return isAuditFile(file) && !isSecurityPolicyOnlyAuditFile(file);
}

function isIgnoredScanFile(file: string, useV47Detectors = false): boolean {
  return (
    /(^|\/)(package-lock\.json|pnpm-lock\.yaml|yarn\.lock|README\.md|CHANGELOG\.md)$/.test(file) ||
    isEnvTemplatePath(file, useV47Detectors)
  );
}

// v24-only. README.md and CHANGELOG.md are documentation pages, and excluding them BY NAME is the
// same class of path rule this rubric exists to remove: the README is where a placeholder is most
// likely and, for exactly that reason, the last place anyone would look for a real credential.
// Lockfiles and `.env` templates stay excluded — a lockfile is a generated artifact (the same
// family as GENERATED_OR_VENDOR_PATH_PATTERN, which v24 does not touch), and an
// `.env.example`/`.sample`/`.template` is placeholder content by definition, which is a claim
// about content rather than a claim about a directory.
function isV24IgnoredScanFile(file: string): boolean {
  return (
    /(^|\/)(package-lock\.json|pnpm-lock\.yaml|yarn\.lock)$/.test(file) ||
    isEnvTemplatePath(file, true)
  );
}

function findRootPackageJson(repoFiles: readonly string[]): string | null {
  return repoFiles.includes('package.json') ? 'package.json' : null;
}

// Declared workspace packages (goal_cejel_v26_workspace_package_scripts_2026-10-14). In npm, yarn
// and pnpm workspaces the root package.json often only orchestrates and the scripts live in the
// workspace packages, so a script check that reads the root alone asserts an absence the repository
// does not have. A recognition fix under every rubric, not gated on rubric version.
//
// Only what the workspace DECLARES is read: the root package.json `workspaces` field (array form,
// https://docs.npmjs.com/cli/v10/using-npm/workspaces, and yarn's `{ packages: [...] }` form,
// https://classic.yarnpkg.com/lang/en/docs/workspaces/) and the `packages:` list of a root
// pnpm-workspace.yaml (https://pnpm.io/pnpm-workspace_yaml). No declaration, no reading: workspaces
// are never inferred from directory shape. Globs are matched against package directories in the
// scan's existing file inventory — never a filesystem walk — with `*`, `?` and whole-segment `**`
// supported and leading-dot segments unmatched by wildcards. A `!` pattern excludes whatever it
// matches, in any position. Each package.json must also pass A1's authored-production predicate
// (isAuthoredProductionPath), so vendored, generated and test/example trees never count.
//
// Fails toward the root-only behaviour, never toward a credit: a negation that cannot be parsed,
// more than WORKSPACE_PATTERN_LIMIT patterns, or an unreadable declaration discards the whole
// declaration; an unparseable positive pattern matches nothing. At most
// WORKSPACE_PACKAGE_MANIFEST_LIMIT manifests are read, in path order, and the count declared
// beyond that is kept so callers can say so.
const WORKSPACE_PATTERN_LIMIT = 64;
const WORKSPACE_PACKAGE_MANIFEST_LIMIT = 200;

interface DeclaredWorkspaceManifests {
  /** Authored workspace package.json paths read, path-sorted, at most the manifest limit. */
  readonly read: readonly string[];
  /** Authored workspace package.json paths the declaration matched, before the cap. */
  readonly declared: number;
  /**
   * True when a declaration exists but was discarded, or one of its patterns matched nothing
   * because it could not be parsed. Read only by v26 item 8, for which that is an unread place.
   */
  readonly unreadable?: true;
}

const NO_DECLARED_WORKSPACE_MANIFESTS: DeclaredWorkspaceManifests = { read: [], declared: 0 };
const UNREADABLE_WORKSPACE_DECLARATION: DeclaredWorkspaceManifests = {
  read: [],
  declared: 0,
  unreadable: true,
};

function findDeclaredWorkspaceManifests(
  repoPath: string,
  repoFiles: readonly string[],
  rootPackageJson: string | null,
): DeclaredWorkspaceManifests {
  const patterns: string[] = [];
  if (rootPackageJson) {
    const declared = readPackageJsonWorkspacePatterns(join(repoPath, rootPackageJson));
    if (declared === null) return UNREADABLE_WORKSPACE_DECLARATION;
    patterns.push(...declared);
  }
  if (repoFiles.includes('pnpm-workspace.yaml')) {
    const declared = readPnpmWorkspacePatterns(join(repoPath, 'pnpm-workspace.yaml'));
    if (declared === null) return UNREADABLE_WORKSPACE_DECLARATION;
    patterns.push(...declared);
  }
  if (patterns.length === 0) return NO_DECLARED_WORKSPACE_MANIFESTS;
  if (patterns.length > WORKSPACE_PATTERN_LIMIT) return UNREADABLE_WORKSPACE_DECLARATION;
  const include: ((dir: string) => boolean)[] = [];
  const exclude: ((dir: string) => boolean)[] = [];
  let unparsedPattern = false;
  for (const pattern of patterns) {
    const negated = pattern.startsWith('!');
    const matcher = workspaceGlobMatcher(negated ? pattern.slice(1) : pattern);
    if (negated) {
      if (matcher === null) return UNREADABLE_WORKSPACE_DECLARATION;
      exclude.push(matcher);
    } else if (matcher !== null) {
      include.push(matcher);
    } else {
      unparsedPattern = true;
    }
  }
  const matched = repoFiles
    .filter((file) => {
      if (file === rootPackageJson || !file.endsWith('/package.json')) return false;
      if (!isAuthoredProductionPath(file)) return false;
      const dir = file.slice(0, -'/package.json'.length);
      return include.some((matches) => matches(dir)) && !exclude.some((matches) => matches(dir));
    })
    .sort();
  return {
    read: matched.slice(0, WORKSPACE_PACKAGE_MANIFEST_LIMIT),
    declared: matched.length,
    ...(unparsedPattern ? { unreadable: true as const } : {}),
  };
}

/** `[]` when the manifest declares no workspaces; null when it cannot be read as declared. */
function readPackageJsonWorkspacePatterns(packageJsonPath: string): string[] | null {
  if (!isRegularFile(packageJsonPath)) return [];
  const parsed = parseJsonObject(readRepoText(packageJsonPath, 'utf8'));
  const workspaces = parsed?.workspaces;
  if (workspaces === undefined) return [];
  const list = isRecord(workspaces) ? workspaces.packages : workspaces;
  if (list === undefined && isRecord(workspaces)) return [];
  if (!Array.isArray(list) || !list.every((entry) => typeof entry === 'string')) return null;
  return list as string[];
}

/**
 * The `packages:` list of a pnpm-workspace.yaml: a top-level block sequence of plain or quoted
 * scalars, or a one-line flow sequence. Anything else under `packages:` is null (unreadable),
 * never a guess. Other top-level keys (catalog, onlyBuiltDependencies, ...) are skipped.
 */
function readPnpmWorkspacePatterns(yamlPath: string): string[] | null {
  if (!isRegularFile(yamlPath)) return [];
  const patterns: string[] = [];
  let inPackages = false;
  for (const line of readRepoText(yamlPath, 'utf8').split(/\r?\n/)) {
    if (!inPackages) {
      const key = /^packages\s*:(.*)$/.exec(line);
      if (!key) continue;
      const rest = stripYamlLineComment(key[1] ?? '').trim();
      if (rest === '') {
        inPackages = true;
        continue;
      }
      const flow = /^\[(.*)\]$/.exec(rest);
      if (!flow) return null;
      if ((flow[1] ?? '').trim() === '') return [];
      for (const item of (flow[1] ?? '').split(',')) {
        const scalar = yamlScalar(item.trim());
        if (scalar === null) return null;
        patterns.push(scalar);
      }
      return patterns;
    }
    if (/^\s*(?:#.*)?$/.test(line)) continue;
    const item = /^\s*-\s+(.*)$/.exec(line);
    if (item) {
      const scalar = yamlScalar((item[1] ?? '').trim());
      if (scalar === null) return null;
      patterns.push(scalar);
      continue;
    }
    if (/^\S/.test(line)) break;
    return null;
  }
  return patterns;
}

function stripYamlLineComment(text: string): string {
  return /^\s*#/.test(text) ? '' : stripTrailingHashComment(text);
}

function yamlScalar(raw: string): string | null {
  const single = /^'((?:[^']|'')*)'\s*(?:#.*)?$/.exec(raw);
  if (single) return (single[1] ?? '').replace(/''/g, "'");
  const double = /^"([^"\\]*)"\s*(?:#.*)?$/.exec(raw);
  if (double) return double[1] ?? '';
  const plain = stripYamlLineComment(raw).trim();
  return plain === '' || /^["'[{&*|>]/.test(plain) ? null : plain;
}

// A declared glob is repository text, so it is never compiled to a regex: a glob with many `*`s
// against a long directory name backtracked polynomially and stalled the scan
// (goal_cejel_scan_path_regex_bounds_2026-10-15). Past either cap a pattern is unparseable.
export const WORKSPACE_GLOB_MAX_LENGTH = 256;
export const WORKSPACE_GLOB_MAX_SEGMENTS = 32;

/**
 * A workspace glob as a matcher over a package directory, or null when unsupported. `*` and `?`
 * stay inside one segment; a whole `**` segment is zero or more segments (one or more when it is
 * the entire pattern); a segment starting with `*` or `?`, and every segment `**` crosses, never
 * matches a leading dot. Matching is iterative, with no regex and no recursion: a set of reachable
 * pattern positions advanced one path segment at a time, each segment compared by
 * `matchesWildcardSegment`.
 */
export function workspaceGlobMatcher(pattern: string): ((dir: string) => boolean) | null {
  // Capped before any normalisation, so no regex below ever sees an unbounded pattern.
  if (pattern.length > WORKSPACE_GLOB_MAX_LENGTH) return null;
  const normalised = stripTrailingSlashes(pattern.trim().replace(/^\.\//, ''));
  if (
    normalised === '' ||
    normalised.startsWith('/') ||
    /(^|\/)\.\.?(\/|$)/.test(normalised) ||
    /[[\]{}()!+@\\]/.test(normalised)
  ) {
    return null;
  }
  const split = normalised.split('/');
  if (split.length > WORKSPACE_GLOB_MAX_SEGMENTS) return null;
  // Consecutive `**` segments mean the same as one.
  const segments = split.filter((segment, index, all) => !(segment === '**' && all[index - 1] === '**'));
  const isAnySegment = (part: string): boolean => part !== '' && !part.startsWith('.');
  if (segments.length === 1 && segments[0] === '**') {
    return (dir) => dir.split('/').every(isAnySegment);
  }
  return (dir) => {
    // reachable[i]: the path segments read so far can be matched by segments[0..i).
    let reachable = withGlobstarSkips(segments, [true, ...segments.map(() => false)]);
    for (const part of dir.split('/')) {
      const next = segments.map(() => false).concat(false);
      segments.forEach((segment, index) => {
        if (!reachable[index]) return;
        if (segment === '**') {
          if (isAnySegment(part)) next[index] = true;
        } else if (matchesWildcardSegment(segment, part)) {
          next[index + 1] = true;
        }
      });
      reachable = withGlobstarSkips(segments, next);
      if (!reachable.includes(true)) return false;
    }
    return reachable[segments.length] === true;
  };
}

/** A `**` matches zero segments too, so reaching it also reaches the position after it. */
function withGlobstarSkips(segments: readonly string[], reachable: boolean[]): boolean[] {
  segments.forEach((segment, index) => {
    if (segment === '**' && reachable[index]) reachable[index + 1] = true;
  });
  return reachable;
}

/**
 * One glob segment against one path segment, `*` any run and `?` any one character. The standard
 * iterative wildcard match: two indices and one backtrack point (the latest `*`), no recursion.
 */
function matchesWildcardSegment(glob: string, part: string): boolean {
  if ((glob.startsWith('*') || glob.startsWith('?')) && part.startsWith('.')) return false;
  let g = 0;
  let p = 0;
  let starGlob = -1;
  let starPart = 0;
  while (p < part.length) {
    if (g < glob.length && glob[g] === '*') {
      starGlob = g;
      starPart = p;
      g += 1;
    } else if (g < glob.length && (glob[g] === '?' || glob[g] === part[p])) {
      g += 1;
      p += 1;
    } else if (starGlob !== -1) {
      g = starGlob + 1;
      starPart += 1;
      p = starPart;
    } else {
      return false;
    }
  }
  while (g < glob.length && glob[g] === '*') g += 1;
  return g === glob.length;
}

// Presentation-only disclosure (goal_cejel_certificate_reads_disclosure_2026-10-13): the citation
// names one workflow file, so the certificate states how many the criterion counted or read.
// Nothing here feeds a score, a weight, or file selection.
//
// `verb` is the true one for the criterion: B3 opens every workflow's content ('read'); A3 and B2
// count path-recognised workflows ('counted'). `unread` is the workflows the file walk withheld
// before any collector saw them, grouped by existing skip reason (never an invented one). Silent
// when nothing differs, so a repository with one workflow file renders exactly as before.
//
// `delegated` (goal_cejel_v26_unread_ci_disclosure_2026-10-14) is the steps the read workflows hand
// to code Cejel does not read; only B3, which reads workflow commands, passes it. Silent at zero.
export function ciWorkflowCitationLabel(
  baseLabel: string,
  verb: 'read' | 'counted',
  considered: number,
  cited: number,
  unread: ReadonlyMap<ContentReadSkipReason, number>,
  delegated: DelegatedCiSteps = NO_DELEGATED_CI_STEPS,
): string {
  const unreadTotal = [...unread.values()].reduce((sum, count) => sum + count, 0);
  const { crossRepositoryReusableWorkflows: crossRepository, compositeActions } = delegated;
  const delegatedTotal = crossRepository + compositeActions;
  if (considered <= cited && unreadTotal === 0 && delegatedTotal === 0) return baseLabel;
  const parts = [
    `${considered} workflow file${considered === 1 ? '' : 's'} ${verb}`,
    `${cited} cited`,
  ];
  if (unreadTotal > 0) {
    const reasons = [...unread.keys()].sort().join(', ');
    parts.push(`${unreadTotal} not read (${reasons})`);
  }
  if (delegatedTotal === 0) return `${baseLabel} (${parts.join('; ')})`;
  const delegatedCount = `${delegatedTotal} delegated step${delegatedTotal === 1 ? '' : 's'} not read`;
  const kinds = [
    ...(crossRepository > 0
      ? [
          `${crossRepository} reusable workflow${crossRepository === 1 ? ' in another repository' : 's in other repositories'}`,
        ]
      : []),
    ...(compositeActions > 0
      ? [`${compositeActions} local action${compositeActions === 1 ? '' : 's'}`]
      : []),
  ];
  const full = `${baseLabel} (${[...parts, `${delegatedCount} (${kinds.join(', ')})`].join('; ')})`;
  // The per-kind breakdown is the only part dropped to stay within the schema's label cap; the
  // count always stays. At most four skip reasons reach `unread` (excluded_by_extension paths are
  // never withheld), so the short form fits for any count below 10,000.
  return full.length <= EVIDENCE_LABEL_MAX_LENGTH
    ? full
    : `${baseLabel} (${[...parts, delegatedCount].join('; ')})`;
}

// WitanEvidencePointerSchema's `label` maximum.
const EVIDENCE_LABEL_MAX_LENGTH = 180;

export interface DelegatedCiSteps {
  readonly crossRepositoryReusableWorkflows: number;
  readonly compositeActions: number;
}

const NO_DELEGATED_CI_STEPS: DelegatedCiSteps = {
  crossRepositoryReusableWorkflows: 0,
  compositeActions: 0,
};

function sumDelegatedCiSteps(left: DelegatedCiSteps, right: DelegatedCiSteps): DelegatedCiSteps {
  return {
    crossRepositoryReusableWorkflows:
      left.crossRepositoryReusableWorkflows + right.crossRepositoryReusableWorkflows,
    compositeActions: left.compositeActions + right.compositeActions,
  };
}

// `{owner}/{repo}/.github/workflows/{file}.yml@{ref}`: GitHub's form for calling a reusable
// workflow from another repository. A same-repository call written this way also names content
// at a ref Cejel does not read, so it is counted with them.
const CROSS_REPOSITORY_REUSABLE_WORKFLOW_PATTERN =
  /^[^./\s][^/\s]*\/[^/\s]+\/\.github\/workflows\/[^@\s]+\.ya?ml@\S+$/u;

// Counts, per recognised GitHub Actions workflow under `root`, the `uses:` values that hand work to
// code Cejel does not read: a reusable workflow in another repository, and a local action (a
// `./path` whose directory holds action.yml or action.yaml; GitHub runs nothing as an action from
// a directory without one). A local reusable workflow (`./.github/workflows/x.yml`) is one of the
// workflows already read, and a marketplace action (`actions/checkout@v4`) runs no repository
// command, so neither is counted. Presentation only: nothing here feeds a score or a weight.
function countDelegatedCiSteps(root: string, workflows: readonly string[]): DelegatedCiSteps {
  let crossRepositoryReusableWorkflows = 0;
  let compositeActions = 0;
  for (const file of workflows) {
    if (!/^\.github\/workflows\//.test(file)) continue;
    const fullPath = join(root, file);
    if (!isRegularFile(fullPath)) continue;
    for (const uses of extractWorkflowUsesValues(readRepoText(fullPath, 'utf8'))) {
      if (CROSS_REPOSITORY_REUSABLE_WORKFLOW_PATTERN.test(uses)) {
        crossRepositoryReusableWorkflows += 1;
        continue;
      }
      if (!uses.startsWith('./') || /^\.\/\.github\/workflows\//.test(uses)) continue;
      const directory = stripTrailingSlashes(uses.slice(2));
      if (directory.length === 0 || directory.split('/').includes('..')) continue;
      if (
        isRegularFile(join(root, directory, 'action.yml')) ||
        isRegularFile(join(root, directory, 'action.yaml'))
      ) {
        compositeActions += 1;
      }
    }
  }
  return { crossRepositoryReusableWorkflows, compositeActions };
}

// Line-based, like extractCiRunCommands: every `uses:` key's scalar value, unquoted and without a
// trailing comment. A commented-out line never matches, and lines inside a `|` or `>` block scalar
// (a `run:` script that merely prints "uses: ...") are skipped.
function extractWorkflowUsesValues(contents: string): string[] {
  const values: string[] = [];
  let blockScalarIndentation: number | null = null;
  for (const line of contents.split(/\r?\n/u)) {
    const indentation = /^\s*/u.exec(line)?.[0].length ?? 0;
    if (blockScalarIndentation !== null) {
      if (line.trim().length === 0 || indentation > blockScalarIndentation) continue;
      blockScalarIndentation = null;
    }
    const match = /^\s*(?:-\s*)?uses\s*:\s*(.*)$/u.exec(line);
    if (match) {
      const value = stripTrailingHashComment(match[1] ?? '').trim();
      const quoted = /^(?:"(.*)"|'(.*)')$/u.exec(value);
      values.push(quoted ? (quoted[1] ?? quoted[2] ?? '') : value);
      continue;
    }
    if (/:\s*[|>][-+0-9]*\s*(?:#.*)?$/u.test(line)) blockScalarIndentation = indentation;
  }
  return values;
}

function unreadCiWorkflowReasons(
  includes: (file: string) => boolean,
): Map<ContentReadSkipReason, number> {
  const unread = new Map<ContentReadSkipReason, number>();
  for (const { path, reasons } of withheldRepoPaths()) {
    if (!isCiWorkflow(path) || !includes(path)) continue;
    const reason = [...reasons].sort()[0];
    if (reason !== undefined) unread.set(reason, (unread.get(reason) ?? 0) + 1);
  }
  return unread;
}

// v26 item 8 (docs/calibration/v26/ruling-item-8.md, operator-signed). A3's "declares neither a
// build nor a typecheck script" finding claims the deployed package has no build or type-check
// step. Under v26 it fires only when all three of the ruling's conditions hold:
//   B-1 the root package has authored TypeScript or a tsconfig (otherwise nothing to build, and
//       nothing to disclose);
//   B-2 no step from BUILD_STEP_* below is found in any package script, CI `run`, Dockerfile `RUN`
//       or Makefile/justfile target read (a step found: nothing to disclose);
//   B-3 every place a step could be was read, and every command in them could be parsed.
// Where the ruling is silent this takes the reading that fires less; each such reading is named
// where it is made. Nothing here feeds a metric.
type V26BuildStepSettlement = 'nothing-to-build' | 'step-found' | 'unsettled' | 'fires';
type BuildStepCommandState = 'step' | 'none' | 'unparseable';

// B-2's fixed vocabulary, matched against the command word after shell splitting, never as a
// substring. A compiler, type checker or bundler run under its own name...
const BUILD_STEP_EXECUTABLES: ReadonlySet<string> = new Set([
  'babel',
  'esbuild',
  'ncc',
  'rollup',
  'svelte-check',
  'swc',
  'tsc',
  'tsup',
  'vue-tsc',
  'webpack',
  'webpack-cli',
]);
// ...one whose build is a subcommand of a wider tool (`vite` alone is a dev server)...
const BUILD_STEP_SUBCOMMANDS: ReadonlyMap<string, string> = new Map([
  ['bun', 'build'],
  ['nest', 'build'],
  ['next', 'build'],
  ['ng', 'build'],
  ['parcel', 'build'],
  ['vite', 'build'],
]);
// ...and a task runner's `build` or `typecheck` target, whatever it runs (Nx also as `project:build`).
const BUILD_STEP_TASK_RUNNERS: ReadonlySet<string> = new Set([
  'bun',
  'gmake',
  'just',
  'lerna',
  'make',
  'npm',
  'nx',
  'pnpm',
  'turbo',
  'yarn',
]);
const BUILD_STEP_TARGET_NAME_PATTERN = /^(?:build|typecheck)$/u;
const BUILD_STEP_TARGET_ARGUMENT_PATTERN = /^(?:[^\s:]+:)?(?:build|typecheck)$/u;

const TYPESCRIPT_SOURCE_PATTERN = /\.(?:ts|tsx|mts|cts)$/u;
const TYPESCRIPT_DECLARATION_PATTERN = /\.d\.(?:ts|mts|cts)$/u;
const TSCONFIG_PATTERN = /(^|\/)tsconfig[^/]*\.json$/u;
const BUILD_STEP_DOCKERFILE_PATTERN = /(^|\/)(?:dockerfile|containerfile)(?:\.[^/]*)?$|[^/]\.dockerfile$/iu;

function settleV26BuildStepEvidence(
  repoPath: string,
  repoFiles: readonly string[],
  packageJson: string,
  workspaceManifests: DeclaredWorkspaceManifests,
  workflows: readonly string[],
  includesWorkflow: (file: string) => boolean,
): V26BuildStepSettlement {
  // B-1. "The package the manifest belongs to" is read narrowly: a file under a directory with its
  // own package.json, workspace or not, belongs to that package, and only authored, readable paths
  // count. A .d.mts or .d.cts is a declaration like a .d.ts.
  const nestedPackageDirs = repoFiles
    .filter((file) => file !== packageJson && /(^|\/)package\.json$/u.test(file))
    .map((file) => file.slice(0, -'package.json'.length));
  const hasSomethingToBuild = repoFiles.some(
    (file) =>
      isAuthoredProductionPath(file) &&
      ((TYPESCRIPT_SOURCE_PATTERN.test(file) && !TYPESCRIPT_DECLARATION_PATTERN.test(file)) ||
        TSCONFIG_PATTERN.test(file)) &&
      !nestedPackageDirs.some((dir) => file.startsWith(dir)),
  );
  if (!hasSomethingToBuild) return 'nothing-to-build';

  // B-2, one block per place. A command that cannot be parsed, or a read file that cannot be
  // parsed as its kind, is not read as an absence: it leaves the question unsettled (B-3).
  let unsettled = false;
  const commandRunsStep = (command: string): boolean => {
    const state = classifyBuildStepCommand(command);
    if (state === 'unparseable') unsettled = true;
    return state === 'step';
  };

  // Place 1: any script, under any name, in the root or a declared workspace package.json read.
  for (const manifest of [packageJson, ...workspaceManifests.read]) {
    const scripts = readBuildStepPackageScripts(join(repoPath, manifest));
    if (scripts === null) {
      unsettled = true;
      continue;
    }
    for (const [name, command] of scripts) {
      if (BUILD_STEP_TARGET_NAME_PATTERN.test(name) || commandRunsStep(command)) return 'step-found';
    }
  }

  // Place 2: any `run` command in a CI workflow read. Only GitHub Actions workflows are read as
  // `run` steps; another CI system's commands are not, so its file is an unread place.
  for (const workflow of workflows) {
    const fullPath = join(repoPath, workflow);
    if (!/^\.github\/workflows\//u.test(workflow) || !isRegularFile(fullPath)) {
      unsettled = true;
      continue;
    }
    if (extractCiRunCommands(readRepoText(fullPath, 'utf8')).some(commandRunsStep)) {
      return 'step-found';
    }
  }

  // Place 3: any RUN instruction in a tracked Dockerfile.
  for (const file of repoFiles.filter((path) => BUILD_STEP_DOCKERFILE_PATTERN.test(path))) {
    const fullPath = join(repoPath, file);
    if (!isRegularFile(fullPath)) {
      unsettled = true;
      continue;
    }
    const run = dockerfileRunCommands(readRepoText(fullPath, 'utf8'));
    if (run.unparseable) unsettled = true;
    if (run.commands.some(commandRunsStep)) return 'step-found';
  }

  // Place 4: any target in a tracked Makefile, GNUmakefile or justfile. A recipe line's trailing
  // continuation backslash is dropped; the continued line is read as a command of its own.
  for (const file of repoFiles.filter(isRecipeFile)) {
    const fullPath = join(repoPath, file);
    if (!isRegularFile(fullPath)) {
      unsettled = true;
      continue;
    }
    for (const [name, target] of readRecipeTargets(readRepoText(fullPath, 'utf8'))) {
      if (BUILD_STEP_TARGET_NAME_PATTERN.test(name)) return 'step-found';
      if (target.commands.some((command) => commandRunsStep(command.replace(/\\$/u, '')))) {
        return 'step-found';
      }
    }
  }

  // B-3. Nothing withheld or delegated, no manifest left unread. A withheld authored package.json
  // counts as well as the four places the ruling names.
  if (workspaceManifests.declared > workspaceManifests.read.length || workspaceManifests.unreadable) {
    unsettled = true;
  }
  if (unreadCiWorkflowReasons(includesWorkflow).size > 0) unsettled = true;
  const delegated = countDelegatedCiSteps(repoPath, workflows);
  if (delegated.crossRepositoryReusableWorkflows + delegated.compositeActions > 0) unsettled = true;
  if (
    withheldRepoPaths().some(
      ({ path }) =>
        BUILD_STEP_DOCKERFILE_PATTERN.test(path) ||
        isRecipeFile(path) ||
        (/(^|\/)package\.json$/u.test(path) && isAuthoredProductionPath(path)),
    )
  ) {
    unsettled = true;
  }
  return unsettled ? 'unsettled' : 'fires';
}

/** A package.json's scripts; null when it is not a JSON object or a script is not a string. */
function readBuildStepPackageScripts(packageJsonPath: string): Map<string, string> | null {
  if (!isRegularFile(packageJsonPath)) return null;
  const parsed = parseJsonObject(readRepoText(packageJsonPath, 'utf8'));
  if (parsed === null) return null;
  if (parsed.scripts === undefined) return new Map();
  if (!isRecord(parsed.scripts)) return null;
  const entries = Object.entries(parsed.scripts);
  if (!entries.every((entry): entry is [string, string] => typeof entry[1] === 'string')) return null;
  return new Map(entries);
}

/**
 * Every RUN instruction's command, continuation lines joined and BuildKit `--flag`s dropped. The
 * exec form is re-quoted so it reaches the same shell splitting as the shell form. A heredoc, an
 * exec form that is not a JSON array of strings, or an `escape` parser directive is unparseable.
 */
export function dockerfileRunCommands(contents: string): {
  readonly commands: readonly string[];
  readonly unparseable: boolean;
} {
  if (/^#\s*escape\s*=/imu.test(contents)) return { commands: [], unparseable: true };
  const lines = contents.split(/\r?\n/u);
  const commands: string[] = [];
  let unparseable = false;
  for (let index = 0; index < lines.length; index += 1) {
    const match = /^\s*RUN(?:\s+(.*))?$/iu.exec(lines[index] ?? '');
    if (!match) continue;
    // The instruction is kept as chunks so each continuation looks only at its tail. Re-testing
    // and rewriting the whole joined string on every line was quadratic in the Dockerfile's
    // length; the result is byte-identical to that form.
    const chunks = [match[1] ?? ''];
    while (endsWithLineContinuation(chunks) && index + 1 < lines.length) {
      index += 1;
      const next = lines[index] ?? '';
      // Docker drops a comment line inside a continued instruction; the backslash still stands.
      if (/^\s*#/u.test(next)) continue;
      dropLineContinuation(chunks);
      chunks.push(' ', next.trim());
    }
    let instruction = chunks.join('');
    instruction = instruction.replace(/^(?:--[A-Za-z][\w-]*(?:=\S*)?\s+)*/u, '').trim();
    if (instruction === '' || /<<-?\s*["']?[A-Za-z_]/u.test(instruction)) {
      unparseable = true;
      continue;
    }
    if (!instruction.startsWith('[')) {
      commands.push(instruction);
      continue;
    }
    const execForm = dockerfileExecFormCommand(instruction);
    if (execForm === null) unparseable = true;
    else commands.push(execForm);
  }
  return { commands, unparseable };
}

/** True when the joined chunks end in a backslash followed only by whitespace. */
function endsWithLineContinuation(chunks: readonly string[]): boolean {
  for (let c = chunks.length - 1; c >= 0; c -= 1) {
    const chunk = chunks[c] ?? '';
    for (let i = chunk.length - 1; i >= 0; i -= 1) {
      const character = chunk.charAt(i);
      if (/\s/u.test(character)) continue;
      return character === '\\';
    }
  }
  return false;
}

/** Removes that trailing backslash and the whitespace after it; callers check it is there. */
function dropLineContinuation(chunks: string[]): void {
  while (chunks.length > 0) {
    const chunk = chunks[chunks.length - 1] ?? '';
    let i = chunk.length - 1;
    while (i >= 0 && /\s/u.test(chunk.charAt(i))) i -= 1;
    if (i < 0) {
      chunks.pop();
      continue;
    }
    chunks[chunks.length - 1] = chunk.slice(0, i);
    return;
  }
}

function dockerfileExecFormCommand(instruction: string): string | null {
  let parsed: unknown;
  try {
    parsed = JSON.parse(instruction);
  } catch {
    return null;
  }
  if (
    !Array.isArray(parsed) ||
    parsed.length === 0 ||
    !parsed.every((part): part is string => typeof part === 'string')
  ) {
    return null;
  }
  return parsed
    .map((part) =>
      /^[A-Za-z0-9_@%+=:,./-]+$/u.test(part) ? part : `'${part.replaceAll("'", "'\\''")}'`,
    )
    .join(' ');
}

/**
 * B-2's command test: `step` when a segment's command word is in the vocabulary above, `none`
 * when no segment's is, and `unparseable` when a segment cannot be split into words or its
 * command word (or a package manager's script name) is an expansion Cejel cannot resolve.
 */
export function classifyBuildStepCommand(command: string): BuildStepCommandState {
  return buildStepCommandState(command, 0);
}

function buildStepCommandState(command: string, depth: number): BuildStepCommandState {
  if (depth > 4) return 'unparseable';
  const states = splitShellCommandSegments(command).map((segment) =>
    buildStepSegmentState(segment, depth),
  );
  if (states.includes('step')) return 'step';
  return states.includes('unparseable') ? 'unparseable' : 'none';
}

function buildStepSegmentState(raw: string, depth: number): BuildStepCommandState {
  let segment = stripUnbalancedShellParentheses(raw.trim());
  for (;;) {
    const keyword = /^(?:if|then|else|elif|do|while|until|exec|!|\{)(?:\s+|$)/u.exec(segment);
    if (!keyword) break;
    segment = segment.slice(keyword[0].length);
  }
  if (segment === '' || /^(?:fi|done|esac|\})$/u.test(segment)) return 'none';
  const normalized = normalizeCoverageCommandPrefixes(segment);
  if (
    normalized.splitShellOperators &&
    splitShellCommandSegments(normalized.segment).length > 1
  ) {
    return buildStepCommandState(normalized.segment, depth + 1);
  }
  if (/\b(?:npm|pnpm|yarn|bun)\s+run\s+(?:\$|["']\$|`)/u.test(normalized.segment)) {
    return 'unparseable';
  }
  const words = strictShellWords(normalized.segment);
  if (words === null) return 'unparseable';
  return words.length === 0 ? 'none' : buildStepWordsState(words);
}

function buildStepWordsState(words: readonly string[]): BuildStepCommandState {
  const first = words[0] === '$(MAKE)' || words[0] === '${MAKE}' ? 'make' : (words[0] ?? '');
  if (isUnresolvedCommandWord(first)) return 'unparseable';
  const runner = buildStepCommandName(first);
  if (
    BUILD_STEP_TASK_RUNNERS.has(runner) &&
    words.slice(1).some((word) => BUILD_STEP_TARGET_ARGUMENT_PATTERN.test(word))
  ) {
    return 'step';
  }
  const command =
    runner === 'bunx'
      ? words.slice(1)
      : runner === 'bun' && words[1] === 'x'
        ? words.slice(2)
        : unwrapPackageManagerExecutable(words);
  const executable = command[0] ?? '';
  if (isUnresolvedCommandWord(executable)) return 'unparseable';
  const name = buildStepCommandName(executable);
  if (BUILD_STEP_EXECUTABLES.has(name)) return 'step';
  const subcommand = BUILD_STEP_SUBCOMMANDS.get(name);
  return subcommand !== undefined && command.slice(1).includes(subcommand) ? 'step' : 'none';
}

function isUnresolvedCommandWord(word: string): boolean {
  return word.startsWith('$') || word.includes('`');
}

function buildStepCommandName(word: string): string {
  return basename(word).replace(/\.(?:cmd|exe)$/iu, '').toLowerCase();
}

/** `(cd app` and `tsc -p .)` are the two halves of a subshell that segment splitting cut apart. */
function stripUnbalancedShellParentheses(segment: string): string {
  const opens = segment.split('(').length - 1;
  const closes = segment.split(')').length - 1;
  if (opens > closes) return segment.replace(/^\(+\s*/u, '');
  if (closes > opens) return stripTrailingCloseParentheses(segment);
  return segment;
}

/** shellWords, but null instead of a silent stop when a word cannot be read to its end. */
function strictShellWords(segment: string): string[] | null {
  const words: string[] = [];
  let offset = 0;
  for (;;) {
    while (offset < segment.length && /\s/u.test(segment[offset] ?? '')) offset += 1;
    if (offset >= segment.length) return words;
    const scanned = scanShellWord(segment, offset);
    if (!scanned) return null;
    if (scanned.word !== '') words.push(scanned.word);
    offset = scanned.end;
  }
}

// A3's build/type-check component reads package scripts from the root package.json only, as does
// B3's ci_script_depth when no workspace is declared, while A1 reads every authored package.json.
// "Authored" is A1's own predicate (isAuthoredProductionPath), so vendored and dependency trees are
// not counted. Returns null when there is nothing to say (no other authored package.json), leaving
// the output unchanged.
function rootOnlyPackageScriptsDisclosure(
  repoFiles: readonly string[],
  rootPackageJson: string | null,
): string | null {
  const others = repoFiles.filter(
    (file) =>
      file !== rootPackageJson &&
      /(^|\/)package\.json$/.test(file) &&
      isAuthoredProductionPath(file),
  ).length;
  if (others === 0) return null;
  const present = `${others}${rootPackageJson ? ' other' : ''} package.json file${others === 1 ? '' : 's'} present`;
  return `${rootPackageJson ? '' : 'no root package.json found; '}package scripts for this metric are read from the root package.json only; ${present}`;
}

// The same disclosure once declared workspace packages were read (B3's ci_script_depth): how many
// were read, how many the cap left unread, and how many other authored package.json files remain.
function workspacePackageScriptsDisclosure(
  repoFiles: readonly string[],
  rootPackageJson: string | null,
  workspace: DeclaredWorkspaceManifests,
): string {
  const readCount = workspace.read.length;
  const workspaceRead =
    workspace.declared > readCount
      ? `the first ${readCount} of ${workspace.declared} declared workspace package.json files`
      : `${readCount} declared workspace package.json file${readCount === 1 ? '' : 's'}`;
  const read = new Set(workspace.read);
  const others = repoFiles.filter(
    (file) =>
      file !== rootPackageJson &&
      !read.has(file) &&
      /(^|\/)package\.json$/.test(file) &&
      isAuthoredProductionPath(file),
  ).length;
  return [
    ...(rootPackageJson ? [] : ['no root package.json found']),
    `package scripts for this metric are read from ${rootPackageJson ? `the root package.json and ${workspaceRead}` : workspaceRead}`,
    ...(others > 0 ? [`${others} other package.json file${others === 1 ? '' : 's'} present`] : []),
  ].join('; ');
}

// Returns true only for regular files — directories and missing paths both return false.
// This prevents EISDIR crashes when git ls-files returns submodule directory entries.
export function isRegularFile(path: string): boolean {
  try {
    return lstatSync(path).isFile();
  } catch {
    return false;
  }
}

export function fileContains(repoPath: string, file: string, pattern: RegExp): boolean {
  const fullPath = join(repoPath, file);
  if (!isRegularFile(fullPath)) return false;
  return pattern.test(readRepoText(fullPath, 'utf8'));
}

/** fileContains for a test that is not a regex (a linear scan in place of a quadratic pattern). */
function fileSatisfies(repoPath: string, file: string, test: (contents: string) => boolean): boolean {
  const fullPath = join(repoPath, file);
  if (!isRegularFile(fullPath)) return false;
  return test(readRepoText(fullPath, 'utf8'));
}

// Same as fileContains, but strips comments before testing. Used wherever a match is credited as
// implementation evidence: a commented-out call (e.g. `// app.use(errorHandler);`) or a comment
// quoting a handler satisfies a pattern textually while implementing nothing at runtime (#352,
// and #433 for the shape half). A `//` directly preceded by `:` is the scheme separator of a URL
// (`'https://api.example'`), not a comment, and is left alone so a one-line
// `const base = 'https://api.example'; app.use(handler);` still matches. Every other `//` strips to
// end of line, including a trailing comment after code (`x(); // app.use(handler);`) — keeping
// that text would credit a dead stub, and a false credit is the worse error here. `/* ... */`
// blocks are blanked with their line breaks kept, so line numbers survive for evidence anchors.
// Python and Ruby files also lose whole-line `#` comments. Naive by design: it does not parse
// string or template literals, so a `//` or `/*` inside one strips too — a documented limit that
// fails toward a miss, never a false credit.
const HASH_COMMENT_SOURCE_PATTERN = /\.(?:py|rb)$/i;

function stripCodeComments(file: string, contents: string): string {
  const withoutComments = contents
    .replace(/\/\*[\s\S]*?\*\//g, (block) => block.replace(/[^\n]/g, ''))
    .replace(/(?<!:)\/\/.*$/gm, '');
  return HASH_COMMENT_SOURCE_PATTERN.test(file)
    ? withoutComments.replace(/^[ \t]*#.*$/gm, '')
    : withoutComments;
}

function fileMatchesOutsideComments(repoPath: string, file: string, pattern: RegExp): boolean {
  const fullPath = join(repoPath, file);
  if (!isRegularFile(fullPath)) return false;
  return pattern.test(stripCodeComments(file, readRepoText(fullPath, 'utf8')));
}

function findFirstMatchingLineOutsideComments(
  repoPath: string,
  file: string,
  pattern: RegExp,
): number | null {
  const fullPath = join(repoPath, file);
  if (!isRegularFile(fullPath)) return null;
  const lines = stripCodeComments(file, readRepoText(fullPath, 'utf8')).split('\n');
  const index = lines.findIndex((line) => pattern.test(line));
  return index === -1 ? null : index + 1;
}

// ---- v23-only: PEM-formatted private-key assignment grammar -------------------------------
// (goal_cejel_v23_pem_private_key_grammar_2026-09-06). SECRET_IDENTIFIER_KEYWORD_PATTERN above
// requires "secret", "token", "api_key", "password" or "access_key" in the identifier —
// "private_key" (the canonical GCP/AWS service-account-JSON field name) matches none of those.
// And even a matching identifier's value would not survive findRealSecretAssignments' capture:
// that loop stops the value at the first real quote or whitespace character, which a PEM
// block trips on its own embedded newline (real, or a JSON string's literal `\n` two-character
// escape makes no difference — [\s\S] below spans both) and on the literal space inside
// "PRIVATE KEY" itself. This is why it is a dedicated, whole-file grammar rather than an
// extension of the shared keyword/value scan — and why it is threaded as its own
// useV23PemPrivateKeyGrammar flag through every call site instead of folding into
// useV39Detectors/useV47Detectors: v17 and v22 must stay byte-stable, and this closure was
// never part of either.
//
// FP discipline: a public key or certificate can never match (the pattern requires the
// literal substring "PRIVATE KEY", which "PUBLIC KEY" and "CERTIFICATE" do not contain).
// Documentation examples, __fixtures__/test-fixture paths, and generated/vendor paths are
// already excluded upstream by the same isV47AuthoredProductionPath gate every other secret
// check in this file uses (see the authoredProductionPath check in collectA2IsolationEvidence)
// — this grammar adds no path filtering of its own for those. What it does add locally is
// what those upstream gates cannot know from a path alone: an identifier/context match for
// "dev"/"self-signed"/"snakeoil"-shaped material, and a nearby "rotated"/"revoked" annotation.
// The body capture is bounded (not an unbounded `[\s\S]*?`): with no bound, a file containing
// several unterminated "-----BEGIN ... PRIVATE KEY-----" markers (no matching END) makes the
// engine re-attempt an ever-shrinking suffix scan from every such start position, which
// measures as clearly super-linear (super-linear time on repeated-unterminated-marker input —
// verified directly: ~61ms to ~3.7s as input doubled from ~165KB to ~1.3MB). 32KB is far more
// than any real PEM private key (even RSA-8192 is a few KB), so this bound never truncates a
// genuine match while capping worst-case per-position work to a constant.
//
// The pattern is sticky (`y`) and is tried only where execFromIdentifierRunStarts says a match can
// start: as a `g` pattern tried at every position, a long run of identifier characters cost the
// square of its length (#550), and that helper returns exactly what the `g` pattern returned.
const PEM_PRIVATE_KEY_ASSIGNMENT_PATTERN =
  /(?:["'])?([A-Za-z_$][\w$.-]*)(?:["'])?\s*[:=]\s*(?:\|[-+0-9]*\s*\r?\n[ \t]*)?["'`]?-----BEGIN((?: (?:RSA|DSA|EC|OPENSSH|ENCRYPTED))? PRIVATE KEY)-----([\s\S]{0,32768}?)-----END\2-----/y;
// A bare key file (id_rsa, server.key, some-cert.pem) has no `identifier =`/`identifier:`
// wrapper at all — isCredentialHistoryPath already treats these basenames as scan-eligible, but
// the assignment grammar above never matched their content. This is the same regex with that
// leading identifier/operator prefix made optional, used only for basenames shaped like a
// standalone key file (see isBarePemKeyFile) so the wider, prefix-free match never runs against
// arbitrary source/doc/log content. Same shape as PEM_PRIVATE_KEY_ASSIGNMENT_PATTERN minus the
// leading identifier/operator group — so the key-type backreference is \1 here (there is no
// group before it), not \2.
const BARE_PEM_PRIVATE_KEY_PATTERN =
  /["'`]?-----BEGIN((?: (?:RSA|DSA|EC|OPENSSH|ENCRYPTED))? PRIVATE KEY)-----([\s\S]{0,32768}?)-----END\1-----/g;
const BARE_PEM_KEY_FILE_PATTERN = /(?:^|\/)id_(?:rsa|dsa|ecdsa|ed25519)$|\.(?:pem|key)$/i;
function isBarePemKeyFile(file: string): boolean {
  return BARE_PEM_KEY_FILE_PATTERN.test(file);
}
// A committed self-signed/local-dev key is a routine, low-value artifact (see e.g. Debian's
// ssl-cert-snakeoil convention) — checked against the identifier, a small surrounding-line
// window, and the file path itself. Lookarounds (not \b) treat "_"/"-" as boundaries too, so
// "self_signed_key" and "local-dev.pem" both match, not just space-delimited prose. "staging" is
// deliberately not in this list: unlike "dev"/"local"/"self-signed", a staging path names a
// real, reachable deployment environment, not routine throwaway material.
const DEV_OR_SELF_SIGNED_KEY_CONTEXT_PATTERN =
  /(?<![A-Za-z0-9])(?:dev|development|local|localhost|self[-_]?signed|snakeoil|insecure|dummy|sample|demo|placeholder|fixture|generated)(?![A-Za-z0-9])/i;
// A key documented as rotated/revoked in its own surrounding context is retired material, not
// a live leak — an honest abstention in the direction of fewer false positives, per this
// goal's binding FP-discipline constraint, even at some cost to recall.
const ROTATED_OR_REVOKED_KEY_CONTEXT_PATTERN =
  /(?<![A-Za-z0-9])(?:rotated|revoked|expired|deprecated|compromised|invalidated|superseded)(?![A-Za-z0-9])|do[-_ ]not[-_ ]use|no longer valid/i;

// A real PEM body is a long run of base64 characters (plus real/escaped newlines and
// indentation, stripped before this check runs) — never a short placeholder, an all-filler
// run, or a synthetic fixture alphabet. Reuses the same placeholder heuristics every other
// secret value in this file is judged by, rather than inventing a parallel notion of "fake".
function isPlausiblePemKeyBody(rawBody: string): boolean {
  const normalized = rawBody.replace(/\\[nr]|[\r\n\s]/g, '');
  if (normalized.length < 40) return false;
  if (!/^[A-Za-z0-9+/=]+$/.test(normalized)) return false;
  return !isPlaceholderSecretValue(normalized);
}

// Runs one compiled PEM pattern over `contents` and returns the first match that survives every
// FP guard, or null. Shared by both the identifier-prefixed grammar and the bare-key-file
// fallback below so the FP-guard logic (dev/self-signed context, rotated/revoked context,
// plausible body) and the evidence-metadata computation exist in exactly one place.
function scanForPemPrivateKeyMatch(
  pattern: RegExp,
  contents: string,
  lines: readonly string[],
  hasIdentifierGroup: boolean,
): RealSecretAssignmentMatch | null {
  // Both patterns' matches are never empty, so the next search starts at the previous match's end.
  const next = (from: number): RegExpExecArray | null => {
    if (pattern.sticky) return execFromIdentifierRunStarts(pattern, contents, from);
    pattern.lastIndex = from;
    return pattern.exec(contents);
  };
  let match: RegExpExecArray | null;
  for (let from = 0; (match = next(from)) !== null; from = match.index + match[0].length) {
    const full = match[0];
    // PEM_PRIVATE_KEY_ASSIGNMENT_PATTERN captures (identifier, keyType, body);
    // BARE_PEM_PRIVATE_KEY_PATTERN has no identifier group, so it captures (keyType, body).
    const identifier = hasIdentifierGroup ? (match[1] ?? '') : '';
    const body = (hasIdentifierGroup ? match[3] : match[2]) ?? '';
    const line = contents.slice(0, match.index).split('\n').length;
    const contextLines = lines.slice(Math.max(0, line - 5), line + 4).join('\n');
    const isDevOrSelfSigned = DEV_OR_SELF_SIGNED_KEY_CONTEXT_PATTERN.test(
      `${identifier}\n${contextLines}`,
    );
    const isRotatedOrRevoked = ROTATED_OR_REVOKED_KEY_CONTEXT_PATTERN.test(contextLines);
    if (isPlausiblePemKeyBody(body) && !isDevOrSelfSigned && !isRotatedOrRevoked) {
      // The evidence value is the PEM block itself (armor + body), not `full` — `full` also
      // contains the identifier and assignment syntax, which would otherwise (a) make
      // characterClasses/valueLength describe the wrapper rather than the secret, and (b) make
      // the fingerprint sensitive to unrelated edits to that wrapper, breaking the
      // current-tree/history dedup this match feeds (see currentFingerprints callers below).
      const value = full.slice(full.indexOf('-----BEGIN'));
      const characterClasses = [
        /[a-z]/.test(value) ? 'lower' : '',
        /[A-Z]/.test(value) ? 'upper' : '',
        /\d/.test(value) ? 'digit' : '',
        /[^A-Za-z0-9]/.test(value) ? 'symbol' : '',
      ]
        .filter(Boolean)
        .join('+');
      return {
        identifier,
        line,
        valueLength: value.length,
        characterClasses: characterClasses || 'other',
        valueFingerprint: createHash('sha256').update(value).digest('hex'),
        kind: 'pem_private_key',
      };
    }
  }
  return null;
}

// Returns the first PEM-formatted private-key assignment in `contents` that survives every FP
// guard, or null — never a fabricated match. `file` is the path being scanned: used for the
// dev/self-signed path check, and to decide whether the identifier-free bare-key-file fallback
// applies (id_rsa, *.pem, *.key have no `identifier =` wrapper at all). The path-based
// fixture/doc/generated exclusion itself already happened upstream, before this function is
// ever called.
function findPemPrivateKeyAssignment(
  contents: string,
  file: string,
): RealSecretAssignmentMatch | null {
  if (!contents.includes('-----BEGIN')) return null;
  if (DEV_OR_SELF_SIGNED_KEY_CONTEXT_PATTERN.test(file)) return null;
  const lines = contents.split('\n');
  const assignmentMatch = scanForPemPrivateKeyMatch(
    PEM_PRIVATE_KEY_ASSIGNMENT_PATTERN,
    contents,
    lines,
    true,
  );
  if (assignmentMatch) return assignmentMatch;
  if (!isBarePemKeyFile(file)) return null;
  return scanForPemPrivateKeyMatch(BARE_PEM_PRIVATE_KEY_PATTERN, contents, lines, false);
}

function findCommittedSecretInFile(
  repoPath: string,
  file: string,
  useV36Detectors = false,
  useV39Detectors = false,
  useV47Detectors = false,
  useV23PemPrivateKeyGrammar = false,
  setAside?: PlaceholderSetAsideCount,
): RealSecretAssignmentMatch | null {
  const fullPath = join(repoPath, file);
  if (!isRegularFile(fullPath)) return null;
  const contents = readRepoText(fullPath, 'utf8');
  const isTestCredentialConfiguration =
    useV39Detectors && isLikelyTestCredentialConfiguration(file, contents);
  const secretScanContents = prepareCredentialScanContents(
    contents,
    file,
    useV36Detectors,
    useV39Detectors,
    useV47Detectors,
  );
  // The count rides on the detection pass. That pass stops only at a match, and a match ends the
  // A2 scan, which then reports no set-aside values; otherwise it has seen every value.
  const secret = findRealSecretAssignment(secretScanContents, new Set(), {
    allowCredentialNamedDigest: useV36Detectors,
    ...(setAside
      ? {
          observeValue: (value: string, outcome: V24ClassificationOutcome) => {
            if (isPlaceholderSetAsideSecret(value, outcome)) setAside.count += 1;
          },
        }
      : {}),
  });
  if (secret) return secret;
  if (useV23PemPrivateKeyGrammar) {
    const pemSecret = findPemPrivateKeyAssignment(secretScanContents, file);
    if (pemSecret) return pemSecret;
  }
  if (useV39Detectors && isEnvHistoryPath(file, useV36Detectors)) {
    const databaseUrlCredential = findDatabaseUrlUserinfoCredential(secretScanContents);
    if (databaseUrlCredential) return databaseUrlCredential;
    const weakCredential = findWeakExplicitEnvCredential(secretScanContents);
    if (weakCredential) return weakCredential;
  }
  return useV36Detectors && !isTestCredentialConfiguration
    ? findDefaultAdministrativeCredential(secretScanContents)
    : null;
}

interface V24ClassifiedCommittedSecret {
  readonly match: RealSecretAssignmentMatch;
  readonly classification: Exclude<V24SecretClassification, 'no_finding'>;
}

/**
 * v24-only current-tree secret scan. Same assignment grammar and same content preparation as
 * findCommittedSecretInFile; only the value gate differs.
 */
function findV24ClassifiedSecretInFile(
  repoPath: string,
  file: string,
  useV36Detectors: boolean,
  useV39Detectors: boolean,
  useV47Detectors: boolean,
  setAside?: PlaceholderSetAsideCount,
): V24ClassifiedCommittedSecret | null {
  const fullPath = join(repoPath, file);
  if (!isRegularFile(fullPath)) return null;
  const contents = readRepoText(fullPath, 'utf8');
  const isTestCredentialConfiguration =
    useV39Detectors && isLikelyTestCredentialConfiguration(file, contents);
  const secretScanContents = prepareCredentialScanContents(
    contents,
    file,
    useV36Detectors,
    useV39Detectors,
    useV47Detectors,
    true,
  );
  // The context window reads the RAW file, not the prepared copy. Every preparation step maps one
  // line to one replacement line, so line numbers are identical between the two — but v39's
  // comment stripping blanks exactly the lines that most often carry the instructional marker
  // (`# replace this with your own key`). Classifying against the stripped copy would discard the
  // evidence this mechanism exists to read.
  const rawLines = contents.split(/\r?\n/);
  const classifyFor =
    (wanted: Exclude<V24SecretClassification, 'no_finding'>, countSetAside = false) =>
    (value: string, identifier: string, line: number): V24ClassificationOutcome => {
      const outcome = classifyV24SecretShapedValue(
        value,
        identifier,
        line,
        rawLines,
        useV36Detectors,
      );
      // Counted on the first pass only, from the classifier's own verdict: a value v24 reports as
      // real or ambiguous is never also described as set aside. That pass sees every value unless
      // it stops at a real one, which ends the A2 scan with no set-aside values reported.
      if (countSetAside && setAside && isPlaceholderSetAsideSecret(value, outcome)) {
        setAside.count += 1;
      }
      return outcome.classification === wanted ? outcome : V24_NO_FINDING;
    };

  // Two bounded passes, not one. A single pass stopping at the first match of either kind would
  // let one unclassifiable value earlier in the file pre-empt a genuine leak below it. The first
  // pass stops at the first confidently real value, so the cost of the common (clean) case is one
  // extra linear scan and the cost of the flagging case is unchanged.
  const real = findRealSecretAssignment(secretScanContents, new Set(), {
    allowCredentialNamedDigest: useV36Detectors,
    classifyValue: classifyFor('real', true),
  });
  if (real) return { match: real, classification: 'real' };

  if (useV39Detectors && isEnvHistoryPath(file, useV36Detectors)) {
    const weakCredential = findWeakExplicitEnvCredential(secretScanContents);
    if (weakCredential) return { match: weakCredential, classification: 'real' };
  }
  const defaultAdministrative =
    useV36Detectors && !isTestCredentialConfiguration
      ? findDefaultAdministrativeCredential(secretScanContents)
      : null;
  if (defaultAdministrative) {
    return { match: defaultAdministrative, classification: 'real' };
  }

  const ambiguous = findRealSecretAssignment(secretScanContents, new Set(), {
    allowCredentialNamedDigest: useV36Detectors,
    classifyValue: classifyFor('ambiguous'),
  });
  return ambiguous ? { match: ambiguous, classification: 'ambiguous' } : null;
}

function prepareCredentialScanContents(
  contents: string,
  file: string,
  useV36Detectors: boolean,
  useV39Detectors: boolean,
  useV47Detectors = false,
  useContentOnlyPublicKeyContext = false,
): string {
  const withoutXamlEventNames =
    useV36Detectors && /\.xaml$/i.test(file)
      ? contents.replace(/\bTokenItem(?:Added|Removed)(?=\s*=)/gi, 'EventHandler')
      : contents;
  const withoutDocumentationExamples = useV39Detectors
    ? stripCommentAndDocumentationExamples(withoutXamlEventNames)
    : withoutXamlEventNames;
  return useV47Detectors
    ? stripV47PublicIdentifiersAndNonCredentialValues(
        withoutDocumentationExamples,
        file,
        useContentOnlyPublicKeyContext,
      )
    : withoutDocumentationExamples;
}

function stripV47PublicIdentifiersAndNonCredentialValues(
  contents: string,
  file: string,
  useContentOnlyPublicKeyContext = false,
): string {
  const lines = contents.split(/\r?\n/);
  return lines
    .map((line, index) => {
      let sanitized = line.replace(
        /^(\s*(?:export\s+)?(?:PUBLIC_)?ALGOLIA_(?:PUBLIC_)?API_KEY\s*[:=]\s*)[^\s#]+/i,
        '$1""',
      );
      if (isPublicDocumentationSearchKeyContext(
        lines,
        index,
        file,
        useContentOnlyPublicKeyContext,
      )) {
        sanitized = sanitized.replace(/(\bapiKey\s*[:=]\s*)(['"])[^'"]+\2/gi, '$1$2$2');
      }
      sanitized = sanitized.replace(
        /(\b[A-Za-z_][A-Za-z0-9_]*(?:token|api[_-]?key|access[_-]?key)[A-Za-z0-9_]*\s*[:=]\s*)(['"]?)0x[0-9a-f]{40}\2/gi,
        '$1""',
      );
      sanitized = sanitized.replace(
        /(\b[A-Za-z_][A-Za-z0-9_]*(?:token|api[_-]?key|access[_-]?key)[A-Za-z0-9_]*\s*[:=]\s*)(['"])([a-z][a-z0-9]*(?:_[a-z0-9]+){2,})\2/gi,
        (assignment, prefix: string, quote: string, value: string) =>
          /\b(?:cost|input|output|context|model|limit|price|usage|audio)\b/i.test(
            value.replaceAll('_', ' '),
          )
            ? `${prefix}${quote}${quote}`
            : assignment,
      );
      return sanitized;
    })
    .join('\n');
}

function isPublicDocumentationSearchKeyContext(
  lines: readonly string[],
  lineIndex: number,
  file: string,
  useContentOnlyPublicKeyContext = false,
): boolean {
  const windowStart = Math.max(0, lineIndex - 6);
  const preceding = lines.slice(windowStart, lineIndex + 1);
  for (let index = preceding.length - 1; index >= 0; index -= 1) {
    const candidate = preceding[index] ?? '';
    if (/}/.test(candidate) && index < preceding.length - 1) return false;
    if (/\bdocsearch(?:Options)?\b/i.test(candidate)) return true;
    if (
      /\balgolia\b/i.test(candidate) &&
      (useContentOnlyPublicKeyContext ||
        /(?:^|\/)(?:website|docs?)(?:\/|$)|(?:site[-_]?config|\.dumirc|docusaurus)/i.test(
          file,
        ))
    ) {
      return true;
    }
  }
  return false;
}

function stripCommentAndDocumentationExamples(contents: string): string {
  let blockCommentEnd: '*/' | '-->' | null = null;
  return contents
    .split(/\r?\n/)
    .map((line) => {
      const trimmed = line.trimStart();
      if (blockCommentEnd) {
        if (trimmed.includes(blockCommentEnd)) blockCommentEnd = null;
        return '';
      }
      if (trimmed.startsWith('/*')) {
        if (!trimmed.includes('*/')) blockCommentEnd = '*/';
        return '';
      }
      if (trimmed.startsWith('<!--')) {
        if (!trimmed.includes('-->')) blockCommentEnd = '-->';
        return '';
      }
      if (/^(?:\/\/|#|\*)/.test(trimmed)) return '';
      if (/\.description\s*\(/i.test(line) && /api[_-]?key|token|password|secret/i.test(line)) {
        return '';
      }
      return line;
    })
    .join('\n');
}

function isLikelyTestCredentialConfiguration(file: string, contents: string): boolean {
  if (!/\.(?:ya?ml|json|toml|ini|conf)$/i.test(file) && !/(?:^|\/)docker-compose/i.test(file)) {
    return false;
  }
  const testMarkers =
    contents.match(/(?:^|[^A-Za-z])(?:tests?|testing|e2e|appium|fixture)(?:[^A-Za-z]|$)/gi)
      ?.length ?? 0;
  return testMarkers >= 2;
}

function hasTemplateOnlyEnvContent(repoPath: string, file: string): boolean {
  const fullPath = join(repoPath, file);
  if (!isRegularFile(fullPath)) return false;
  const substantiveLines = readRepoText(fullPath, 'utf8')
    .split(/\r?\n/)
    .filter((line) => line.trim().length > 0 && !/^\s*#/.test(line));
  if (substantiveLines.length === 0) return true;
  const assignments = substantiveLines.map(
    (line) => /^\s*(?:export\s+)?[A-Za-z_][A-Za-z0-9_]*\s*=\s*(.*?)\s*$/.exec(line)?.[1] ?? null,
  );
  if (assignments.some((value) => value === null)) return false;
  return assignments.every((raw) => {
    if (raw === null) return false;
    const value = raw.replace(/^['"]|['"]$/g, '').trim();
    return value.length === 0 || isPlaceholderSecretValue(value);
  });
}

function findSecretFingerprintsInFile(
  repoPath: string,
  file: string,
  useV36Detectors = false,
  useV39Detectors = false,
  useV47Detectors = false,
  useV23PemPrivateKeyGrammar = false,
): string[] {
  const fullPath = join(repoPath, file);
  if (!isRegularFile(fullPath)) return [];
  const contents = readRepoText(fullPath, 'utf8');
  const scanContents = prepareCredentialScanContents(
    contents,
    file,
    useV36Detectors,
    useV39Detectors,
    useV47Detectors,
  );
  const fingerprints = findRealSecretAssignments(
    scanContents,
    new Set(),
    Number.POSITIVE_INFINITY,
    { allowCredentialNamedDigest: useV36Detectors },
  ).map(({ valueFingerprint }) => valueFingerprint);
  if (useV23PemPrivateKeyGrammar) {
    const pemSecret = findPemPrivateKeyAssignment(scanContents, file);
    if (pemSecret) fingerprints.push(pemSecret.valueFingerprint);
  }
  if (useV39Detectors && isEnvHistoryPath(file, useV36Detectors)) {
    const databaseUrlCredential = findDatabaseUrlUserinfoCredential(scanContents);
    if (databaseUrlCredential) fingerprints.push(databaseUrlCredential.valueFingerprint);
    const weakCredential = findWeakExplicitEnvCredential(scanContents);
    if (weakCredential) fingerprints.push(weakCredential.valueFingerprint);
  }
  return [...new Set(fingerprints)];
}

export function containsRealSecret(contents: string): boolean {
  return findRealSecretAssignment(contents) !== null;
}

interface RealSecretAssignmentMatch {
  identifier: string;
  line: number;
  valueLength: number;
  characterClasses: string;
  valueFingerprint: string;
  kind?: 'secret' | 'default_admin' | 'pem_private_key';
  /** v24-only; absent on every other rubric, which is what keeps v17 and v22 byte-stable. */
  classification?: Exclude<V24SecretClassification, 'no_finding'>;
  classificationReason?: string;
}

interface SecretAssignmentOptions {
  allowCredentialNamedDigest?: boolean;
  /**
   * v24-only. When supplied, the classifier's verdict replaces the fixed
   * `!isPlaceholderSecretValue(value) && looksLikeSecretValue(value)` value gate: it widens what
   * counts as a candidate and decides among no_finding / real / ambiguous. Absent on every other
   * rubric, so the legacy branch below is reached unchanged.
   */
  classifyValue?: (value: string, identifier: string, line: number) => V24ClassificationOutcome;
  /** Sees every assignment value the pass reaches, with its verdict. Never changes the verdict. */
  observeValue?: (value: string, outcome: V24ClassificationOutcome) => void;
}

function findRealSecretAssignment(
  contents: string,
  excludedValueFingerprints: ReadonlySet<string> = new Set(),
  options: SecretAssignmentOptions = {},
): RealSecretAssignmentMatch | null {
  return findRealSecretAssignments(contents, excludedValueFingerprints, 1, options)[0] ?? null;
}

function findRealSecretAssignments(
  contents: string,
  excludedValueFingerprints: ReadonlySet<string> = new Set(),
  maximumMatches = Number.POSITIVE_INFINITY,
  options: SecretAssignmentOptions = {},
): RealSecretAssignmentMatch[] {
  const matches: RealSecretAssignmentMatch[] = [];
  // The former all-in-one expression started its greedy identifier scan at every character.
  // On large generated or minified files with no assignment, that can revisit the same suffix
  // quadratically. Search for the required keyword first, then parse only its identifier suffix,
  // assignment delimiter, and value. This accepts the same assignment grammar as the former
  // expression while keeping the scan linear in file size.
  SECRET_IDENTIFIER_KEYWORD_PATTERN.lastIndex = 0;
  let match = SECRET_IDENTIFIER_KEYWORD_PATTERN.exec(contents);
  let line = 1;
  let lineCursor = 0;
  while (match !== null) {
    const keyword = match[0];
    const keywordStart = match.index;
    while (lineCursor < keywordStart) {
      if (contents.charCodeAt(lineCursor) === 10) line += 1;
      lineCursor += 1;
    }

    let cursor = keywordStart + keyword.length;
    while (cursor < contents.length && isSecretIdentifierCharacter(contents.charCodeAt(cursor))) {
      cursor += 1;
    }
    const identifierEnd = cursor;
    let identifierStart = keywordStart;
    while (
      identifierStart > 0 &&
      isSecretIdentifierCharacter(contents.charCodeAt(identifierStart - 1))
    ) {
      identifierStart -= 1;
    }
    const identifier = contents.slice(identifierStart, identifierEnd);
    let nextSearchIndex = identifierEnd;
    while (cursor < contents.length && SINGLE_WHITESPACE_PATTERN.test(contents[cursor] ?? '')) {
      cursor += 1;
    }
    const delimiter = contents[cursor];
    if (delimiter === ':' || delimiter === '=') {
      cursor += 1;
      while (cursor < contents.length && SINGLE_WHITESPACE_PATTERN.test(contents[cursor] ?? '')) {
        cursor += 1;
      }
      if (contents[cursor] === "'" || contents[cursor] === '"') cursor += 1;

      const valueStart = cursor;
      while (cursor < contents.length) {
        const character = contents[cursor] ?? '';
        if (character === "'" || character === '"' || SINGLE_WHITESPACE_PATTERN.test(character)) {
          break;
        }
        cursor += 1;
      }
      if (cursor > valueStart) {
        const value = contents.slice(valueStart, cursor).replace(/[,;)]$/, '');
        // The former global assignment expression consumed the complete raw value before looking
        // for another assignment. Preserve that behavior and avoid rescans inside the value.
        nextSearchIndex = cursor;
        const outcome: V24ClassificationOutcome = options.classifyValue
          ? options.classifyValue(value, identifier, line)
          : !isPlaceholderSecretValue(value) &&
              (looksLikeSecretValue(value) ||
                (options.allowCredentialNamedDigest === true &&
                  isLikelyDigestOrHash(value) &&
                  isExplicitCredentialIdentifier(identifier)))
            ? V24_REAL
            : V24_NO_FINDING;
        options.observeValue?.(value, outcome);
        if (outcome.classification !== 'no_finding') {
          const valueFingerprint = createHash('sha256').update(value).digest('hex');
          const characterClasses = [
            /[a-z]/.test(value) ? 'lower' : '',
            /[A-Z]/.test(value) ? 'upper' : '',
            /\d/.test(value) ? 'digit' : '',
            /[^A-Za-z0-9]/.test(value) ? 'symbol' : '',
          ]
            .filter(Boolean)
            .join('+');
          if (!excludedValueFingerprints.has(valueFingerprint)) {
            matches.push({
              identifier,
              line,
              valueLength: value.length,
              characterClasses: characterClasses || 'other',
              valueFingerprint,
              // Only ever set on the v24 classifier path; the legacy branch above yields V24_REAL,
              // whose `reason` is undefined, so these two keys stay absent exactly as before.
              ...(options.classifyValue
                ? {
                    classification: outcome.classification as Exclude<
                      V24SecretClassification,
                      'no_finding'
                    >,
                    ...(outcome.reason ? { classificationReason: outcome.reason } : {}),
                  }
                : {}),
            });
            if (matches.length >= maximumMatches) return matches;
          }
        }
      }
    }
    // Every later keyword before identifierEnd belongs to the same identifier and would inspect
    // the same suffix. Skip it so keyword-dense generated identifiers remain a single pass. When
    // a value matched, nextSearchIndex also skips the raw value consumed by the former expression.
    SECRET_IDENTIFIER_KEYWORD_PATTERN.lastIndex = nextSearchIndex;
    match = SECRET_IDENTIFIER_KEYWORD_PATTERN.exec(contents);
  }
  return matches;
}

function isExplicitCredentialIdentifier(identifier: string): boolean {
  return /^(?:github|gitlab|api|access)[_-]?(?:token|key)$/i.test(identifier);
}

function findWeakExplicitEnvCredential(contents: string): RealSecretAssignmentMatch | null {
  const lines = contents.split(/\r?\n/);
  for (const [index, line] of lines.entries()) {
    if (/^\s*#/.test(line)) continue;
    const match =
      /^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*(?:PASSWORD|PASSWD|PWD|SECRET(?:_KEY)?|API_KEY|TOKEN))\s*=\s*['"]?([^\s#'"]+)['"]?/i.exec(
        line,
      );
    const identifier = match?.[1];
    const value = match?.[2];
    if (!identifier || !value || isPlaceholderSecretValue(value)) continue;
    const minimumLength = /(?:API_KEY|TOKEN)$/i.test(identifier) ? 12 : 6;
    if (value.length < minimumLength) continue;
    const characterClasses = [
      /[a-z]/.test(value) ? 'lower' : '',
      /[A-Z]/.test(value) ? 'upper' : '',
      /\d/.test(value) ? 'digit' : '',
      /[^A-Za-z0-9]/.test(value) ? 'symbol' : '',
    ]
      .filter(Boolean)
      .join('+');
    return {
      identifier,
      line: index + 1,
      valueLength: value.length,
      characterClasses: characterClasses || 'other',
      valueFingerprint: createHash('sha256').update(value).digest('hex'),
    };
  }
  return null;
}

function findDatabaseUrlUserinfoCredential(contents: string): RealSecretAssignmentMatch | null {
  const lines = contents.split(/\r?\n/);
  for (const [index, line] of lines.entries()) {
    if (/^\s*#/.test(line)) continue;
    const match =
      /^\s*(?:export\s+)?(DATABASE_URL)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s#]+))/i.exec(line);
    const identifier = match?.[1];
    const rawValue = match?.[2] ?? match?.[3] ?? match?.[4];
    if (!identifier || !rawValue) continue;
    let parsed: URL;
    try {
      parsed = new URL(rawValue);
    } catch {
      continue;
    }
    if (
      (parsed.protocol !== 'postgres:' && parsed.protocol !== 'postgresql:') ||
      !parsed.username ||
      !parsed.password
    ) {
      continue;
    }
    let password: string;
    try {
      password = decodeURIComponent(parsed.password);
    } catch {
      continue;
    }
    if (isPlaceholderSecretValue(password)) continue;
    const characterClasses = [
      /[a-z]/.test(password) ? 'lower' : '',
      /[A-Z]/.test(password) ? 'upper' : '',
      /\d/.test(password) ? 'digit' : '',
      /[^A-Za-z0-9]/.test(password) ? 'symbol' : '',
    ]
      .filter(Boolean)
      .join('+');
    return {
      identifier,
      line: index + 1,
      valueLength: password.length,
      characterClasses: characterClasses || 'other',
      valueFingerprint: createHash('sha256').update(password).digest('hex'),
    };
  }
  return null;
}

function findDefaultAdministrativeCredential(contents: string): RealSecretAssignmentMatch | null {
  const lines = contents.split(/\r?\n/);
  for (const [index, line] of lines.entries()) {
    const match =
      /\b([A-Za-z0-9_]*(?:ADMIN|ROOT)[A-Za-z0-9_]*(?:PASSWORD|PASSWD|PWD))\s*[:=]\s*["']?(admin|root|password)["']?(?:\s|$)/i.exec(
        line,
      );
    const identifier = match?.[1];
    const value = match?.[2];
    if (!identifier || !value) continue;
    return {
      identifier,
      line: index + 1,
      valueLength: value.length,
      characterClasses: 'lower',
      valueFingerprint: createHash('sha256').update(value).digest('hex'),
      kind: 'default_admin',
    };
  }
  return null;
}

function secretEvidenceLabel(prefix: string, match: RealSecretAssignmentMatch): string {
  return `${prefix} (value redacted; length ${match.valueLength}; classes ${match.characterClasses})`;
}

function isSecretIdentifierCharacter(characterCode: number): boolean {
  return (
    (characterCode >= 48 && characterCode <= 57) ||
    (characterCode >= 65 && characterCode <= 90) ||
    characterCode === 95 ||
    (characterCode >= 97 && characterCode <= 122)
  );
}

interface HistorySecretScanResult {
  // A confirmed high-entropy secret value found in a historical blob — critical.
  evidence: WitanEvidencePointer | null;
  // The `kind` of the match `evidence` was built from (mirrors RealSecretAssignmentMatch['kind']
  // — e.g. 'pem_private_key'), carried alongside `evidence` rather than recovered by matching
  // substrings in `evidence.label`, so a future wording change to that label can never silently
  // reclassify the finding. Only meaningful when `evidence` is non-null.
  secretKind: RealSecretAssignmentMatch['kind'] | null;
  // A non-template .env file path was tracked in history, but no confirmed secret
  // value was found in the scanned content — at most a warning, never a critical
  // ("bare path", not a "value"). Templates never reach this: isCredentialHistoryPath
  // excludes them before they are ever blob-scanned.
  envPathEvidence: WitanEvidencePointer | null;
  truncated: boolean;
}

const CONTROL_CHARACTER_HISTORY_PATH_LIMITATION =
  'Git history contained a credential-shaped pathname with control characters. Cejel omitted that path from historical blob inspection and continued with reduced history evidence.';
// #569: the same skip for a path that is neither credential- nor `.env`-shaped. The sentence above
// called every such path credential-shaped, which was false (axios's `\bMIGRATION_GUIDE.md`). It is
// still a scan limitation, so the badge and `--min-score` outcome do not change; only its words do.
const CONTROL_CHARACTER_HISTORY_OTHER_PATH_LIMITATION =
  'Git history contained a pathname with control characters that is not credential-shaped. Cejel did not read that path in its history scans.';

const HISTORY_READ_FAILURE_SUFFIX = ' Cejel continued with reduced Git history evidence.';

/**
 * #560: an expected absence (git not installed, or no repository here) is not reported as a scan
 * limitation, as before. When git itself could not be run, A2's recorder notes it, so A2 can tell
 * an unread repository history from a directory with none (a2HistoryIncompleteness).
 */
function isExpectedHistoryAbsence(
  scanLimitations: Set<string>,
  result: Exclude<GitExecResult, { readonly ok: true }>,
): boolean {
  if (!isExpectedGitAbsence(result)) return false;
  if (scanLimitations instanceof HistoryReadRecorder) {
    if (result.reason === 'git_absent') scanLimitations.gitAbsent = true;
    if (result.reason === 'not_a_repo') scanLimitations.notARepository = true;
  }
  return true;
}

/**
 * #569: the one definition of "credential-shaped" for the control-character limitation's wording,
 * shared by all three history readers so a path gets the same sentence whichever reader meets it.
 * It classifies the name's shape under the rubric's own grammar (hasCredentialHistoryPathShape with
 * the rubric's flags; under v23 that includes key-shaped JSON), ignoring the hard-excluded-directory
 * rule, or'd with the `.env` pattern. When in doubt it errs toward the credential-shaped sentence,
 * the cautious one: a path in `node_modules/` named `secret.key` has a credential-shaped name.
 */
function controlCharacterPathIsCredentialShaped(
  path: string,
  useV36Detectors: boolean,
  useV23PemPrivateKeyGrammar: boolean,
): boolean {
  return (
    /(?:^|\/)\.env(?:\.|$)/i.test(path) ||
    hasCredentialHistoryPathShape(path, useV36Detectors, useV23PemPrivateKeyGrammar)
  );
}

/**
 * #560: a history path with control characters in its name is left unread and named in the scan
 * limitations. When the path is one the reader would otherwise have used (`candidate`), A2's
 * recorder also counts it as an incomplete read. #569: the sentence is chosen by
 * controlCharacterPathIsCredentialShaped, the same for every reader.
 */
function skipControlCharacterHistoryPath(
  scanLimitations: Set<string>,
  path: string,
  candidate: boolean,
  useV36Detectors: boolean,
  useV23PemPrivateKeyGrammar: boolean,
): void {
  if (candidate && scanLimitations instanceof HistoryReadRecorder) {
    scanLimitations.controlCharacterCandidate = true;
  }
  scanLimitations.add(
    controlCharacterPathIsCredentialShaped(path, useV36Detectors, useV23PemPrivateKeyGrammar)
      ? CONTROL_CHARACTER_HISTORY_PATH_LIMITATION
      : CONTROL_CHARACTER_HISTORY_OTHER_PATH_LIMITATION,
  );
}

function declareHistoryFailure(
  scanLimitations: Set<string>,
  reason: Exclude<GitExecResult, { readonly ok: true }>['reason'],
  operation: string,
  maxBufferBytes?: number,
): void {
  if (scanLimitations instanceof HistoryReadRecorder) {
    scanLimitations.noteFailure(reason, maxBufferBytes);
  }
  scanLimitations.add(
    `${describeGitFailure(reason, operation, maxBufferBytes)}${HISTORY_READ_FAILURE_SUFFIX}`,
  );
}

/**
 * #556: a scanLimitations stand-in for one criterion's history reads. Every limitation is
 * forwarded to the real set at once, in the same order, so the report is unchanged.
 * declareHistoryFailure tells it about each failed git read: `limitHits` names Cejel's own limits a
 * read stopped at (an output limit or the timeout), and `otherFailure` records any other failure.
 * #560: `gitAbsent` records that git itself could not be run (an expected absence, so no scan
 * limitation), and `controlCharacterCandidate` that a path the read would have used was skipped for
 * control characters in its name. A2 counts both as an incomplete read; a control-character path
 * the read would not have used anyway is not counted.
 */
class HistoryReadRecorder extends Set<string> {
  readonly limitHits = new Set<string>();
  otherFailure = false;
  /** git itself could not be run (ENOENT), which every read reports as an expected absence. */
  gitAbsent = false;
  /** git reported "no repository" (or no revision) for a history read: also an expected absence. */
  notARepository = false;
  /** A credential- or .env-shaped history path was skipped for control characters in its name. */
  controlCharacterCandidate = false;
  private readonly target: Set<string>;

  constructor(target: Set<string>) {
    super();
    this.target = target;
  }

  get failed(): boolean {
    return this.limitHits.size > 0 || this.otherFailure;
  }

  noteFailure(reason: Exclude<GitExecResult, { readonly ok: true }>['reason'], maxBufferBytes?: number): void {
    if (reason === 'buffer_exceeded') {
      const bytes = maxBufferBytes ?? GIT_EXEC_MAX_BUFFER_BYTES;
      const limit =
        bytes % (1024 * 1024) === 0 ? `${bytes / (1024 * 1024)} MiB` : `${Math.ceil(bytes / 1024)} KiB`;
      this.limitHits.add(`${limit} output limit`);
    } else if (reason === 'timeout') {
      this.limitHits.add(HISTORY_READ_TIMEOUT_NAME);
    } else {
      this.otherFailure = true;
    }
  }

  /** #586: a batched re-read stopped at its time budget, one of Cejel's own limits. */
  noteBudgetExhausted(): void {
    this.limitHits.add(historyFallbackBudgetName());
  }

  override add(value: string): this {
    this.target.add(value);
    return super.add(value);
  }
}

/**
 * Test probe (#556): runs only A2's `.env`-path history read through a recorder and reports what
 * it found and which failures it detected. Not used by the scan.
 */
export function probeA2EnvPathHistoryRead(repoPath: string): {
  found: boolean;
  limitations: string[];
  limitHits: string[];
  otherFailure: boolean;
  gitAbsent: boolean;
  controlCharacterCandidate: boolean;
} {
  const limitations = new Set<string>();
  const recorder = new HistoryReadRecorder(limitations);
  const found = hasEnvPathInGitHistory(repoPath, recorder);
  return {
    found,
    limitations: [...limitations],
    limitHits: [...recorder.limitHits],
    otherFailure: recorder.otherFailure,
    gitAbsent: recorder.gitAbsent,
    controlCharacterCandidate: recorder.controlCharacterCandidate,
  };
}

function collectHistorySecretEvidence(
  repoPath: string,
  excludeHead: boolean,
  currentSecretFingerprintsByPath: ReadonlyMap<string, ReadonlySet<string>>,
  scanLimitations: Set<string>,
  authoredProductionOnly = false,
  useV36Detectors = false,
  useV39Detectors = false,
  useV47Detectors = false,
  useV23PemPrivateKeyGrammar = false,
): HistorySecretScanResult {
  const historyEntries = readCredentialHistoryEntries(
    repoPath,
    scanLimitations,
    useV36Detectors,
    useV23PemPrivateKeyGrammar,
  );
  const head = excludeHead ? readGitHead(repoPath) : null;
  let scannedFiles = 0;
  let v23WidenedOnlyScanned = 0;
  let envPathEvidence: WitanEvidencePointer | null = null;
  for (const entry of historyEntries) {
    if (head && entry.commit === head) continue;
    if (
      authoredProductionOnly &&
      !(useV47Detectors
        ? isV47AuthoredProductionPath(entry.path)
        : useV39Detectors
          ? isV39AuthoredProductionPath(entry.path)
          : isAuthoredProductionPath(entry.path))
    ) {
      continue;
    }
    // Draws from the small, separate v23-widened budget instead of the main one — see
    // V23_PEM_WIDENED_HISTORY_BLOB_LIMIT above — so it can never crowd out base-classified
    // candidates from HISTORY_SECRET_SCAN_CREDENTIAL_BLOB_LIMIT.
    const isV23WidenedOnly =
      useV23PemPrivateKeyGrammar &&
      isV23PemCredentialHistoryPath(historyPathBasename(entry.path.toLowerCase())) &&
      !isCredentialHistoryPath(entry.path, useV36Detectors, false);
    if (isV23WidenedOnly) {
      if (v23WidenedOnlyScanned >= V23_PEM_WIDENED_HISTORY_BLOB_LIMIT) continue;
      v23WidenedOnlyScanned += 1;
    } else {
      if (scannedFiles >= HISTORY_SECRET_SCAN_CREDENTIAL_BLOB_LIMIT) {
        return { evidence: null, secretKind: null, envPathEvidence, truncated: true };
      }
      scannedFiles += 1;
    }
    const contents = readGitBlob(repoPath, entry.commit, entry.path, scanLimitations);
    if (!contents) continue;
    const scanContents = prepareCredentialScanContents(
      contents,
      entry.path,
      useV36Detectors,
      useV39Detectors,
      useV47Detectors,
    );
    const currentFingerprints = currentSecretFingerprintsByPath.get(entry.path) ?? new Set();
    let secretMatch = findRealSecretAssignment(scanContents, currentFingerprints, {
      allowCredentialNamedDigest: useV36Detectors,
    });
    if (!secretMatch && useV23PemPrivateKeyGrammar) {
      const pemMatch = findPemPrivateKeyAssignment(scanContents, entry.path);
      if (pemMatch && !currentFingerprints.has(pemMatch.valueFingerprint)) {
        secretMatch = pemMatch;
      }
    }
    if (
      !secretMatch &&
      useV39Detectors &&
      isEnvHistoryPath(entry.path, useV36Detectors, useV47Detectors)
    ) {
      const databaseUrlCredential = findDatabaseUrlUserinfoCredential(scanContents);
      if (databaseUrlCredential && !currentFingerprints.has(databaseUrlCredential.valueFingerprint)) {
        secretMatch = databaseUrlCredential;
      }
    }
    if (
      !secretMatch &&
      useV39Detectors &&
      isEnvHistoryPath(entry.path, useV36Detectors, useV47Detectors)
    ) {
      const weakCredential = findWeakExplicitEnvCredential(scanContents);
      if (weakCredential && !currentFingerprints.has(weakCredential.valueFingerprint)) {
        secretMatch = weakCredential;
      }
    }
    if (secretMatch) {
      return {
        evidence: {
          kind: 'secret_scan',
          label: secretEvidenceLabel(
            secretMatch.kind === 'pem_private_key'
              ? 'Committed PEM-formatted private key in recent git history'
              : 'Committed secret in recent git history',
            secretMatch,
          ),
          path: entry.path,
          line: secretMatch.line,
          contentHash: entry.commit,
        },
        secretKind: secretMatch.kind ?? null,
        envPathEvidence,
        truncated: false,
      };
    }
    if (!envPathEvidence && isEnvHistoryPath(entry.path, useV36Detectors, useV47Detectors)) {
      envPathEvidence = {
        kind: 'secret_scan',
        label: '.env file (not a template) tracked in git history; no confirmed secret value found',
        path: entry.path,
        contentHash: entry.commit,
      };
    }
  }
  return { evidence: null, secretKind: null, envPathEvidence, truncated: false };
}

interface GitHistoryEntry {
  commit: string;
  path: string;
}

// #567: when one of A2's whole-history reads stops at Cejel's own output limit or timeout, it is
// re-run over the commit list in pages and batches, each small enough to finish within those
// limits, instead of being given up. Only a read that hits a limit falls back, so every other
// repository is read exactly as before, byte for byte.
const HISTORY_COMMIT_PAGE = 50_000;
const HISTORY_COMMIT_BATCH = 1_000;

// #586: the time one such re-read may take, its rev-list pages and batches together. Each git call
// already stops at the 30-second timeout, but a batch that times out is halved and retried, so
// without this a slow repository could take many times longer than before #567, when the read gave
// up at the first limit. 120 s is about 50 times the slowest re-read measured on the public rows
// (biomejs, about 2.4 s; react about 1.4 s) and four times the per-call timeout. A read that hits no
// limit never starts a re-read, so the budget does not apply to it.
const HISTORY_FALLBACK_TIME_BUDGET_MS = 120_000;

/**
 * #586: the time budget of one batched re-read. Checked before each git call of the re-read; once
 * the time is spent, the re-read stops and the read is declared incomplete, once, exactly as a read
 * that stops at Cejel's own timeout is: a scan limitation for every rubric, and A2's recorder notes
 * the limit, so v27's A2 treats it as a failed history read (ADR-0001). What was read is kept but
 * is never presented as the whole history.
 */
class HistoryFallbackBudget {
  private readonly deadline = performance.now() + HISTORY_FALLBACK_TIME_BUDGET_MS;
  private declared = false;

  constructor(private readonly scanLimitations: Set<string>) {}

  /**
   * True while time remains. Once it is spent, declares the read incomplete (once) and returns
   * false. `operation` names the git read that found the budget spent, in the words the same read
   * uses when it stops at Cejel's other limits (the tree enumeration's rev-list paging is "history
   * revision enumeration", its batches "history tree enumeration").
   */
  allows(operation: string): boolean {
    if (performance.now() < this.deadline) return true;
    if (!this.declared) {
      this.declared = true;
      if (this.scanLimitations instanceof HistoryReadRecorder) this.scanLimitations.noteBudgetExhausted();
      this.scanLimitations.add(
        `Cejel: local git ${operation} stopped at Cejel's ${historyFallbackBudgetName()}.${HISTORY_READ_FAILURE_SUFFIX}`,
      );
    }
    return false;
  }
}

function stoppedAtOwnLimit(result: GitExecResult): boolean {
  return !result.ok && (result.reason === 'buffer_exceeded' || result.reason === 'timeout');
}

/**
 * #567: `git rev-list HEAD` in pages of HISTORY_COMMIT_PAGE commits, in the same order as one
 * call. A page that fails is declared, and the commits read so far are returned.
 */
function readHistoryCommitsInPages(
  repoPath: string,
  scanLimitations: Set<string>,
  operation: string,
  budget: HistoryFallbackBudget,
): string[] {
  const commits: string[] = [];
  for (let skip = 0; ; skip += HISTORY_COMMIT_PAGE) {
    if (!budget.allows(operation)) return commits;
    const page = execGit(['rev-list', `--max-count=${HISTORY_COMMIT_PAGE}`, `--skip=${skip}`, 'HEAD'], {
      cwd: repoPath,
    });
    if (!page.ok) {
      if (!isExpectedHistoryAbsence(scanLimitations, page)) {
        declareHistoryFailure(scanLimitations, page.reason, operation);
      }
      return commits;
    }
    const lines = page.stdout.split('\n').filter((line) => line !== '');
    commits.push(...lines);
    if (lines.length < HISTORY_COMMIT_PAGE) return commits;
  }
}

/**
 * #567: runs `argv`, which reads commit ids on stdin, over `commits` in order, HISTORY_COMMIT_BATCH
 * at a time. A batch that stops at Cejel's own output limit or timeout is halved and retried, so the
 * outputs, concatenated, are what one call would have printed. A single commit that still hits a
 * limit, or any other failure, is declared and skipped. `stop` ends the run early once a caller has
 * what it needs. Returns each batch's output, in order.
 */
function runHistoryCommandInBatches(
  repoPath: string,
  argv: readonly string[],
  commits: readonly string[],
  scanLimitations: Set<string>,
  operation: string,
  budget: HistoryFallbackBudget,
  stop?: (output: string) => boolean,
): string[] {
  const outputs: string[] = [];
  const queue: string[][] = [];
  for (let start = 0; start < commits.length; start += HISTORY_COMMIT_BATCH) {
    queue.push(commits.slice(start, start + HISTORY_COMMIT_BATCH));
  }
  while (queue.length > 0) {
    if (!budget.allows(operation)) break;
    const batch = queue.shift() as string[];
    const result = execGit(argv, { cwd: repoPath, input: `${batch.join('\n')}\n` });
    if (result.ok) {
      outputs.push(result.stdout);
      if (stop?.(result.stdout)) break;
      continue;
    }
    if (isExpectedHistoryAbsence(scanLimitations, result)) continue;
    if (stoppedAtOwnLimit(result) && batch.length > 1) {
      const middle = Math.ceil(batch.length / 2);
      queue.unshift(batch.slice(0, middle), batch.slice(middle));
      continue;
    }
    declareHistoryFailure(scanLimitations, result.reason, operation);
  }
  return outputs;
}

const HISTORY_TREE_ENUMERATION_ARGV = [
  'diff-tree',
  '--stdin',
  '--root',
  '--name-only',
  '-r',
  '--diff-filter=AM',
  '-z',
  '--pretty=format:commit:%H%x00',
] as const;

function readCredentialHistoryEntries(
  repoPath: string,
  scanLimitations: Set<string>,
  useV36Detectors = false,
  useV23PemPrivateKeyGrammar = false,
): GitHistoryEntry[] {
  const entries: GitHistoryEntry[] = [];
  const seen = new Set<string>();

  const appendEntry = (entry: GitHistoryEntry): void => {
    const key = `${entry.commit}:${entry.path}`;
    if (seen.has(key)) return;
    seen.add(key);
    entries.push(entry);
  };

  // A report is bound to the checked-out revision. Unrelated local branches and
  // remote-tracking refs are ambient clone state, not evidence for that revision.
  const commitsResult = execGit(['rev-list', 'HEAD'], { cwd: repoPath });
  let commits: string[] | undefined;
  // #586: one time budget for this read's whole re-read, started only when a re-read starts.
  let budget: HistoryFallbackBudget | undefined;
  const fallbackBudget = () => (budget ??= new HistoryFallbackBudget(scanLimitations));
  if (commitsResult.ok) {
    commits = undefined;
  } else if (stoppedAtOwnLimit(commitsResult)) {
    commits = readHistoryCommitsInPages(repoPath, scanLimitations, 'history revision enumeration', fallbackBudget());
  } else if (!isExpectedHistoryAbsence(scanLimitations, commitsResult)) {
    declareHistoryFailure(scanLimitations, commitsResult.reason, 'history revision enumeration');
  }
  const treeOutputs: string[] = [];
  if (commitsResult.ok) {
    const historyResult = execGit(HISTORY_TREE_ENUMERATION_ARGV, {
      cwd: repoPath,
      input: commitsResult.stdout,
    });
    if (historyResult.ok) {
      treeOutputs.push(historyResult.stdout);
    } else if (stoppedAtOwnLimit(historyResult)) {
      commits = commitsResult.stdout.split('\n').filter((line) => line !== '');
    } else if (!isExpectedHistoryAbsence(scanLimitations, historyResult)) {
      declareHistoryFailure(scanLimitations, historyResult.reason, 'history tree enumeration');
    }
  }
  if (commits !== undefined) {
    treeOutputs.push(
      ...runHistoryCommandInBatches(
        repoPath,
        HISTORY_TREE_ENUMERATION_ARGV,
        commits,
        scanLimitations,
        'history tree enumeration',
        fallbackBudget(),
      ),
    );
  }
  for (const treeOutput of treeOutputs) {
    let currentCommit: string | null = null;
    for (const rawToken of treeOutput.split('\0')) {
      const token = rawToken.startsWith('\n') ? rawToken.slice(1) : rawToken;
      if (token.startsWith('commit:')) {
        currentCommit = token.slice('commit:'.length);
        continue;
      }
      const path = token;
      if (!currentCommit || !path) continue;
      if (/[\u0000-\u001f\u007f]/.test(path)) {
        skipControlCharacterHistoryPath(
          scanLimitations,
          path,
          isCredentialHistoryPath(path, useV36Detectors, useV23PemPrivateKeyGrammar),
          useV36Detectors,
          useV23PemPrivateKeyGrammar,
        );
        continue;
      }
      if (!isCredentialHistoryPath(path, useV36Detectors, useV23PemPrivateKeyGrammar)) continue;
      appendEntry({ commit: currentCommit, path });
    }
  }

  for (const entry of readDeletedCredentialHistoryEntries(
    repoPath,
    scanLimitations,
    useV36Detectors,
    useV23PemPrivateKeyGrammar,
  )) {
    appendEntry(entry);
  }

  return entries;
}

function readDeletedCredentialHistoryEntries(
  repoPath: string,
  scanLimitations: Set<string>,
  useV36Detectors = false,
  useV23PemPrivateKeyGrammar = false,
): GitHistoryEntry[] {
  const deletedPaths = readDeletedCredentialHistoryPaths(
    repoPath,
    scanLimitations,
    useV36Detectors,
    useV23PemPrivateKeyGrammar,
  );
  const entries: GitHistoryEntry[] = [];
  const seen = new Set<string>();
  for (const path of deletedPaths) {
    for (const commit of readHistoryCommitsForPath(repoPath, path, scanLimitations)) {
      const key = `${commit}:${path}`;
      if (seen.has(key)) continue;
      seen.add(key);
      entries.push({ commit, path });
    }
  }
  return entries;
}

function readDeletedCredentialHistoryPaths(
  repoPath: string,
  scanLimitations: Set<string>,
  useV36Detectors = false,
  useV23PemPrivateKeyGrammar = false,
): string[] {
  const flags = ['--diff-filter=D', '--name-only', '-z', '--format=commit:%H%x00'];
  const historyResult = execGit(['log', '--no-show-signature', 'HEAD', ...flags], { cwd: repoPath });
  let output: string;
  if (historyResult.ok) {
    output = historyResult.stdout;
  } else if (stoppedAtOwnLimit(historyResult)) {
    // #567: the same log, one batch of commits at a time, in the same order.
    const budget = new HistoryFallbackBudget(scanLimitations);
    const commits = readHistoryCommitsInPages(repoPath, scanLimitations, 'deleted-path history scan', budget);
    output = runHistoryCommandInBatches(
      repoPath,
      ['log', '--no-show-signature', '--no-walk=unsorted', '--stdin', ...flags],
      commits,
      scanLimitations,
      'deleted-path history scan',
      budget,
    ).join('\0');
  } else {
    if (isExpectedHistoryAbsence(scanLimitations, historyResult)) return [];
    declareHistoryFailure(scanLimitations, historyResult.reason, 'deleted-path history scan');
    return [];
  }
  const paths: string[] = [];
  const seen = new Set<string>();
  for (const rawToken of output.split('\0')) {
    const path = rawToken.startsWith('\n') ? rawToken.slice(1) : rawToken;
    if (path.startsWith('commit:') || !path) continue;
    if (/[\u0000-\u001f\u007f]/.test(path)) {
      skipControlCharacterHistoryPath(
        scanLimitations,
        path,
        isCredentialHistoryPath(path, useV36Detectors, useV23PemPrivateKeyGrammar),
        useV36Detectors,
        useV23PemPrivateKeyGrammar,
      );
      continue;
    }
    if (!path || seen.has(path)) continue;
    if (!isCredentialHistoryPath(path, useV36Detectors, useV23PemPrivateKeyGrammar)) continue;
    seen.add(path);
    paths.push(path);
  }
  return paths;
}

function readHistoryCommitsForPath(
  repoPath: string,
  path: string,
  scanLimitations: Set<string>,
): string[] {
  const historyResult = execGit(
    // A literal pathspec: a deleted file named, say, `:(exclude)secrets` must name that file, not
    // every other path (#560 review, F7).
    ['log', '--no-show-signature', 'HEAD', '--diff-filter=AM', '--format=%H', '--', `:(literal)${path}`],
    { cwd: repoPath },
  );
  if (!historyResult.ok) {
    if (isExpectedHistoryAbsence(scanLimitations, historyResult)) return [];
    declareHistoryFailure(scanLimitations, historyResult.reason, 'path history scan');
    return [];
  }
  return historyResult.stdout
    .split('\n')
    .map((line) => line.trim())
    .filter((line) => /^[0-9a-f]{40}$/i.test(line));
}

// v23-only (goal_cejel_v23_pem_private_key_grammar_2026-09-06): a service-account key export
// (GCP/AWS-style) is conventionally named around "key" or "service-account", not "secret" or
// "credential" — the cycle-12 miss was exactly this shape, and isCredentialHistoryPath's prior
// path candidate set excludes it, so the blob is never even read for the value grammar below to
// reject or accept. Narrowly widened to basenames that are both ".json" AND key-shaped, rather
// than every ".json" in history, to keep the history-scan blob-read cost bounded — the same
// reasoning that keeps the rest of this candidate set to a short, specific list.
const V23_KEY_SHAPED_JSON_PATH_PATTERN =
  /(?<![A-Za-z0-9])(?:service[-_]?account|private[-_]?key|creds?|key)(?![A-Za-z0-9])/i;

// Shared by isCredentialHistoryPath and isV23PemCredentialHistoryPath so a future hardening of
// basename extraction here (e.g. also splitting on `\` for Windows-style paths) is inherited by
// both instead of being applied to one and silently missed on the other.
function historyPathBasename(lowerPath: string): string {
  return lowerPath.split('/').at(-1) ?? lowerPath;
}

function isV23PemCredentialHistoryPath(basename: string): boolean {
  return basename.endsWith('.json') && V23_KEY_SHAPED_JSON_PATH_PATTERN.test(basename);
}

function isCredentialHistoryPath(
  path: string,
  useV36Detectors = false,
  useV23PemPrivateKeyGrammar = false,
): boolean {
  if (isHardExcludedPath(path)) return false;
  return hasCredentialHistoryPathShape(path, useV36Detectors, useV23PemPrivateKeyGrammar);
}

// The name-shape half of isCredentialHistoryPath: whether the path's name is credential-shaped
// under the rubric's grammar, whatever directory it sits in. isCredentialHistoryPath adds the
// hard-excluded-directory rule; the control-character limitation's wording uses the shape alone
// (#571 review), since "not credential-shaped" would describe the name falsely.
function hasCredentialHistoryPathShape(
  path: string,
  _useV36Detectors = false,
  useV23PemPrivateKeyGrammar = false,
): boolean {
  // Note: template paths (.env.example etc.) are intentionally NOT excluded here —
  // a real secret can still leak through a template path (e.g. committed, then later
  // redacted to placeholders in a follow-up commit); the path alone never proves the
  // content is safe. containsRealSecret (content-based) is what decides critical vs
  // not — see isPlaceholderSecretValue's ALL_CAPS_SNAKE_PLACEHOLDER_PATTERN for how
  // genuine template placeholder VALUES are told apart from real leaked values.
  const lowerPath = path.toLowerCase();
  const basename = historyPathBasename(lowerPath);
  if (/\.env(?:\.|$)/.test(basename)) {
    return true;
  }
  if (
    lowerPath.includes('secret') ||
    lowerPath.includes('credential') ||
    basename.endsWith('.pem') ||
    basename.endsWith('.key') ||
    basename === 'id_rsa' ||
    basename.endsWith('.p12') ||
    basename.endsWith('.pfx')
  ) {
    return true;
  }
  return useV23PemPrivateKeyGrammar && isV23PemCredentialHistoryPath(basename);
}

// Non-template .env-shaped path — explicitly excludes .env.example/.sample/.template/.dist,
// since a bare template PATH (with no confirmed secret value) is never even a warning: it's
// the canonical safe pattern (goal_cejel_calibration_findings_precision_2026-07-06). Used to
// distinguish "a real, non-template .env file was tracked, value unknown" (warning) from
// "a real high-entropy secret value was found" (critical, handled separately via containsRealSecret).
function isEnvHistoryPath(path: string, useV36Detectors = false, useV47Detectors = false): boolean {
  if (isEnvTemplatePath(path, useV47Detectors)) return false;
  if (useV47Detectors && !isV47AuthoredProductionPath(path)) return false;
  const basename = path.toLowerCase().split('/').at(-1) ?? path.toLowerCase();
  return (useV36Detectors ? /^\.env(?:\.|$)/ : /\.env(?:\.|$)/).test(basename);
}

function readGitBlob(
  repoPath: string,
  commit: string,
  path: string,
  scanLimitations: Set<string>,
): string | null {
  const maxBufferBytes = 512_000;
  const blobResult = execGit(['show', `${commit}:${path}`], {
    cwd: repoPath,
    maxBufferBytes,
  });
  if (!blobResult.ok) {
    if (isExpectedHistoryAbsence(scanLimitations, blobResult)) return null;
    // #560: a submodule entry (a gitlink, mode 160000) at a credential-shaped path names a commit
    // in another repository, not a file; it has no content here to read, so it is not a failed
    // read. Checked only after the read fails, so every other read is unchanged.
    if (isGitlinkInCommit(repoPath, commit, path)) return null;
    declareHistoryFailure(
      scanLimitations,
      blobResult.reason,
      'historical blob read',
      maxBufferBytes,
    );
    return null;
  }
  return blobResult.stdout;
}

/** True when `commit` added or changed `path` as a gitlink (a submodule entry, mode 160000). */
function isGitlinkInCommit(repoPath: string, commit: string, path: string): boolean {
  const result = execGit(
    ['diff-tree', '--root', '-r', '--raw', '-z', '--no-commit-id', commit, '--', `:(literal)${path}`],
    { cwd: repoPath },
  );
  if (!result.ok) return false;
  const [status, entryPath] = result.stdout.split('\0');
  return entryPath === path && /^:\d{6} 160000 /.test(status ?? '');
}

// A human-readable ALL-CAPS snake_case label (YOUR_API_KEY_HERE, CHANGE_THIS_VALUE,
// INSERT_SECRET_HERE, NOT_SET) is a common .env.example placeholder convention that
// doesn't necessarily contain "your"/"example"/etc — but real secret tokens are never
// pure-uppercase English words joined by underscores; they use mixed-case/base64/hex
// charsets with no natural word boundaries. Requires >=1 underscore so contiguous
// all-caps IDs like AKIA... (no separator) are unaffected — found running Cejel on
// site-machine's .env.example (goal_cejel_calibration_findings_precision_2026-07-06).
const ALL_CAPS_SNAKE_PLACEHOLDER_PATTERN = /^[A-Z][A-Z0-9]*(?:_[A-Z0-9]+)+$/;

export function isPlaceholderSecretValue(value: string): boolean {
  const normalized = value.trim().toLowerCase();
  return (
    PLACEHOLDER_SECRET_PATTERN.test(normalized) ||
    normalized.includes('your-') ||
    normalized.includes('example') ||
    ALL_CAPS_SNAKE_PLACEHOLDER_PATTERN.test(value.trim()) ||
    isSyntheticFixtureSecretValue(normalized) ||
    isFillerRunSecretValue(normalized)
  );
}

// A2 disclosure, every rubric. A value that has the shape of a credential (looksLikeSecretValue)
// but that isPlaceholderSecretValue sets aside — the AWS documentation pair, for example, which
// contains "EXAMPLE" — does not count against secret cleanliness. That is a precision choice and is
// unchanged. Before this, it left no trace, so "clean" read as "nothing credential-shaped was
// found". These values are now counted, by file, and named on the certificate. Nothing here feeds
// a metric, a finding or an evidence pointer.
interface PlaceholderSetAsideCount {
  count: number;
}

/**
 * A credential-shaped value the placeholder rule set aside: the scan reported nothing for it, it
 * carries a placeholder marker, and without that marker it would read as a secret.
 */
function isPlaceholderSetAsideSecret(value: string, outcome: V24ClassificationOutcome): boolean {
  return (
    outcome.classification === 'no_finding' &&
    isPlaceholderSecretValue(value) &&
    looksLikeSecretValue(value)
  );
}

export interface PlaceholderSetAsideFile {
  readonly path: string;
  readonly count: number;
}

const PLACEHOLDER_SET_ASIDE_PATHS_SHOWN = 3;

function placeholderSetAsidePathList(files: readonly PlaceholderSetAsideFile[], shown: number): string {
  const named = files.slice(0, shown).map((file) => file.path);
  const more = files.length - named.length;
  return more > 0 ? `${named.join(', ')} and ${more} more file${more === 1 ? '' : 's'}` : named.join(', ');
}

function placeholderSetAsideValues(files: readonly PlaceholderSetAsideFile[]): string {
  const total = files.reduce((sum, file) => sum + file.count, 0);
  return `${total} credential-shaped value${total === 1 ? '' : 's'}`;
}

/**
 * A2's disclosure, which the certificate lists under "What was not established". It always starts
 * with WITAN_A2_PLACEHOLDER_SET_ASIDE_PREFIX. `budget` is the schema's room for one disclosure;
 * paths are dropped to fit.
 */
export function placeholderSetAsideDisclosure(
  files: readonly PlaceholderSetAsideFile[],
  budget = Number.POSITIVE_INFINITY,
): string {
  const total = files.reduce((sum, file) => sum + file.count, 0);
  const lead = `${WITAN_A2_PLACEHOLDER_SET_ASIDE_PREFIX}${placeholderSetAsideValues(files)} as ${total === 1 ? 'a documentation placeholder because it contains' : 'documentation placeholders because they contain'} a placeholder marker such as "example", so ${total === 1 ? 'it was' : 'they were'} not counted against secret cleanliness or checked further`;
  for (let shown = Math.min(files.length, PLACEHOLDER_SET_ASIDE_PATHS_SHOWN); shown > 0; shown -= 1) {
    const sentence = `${lead}: ${placeholderSetAsidePathList(files, shown)}.`;
    if (sentence.length <= budget) return sentence;
  }
  const countOnly = `${lead}, in ${files.length} file${files.length === 1 ? '' : 's'}.`;
  return countOnly.length <= budget ? countOnly : '';
}

/** The same fact, short enough for the secret_cleanliness metric line (schema maximum 240). */
function placeholderSetAsideCondition(files: readonly PlaceholderSetAsideFile[]): string {
  const lead = `${placeholderSetAsideValues(files)} set aside as documentation placeholders, not counted`;
  for (let shown = Math.min(files.length, PLACEHOLDER_SET_ASIDE_PATHS_SHOWN); shown > 0; shown -= 1) {
    const condition = `${lead}: ${placeholderSetAsidePathList(files, shown)}`;
    if (condition.length <= METRIC_CONDITION_MAX_LENGTH) return condition;
  }
  return `${lead} (${files.length} file${files.length === 1 ? '' : 's'})`;
}

// WitanCriterionMetric presentation `condition` maximum.
const METRIC_CONDITION_MAX_LENGTH = 240;
// WitanCriterionSignalPayload `notes` maximum.
const CRITERION_NOTES_MAX_LENGTH = 1000;
// WitanCriterionDisclosuresSchema's per-sentence maximum.
const CRITERION_DISCLOSURE_MAX_LENGTH = 1000;

function placeholderSetAsideDisclosures(
  files: readonly PlaceholderSetAsideFile[],
): { disclosures?: string[] } {
  if (files.length === 0) return {};
  const sentence = placeholderSetAsideDisclosure(files, CRITERION_DISCLOSURE_MAX_LENGTH);
  return sentence ? { disclosures: [sentence] } : {};
}

// A doc placeholder often looks like a real token — a plausible prefix followed
// by a long run of a single filler character (e.g. `qd_agent_xxxxxxxx…`,
// `sk-xxxxxxxx`, `ghp_0000…`). PLACEHOLDER_SECRET_PATTERN only catches values that
// are ENTIRELY filler (`^x{3,}$`), so a prefixed filler-run slips through and gets
// scored as a committed secret (found 2026-06-30 running Witan on the QuantDinger
// competitor repo). This recognizes an entropy-free body: after optionally stripping
// a prefix that ends in a separator, the remainder is dominated by one repeated
// character with at most two distinct characters. A genuine high-entropy secret has
// many distinct characters and is never matched.
function isFillerRunSecretValue(value: string): boolean {
  const candidates = [value];
  const sepIdx = Math.max(value.lastIndexOf('_'), value.lastIndexOf('-'));
  if (sepIdx > 0 && sepIdx < value.length - 1) {
    candidates.push(value.slice(sepIdx + 1));
  }
  for (const body of candidates) {
    if (body.length < 8) continue;
    const counts = new Map<string, number>();
    for (const ch of body) counts.set(ch, (counts.get(ch) ?? 0) + 1);
    const distinct = counts.size;
    const maxRun = Math.max(...counts.values());
    if (distinct <= 2 && maxRun / body.length >= 0.8) return true;
  }
  return false;
}

function isSyntheticFixtureSecretValue(value: string): boolean {
  return (
    value.includes('abcdefghijklmnopqrstuvwxyz') ||
    value.includes('0123456789abcdefghijklmnopqrstuvwxyz') ||
    value.includes('abcdefghijklmnopqrstuvwxyz0123456789') ||
    value.includes('abcdefghijklmnopqrst')
  );
}

// ---- v24-only: A2 content-context classification of secret-shaped values -------------------
// (goal_cejel_secret_posture_context_track_b_2026-09-15.) Every rubric up to v23 answers part of
// "is this matched value a real credential?" from the file's PATH: V39_NON_PRODUCTION_CREDENTIAL_
// PATH_PATTERN and V47_NON_PRODUCTION_CREDENTIAL_PATH_PATTERN delete docs/, documentation/,
// lessons/, cookbooks/ and every .md/.mdx/.rst/.adoc file from A2's current-tree secret scan. That
// rule is disqualified by design, not by defect: it cannot tell a placeholder written into a
// documentation page from a live credential accidentally committed to one, and it silences the
// second in order to suppress the first. A real secret under docs/ must still flag.
//
// v24 replaces it with a classification of the value itself plus a bounded window of that file's
// own text, producing exactly one of three outcomes:
//
//   no_finding — the value is intrinsically instructional, or below the candidate net entirely;
//   real       — the value clears the unchanged v22 high-confidence bar, flagged at unchanged
//                severity and evidence wherever it lives;
//   ambiguous  — Cejel cannot decide from content, and abstains `secret_cleanliness` with a
//                stated reason instead of reporting a silent pass.
//
// SIGNALS THE CLASSIFIER USES: the matched value's own composition — word structure against a
// closed committed gazetteer, character classes, Shannon entropy, filler runs, template
// interpolation, a documented vendor test-mode prefix combined with a placeholder-shaped body —
// and a ±3-line window of the same file's raw text matched against a closed committed
// instructional-marker vocabulary.
//
// SIGNALS IT DELIBERATELY DOES NOT USE: the file's path, directory name, or extension; the
// repository's name, archetype, language, or size; the assigned identifier's resemblance to a
// path; and anything outside the file being scanned. Identical bytes therefore produce an
// identical verdict wherever they live — asserted directly in a2-secret-content-context-v24.test.ts
// rather than inferred from the absence of a path read here.
type V24SecretClassification = 'no_finding' | 'real' | 'ambiguous';

interface V24ClassificationOutcome {
  readonly classification: V24SecretClassification;
  readonly reason?: string;
}

const V24_NO_FINDING: V24ClassificationOutcome = { classification: 'no_finding' };
const V24_REAL: V24ClassificationOutcome = { classification: 'real' };

// Both reasons are reproduced verbatim in the emitted finding, so a certificate reader sees why
// Cejel declined to answer rather than a bare "insufficient_data".
const V24_AMBIGUOUS_INSTRUCTIONAL_REASON =
  'the value clears the confident real-secret bar but sits in an instructional context, and a committed example is indistinguishable from a pasted live credential by content alone';
const V24_AMBIGUOUS_UNCLASSIFIED_REASON =
  'the value clears neither the placeholder vocabulary nor the confident real-secret bar, so Cejel has no basis to call it either a credential or an example';

const V24_CONTEXT_LINE_RADIUS = 3;
// Each window line is truncated before matching. The marker pattern is a flat literal alternation
// with no nested quantifier, but a minified or generated file can still be one megabyte-long line
// and there is no instructional marker worth finding past the first few hundred characters
// (docs/filename-redos-verification-2026-09-10.md discipline).
const V24_CONTEXT_LINE_SCAN_LIMIT = 400;

// Closed, explicit, version-controlled instructional vocabulary. Reviewable in the pull request,
// never inferred at runtime, never extended from repository content.
const V24_INSTRUCTIONAL_MARKER_PATTERN =
  /replace (?:this|it|the|with|these|your)|your own|for example|example only|sample value|placeholder|dummy value|not a real|not real|do not use this|never commit|for illustration|paste your|copy your|insert your|fill in|shown here/i;

// The same discipline for the value itself: a credential is never a sequence of ordinary English
// instruction words, however long or mixed-case it is. Lexical shape alone cannot separate
// `ReplaceThisWithYourOwnApiKeyValue1234567890` from a token — word composition can
// (alfred_pr_lessons_2026-07-09, entry 22).
const V24_PLACEHOLDER_WORD_GAZETTEER: ReadonlySet<string> = new Set([
  'a', 'actual', 'add', 'api', 'application', 'before', 'change', 'changeme', 'console', 'copy',
  'credential', 'dashboard', 'demo', 'do', 'docs', 'documentation', 'dummy', 'enter', 'example',
  'fake', 'fill', 'for', 'from', 'generate', 'get', 'goes', 'here', 'hidden', 'in', 'insert',
  'instead', 'key', 'live', 'me', 'my', 'not', 'of', 'obtain', 'omitted', 'on', 'own', 'paste',
  'password', 'placeholder', 'production', 'provide', 'put', 'real', 'redacted', 'removed',
  'replace', 'running', 'sample', 'secret', 'set', 'supply', 'the', 'this', 'to', 'token',
  'tutorial', 'type', 'use', 'value', 'with', 'your',
]);

const V24_TEMPLATE_INTERPOLATION_PATTERN =
  /\{\{[^{}]{1,64}\}\}|\$\{[^{}]{1,64}\}|%\([A-Za-z_][A-Za-z0-9_]{0,63}\)s|^<[^<>]{1,64}>$|^\$[A-Z][A-Z0-9_]{2,63}$/;

// Publicly documented vendor test-mode prefixes. The prefix ALONE never qualifies a value: a real
// key is routinely copy-pasted into a variable whose name says `test`, so the body must itself be
// placeholder-shaped.
const V24_VENDOR_TEST_MODE_PREFIX_PATTERN = /^(?:sk|pk|rk|whsec)_test_/i;

// The candidate net — deliberately wider than `looksLikeSecretValue`, because the whole point of
// the third outcome is that values BETWEEN "obviously an example" and "confidently a credential"
// stop disappearing silently.
const V24_CANDIDATE_VALUE_PATTERN = /^[A-Za-z0-9/+_.:~-]{16,}$/;
const V24_CANDIDATE_MINIMUM_ENTROPY_PER_CHAR = 3;
// A value that is plainly a REFERENCE to a credential rather than a credential: a dotted
// identifier chain (`process.env.API_KEY`, `settings.SECRET_KEY`), a URL, or a filesystem path.
// Without these the candidate net would abstain on the single most common CORRECT way to handle a
// secret, which would make the abstention worthless noise rather than a signal.
const V24_CREDENTIAL_REFERENCE_PATTERN =
  /^[A-Za-z_$][A-Za-z0-9_$]*(?:\.[A-Za-z_$][A-Za-z0-9_$]*)+$/;
const V24_URL_OR_FILESYSTEM_VALUE_PATTERN = /^(?:[a-z][a-z0-9+.-]{0,31}:\/\/|\.{0,2}\/|~\/)/i;

/**
 * Splits a value into words on separators, camelCase boundaries, and letter/digit boundaries.
 * The last of those matters: `...ApiKeyValue1234567890` is one instructional phrase with a filler
 * digit run glued to its final word, and without that split the whole value fails the gazetteer on
 * a token (`Value1234567890`) that is not a word at all.
 */
function splitV24ValueWords(value: string): string[] {
  return value
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2')
    .replace(/([A-Za-z])(\d)/g, '$1 $2')
    .replace(/(\d)([A-Za-z])/g, '$1 $2')
    .split(/[^A-Za-z0-9]+/)
    .filter((word) => word.length > 0);
}

/**
 * True when every alphabetic word in the value is drawn from the committed gazetteer and there are
 * at least three of them. Requiring EVERY word (not a majority) is what keeps this safe: a real
 * credential would have to be composed entirely of common instruction words to collide.
 */
function isV24InstructionalPhraseValue(value: string): boolean {
  const words = splitV24ValueWords(value);
  if (words.length < 3) return false;
  let alphabeticWords = 0;
  for (const word of words) {
    if (/^\d+$/.test(word)) continue;
    if (!V24_PLACEHOLDER_WORD_GAZETTEER.has(word.toLowerCase())) return false;
    alphabeticWords += 1;
  }
  return alphabeticWords >= 3;
}

/**
 * Value-intrinsic placeholder evidence. This is the ONLY branch that can clear a value to a silent
 * no-finding, so it reads nothing but the value: an instructional phrase, an unfilled template
 * interpolation, or a vendor test-mode prefix over a placeholder-shaped body. Surrounding prose can
 * never reach this branch — prose next to a real-looking value abstains instead.
 */
function isV24IntrinsicPlaceholderValue(value: string): boolean {
  if (isPlaceholderSecretValue(value)) return true;
  if (isV24InstructionalPhraseValue(value)) return true;
  if (V24_TEMPLATE_INTERPOLATION_PATTERN.test(value)) return true;
  if (V24_VENDOR_TEST_MODE_PREFIX_PATTERN.test(value)) {
    const body = value.replace(V24_VENDOR_TEST_MODE_PREFIX_PATTERN, '');
    return isPlaceholderSecretValue(body) || isV24InstructionalPhraseValue(body);
  }
  return false;
}

function isV24CandidateSecretValue(value: string): boolean {
  if (!V24_CANDIDATE_VALUE_PATTERN.test(value)) return false;
  if (V24_CREDENTIAL_REFERENCE_PATTERN.test(value)) return false;
  if (V24_URL_OR_FILESYSTEM_VALUE_PATTERN.test(value)) return false;
  if (isLikelyDigestOrHash(value)) return false;
  const classCount = [/[a-z]/, /[A-Z]/, /[0-9]/, /[+/_.:~-]/].filter((pattern) =>
    pattern.test(value),
  ).length;
  if (classCount < 2) return false;
  return shannonEntropyPerChar(value) >= V24_CANDIDATE_MINIMUM_ENTROPY_PER_CHAR;
}

function hasV24InstructionalContext(rawLines: readonly string[], line: number): boolean {
  const start = Math.max(0, line - 1 - V24_CONTEXT_LINE_RADIUS);
  const end = Math.min(rawLines.length, line + V24_CONTEXT_LINE_RADIUS);
  for (let index = start; index < end; index += 1) {
    const candidate = (rawLines[index] ?? '').slice(0, V24_CONTEXT_LINE_SCAN_LIMIT);
    if (V24_INSTRUCTIONAL_MARKER_PATTERN.test(candidate)) return true;
  }
  return false;
}

function classifyV24SecretShapedValue(
  value: string,
  identifier: string,
  line: number,
  rawLines: readonly string[],
  allowCredentialNamedDigest: boolean,
): V24ClassificationOutcome {
  if (isV24IntrinsicPlaceholderValue(value)) return V24_NO_FINDING;
  // Rule 3 of the protocol: a match satisfying no intrinsic placeholder signal is evaluated
  // against the EXISTING high-confidence bar, unchanged. Context can move it to an abstention but
  // must never downgrade it to a silent pass.
  const clearsRealBar =
    looksLikeSecretValue(value) ||
    (allowCredentialNamedDigest &&
      isLikelyDigestOrHash(value) &&
      isExplicitCredentialIdentifier(identifier));
  const instructionalContext = hasV24InstructionalContext(rawLines, line);
  if (clearsRealBar) {
    return instructionalContext
      ? { classification: 'ambiguous', reason: V24_AMBIGUOUS_INSTRUCTIONAL_REASON }
      : V24_REAL;
  }
  if (!isV24CandidateSecretValue(value)) return V24_NO_FINDING;
  if (instructionalContext) return V24_NO_FINDING;
  return { classification: 'ambiguous', reason: V24_AMBIGUOUS_UNCLASSIFIED_REASON };
}

function hasSuspiciousDependencies(
  repoPath: string,
  manifest: string,
  useV47Detectors = false,
): boolean {
  if (!manifest.endsWith('package.json')) return false;
  const fullPath = join(repoPath, manifest);
  if (!isRegularFile(fullPath)) return false;
  // A malformed/BOM'd package.json must skip this check, never abort the scan.
  const parsed = parseJsonObject(readRepoText(fullPath, 'utf8'));
  if (!parsed) return false;
  const dependencies = isRecord(parsed.dependencies) ? parsed.dependencies : {};
  const devDependencies = isRecord(parsed.devDependencies) ? parsed.devDependencies : {};
  const names = [...Object.keys(dependencies), ...Object.keys(devDependencies)];
  if (
    names.some((name) =>
      /^(todo|fake|placeholder|example)-|does-not-exist| hallucinated/i.test(name),
    )
  ) {
    return true;
  }
  if (!useV47Detectors || typeof parsed.name !== 'string') return false;
  const placeholderIdentity = /^(?:example|sample|placeholder|todo|fake)(?:-|$)/i.test(parsed.name);
  const placeholderMetadata =
    (typeof parsed.author === 'string' &&
      /^(?:your name|example|placeholder)$/i.test(parsed.author)) ||
    (typeof parsed.description === 'string' &&
      /^(?:package description|example|placeholder|todo)$/i.test(parsed.description));
  return placeholderIdentity && placeholderMetadata;
}

interface GitCommitSummary {
  sha: string;
  subject: string;
}

function readRecentCommits(repoPath: string): GitCommitSummary[] {
  const historyResult = execGit(
    ['log', '--no-show-signature', `--max-count=${RECENT_COMMIT_WINDOW}`, '--format=%H%x00%s'],
    {
      cwd: repoPath,
    },
  );
  if (!historyResult.ok) {
    if (isExpectedGitAbsence(historyResult)) return [];
    throw new Error(describeGitFailure(historyResult.reason, 'recent history scan'));
  }
  const output = historyResult.stdout.trim();
  if (!output) return [];
  return output
    .split('\n')
    .map((line) => {
      const [sha = '', subject = ''] = line.split('\0');
      return { sha, subject };
    })
    .filter((commit) => commit.sha.length >= 7);
}

function readPackageScripts(packageJsonPath: string): Map<string, string> {
  if (!isRegularFile(packageJsonPath)) return new Map();
  // A malformed/BOM'd package.json must skip this check, never abort the scan.
  const parsed = parseJsonObject(readRepoText(packageJsonPath, 'utf8'));
  const scripts = parsed?.scripts;
  if (!isRecord(scripts)) return new Map();
  return new Map(
    Object.entries(scripts).filter(
      (entry): entry is [string, string] => typeof entry[1] === 'string',
    ),
  );
}

export function evidenceForRelative(
  repoPath: string,
  path: string,
  kind: WitanEvidencePointer['kind'],
  label: string,
): WitanEvidencePointer {
  const fullPath = join(repoPath, path);
  const contents = isRegularFile(fullPath) ? readRepoText(fullPath, 'utf8') : '';
  return {
    kind,
    label,
    path,
    ...(contents
      ? {
          line: firstMeaningfulLine(contents),
          contentHash: createHash('sha256').update(contents).digest('hex'),
        }
      : {}),
  };
}

// Evidence for a finding anchored to a SPECIFIC in-file match (not mere file presence): line is
// the real 1-based line the caller already measured, or explicit null when no real position was
// found — never firstMeaningfulLine's "first non-blank line of the file" fallback, which is a
// fabricated position for a match-anchored finding (D4 — cejel reported `line: 1` for its own
// test fixture this way; see goal_cejel_a2_one_notion_of_production_code_2026-07-13).
export function evidenceForRelativeAtLine(
  repoPath: string,
  path: string,
  kind: WitanEvidencePointer['kind'],
  label: string,
  line: number | null,
): WitanEvidencePointer {
  const fullPath = join(repoPath, path);
  const contents = isRegularFile(fullPath) ? readRepoText(fullPath, 'utf8') : '';
  return {
    kind,
    label,
    path,
    line,
    ...(contents ? { contentHash: createHash('sha256').update(contents).digest('hex') } : {}),
  };
}

function metric(
  name: CertificateMetricName,
  label: string,
  value: number,
  max: number,
  weight: number,
  unit: string,
  description: string,
  kind?: 'ratio' | 'saturating_count',
  presentation?: WitanCriterionMetric['presentation'],
): WitanCriterionMetric {
  const normalizedValue = Math.max(0, value);
  if (presentation?.components) {
    const explainedValue = presentation.components.reduce(
      (sum, component) => sum + component.count,
      0,
    );
    if (explainedValue !== normalizedValue) {
      throw new Error(
        `Cejel invariant: presentation components for ${name} total ${explainedValue}, expected ${normalizedValue}`,
      );
    }
  }
  return {
    name,
    label,
    value: normalizedValue,
    max,
    ...(kind ? { kind } : {}),
    weight,
    unit,
    description,
    ...(presentation ? { presentation } : {}),
  };
}

function firstMeaningfulLine(contents: string): number {
  const lines = contents.split('\n');
  const index = lines.findIndex((line) => line.trim().length > 0);
  return index === -1 ? 1 : index + 1;
}

function readGitHead(repoPath: string): string | null {
  const headResult = execGit(['rev-parse', 'HEAD'], { cwd: repoPath });
  if (!headResult.ok) {
    if (isExpectedGitAbsence(headResult)) return null;
    throw new Error(describeGitFailure(headResult.reason, 'HEAD resolution'));
  }
  return headResult.stdout.trim() || null;
}

// True if any .env* file has ever been added/modified in git history (including deleted files).
// A once-committed .env file is a ratable secrets surface even after deletion.
function hasEnvPathInGitHistory(
  repoPath: string,
  scanLimitations: Set<string>,
  useV36Detectors = false,
  useV23PemPrivateKeyGrammar = false,
): boolean {
  const flags = ['--diff-filter=AM', '--name-only', '-z', '--format='];
  const historyResult = execGit(['log', '--no-show-signature', 'HEAD', ...flags], { cwd: repoPath });
  if (!historyResult.ok) {
    if (stoppedAtOwnLimit(historyResult)) {
      // #567: the same log, one batch of commits at a time, stopping at the first .env path.
      const budget = new HistoryFallbackBudget(scanLimitations);
      const commits = readHistoryCommitsInPages(repoPath, scanLimitations, 'environment-file history scan', budget);
      let found = false;
      runHistoryCommandInBatches(
        repoPath,
        ['log', '--no-show-signature', '--no-walk=unsorted', '--stdin', ...flags],
        commits,
        scanLimitations,
        'environment-file history scan',
        budget,
        (output) =>
          (found = envPathInHistoryOutput(output, scanLimitations, useV36Detectors, useV23PemPrivateKeyGrammar)),
      );
      return found;
    }
    if (isExpectedHistoryAbsence(scanLimitations, historyResult)) return false;
    declareHistoryFailure(scanLimitations, historyResult.reason, 'environment-file history scan');
    return false;
  }
  return envPathInHistoryOutput(historyResult.stdout, scanLimitations, useV36Detectors, useV23PemPrivateKeyGrammar);
}

function envPathInHistoryOutput(
  output: string,
  scanLimitations: Set<string>,
  useV36Detectors: boolean,
  useV23PemPrivateKeyGrammar: boolean,
): boolean {
  if (!output) return false;
  return output.split('\0').some((rawPath) => {
    const path = rawPath.startsWith('\n') ? rawPath.slice(1) : rawPath;
    if (/[\u0000-\u001f\u007f]/.test(path)) {
      // Counted when this read would have used it (an .env path); worded by the shared rule (#569).
      skipControlCharacterHistoryPath(
        scanLimitations,
        path,
        /(?:^|\/)\.env(?:\.|$)/i.test(path),
        useV36Detectors,
        useV23PemPrivateKeyGrammar,
      );
      return false;
    }
    return /(?:^|\/)\.env(?:\.|$)/i.test(path);
  });
}
